/// Provenance for planning one owned parsed HIR.
///
/// The ripgrep variant is minted only after the direct-HIR seam has checked
/// the complete flat literal shape and its capture-free HIR properties. It is
/// moved beside that same HIR into `PortableParsedBuildContext`. It authorizes
/// both capture-free metadata publication and the exact flat-literal planner
/// route; generic parsed construction cannot claim either shortcut.
enum ParsedBuildProvenance {
    Canonical,
    RipgrepFlatLiteral,
}

/// Result of consuming ripgrep's ordinary literal HIR construction candidate.
///
/// A refusal returns the exact owned HIR so the adapter can preserve its
/// canonical source fallback without cloning the recursive HIR allocation
/// graph on the admitted path.
#[doc(hidden)]
#[derive(Debug)]
pub enum RipgrepStandardLiteralHirBuild {
    /// FRE independently authenticated and built the literal HIR.
    Built(PortableRegex),
    /// FRE declined the seam and returned the unchanged HIR to its owner.
    Refused(Hir),
}

/// Result of ripgrep's authenticated ordinary literal-set construction.
///
/// The ordinary variant deliberately has no checked or finite-search surface.
/// Callers that receive the portable variant retain the complete established
/// [`PortableRegex`] contract.
#[doc(hidden)]
pub enum RipgrepStandardLiteralsBuild {
    /// Ripgrep may bind only an ordinary unmetered worker session.
    Ordinary(RipgrepOrdinaryRegex),
    /// Construction retained the checked canonical portable owner.
    Portable(PortableRegex),
}

/// Bytes observed while authenticating ripgrep's standard literal handoff.
///
/// This receipt is transient construction data. It is not retained by either
/// FRE owner and therefore does not change persistent-byte accounting.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct RipgrepStandardLiteralByteCensus {
    matching_bytes: [u64; 4],
}

// Switch before validating the pattern that brings the authenticated literal
// byte total to this boundary. The byte-indexed accumulator removes one
// variable shift and one word read-modify-write from every later byte while
// retaining a bounded conversion back to the exact public receipt.
const RIPGREP_STANDARD_LITERAL_CENSUS_PRESENCE_THRESHOLD_BYTES: u64 = 1_024;

impl RipgrepStandardLiteralByteCensus {
    fn empty() -> RipgrepStandardLiteralByteCensus {
        RipgrepStandardLiteralByteCensus {
            matching_bytes: [0; 4],
        }
    }

    fn insert(&mut self, byte: u8) {
        let word = usize::from(byte >> 6);
        let bit = byte & 0x3F;
        self.matching_bytes[word] |= 1_u64 << bit;
    }

    /// Whether this byte occurred in an authenticated literal.
    #[doc(hidden)]
    #[must_use]
    pub fn contains(&self, byte: u8) -> bool {
        let word = usize::from(byte >> 6);
        let bit = byte & 0x3F;
        self.matching_bytes[word] & (1_u64 << bit) != 0
    }
}

#[allow(
    clippy::large_enum_variant,
    reason = "inline presence avoids allocation and per-byte bit arithmetic"
)]
enum RipgrepStandardLiteralByteCensusAccumulator {
    Bitset(RipgrepStandardLiteralByteCensus),
    Presence([bool; 256]),
}

impl RipgrepStandardLiteralByteCensusAccumulator {
    fn empty() -> Self {
        Self::Bitset(RipgrepStandardLiteralByteCensus::empty())
    }

    fn prepare_for_cumulative_bytes(&mut self, cumulative_bytes: u64) {
        if cumulative_bytes < RIPGREP_STANDARD_LITERAL_CENSUS_PRESENCE_THRESHOLD_BYTES {
            return;
        }
        let Self::Bitset(census) = self else {
            return;
        };
        let census = *census;
        let mut presence = [false; 256];
        for byte in 0..=u8::MAX {
            presence[usize::from(byte)] = census.contains(byte);
        }
        *self = Self::Presence(presence);
    }

    #[inline]
    fn classify(&mut self, text: &str, forbidden_byte: Option<u8>) -> Option<bool> {
        match self {
            Self::Bitset(census) => {
                classify_ripgrep_standard_literal_text_with_census(text, forbidden_byte, census)
            }
            Self::Presence(presence) => {
                classify_ripgrep_standard_literal_text_with_recorder(text, forbidden_byte, |byte| {
                    presence[usize::from(byte)] = true
                })
            }
        }
    }

    fn into_census(self) -> RipgrepStandardLiteralByteCensus {
        match self {
            Self::Bitset(census) => census,
            Self::Presence(presence) => {
                let mut census = RipgrepStandardLiteralByteCensus::empty();
                for byte in 0..=u8::MAX {
                    if presence[usize::from(byte)] {
                        census.insert(byte);
                    }
                }
                census
            }
        }
    }

    #[cfg(test)]
    fn uses_presence(&self) -> bool {
        matches!(self, Self::Presence(_))
    }
}

