enum K0PooledValue {
    Exists(bool),
    Span(Option<fre_automata::MatchSpan>),
}

enum K0PooledSpanRoute {
    Declined,
    Complete(Option<fre_automata::MatchSpan>),
}

enum K0PooledFiniteConsumptionSpanRoute {
    Unattempted,
    Complete(Option<fre_automata::MatchSpan>),
    Fallback(SearchWindow),
}

/// Search one already-retained exact minimum word for warm ordinary Exists.
///
/// Mandatory-suffix construction accepts only a nonempty language and proves
/// that every accepted word ends in `suffix`. When its length equals the exact
/// minimum match length, one minimum-length accepted word is therefore exactly
/// `suffix`. The warm admission below separately excludes assertions, so an
/// occurrence of that word in the full haystack is both necessary and
/// sufficient for Exists.
/// Literal refusal is a transactional performance decline; the caller must
/// continue through the incumbent pooled K0 chain from its authenticated cut
/// floor.
#[inline(never)]
fn try_k0_warm_exact_minimum_suffix_exists(
    suffix: &K0MandatorySuffixPlan,
    haystack: &[u8],
    window: SearchWindow,
) -> Option<bool> {
    #[cfg(test)]
    if k0_exact_minimum_suffix_exists_probe::begin_scan() {
        return None;
    }
    suffix
        .find_window(haystack, window.start(), window.end())
        .ok()
        .map(|found| found.is_some())
}

/// Complete one receipt-authenticated early bounded-literal-repeat Span
/// without borrowing K0 workspace.
///
/// Construction proves the exact language `L{m,n}S`, binds the retained
/// mandatory suffix to `L^m S`, proves a tail barrier, and admits only a
/// zero-distance mandatory cut. The revalidated receipt supplies the suffix
/// offset. If the first cut member begins a whole number of additional `L`
/// tokens ending at that suffix, the cut proves no earlier match start and the
/// barrier proves this accepted endpoint is the unique greedy endpoint.
/// Every mismatch is a read-only decline to the complete immutable leaf.
#[inline(never)]
fn try_k0_bounded_literal_repeat_early_span(
    suffix: &K0MandatorySuffixPlan,
    cut: K0MandatoryCutPlan,
    haystack: &[u8],
    window: SearchWindow,
    minimum_match_bytes: usize,
    maximum_match_bytes: usize,
    suffix_offset: usize,
) -> Option<fre_automata::MatchSpan> {
    #[cfg(test)]
    bounded_literal_repeat_early_span_probe::record_attempt();
    if window.start() != 0
        || window.end() != haystack.len()
        || cut.maximum_before_root() != MaximumConsumedDistance::Finite(0)
        || minimum_match_bytes == 0
        || minimum_match_bytes > maximum_match_bytes
    {
        return None;
    }
    let (token_bytes, tail_bytes) = suffix.bounded_literal_repeat_span_lengths()?;
    let needle = suffix.needle();
    if needle.len() != minimum_match_bytes
        || token_bytes == 0
        || tail_bytes == 0
        || tail_bytes >= needle.len()
        || tail_bytes > maximum_match_bytes
    {
        return None;
    }
    let minimum_prefix_bytes = needle.len().checked_sub(tail_bytes)?;
    let maximum_prefix_bytes = maximum_match_bytes.checked_sub(tail_bytes)?;
    if minimum_prefix_bytes == 0
        || !minimum_prefix_bytes.is_multiple_of(token_bytes)
        || !maximum_prefix_bytes.is_multiple_of(token_bytes)
    {
        return None;
    }
    let token = needle.get(..token_bytes)?;
    let tail_first = *needle.get(minimum_prefix_bytes)?;
    if token.contains(&tail_first) {
        return None;
    }

    let first_member = cut.first_member(&haystack[window.start()..window.end()])?;
    let selected_start = window.start().checked_add(first_member)?;
    let suffix_start = window.start().checked_add(suffix_offset)?;
    let added_prefix_bytes = suffix_start.checked_sub(selected_start)?;
    if !added_prefix_bytes.is_multiple_of(token_bytes) {
        return None;
    }
    let minimum_repeats = minimum_prefix_bytes / token_bytes;
    let maximum_repeats = maximum_prefix_bytes / token_bytes;
    let added_repeats = added_prefix_bytes / token_bytes;
    let selected_repeats = minimum_repeats.checked_add(added_repeats)?;
    if selected_repeats > maximum_repeats {
        return None;
    }
    let prefix = haystack.get(selected_start..suffix_start)?;
    if prefix
        .chunks_exact(token_bytes)
        .any(|candidate| candidate != token)
    {
        return None;
    }
    let selected_end = suffix_start.checked_add(needle.len())?;
    if selected_end > window.end()
        || selected_end.checked_sub(selected_start)?
            != selected_repeats
                .checked_mul(token_bytes)?
                .checked_add(tail_bytes)?
    {
        return None;
    }
    #[cfg(test)]
    bounded_literal_repeat_early_span_probe::record_completion();
    Some(fre_automata::MatchSpan::new(
        selected_start,
        selected_end,
    ))
}

/// Complete one bounded-literal-repeat Span without borrowing K0 workspace.
///
/// Construction proves the exact language `L{m,n}S`, binds the retained
/// mandatory suffix to `L^m S`, proves a tail barrier, and admits only a
/// zero-distance mandatory cut. The first occurrence of `L^m S` is therefore
/// an accepted endpoint. Walking backward over at most `n - m` whole `L`
/// tokens recovers the selected start: the walk implements greedy priority,
/// while the barrier makes lazy priority select the same unique endpoint. A
/// later suffix cannot move the selected start before the first suffix because
/// its `L` corridor would have to cross the earlier tail's barrier byte.
/// The zero-distance mandatory cut first completes root-byte absence and
/// publishes the earliest possible suffix-search floor.
/// Every metadata mismatch is a read-only decline to the incumbent K0 path.
#[inline(never)]
fn try_k0_bounded_literal_repeat_span(
    suffix: &K0MandatorySuffixPlan,
    cut: K0MandatoryCutPlan,
    haystack: &[u8],
    window: SearchWindow,
    minimum_match_bytes: usize,
    maximum_match_bytes: usize,
) -> Option<Option<fre_automata::MatchSpan>> {
    #[cfg(test)]
    bounded_literal_repeat_span_probe::record_attempt();
    if window.start() != 0
        || window.end() != haystack.len()
        || cut.maximum_before_root() != MaximumConsumedDistance::Finite(0)
        || minimum_match_bytes == 0
        || minimum_match_bytes > maximum_match_bytes
    {
        return None;
    }
    let (token_bytes, tail_bytes) = suffix.bounded_literal_repeat_span_lengths()?;
    let needle = suffix.needle();
    if needle.len() != minimum_match_bytes
        || token_bytes == 0
        || tail_bytes == 0
        || tail_bytes >= needle.len()
        || tail_bytes > maximum_match_bytes
    {
        return None;
    }
    let minimum_prefix_bytes = needle.len().checked_sub(tail_bytes)?;
    let maximum_prefix_bytes = maximum_match_bytes.checked_sub(tail_bytes)?;
    if minimum_prefix_bytes == 0
        || !minimum_prefix_bytes.is_multiple_of(token_bytes)
        || !maximum_prefix_bytes.is_multiple_of(token_bytes)
    {
        return None;
    }
    let token = needle.get(..token_bytes)?;
    let tail_first = *needle.get(minimum_prefix_bytes)?;
    if token.contains(&tail_first) {
        return None;
    }

    let minimum_repeats = minimum_prefix_bytes / token_bytes;
    let maximum_repeats = maximum_prefix_bytes / token_bytes;
    let additional_repeats = maximum_repeats.checked_sub(minimum_repeats)?;
    let first_member = cut.first_member(&haystack[window.start()..window.end()]);
    let Some(first_member) = first_member else {
        #[cfg(test)]
        bounded_literal_repeat_span_probe::record_completion();
        return Some(None);
    };
    let suffix_search_start = cut.candidate_floor(window.start(), first_member)?;
    if suffix_search_start < window.start() || suffix_search_start > window.end() {
        return None;
    }
    let found = suffix
        .find_window(haystack, suffix_search_start, window.end())
        .ok()?;
    let Some((minimum_start, selected_end)) = found else {
        #[cfg(test)]
        bounded_literal_repeat_span_probe::record_completion();
        return Some(None);
    };
    if selected_end != minimum_start.checked_add(needle.len())? {
        return None;
    }
    let mut selected_start = minimum_start;
    for _ in 0..additional_repeats {
        let Some(previous_start) = selected_start
            .checked_sub(token_bytes)
            .filter(|start| *start >= window.start())
        else {
            break;
        };
        if haystack.get(previous_start..selected_start) != Some(token) {
            break;
        }
        selected_start = previous_start;
    }
    if selected_end > window.end()
        || selected_end.checked_sub(selected_start)? > maximum_match_bytes
    {
        return None;
    }
    #[cfg(test)]
    bounded_literal_repeat_span_probe::record_completion();
    Some(Some(fre_automata::MatchSpan::new(
        selected_start,
        selected_end,
    )))
}

impl PortableK0Plan {
    fn correlated_terminal(&self) -> Option<&correlated_bounded_alternation::Plan> {
        self.exclusive.correlated_terminal()
    }

    fn packed_frontier(&self) -> Option<&K0PackedFrontierPlan> {
        self.exclusive.packed_frontier()
    }

    fn pooled_reverse_suffix_span(
        &self,
        suffix: &K0MandatorySuffixPlan,
        preclaimed_admission: Option<K0ReverseSuffixSpanAdmission<'_>>,
        haystack: &[u8],
        window: SearchWindow,
        incumbent_search_start: usize,
        suffix_search_start: usize,
        limits: SearchLimits,
        workspace_limits: SearchSessionLimits,
    ) -> Result<K0PooledSpanRoute, K0SearchError> {
        // Reject every finite/invalid invocation before inspecting the source
        // or mutating the hidden value-only pool. Diagnostic APIs never call
        // this helper and therefore retain their independent setup receipt.
        if limits != SearchLimits::unlimited()
            || window.start() > window.end()
            || window.end() > haystack.len()
            || suffix_search_start < window.start()
            || suffix_search_start > window.end()
            || incumbent_search_start < window.start()
            || incumbent_search_start > suffix_search_start
            || window.end().saturating_sub(window.start())
                < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        {
            return Ok(K0PooledSpanRoute::Declined);
        }
        let window_bytes = window.end().saturating_sub(window.start());
        // Consume one transient clock step before touching source. A losing
        // source shape must not make later sparse calls pay a full literal
        // pass merely to discover that this optional route is cooling down.
        // The invocation-local token alone may publish measured feedback.
        let admission = match preclaimed_admission {
            Some(admission) => admission,
            None => {
                let Some(admission) = suffix.try_admit_reverse_suffix_span(window_bytes) else {
                    return Ok(K0PooledSpanRoute::Declined);
                };
                admission
            }
        };
        let first = match suffix.find_window(haystack, suffix_search_start, window.end()) {
            Ok(Some(first)) => first,
            Ok(None) => return Ok(K0PooledSpanRoute::Complete(None)),
            Err(_) => return Ok(K0PooledSpanRoute::Declined),
        };
        // Exists and Span share this stable endpoint-capable bidirectional
        // layout, so whichever operation reaches the immutable owner first
        // cannot restrict later reverse-suffix execution.
        let Some(mut session) = self.automaton.try_checkout_pooled_search_session(
            workspace_limits,
            true,
            true,
        )? else {
            return Ok(K0PooledSpanRoute::Declined);
        };
        let result = execute_k0_reverse_suffix_span_from_first(
            &mut session,
            suffix,
            haystack,
            window,
            incumbent_search_start,
            limits,
            first,
        );
        match result {
            Ok(execution) => {
                if execution.transient_loss {
                    admission.observe_loss();
                } else {
                    drop(admission);
                }
                // A measured losing sidecar may have filled endpoint-oriented
                // reverse rows or saturated optional caches that are actively
                // unhelpful to the ordinary forward incumbent. Transactionally
                // replace that private workspace through its original pool
                // return route. The replacement is constructed fresh rather
                // than borrowed from another warm lane. If bounded replacement
                // allocation is unavailable, return the old workspace so an
                // optional acceleration cannot create a new allocation-failure
                // opportunity for fallback.
                // Successful and unmeasured sidecars retain their warm session.
                if execution.transient_loss {
                    self.automaton.refresh_pooled_search_session(
                        session,
                        workspace_limits,
                        true,
                        true,
                    )?;
                } else {
                    self.automaton.return_pooled_search_session(session)?;
                }
                match execution.attempt {
                    K0ReverseSuffixSpanAttempt::Complete(output) => {
                        Ok(K0PooledSpanRoute::Complete(output.map(|matched| {
                            fre_automata::MatchSpan::new(matched.start, matched.end)
                        })))
                    }
                    K0ReverseSuffixSpanAttempt::Unattempted
                    | K0ReverseSuffixSpanAttempt::Bypass
                    | K0ReverseSuffixSpanAttempt::Declined => {
                        Ok(K0PooledSpanRoute::Declined)
                    }
                }
            }
            Err(error) => Err(error),
        }
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the outlined ordinary facade keeps its admission token and cut transaction out of the shared pooled caller"
    )]
    #[inline(never)]
    fn pooled_finite_consumption_suffix_span_route(
        &self,
        suffix: &K0MandatorySuffixPlan,
        minimum_match_bytes: usize,
        maximum_match_bytes: usize,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
        workspace_limits: SearchSessionLimits,
    ) -> Result<K0PooledFiniteConsumptionSpanRoute, K0SearchError> {
        if limits != SearchLimits::unlimited()
            || workspace_limits != SearchSessionLimits::unlimited()
            || self.absolute_end_proof.is_some()
            || self.automaton.stats().has_assertions()
            || minimum_match_bytes == 0
            || minimum_match_bytes > maximum_match_bytes
            || suffix.needle().len() > minimum_match_bytes
            || window.start() > window.end()
            || window.end() > haystack.len()
        {
            return Ok(K0PooledFiniteConsumptionSpanRoute::Unattempted);
        }
        let window_bytes = window.end().saturating_sub(window.start());
        if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
            || maximum_match_bytes
                > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
        {
            return Ok(K0PooledFiniteConsumptionSpanRoute::Unattempted);
        }
        if suffix.bounded_literal_repeat_span_lengths().is_some() {
            if let Some(suffix_offset) =
                suffix.pooled_finite_consumption_span_early_prefix_offset(haystack, window)
                && let Some(matched) = self.mandatory_cut.and_then(|cut| {
                    try_k0_bounded_literal_repeat_early_span(
                        suffix,
                        cut,
                        haystack,
                        window,
                        minimum_match_bytes,
                        maximum_match_bytes,
                        suffix_offset,
                    )
                })
            {
                #[cfg(test)]
                {
                    finite_consumption_span_facade_probe::record_attempt();
                    finite_consumption_span_facade_probe::record_result(true);
                }
                return Ok(K0PooledFiniteConsumptionSpanRoute::Complete(Some(matched)));
            }
            if let Some(output) = self.mandatory_cut.and_then(|cut| {
                try_k0_bounded_literal_repeat_span(
                    suffix,
                    cut,
                    haystack,
                    window,
                    minimum_match_bytes,
                    maximum_match_bytes,
                )
            }) {
                if let Some(matched) = output
                    && let Some(suffix_start) = matched.end().checked_sub(suffix.needle().len())
                    && let Some(suffix_offset) = suffix_start.checked_sub(window.start())
                    && suffix_offset < K0_SUFFIX_FORWARD_FALLBACK_BYTES
                    && let Some(admission) =
                        suffix.try_admit_pooled_finite_consumption_span(window_bytes)
                {
                    admission.observe_finite_early_prefix(window_bytes, suffix_offset);
                }
                #[cfg(test)]
                {
                    finite_consumption_span_facade_probe::record_attempt();
                    finite_consumption_span_facade_probe::record_result(true);
                }
                return Ok(K0PooledFiniteConsumptionSpanRoute::Complete(output));
            }
        }
        let Some(admission) = suffix.try_admit_pooled_finite_consumption_span(window_bytes)
        else {
            return Ok(K0PooledFiniteConsumptionSpanRoute::Unattempted);
        };

        // Once this invocation owns the optional route, let the retained cut
        // arbitrate first even when its maximum distance is zero. A negative
        // cut completes the whole call without checking out or disturbing the
        // pooled workspace. A positive cut may publish only its authenticated
        // candidate floor; the finite suffix revalidates that bound below.
        let mut incumbent_search_start = window.start();
        if let Some(cut) = self.mandatory_cut.as_ref()
            && k0_negative_prefilter_admitted(
                Some(cut),
                None,
                haystack.len(),
                window,
                limits,
            )
        {
            match cut.first_member(&haystack[window.start()..window.end()]) {
                None => {
                    drop(admission);
                    return Ok(K0PooledFiniteConsumptionSpanRoute::Complete(None));
                }
                Some(first_member) => {
                    if let Some(floor) = cut.candidate_floor(window.start(), first_member) {
                        incumbent_search_start = floor;
                    }
                }
            }
        }
        #[cfg(test)]
        finite_consumption_span_facade_probe::record_attempt();
        let mut incumbent_candidate_floor =
            (incumbent_search_start != window.start()).then_some(incumbent_search_start);
        if incumbent_candidate_floor.is_none() {
            // The exact route deliberately declines when its first suffix is
            // within the incumbent's short forward prefix. Probe only that
            // bounded prefix before checking out reverse workspace: a known
            // losing source must not dirty and replace the pooled session.
            // When the prefix contains no suffix, its mandatory-literal proof
            // also publishes the earliest possible match-start floor. The
            // exact route resumes with only the maximum-width overlap, so the
            // probe does not add another whole-window literal pass.
            let suffix_search_start = window
                .start()
                .saturating_add(minimum_match_bytes - suffix.needle().len())
                .min(window.end());
            let probe_end = window
                .start()
                .saturating_add(K0_SUFFIX_FORWARD_FALLBACK_BYTES)
                .min(window.end());
            let early_suffix = if suffix_search_start < probe_end {
                suffix.find_window(haystack, suffix_search_start, probe_end)
            } else {
                Ok(None)
            };
            match early_suffix {
                Ok(Some((suffix_start, _))) => {
                    #[cfg(test)]
                    finite_consumption_span_facade_probe::record_result(false);
                    admission.observe_finite_early_prefix(
                        window_bytes,
                        suffix_start.saturating_sub(window.start()),
                    );
                    return Ok(K0PooledFiniteConsumptionSpanRoute::Fallback(window));
                }
                Err(_) => {
                    #[cfg(test)]
                    finite_consumption_span_facade_probe::record_result(false);
                    admission.observe_loss();
                    return Ok(K0PooledFiniteConsumptionSpanRoute::Fallback(window));
                }
                Ok(None) if probe_end == window.end() => {
                    #[cfg(test)]
                    finite_consumption_span_facade_probe::record_result(true);
                    drop(admission);
                    return Ok(K0PooledFiniteConsumptionSpanRoute::Complete(None));
                }
                Ok(None) => {
                    let floor = probe_end
                        .saturating_add(1)
                        .saturating_sub(maximum_match_bytes)
                        .max(window.start());
                    if floor > incumbent_search_start {
                        incumbent_search_start = floor;
                        incumbent_candidate_floor = Some(floor);
                    }
                }
            }
        }
        let route = self.pooled_finite_consumption_suffix_span(
            suffix,
            minimum_match_bytes,
            maximum_match_bytes,
            admission,
            haystack,
            window,
            incumbent_candidate_floor,
            limits,
            workspace_limits,
        )?;
        #[cfg(test)]
        finite_consumption_span_facade_probe::record_result(matches!(
            route,
            K0PooledSpanRoute::Complete(_)
        ));
        Ok(match route {
            K0PooledSpanRoute::Complete(output) => {
                K0PooledFiniteConsumptionSpanRoute::Complete(output)
            }
            K0PooledSpanRoute::Declined => K0PooledFiniteConsumptionSpanRoute::Fallback(
                SearchWindow::new(incumbent_search_start, window.end()),
            ),
        })
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the pooled finite proof carries its authenticated bounds, incumbent floor, and workspace contract"
    )]
    #[inline(never)]
    fn pooled_finite_consumption_suffix_span(
        &self,
        suffix: &K0MandatorySuffixPlan,
        minimum_match_bytes: usize,
        maximum_match_bytes: usize,
        admission: K0ReverseSuffixSpanAdmission<'_>,
        haystack: &[u8],
        window: SearchWindow,
        incumbent_candidate_floor: Option<usize>,
        limits: SearchLimits,
        workspace_limits: SearchSessionLimits,
    ) -> Result<K0PooledSpanRoute, K0SearchError> {
        if limits != SearchLimits::unlimited()
            || workspace_limits != SearchSessionLimits::unlimited()
            || minimum_match_bytes == 0
            || minimum_match_bytes > maximum_match_bytes
            || suffix.needle().len() > minimum_match_bytes
            || window.start() > window.end()
            || window.end() > haystack.len()
            || incumbent_candidate_floor
                .is_some_and(|floor| !(window.start()..=window.end()).contains(&floor))
        {
            admission.observe_loss();
            return Ok(K0PooledSpanRoute::Declined);
        }
        let window_bytes = window.end().saturating_sub(window.start());
        if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
            || maximum_match_bytes
                > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
        {
            admission.observe_loss();
            return Ok(K0PooledSpanRoute::Declined);
        }

        let mut session = match self.automaton.try_checkout_pooled_search_session(
            workspace_limits,
            true,
            true,
        ) {
            Ok(Some(session)) => session,
            Ok(None) => {
                admission.observe_loss();
                return Ok(K0PooledSpanRoute::Declined);
            }
            Err(error) => {
                admission.observe_loss();
                return Err(error);
            }
        };
        let mut direct_state = K0NegativePrefilterState::default();
        let window_size_class = usize::BITS - window_bytes.leading_zeros();
        let class_index = direct_state.class_for(window_size_class);
        direct_state.classes[class_index].next_predicate = K0_FINITE_SUFFIX_EXACT_ROUTE;
        let attempt = match try_k0_finite_mandatory_suffix_span_start(
            &mut session,
            suffix,
            minimum_match_bytes,
            maximum_match_bytes,
            direct_state,
            haystack,
            window,
            limits,
            incumbent_candidate_floor,
        ) {
            Ok(attempt) => attempt,
            Err(SearchError::K0(error)) => {
                admission.observe_loss();
                return Err(error);
            }
            Err(_) => {
                admission.observe_loss();
                return Err(K0SearchError::InternalInvariant {
                    detail: "pooled finite mandatory-suffix proof escaped the K0 error domain",
                });
            }
        };
        let learned_loss = attempt.state_after_success.classes[class_index].next_predicate
            & K0_FINITE_SUFFIX_BACKOFF_ROUTE
            != 0;
        let (route, transient_loss) = match attempt.outcome {
            K0MandatorySuffixSpanOutcome::Absent
            | K0MandatorySuffixSpanOutcome::ProvedAbsent => {
                (K0PooledSpanRoute::Complete(None), learned_loss)
            }
            K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => (
                K0PooledSpanRoute::Complete(Some(fre_automata::MatchSpan::new(start, end))),
                learned_loss,
            ),
            K0MandatorySuffixSpanOutcome::ProvedStart {
                start,
                maximum_match_bytes,
            } => {
                let (output, exact_receipt) = match replay_k0_finite_proved_start_with_exact_receipt(
                    &mut session,
                    haystack,
                    window,
                    limits,
                    start,
                    maximum_match_bytes,
                ) {
                    Ok(result) => result,
                    Err(SearchError::K0(error)) => {
                        admission.observe_loss();
                        return Err(error);
                    }
                    Err(_) => {
                        admission.observe_loss();
                        return Err(K0SearchError::InternalInvariant {
                            detail: "pooled finite selected-end replay escaped the K0 error domain",
                        });
                    }
                };
                (
                    K0PooledSpanRoute::Complete(output.map(|matched| {
                        fre_automata::MatchSpan::new(matched.start, matched.end)
                    })),
                    learned_loss || !exact_receipt,
                )
            }
            K0MandatorySuffixSpanOutcome::Bypass
            | K0MandatorySuffixSpanOutcome::GeometryBypass
            | K0MandatorySuffixSpanOutcome::Incumbent { .. }
            | K0MandatorySuffixSpanOutcome::Fallback
            | K0MandatorySuffixSpanOutcome::Narrowed(_)
            | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. } => {
                (K0PooledSpanRoute::Declined, true)
            }
        };
        if transient_loss {
            admission.observe_loss();
        } else {
            drop(admission);
        }
        if transient_loss {
            self.automaton.refresh_pooled_search_session(
                session,
                workspace_limits,
                true,
                true,
            )?;
        } else {
            self.automaton.return_pooled_search_session(session)?;
        }
        Ok(route)
    }

    /// Attempt an ordinary full-window absolute-end query through the
    /// populated owner without moving its workspace. A cold or incompatible
    /// owner returns `None` so the incumbent pooled path remains authoritative.
    #[inline(never)]
    fn warm_absolute_end_ordinary_exists(
        &self,
        haystack: &[u8],
        maximum_match_bytes: Option<usize>,
    ) -> Result<Option<bool>, K0SearchError> {
        let window = SearchWindow::full(haystack);
        #[cfg(test)]
        absolute_end_warm_owner_facade_probe::record_exists_attempt();
        let attempted = self
            .automaton
            .search_window_with_warm_owner_positive_end_exists_value(
                haystack,
                window,
                maximum_match_bytes,
            )?;
        #[cfg(test)]
        if attempted.is_some() {
            absolute_end_warm_owner_facade_probe::record_exists_completion();
        }
        Ok(attempted)
    }

    /// Attempt the matching ordinary Span projection through the same
    /// in-place warm owner. The exact verifier remains the sole start owner.
    #[inline(never)]
    fn warm_absolute_end_ordinary_span(
        &self,
        haystack: &[u8],
        maximum_match_bytes: Option<usize>,
    ) -> Result<Option<Option<fre_automata::MatchSpan>>, K0SearchError> {
        let window = SearchWindow::full(haystack);
        #[cfg(test)]
        absolute_end_warm_owner_facade_probe::record_span_attempt();
        let attempted = self
            .automaton
            .search_window_with_warm_owner_positive_end_span_value(
                haystack,
                window,
                maximum_match_bytes,
            )?;
        #[cfg(test)]
        if attempted.is_some() {
            absolute_end_warm_owner_facade_probe::record_span_completion();
        }
        Ok(attempted)
    }

    fn pooled_value(
        &self,
        operation: K0PooledValueOperation,
        execution: K0PooledValueExecution,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
        workspace_limits: SearchSessionLimits,
        minimum_match_bytes: Option<usize>,
    ) -> Result<Option<K0PooledValue>, K0SearchError> {
        debug_assert!(
            matches!(execution, K0PooledValueExecution::Canonical)
                || matches!(
                    (operation, execution),
                    (
                        K0PooledValueOperation::Exists,
                        K0PooledValueExecution::OrdinaryExists,
                    ) | (
                        K0PooledValueOperation::Span,
                        K0PooledValueExecution::OrdinarySpan,
                    )
                ) && limits == SearchLimits::unlimited()
                    && workspace_limits == SearchSessionLimits::unlimited(),
            "the unmetered K0 policies are reserved for ordinary is_match and find",
        );
        // Both finite value calls and the Rust-style ordinary facade
        // automatically own reusable K0 scratch. Work-unlimited calls may
        // additionally consume the optional proof shortcuts below; default
        // finite calls go straight to the generic pooled executor so their
        // checked envelope stays exact. `workspace_limits` is independent:
        // finite calls retain their explicit default quota, while ordinary
        // calls admit the fixed plan-derived layout without a per-call quota.
        if limits == SearchLimits::default() {
            return self.pooled_workspace_value(
                operation,
                execution,
                haystack,
                window,
                limits,
                workspace_limits,
                minimum_match_bytes,
            );
        }
        if limits != SearchLimits::unlimited()
            || window.start() > window.end()
            || window.end() > haystack.len()
        {
            return Ok(None);
        }

        if let Some(proof) = self.absolute_end_proof {
            if window.start() == window.end() || window.end() < haystack.len() {
                return Ok(Some(match operation {
                    K0PooledValueOperation::Exists => K0PooledValue::Exists(false),
                    K0PooledValueOperation::Span => K0PooledValue::Span(None),
                }));
            }
            if window.start() == 0 && window.end() == haystack.len() {
                let attempted = match (operation, execution) {
                    (
                        K0PooledValueOperation::Exists,
                        K0PooledValueExecution::OrdinaryExists,
                    ) => self
                        .warm_absolute_end_ordinary_exists(
                            haystack,
                            proof.maximum_match_bytes(),
                        )?
                        .map(K0PooledValue::Exists),
                    (
                        K0PooledValueOperation::Span,
                        K0PooledValueExecution::OrdinarySpan,
                    ) => self
                        .warm_absolute_end_ordinary_span(
                            haystack,
                            proof.maximum_match_bytes(),
                        )?
                        .map(K0PooledValue::Span),
                    _ => None,
                };
                if attempted.is_some() {
                    return Ok(attempted);
                }
            }
            let attempted = match operation {
                K0PooledValueOperation::Exists => self
                    .automaton
                    .search_window_with_optional_pooled_positive_end_exists_value(
                        haystack,
                        window,
                        limits,
                        workspace_limits,
                        proof.maximum_match_bytes(),
                    )
                    .map(|value| value.map(K0PooledValue::Exists)),
                K0PooledValueOperation::Span => self
                    .automaton
                    .search_window_with_optional_pooled_positive_end_span_value(
                        haystack,
                        window,
                        limits,
                        workspace_limits,
                        proof.maximum_match_bytes(),
                    )
                    .map(|value| value.map(K0PooledValue::Span)),
            }?;
            if attempted.is_some() {
                return Ok(attempted);
            }
        }

        // Keep the Drop-bearing adaptive admission and its reverse workspace
        // entirely inside the outlined finite facade. The shared pooled caller
        // retains only this immutable geometry check, so unrelated K0 Span and
        // every Exists path preserve their incumbent frame and cleanup graph.
        if matches!(
            (operation, execution),
            (
                K0PooledValueOperation::Span,
                K0PooledValueExecution::OrdinarySpan,
            )
        ) && self.absolute_end_proof.is_none()
            && !self.automaton.stats().has_assertions()
            && let Some(minimum_match_bytes) = minimum_match_bytes.filter(|minimum| *minimum != 0)
            && let Some(suffix) = self.mandatory_suffix.as_ref()
            && let Some(maximum_match_bytes) =
                suffix.pooled_finite_consumption_span_maximum_match_bytes()
            && window.end().saturating_sub(window.start())
                >= K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
            && maximum_match_bytes
                <= window.end().saturating_sub(window.start())
                    / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
            && !suffix.pooled_finite_consumption_span_should_bypass_early(haystack, window)
        {
            match self.pooled_finite_consumption_suffix_span_route(
                suffix,
                minimum_match_bytes,
                maximum_match_bytes,
                haystack,
                window,
                limits,
                workspace_limits,
            )? {
                K0PooledFiniteConsumptionSpanRoute::Unattempted => {}
                K0PooledFiniteConsumptionSpanRoute::Complete(output) => {
                    return Ok(Some(K0PooledValue::Span(output)));
                }
                K0PooledFiniteConsumptionSpanRoute::Fallback(search_window) => {
                    return self.pooled_workspace_value(
                        operation,
                        execution,
                        haystack,
                        search_window,
                        limits,
                        workspace_limits,
                        Some(minimum_match_bytes),
                    );
                }
            }
        }

        // Rust regex's meta engine runs a rare mandatory byte set before its
        // lazy DFA. K0 already derives the stronger graph-dominator proof for
        // explicit sessions; ordinary value-only calls can consume its
        // immutable part without retaining any source cursor or adaptive
        // policy. Absence is a complete language proof. Presence can publish
        // a sound lower bound on every possible match start, so exact K0 may
        // begin at that floor while keeping assertion context in the original
        // haystack. The existing minimum window keeps the extra pass out of
        // short/cold calls.
        let mut search_window = window;
        let mut suffix_search_start = window.start();
        let window_bytes = window.end().saturating_sub(window.start());
        let exact_minimum_suffix = if matches!(operation, K0PooledValueOperation::Exists)
            && workspace_limits == SearchSessionLimits::unlimited()
            && window.start() == 0
            && window.end() == haystack.len()
            && window_bytes >= K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
            && !self.automaton.stats().has_assertions()
            && let Some(suffix) = self
                .mandatory_suffix
                .as_ref()
                .filter(|suffix| !suffix.has_short_standalone_reverse_suffix_span())
            && minimum_match_bytes == Some(suffix.needle().len())
            && self
                .automaton
                .has_compatible_warm_pooled_ordinary_exists_owner()
        {
            Some(suffix)
        } else {
            None
        };
        // Optional suffix routes are lower-priority than the actual pooled cut
        // execution. Require that cut and a claimed route before changing the
        // ordinary zero-distance-cut dispatch. Immutable negative metadata has
        // no pooled executor and therefore is not an incumbent source pass.
        // Cooldown, in-flight ownership, and targets without one-word atomic
        // admission leave the established path byte-for-byte unchanged.
        let mut short_reverse_admission = if matches!(operation, K0PooledValueOperation::Span)
            && self.absolute_end_proof.is_none()
            && self.mandatory_cut.is_some()
        {
            self.mandatory_suffix
                .as_ref()
                .filter(|suffix| suffix.has_short_standalone_reverse_suffix_span())
                .and_then(|suffix| suffix.try_admit_reverse_suffix_span(window_bytes))
        } else {
            None
        };
        let short_reverse_span_needs_cut = short_reverse_admission.is_some();
        let exact_minimum_suffix_needs_cut = exact_minimum_suffix.is_some();
        if let Some(cut) = self.mandatory_cut.as_ref()
            // A zero-distance cut is the ordinary K0 start predicate. Running
            // the same scanner twice normally adds traffic without proving a
            // stronger floor. An admitted suffix route is the exception: let
            // the actual retained start predicate arbitrate first so an absent
            // prefix never pays a suffix pass.
            && (cut.maximum_before_root() != MaximumConsumedDistance::Finite(0)
                || short_reverse_span_needs_cut
                || exact_minimum_suffix_needs_cut)
            && k0_negative_prefilter_admitted(
                Some(cut),
                None,
                haystack.len(),
                window,
                limits,
            )
        {
            match cut.first_member(&haystack[window.start()..window.end()]) {
                None => {
                    return Ok(Some(match operation {
                        K0PooledValueOperation::Exists => K0PooledValue::Exists(false),
                        K0PooledValueOperation::Span => K0PooledValue::Span(None),
                    }));
                }
                Some(first_member) => {
                    if let Some(floor) = cut.candidate_floor(window.start(), first_member) {
                        search_window = SearchWindow::new(floor, window.end());
                    }
                    // Every match consumes a cut member no later than its
                    // terminal suffix. Its first source occurrence therefore
                    // proves a conservative suffix-candidate floor, adjusted
                    // backward when the class also occurs inside the suffix.
                    // The cut proof makes the narrowed ordinary-K0 start an
                    // equally sound lower bound for reverse verification.
                    // Avoid rescanning the independently proved prefix for
                    // suffix occurrences as well.
                    if matches!(operation, K0PooledValueOperation::Span)
                        && self.absolute_end_proof.is_none()
                        && let Some(suffix) = self.mandatory_suffix.as_ref()
                        && (!suffix.has_short_standalone_reverse_suffix_span()
                            || short_reverse_admission.is_some())
                        && suffix.reverse_suffix_span_is_eligible(window_bytes)
                    {
                        suffix_search_start = cut
                            .mandatory_suffix_candidate_floor(
                                window.start(),
                                first_member,
                                suffix.needle(),
                            )
                            .ok_or(K0SearchError::ArithmeticOverflow {
                                computation: "post-cut reverse-suffix search start",
                            })?;
                    }
                }
            }
        }

        // The retained cut owns first refusal. Only after it admits the source
        // may a warm ordinary Exists call consume an exact minimum suffix.
        if let Some(suffix) = exact_minimum_suffix {
            if let Some(found) =
                try_k0_warm_exact_minimum_suffix_exists(suffix, haystack, search_window)
            {
                return Ok(Some(K0PooledValue::Exists(found)));
            }
            #[cfg(test)]
            k0_exact_minimum_suffix_exists_probe::record_pooled_fallback();
        }

        if matches!(operation, K0PooledValueOperation::Span)
            && self.absolute_end_proof.is_none()
            && let Some(suffix) = self
                .mandatory_suffix
                .as_ref()
                .filter(|suffix| {
                    (!suffix.has_short_standalone_reverse_suffix_span()
                        || short_reverse_admission.is_some())
                        && suffix.reverse_suffix_span_is_eligible(window_bytes)
                })
        {
            // The cut theorem authenticates the prefix before
            // `search_window.start()`; the reverse theorem is bound to the
            // residual range at or above that immutable incumbent floor. If
            // its private performance envelope declines, ordinary K0 may
            // still consume the same independently proved lower bound.
            match self.pooled_reverse_suffix_span(
                suffix,
                short_reverse_admission.take(),
                haystack,
                window,
                search_window.start(),
                suffix_search_start,
                limits,
                workspace_limits,
            )? {
                K0PooledSpanRoute::Complete(output) => {
                    return Ok(Some(K0PooledValue::Span(output)));
                }
                K0PooledSpanRoute::Declined => {}
            }
        }

        // Contextual value projection remains behind every incumbent
        // absolute-end, cut, and suffix decision above. It sees the same
        // possibly narrowed K0 window together with the full haystack
        // assertion context. Static or owner decline falls through to the
        // incumbent pool; after checkout, a cache hole replays canonically
        // under that same owner and therefore cannot escape as `None` here.
        let contextual_window_bytes = search_window
            .end()
            .saturating_sub(search_window.start());
        let positive = matches!(minimum_match_bytes, Some(minimum) if minimum > 0);
        if matches!(operation, K0PooledValueOperation::Exists)
            && matches!(execution, K0PooledValueExecution::OrdinaryExists)
            && positive
            && self.automaton.stats().has_assertions()
            && (PREPARED_CONTEXTUAL_ORDINARY_VALUE_MIN_WINDOW_BYTES
                ..PREPARED_CONTEXTUAL_ORDINARY_VALUE_MAX_WINDOW_BYTES)
                .contains(&contextual_window_bytes)
        {
            #[cfg(test)]
            contextual_v4_facade_probe::record_attempt();
            if let Some(value) = self
                .automaton
                .search_window_with_warm_owner_contextual_ordinary_exists_value(
                    haystack,
                    search_window,
                )?
            {
                #[cfg(test)]
                if matches!(
                    value.completion(),
                    fre_automata::K0OrderedResumeCompletion::FullyWarmRows,
                ) {
                    contextual_v4_facade_probe::record_completion();
                }
                return Ok(Some(K0PooledValue::Exists(value.into_output())));
            }
        }
        if matches!(operation, K0PooledValueOperation::Span)
            && self.contextual_ordinary_span_projection_eligible(
                execution,
                positive,
                contextual_window_bytes,
            )
        {
            #[cfg(test)]
            contextual_span_v1_facade_probe::record_attempt();
            if let Some(value) = self
                .automaton
                .search_window_with_warm_owner_contextual_ordinary_span_value(
                    haystack,
                    search_window,
                )?
            {
                #[cfg(test)]
                if matches!(
                    value.completion(),
                    fre_automata::K0OrderedResumeCompletion::FullyWarmRows,
                ) {
                    contextual_span_v1_facade_probe::record_completion();
                }
                return Ok(Some(K0PooledValue::Span(value.into_output())));
            }
        }

        self.pooled_workspace_value(
            operation,
            execution,
            haystack,
            search_window,
            limits,
            workspace_limits,
            minimum_match_bytes,
        )
    }

    fn pooled_workspace_value(
        &self,
        operation: K0PooledValueOperation,
        execution: K0PooledValueExecution,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
        workspace_limits: SearchSessionLimits,
        minimum_match_bytes: Option<usize>,
    ) -> Result<Option<K0PooledValue>, K0SearchError> {
        if window.start() > window.end() || window.end() > haystack.len() {
            return Ok(None);
        }
        let positive = matches!(minimum_match_bytes, Some(minimum) if minimum > 0);
        let assertion_free_nullable =
            minimum_match_bytes == Some(0) && !self.automaton.stats().has_assertions();
        let endpoint_eligible = positive || assertion_free_nullable;
        let window_bytes = window.end().saturating_sub(window.start());
        let prepared_ordinary_exists_eligible = if window_bytes
            >= PREPARED_ORDINARY_EXISTS_MIN_WINDOW_BYTES
        {
            matches!(execution, K0PooledValueExecution::OrdinaryExists)
                && positive
                && !self.automaton.stats().has_assertions()
                && window.end().saturating_sub(window.start())
                    >= PREPARED_ORDINARY_EXISTS_MIN_WINDOW_BYTES
                && self
                    .automaton
                    .can_use_pooled_ordinary_exists_projection()
        } else {
            window_bytes >= PREPARED_COMPACT_ORDINARY_EXISTS_MIN_WINDOW_BYTES
                && matches!(execution, K0PooledValueExecution::OrdinaryExists)
                && positive
                && !self.automaton.stats().has_assertions()
                && self
                    .automaton
                    .can_use_pooled_compact_ordinary_exists_projection()
        };
        #[cfg(test)]
        if matches!(operation, K0PooledValueOperation::Exists)
            && matches!(execution, K0PooledValueExecution::OrdinaryExists)
        {
            k0_ordinary_exists_route_probe::record(prepared_ordinary_exists_eligible);
        }
        // Existence needs only the forward endpoint cache. If a later Span
        // call needs reverse recovery, the automaton-owned pool constructs a
        // complete bidirectional replacement while retaining this workspace,
        // then publishes the stronger workspace only after successful execution.
        match (operation, execution) {
            (
                K0PooledValueOperation::Exists,
                K0PooledValueExecution::OrdinaryExists,
            ) if prepared_ordinary_exists_eligible => self
                .automaton
                .search_window_with_optional_pooled_ordinary_exists_value(
                    haystack,
                    window,
                    workspace_limits,
                    endpoint_eligible,
                    false,
                )
                .map(|value| value.map(K0PooledValue::Exists)),
            (K0PooledValueOperation::Exists, _) => self
                .automaton
                .search_window_with_optional_pooled_exists_value(
                    haystack,
                    window,
                    limits,
                    workspace_limits,
                    endpoint_eligible,
                    false,
                )
                .map(|value| value.map(K0PooledValue::Exists)),
            (K0PooledValueOperation::Span, _) => self
                .automaton
                .search_window_with_optional_pooled_span_value(
                    haystack,
                    window,
                    limits,
                    workspace_limits,
                    endpoint_eligible,
                    positive,
                )
                .map(|value| value.map(K0PooledValue::Span)),
        }
    }

    #[cfg(test)]
    fn contextual_ordinary_exists_projection_eligible(
        &self,
        execution: K0PooledValueExecution,
        positive: bool,
        window_bytes: usize,
    ) -> bool {
        matches!(execution, K0PooledValueExecution::OrdinaryExists)
            && positive
            && self.automaton.stats().has_assertions()
            && (PREPARED_CONTEXTUAL_ORDINARY_VALUE_MIN_WINDOW_BYTES
                ..PREPARED_CONTEXTUAL_ORDINARY_VALUE_MAX_WINDOW_BYTES)
                .contains(&window_bytes)
            && self
                .automaton
                .can_use_pooled_contextual_ordinary_exists_projection()
    }

    fn contextual_ordinary_span_projection_eligible(
        &self,
        execution: K0PooledValueExecution,
        positive: bool,
        window_bytes: usize,
    ) -> bool {
        matches!(execution, K0PooledValueExecution::OrdinarySpan)
            && positive
            && self.automaton.stats().has_assertions()
            && (PREPARED_CONTEXTUAL_ORDINARY_VALUE_MIN_WINDOW_BYTES
                ..PREPARED_CONTEXTUAL_ORDINARY_VALUE_MAX_WINDOW_BYTES)
                .contains(&window_bytes)
            && self
                .automaton
                .can_use_pooled_contextual_ordinary_span_projection()
    }

    fn pooled_earliest_end_value(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
        workspace_limits: SearchSessionLimits,
        minimum_match_bytes: Option<usize>,
    ) -> Result<Option<Option<usize>>, K0SearchError> {
        if window.start() > window.end() || window.end() > haystack.len() {
            return Ok(None);
        }
        let positive = matches!(minimum_match_bytes, Some(minimum) if minimum > 0);
        let assertion_free_nullable =
            minimum_match_bytes == Some(0) && !self.automaton.stats().has_assertions();
        self.automaton
            .search_window_with_optional_pooled_earliest_end_value(
                haystack,
                window,
                limits,
                workspace_limits,
                positive || assertion_free_nullable,
            )
    }
}

struct PortableLiteralSetDfaPlan {
    canonical: LiteralSetPlan,
    ordinary_ascii_folded: Option<Box<ascii_folded_literal_alternation::OrdinaryPlan>>,
}

impl PortableLiteralSetDfaPlan {
    const fn canonical(canonical: LiteralSetPlan) -> Self {
        Self {
            canonical,
            ordinary_ascii_folded: None,
        }
    }

    const fn with_ordinary_ascii_folded(
        canonical: LiteralSetPlan,
        ordinary_ascii_folded: Option<Box<ascii_folded_literal_alternation::OrdinaryPlan>>,
    ) -> Self {
        Self {
            canonical,
            ordinary_ascii_folded,
        }
    }

    #[inline]
    fn ordinary_ascii_folded(
        &self,
    ) -> Option<&ascii_folded_literal_alternation::OrdinaryPlan> {
        self.ordinary_ascii_folded.as_deref()
    }

    #[inline]
    fn ordinary_ascii_folded_for_input(
        &self,
        input_bytes: usize,
    ) -> Option<&ascii_folded_literal_alternation::OrdinaryPlan> {
        if !ascii_folded_literal_alternation::OrdinaryPlan::supports_full_input(input_bytes) {
            return None;
        }
        self.ordinary_ascii_folded()
    }
}

impl core::ops::Deref for PortableLiteralSetDfaPlan {
    type Target = LiteralSetPlan;

    fn deref(&self) -> &Self::Target {
        &self.canonical
    }
}

impl From<LiteralSetPlan> for PortableLiteralSetDfaPlan {
    fn from(canonical: LiteralSetPlan) -> Self {
        Self::canonical(canonical)
    }
}

enum PortablePlan {
    ExactLiteral(LiteralPlan),
    PackedLiteralSet(PackedLiteralSetPlan),
    LiteralSetDfa(PortableLiteralSetDfaPlan),
    RequiredLiteral(RequiredLiteralPlan),
    DispatchedRequiredLiteral(DispatchedRequiredLiteralPlan),
    BoundedRequiredLiteral(BoundedRequiredLiteralPlan),
    DispatchedBoundedRequiredLiteral(DispatchedBoundedRequiredLiteralPlan),
    LiteralClassRunLiteral(LiteralClassRunLiteralPlan),
    LiteralClassRunSearch(LiteralClassRunSearchPlan),
    PureByteClassRepeat(pure_byte_class_repeat::Plan),
    ForwardAnchored(ForwardAnchoredPlan),
    DispatchedForwardAnchored(DispatchedForwardAnchoredPlan),
    ForwardEndFixed(AbsoluteEndFixedPlan),
    K0(PortableK0Plan),
    UnicodeFoldedLiteral(Box<unicode_folded_literal::UnicodeFoldedLiteralSearchPlan>),
    UnicodeWordRun(unicode_word_run::Plan),
    AsciiWordRun(unicode_word_run::AsciiPlan),
    BoundedWordClass(bounded_word_class::Plan),
    // Append new runtime classes so existing implicit discriminants, including
    // K0's, remain unchanged for code-layout containment.
    BoundedByteClassRepeat(bounded_byte_class_repeat::Plan),
    FixedPredicateWord64(Box<FixedPredicateWord64Plan>),
    BoundedByteClassSequence(bounded_byte_class_sequence::Plan),
    GuardedLiteralSet(guarded_literal_set::Plan),
    NullableOptionalChain(Box<nullable_optional_chain::Plan>),
    NullableFiniteTokenRepeat(Box<nullable_finite_token_repeat::Plan>),
    BoundedLiteralClassRun(Box<BoundedLiteralClassRunPlan>),
    ReverseInner(ReverseInnerPlan),
    PrefixClassAlternation(PrefixClassAlternationPlan),
    DispatchedPrefixClassAlternation(DispatchedPrefixClassAlternationPlan),
    UniversalFiniteGreedyCorridor(Box<universal_finite_greedy_corridor::Plan>),
    BoundedDelimitedSegmentRepeat(
        Box<universal_finite_greedy_corridor::BoundedDelimitedSegmentPlan>,
    ),
    UnicodeScalarRun(Box<UnicodeScalarSearchPlan>),
    LineDomainByteAtoms(Box<line_domain_byte_atoms::OwnedPlan>),
    /// Append the authenticated compact owner so every established runtime
    /// plan discriminant and dense literal-set layout remains unchanged.
    LiteralSetCompact(Box<LiteralSetCompactPlan>),
}

impl PortablePlan {
    const fn runtime_implementation_id(&self) -> &'static str {
        match self {
            Self::ExactLiteral(_) => "exact-literal",
            Self::PackedLiteralSet(plan) => plan.runtime_implementation_id(),
            Self::LiteralSetDfa(_) => "literal-set-dfa",
            Self::RequiredLiteral(required) => required.plan_id(),
            Self::DispatchedRequiredLiteral(required) => required.plan_id(),
            Self::BoundedRequiredLiteral(required) => required.plan_id(),
            Self::DispatchedBoundedRequiredLiteral(required) => required.plan_id(),
            Self::LiteralClassRunLiteral(_) => fre_kernels::LITERAL_CLASS_RUN_LITERAL_PLAN_ID,
            Self::LiteralClassRunSearch(plan) => plan.plan_id(),
            Self::BoundedLiteralClassRun(plan) => plan.plan_id(),
            Self::PureByteClassRepeat(_) => pure_byte_class_repeat::PLAN_ID,
            Self::BoundedByteClassRepeat(_) => bounded_byte_class_repeat::PLAN_ID,
            Self::ForwardAnchored(forward) => forward.plan_id(),
            Self::DispatchedForwardAnchored(forward) => forward.plan_id(),
            Self::ForwardEndFixed(fixed) => fixed.plan_id(),
            Self::K0(_) => "k0",
            Self::UnicodeFoldedLiteral(plan) => plan.plan_id(),
            Self::UnicodeWordRun(plan) => plan.plan_id(),
            Self::AsciiWordRun(_) => unicode_word_run::ASCII_PLAN_ID,
            Self::BoundedWordClass(plan) => plan.plan_id(),
            Self::FixedPredicateWord64(_) => FIXED_PREDICATE_WORD64_SEARCH_PLAN_ID,
            Self::BoundedByteClassSequence(_) => bounded_byte_class_sequence::PLAN_ID,
            Self::GuardedLiteralSet(plan) => plan.plan_id(),
            Self::NullableOptionalChain(_) => nullable_optional_chain::PLAN_ID,
            Self::NullableFiniteTokenRepeat(_) => nullable_finite_token_repeat::PLAN_ID,
            Self::ReverseInner(plan) => plan.plan_id(),
            Self::PrefixClassAlternation(_) => PREFIX_CLASS_ALTERNATION_PLAN_ID,
            Self::DispatchedPrefixClassAlternation(plan) => plan.search_identity().plan_id,
            Self::UniversalFiniteGreedyCorridor(plan) => plan.plan_id(),
            Self::BoundedDelimitedSegmentRepeat(plan) => plan.plan_id(),
            Self::UnicodeScalarRun(_) => UNICODE_SCALAR_RUN_SEARCH_PLAN_ID,
            Self::LineDomainByteAtoms(_) => fre_kernels::LINE_DOMAIN_BYTE_ATOMS_PLAN_ID,
            Self::LiteralSetCompact(plan) => plan.runtime_implementation_id(),
        }
    }
}

impl PortableRegex {
    /// Construct with pinned Rust-bytes defaults and default resource limits.
    ///
    /// # Errors
    ///
    /// Returns [`BuildError`] under the same conditions as
    /// [`PortableBuilder::build`].
    pub fn new(pattern: impl Into<String>) -> Result<Self, BuildError> {
        PortableBuilder::new(pattern).build()
    }

    /// Return the original pattern source exactly as supplied at construction.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.source
    }

    /// Iterate over every capture slot's optional name in capture-index order.
    ///
    /// This metadata is retained before capture-erasing execution planning,
    /// so it remains identical across every portable plan family.
    #[must_use]
    pub fn capture_names(&self) -> PortableCaptureNames<'_> {
        PortableCaptureNames {
            names: self.capture_names.iter(),
        }
    }

    /// Return the number of capture slots, including the implicit unnamed
    /// slot for the overall match.
    ///
    /// This metadata is preserved before capture-erasing execution planning,
    /// so it is identical for every selected portable plan family.
    #[must_use]
    pub const fn captures_len(&self) -> usize {
        self.report.captures_len
    }

    /// Return the number of capture slots that participate in every possible
    /// match, including the implicit whole-match slot.
    ///
    /// `None` means that capture participation cardinality can vary across
    /// alternatives or repetitions. This is construction metadata and does
    /// not execute a search.
    #[must_use]
    pub const fn static_captures_len(&self) -> Option<usize> {
        self.report.static_captures_len
    }

    /// Allocate fresh reusable locations for every capture slot.
    ///
    /// The returned buffer has the same fixed cardinality as
    /// [`Self::captures_len`] and initially contains no matched offsets.
    #[must_use]
    pub fn capture_locations(&self) -> PortableCaptureLocations {
        PortableCaptureLocations {
            slots: vec![None; self.captures_len()].into_boxed_slice(),
        }
    }

    /// Compatibility alias mirroring the pinned bytes API's legacy method.
    #[doc(hidden)]
    #[must_use]
    pub fn locations(&self) -> PortableCaptureLocations {
        self.capture_locations()
    }

    /// Search and populate reusable locations for a capture-free regex.
    ///
    /// This is the admitted group-zero slice of the pinned Rust bytes
    /// `captures_read` contract. The buffer is cleared before every attempt,
    /// including typed refusals, and a successful match stores its offsets in
    /// slot zero. Patterns with explicit capture groups are refused until the
    /// portable facade has a capture-preserving executor for their offsets.
    ///
    /// # Errors
    ///
    /// Returns [`PortableCapturesReadError`] if `locations` belongs to a regex
    /// with different capture cardinality, explicit subgroups require an
    /// unavailable capability, or the selected search exceeds its limits.
    pub fn captures_read<'h>(
        &self,
        locations: &mut PortableCaptureLocations,
        haystack: &'h [u8],
        limits: SearchLimits,
    ) -> Result<(Option<ByteMatch<'h>>, SearchAccounting), PortableCapturesReadError> {
        locations.slots.fill(None);
        if locations.len() != self.captures_len() {
            return Err(PortableCapturesReadError::LocationCount {
                expected: self.captures_len(),
                actual: locations.len(),
            });
        }
        let explicit_captures = self.captures_len().saturating_sub(1);
        if explicit_captures != 0 {
            return Err(PortableCapturesReadError::ExplicitCapturesUnsupported {
                captures: explicit_captures,
            });
        }
        let (matched, accounting) = self.find_borrowed(haystack, limits)?;
        if let Some(matched) = matched {
            locations.slots[0] = Some((matched.start(), matched.end()));
        }
        Ok((matched, accounting))
    }

    /// Search and populate reusable group-zero locations without constructing
    /// facade diagnostic accounting on the success path.
    ///
    /// Location clearing, cardinality checks, capture-free admission, selected
    /// span and typed failures are identical to [`Self::captures_read`].
    ///
    /// # Errors
    ///
    /// Returns [`PortableCapturesReadError`] under the same contract as
    /// [`Self::captures_read`].
    pub fn captures_read_value<'h>(
        &self,
        locations: &mut PortableCaptureLocations,
        haystack: &'h [u8],
        limits: SearchLimits,
    ) -> Result<Option<ByteMatch<'h>>, PortableCapturesReadError> {
        locations.slots.fill(None);
        if locations.len() != self.captures_len() {
            return Err(PortableCapturesReadError::LocationCount {
                expected: self.captures_len(),
                actual: locations.len(),
            });
        }
        let explicit_captures = self.captures_len().saturating_sub(1);
        if explicit_captures != 0 {
            return Err(PortableCapturesReadError::ExplicitCapturesUnsupported {
                captures: explicit_captures,
            });
        }
        let matched = self.find_value(haystack, limits)?;
        if let Some(matched) = matched {
            locations.slots[0] = Some((matched.start(), matched.end()));
        }
        Ok(matched.map(|span| ByteMatch { haystack, span }))
    }

    /// The immutable compatibility profile used during parsing.
    #[must_use]
    pub const fn profile(&self) -> &CompatibilityProfile {
        &self.profile
    }

    /// Construction accounting and admission status.
    #[must_use]
    pub const fn build_report(&self) -> &BuildReport {
        &self.report
    }

    /// Maximum length among the construction-proved mandatory literals
    /// retained for reusable unlimited K0 value searches.
    ///
    /// `None` means either another runtime family was selected or the
    /// optional proof, resource, and regret gates declined the sidecar.
    /// Literals prove negative results directly. An exact graph-proved suffix
    /// may additionally propose endpoints, but every positive result is still
    /// authenticated by the original K0 reverse machine.
    #[must_use]
    pub fn k0_negative_prefilter_needle_bytes(&self) -> Option<usize> {
        match &self.plan {
            PortablePlan::K0(k0) => {
                let suffix = k0
                    .mandatory_suffix
                    .as_ref()
                    .map(|suffix| suffix.needle().len());
                let conjunctive = k0
                    .negative_prefilter
                    .as_deref()
                    .and_then(K0NegativePrefilterPlan::primary_needle_bytes);
                match (suffix, conjunctive) {
                    (Some(left), Some(right)) => Some(left.max(right)),
                    (Some(length), None) | (None, Some(length)) => Some(length),
                    (None, None) => None,
                }
            }
            _ => None,
        }
    }

    /// Number of independent mandatory literal sidecars retained for K0.
    ///
    /// This includes the exact graph-proved suffix, when present, plus every
    /// conjunctive negative-prefilter literal.
    #[must_use]
    pub fn k0_negative_prefilter_needle_count(&self) -> usize {
        match &self.plan {
            PortablePlan::K0(k0) => {
                usize::from(k0.mandatory_suffix.is_some())
                    + k0.negative_prefilter
                        .as_deref()
                        .map_or(0, |plan| plan.literals.len())
            }
            _ => 0,
        }
    }

    /// Complete admitted-only construction census for the Unicode
    /// folded-literal plan.
    ///
    /// The census is retained with that optional plan instead of enlarging
    /// every portable matcher and aggregate owner. Other plan families return
    /// `None`.
    #[must_use]
    pub fn unicode_folded_literal_build_accounting(
        &self,
    ) -> Option<UnicodeFoldedLiteralSearchBuildAccounting> {
        match &self.plan {
            PortablePlan::UnicodeFoldedLiteral(plan) => Some(plan.build_accounting()),
            _ => None,
        }
    }

    /// Complete construction accounting for the admitted two-prefix/class
    /// ordinary-search owner. Other plan families return `None`.
    #[must_use]
    pub fn prefix_class_alternation_build_accounting(
        &self,
    ) -> Option<PrefixClassAlternationBuildAccounting> {
        match &self.plan {
            PortablePlan::PrefixClassAlternation(plan) => Some(plan.build_accounting()),
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                Some(plan.build_accounting())
            }
            _ => None,
        }
    }

    /// Derive the folded plan's complete source-independent search envelope
    /// without touching a haystack.
    ///
    /// Other plan families return `Ok(None)`.
    ///
    /// # Errors
    ///
    /// Returns a checked arithmetic failure if `input_bytes` cannot be
    /// represented by the retained folded plan's envelope.
    pub fn unicode_folded_literal_search_upper_bounds(
        &self,
        input_bytes: usize,
    ) -> Result<
        Option<fre_kernels::FoldedLiteralTrieScanUpperBounds>,
        fre_kernels::FoldedLiteralTrieScanError,
    > {
        match &self.plan {
            PortablePlan::UnicodeFoldedLiteral(plan) => {
                plan.scan_upper_bounds(input_bytes).map(Some)
            }
            _ => Ok(None),
        }
    }

    /// Stable identity of the selected runtime implementation.
    ///
    /// This is intentionally obtained from the stored plan rather than
    /// reconstructed from [`PlanKind`]. For the required-literal and
    /// forward-anchored plans, it is the same strategy identity stored in
    /// their operation cache keys.
    #[must_use]
    pub const fn runtime_implementation_id(&self) -> &'static str {
        self.plan.runtime_implementation_id()
    }

    /// Exact immutable receipt for a selected long shared-fragment packed
    /// subengine.
    ///
    /// This returns `None` for every other portable plan and packed subengine.
    /// A present receipt authenticates that whole-buffer packed search uses an
    /// exact common fragment of at least eight bytes; callers do not need to
    /// infer that private planner decision from pattern syntax.
    #[must_use]
    pub const fn packed_literal_set_long_shared_fragment_build_receipt(
        &self,
    ) -> Option<PackedLiteralSetLongSharedFragmentBuildReceipt> {
        match &self.plan {
            PortablePlan::PackedLiteralSet(plan) => {
                plan.long_shared_fragment_build_receipt()
            }
            _ => None,
        }
    }

    /// Separately versioned resources retained for session-backed iteration.
    /// Direct find operations continue to report [`Self::runtime_implementation_id`].
    #[must_use]
    pub const fn retained_find_iter_build_accounting(
        &self,
    ) -> Option<PackedLiteralSetRetainedIterBuildAccounting> {
        #[cfg(not(feature = "static-dispatch"))]
        if let PortablePlan::PackedLiteralSet(plan) = &self.plan {
            return plan.retained_iter_build_accounting();
        }
        None
    }

    /// Stable operation identity when the selected matcher retains a direct
    /// complete-span visitor.
    #[must_use]
    pub const fn span_visit_runtime_implementation_id(&self) -> Option<&'static str> {
        match &self.plan {
            PortablePlan::ExactLiteral(_) => Some(LITERAL_SPAN_VISIT_OPERATION_ID),
            PortablePlan::LiteralClassRunLiteral(_) => {
                Some(LITERAL_CLASS_RUN_LITERAL_SPAN_VISIT_OPERATION_ID)
            }
            PortablePlan::PrefixClassAlternation(_)
            | PortablePlan::DispatchedPrefixClassAlternation(_) => {
                Some(PREFIX_CLASS_ALTERNATION_SPAN_VISIT_OPERATION_ID)
            }
            PortablePlan::K0(plan) if plan.k0_casefold_prefix_class_span.is_some() => {
                Some(K0_CASEFOLD_PREFIX_CLASS_SPAN_VISIT_OPERATION_ID)
            }
            PortablePlan::K0(plan) if plan.lazy_delimited_repeat.is_some() => {
                Some(LAZY_DELIMITED_REPEAT_SPAN_VISIT_OPERATION_ID)
            }
            PortablePlan::K0(plan) if plan.greedy_delimited_corridor.is_some() => {
                Some(GREEDY_DELIMITED_CORRIDOR_SPAN_VISIT_OPERATION_ID)
            }
            PortablePlan::K0(plan) if plan.unicode_token_phrase.is_some() => {
                Some(UNICODE_TOKEN_PHRASE_SPAN_VISIT_OPERATION_ID)
            }
            PortablePlan::K0(plan) if plan.greedy_class_literal_tail.is_some() => {
                Some(GREEDY_CLASS_LITERAL_TAIL_SPAN_VISIT_OPERATION_ID)
            }
            _ => None,
        }
    }

    /// Complete direct-visitor identity for a selected fixed-predicate plan.
    ///
    /// Other plan families return `None`.
    #[must_use]
    pub const fn fixed_predicate_span_visit_operation_identity(
        &self,
    ) -> Option<FixedPredicateWord64OperationIdentity> {
        match &self.plan {
            PortablePlan::FixedPredicateWord64(plan) => {
                Some(plan.operation_identity(FixedPredicateWord64Operation::SpanVisit))
            }
            _ => None,
        }
    }

    /// Bind reusable worker-owned state for ordinary unlimited searches.
    ///
    /// A positive exact literal binds its retained finder and needle without
    /// allocating a canonical worker. A K0 matcher authenticates one
    /// source-free executor and settles its immutable start-filter policy
    /// during this call. Unanchored
    /// required-literal matchers bind their value-only projection alongside
    /// the already-proven native regex owner for spans. An attachment-free,
    /// positive-width leftmost-first literal set binds its immutable span
    /// executor and, on AArch64, may retain a wider exact ASCII-root
    /// capability whose engine is bound on the first Exists projection and
    /// whose classifier is prepared only when that call reaches the branch
    /// that can use it. A
    /// uniform-standard literal set additionally starts with one cleared
    /// performance-only route bit; near acceptances may spend that bit on one
    /// bounded direct same-DFA probe. Other selected plan families bind
    /// only the compact canonical non-K0 projection. The
    /// returned owner retains no haystack and may be reused across unrelated
    /// inputs by one mutable worker.
    ///
    /// This is deliberately separate from [`Self::search_session`]: ordinary
    /// methods accept no finite limits and construct no facade accounting.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if fallible K0 workspace allocation or
    /// immutable preparation fails, or if an internal route invariant tries
    /// to place K0 in the compact canonical projection.
    pub fn ordinary_session(&self) -> Result<PortableOrdinarySession<'_>, SearchError> {
        let plan = match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                if let Some(executor) = literal.ordinary_executor() {
                    PortableOrdinarySessionPlan::ExactLiteral { executor }
                } else {
                    PortableOrdinarySessionPlan::Canonical(
                        PortableOrdinaryCanonical::try_new(self)?,
                    )
                }
            }
            PortablePlan::K0(k0) => {
                let positive =
                    matches!(self.report.minimum_match_bytes, Some(minimum) if minimum > 0);
                let assertion_free_nullable = self.report.minimum_match_bytes == Some(0)
                    && !k0.automaton.stats().has_assertions();
                let endpoint_eligible = positive || assertion_free_nullable;
                PortableOrdinarySessionPlan::K0 {
                    executor: K0OrdinaryExecutor::new(
                        &k0.automaton,
                        endpoint_eligible,
                        positive,
                    )?,
                    positive,
                }
            }
            PortablePlan::RequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                PortableOrdinarySessionPlan::RequiredLiteral {
                    projection: PortableOrdinaryRequiredLiteral::Scalar(required),
                    regex: self,
                }
            }
            PortablePlan::DispatchedRequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                PortableOrdinarySessionPlan::RequiredLiteral {
                    projection: PortableOrdinaryRequiredLiteral::Dispatched(required),
                    regex: self,
                }
            }
            PortablePlan::PackedLiteralSet(packed) => {
                PortableOrdinarySessionPlan::PackedLiteralSet {
                    executor: packed.ordinary_executor(),
                }
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                if let Some(executor) = literal_set.ordinary_executor() {
                    if let Some(executor) = executor.uniform_standard_executor() {
                        PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                            executor,
                            direct_next: false,
                        }
                    } else {
                        PortableOrdinarySessionPlan::LiteralSetDfa {
                            executor,
                            ascii_exists: PortableOrdinaryLiteralSetExists::Unbound,
                        }
                    }
                } else {
                    PortableOrdinarySessionPlan::Canonical(
                        PortableOrdinaryCanonical::try_new(self)?,
                    )
                }
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                PortableOrdinarySessionPlan::LiteralSetCompact {
                    executor: literal_set.ordinary_executor(),
                }
            }
            _ => PortableOrdinarySessionPlan::Canonical(
                PortableOrdinaryCanonical::try_new(self)?,
            ),
        };
        Ok(PortableOrdinarySession { plan })
    }

    /// Prepare a demand-grown reusable search session over this immutable
    /// matcher.
    ///
    /// K0 admits a finite source-independent workspace layout here, but may
    /// allocate and initialize cache storage transactionally during later
    /// searches as the requested operation demands it. One admitted
    /// capture-free Exists proof may also retain a second, reverse-capable
    /// prefix workspace from the residual aggregate setup and scratch limits.
    /// No source-dependent cursor is retained in either owner.
    /// Eligible byte graphs with a statically known positive minimum length
    /// retain a bounded forward endpoint cache plus a separate reverse cache
    /// for exact full-span recovery. Assertion-free nullable graphs retain a
    /// forward cache whose initial pending match proves every selected span
    /// starts at the requested window; they need no reverse cache.
    /// Assertion-free graphs use direct byte rows; assertion-bearing graphs key
    /// transitions by the exact enabled-assertion mask at each boundary.
    /// Contextual nullable, statically empty, or resource-refused graphs keep
    /// the ordinary Pike workspace. Capability admission remains source-free.
    /// Native plans retain their existing operation-specific dispatch and need
    /// no allocated session storage. Exact literals and fixed-predicate words
    /// bind their selected immutable plans directly in the inline session
    /// owner.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if primary K0 workspace construction exceeds
    /// the supplied setup-work or scratch limit, or if its allocation fails.
    /// An optional reverse-inner sidecar may decline on allocation or scratch
    /// refusal and publish the primary-only session; its discarded attempt is
    /// not included in that successful setup receipt. Native specialized plans
    /// ignore these limits because they construct no K0 workspace.
    pub fn search_session(
        &self,
        limits: SearchSessionLimits,
    ) -> Result<PortableSearchSession<'_>, SearchError> {
        self.search_session_mode(limits, true, PortableSearchSessionStorage::Adaptive)
    }

    /// Prepare a fixed-capacity session whose searches do not grow K0 cache
    /// storage.
    ///
    /// This preserves the preallocated session contract for callers that put
    /// all workspace construction outside an allocation-free operation
    /// boundary. K0 selects and reserves its complete admitted workspace
    /// during this call. Direct rows publish sentinel-initialized cells during
    /// execution without allocating or increasing cache capacity. A cold
    /// immutable start-filter proof is separate from workspace capacity and
    /// may still allocate on its first search; callers that require an
    /// end-to-end allocation-free measured region must call
    /// [`PortableSearchSession::prepare_k0_start_filter`] or warm that plan
    /// proof before entering it. Native specialized plans behave exactly as
    /// in [`Self::search_session`] because they own no K0 workspace.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if primary fixed K0 workspace construction
    /// exceeds the supplied setup-work or scratch limit, or if its allocation
    /// fails. An optional reverse-inner sidecar may decline to the primary-only
    /// session under the same policy as [`Self::search_session`]. Native
    /// specialized plans ignore these limits.
    pub fn fixed_search_session(
        &self,
        limits: SearchSessionLimits,
    ) -> Result<PortableSearchSession<'_>, SearchError> {
        self.search_session_mode(limits, true, PortableSearchSessionStorage::Fixed)
    }

    /// Prepare a smaller reusable session for existence and endpoint
    /// projections.
    ///
    /// Eligible K0 graphs retain only the ordered forward cache.
    /// Assertion-free nullable full-span methods can reuse that cache because
    /// their selected start is known; other full-span calls remain correct but
    /// use Pike. Callers that need nonnullable `find`/iteration acceleration
    /// should use [`Self::search_session`].
    ///
    /// Like [`Self::search_session`], this endpoint session is adaptive: K0
    /// allocates a compact cache seed during construction while admitting its
    /// finite workspace ceiling, then may allocate and initialize more cache
    /// storage transactionally under a later search's limits.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same conditions as
    /// [`Self::search_session`].
    pub fn endpoint_search_session(
        &self,
        limits: SearchSessionLimits,
    ) -> Result<PortableSearchSession<'_>, SearchError> {
        self.search_session_mode(limits, false, PortableSearchSessionStorage::Adaptive)
    }

    /// Prepare a fixed-capacity endpoint session for an aggregate owner whose
    /// construction receipt must cover every byte the constituent can retain.
    pub(crate) fn fixed_endpoint_search_session(
        &self,
        limits: SearchSessionLimits,
    ) -> Result<PortableSearchSession<'_>, SearchError> {
        self.search_session_mode(limits, false, PortableSearchSessionStorage::Fixed)
    }

    fn search_session_mode(
        &self,
        limits: SearchSessionLimits,
        bidirectional: bool,
        storage: PortableSearchSessionStorage,
    ) -> Result<PortableSearchSession<'_>, SearchError> {
        let plan = match &self.plan {
            PortablePlan::K0(k0) => {
                let workspace_limits = SearchSessionLimits {
                    max_setup_work: limits.max_setup_work,
                    max_scratch_bytes: limits.max_scratch_bytes,
                };
                let positive =
                    matches!(self.report.minimum_match_bytes, Some(minimum) if minimum > 0);
                let assertion_free_nullable = self.report.minimum_match_bytes == Some(0)
                    && !k0.automaton.stats().has_assertions();
                let endpoint_eligible = positive || assertion_free_nullable;
                // Select the primary cache from its source-free layout before
                // allocating. Once primary construction begins, propagate
                // every failure so a partial attempt cannot disappear from
                // successful setup accounting. The reverse-inner owner below
                // is an optional independent sidecar: its physical or scratch
                // refusal deliberately publishes this primary alone, and the
                // successful receipt excludes that discarded optional attempt.
                let session = match storage {
                    PortableSearchSessionStorage::Adaptive => {
                        K0SearchSession::new_adaptive_selected(
                            &k0.automaton,
                            workspace_limits,
                            endpoint_eligible,
                            bidirectional && positive,
                        )
                    }
                    PortableSearchSessionStorage::Fixed => K0SearchSession::new_selected(
                        &k0.automaton,
                        workspace_limits,
                        endpoint_eligible,
                        bidirectional && positive,
                    ),
                }?;
                let primary_setup = session.construction_accounting();
                let primary_scratch_ceiling = primary_setup
                    .retained_bytes()
                    .max(session.admitted_scratch_bytes());
                let reverse_inner = if bidirectional
                    && let Some(plan) = k0.reverse_inner.as_deref()
                {
                    let residual = SearchSessionLimits {
                        max_setup_work: limits
                            .max_setup_work
                            .checked_sub(primary_setup.work())
                            .ok_or(K0SearchError::InternalInvariant {
                                detail: "primary K0 setup exceeded its admitted work limit",
                            })?,
                        max_scratch_bytes: limits
                            .max_scratch_bytes
                            .checked_sub(primary_scratch_ceiling)
                            .ok_or(K0SearchError::InternalInvariant {
                                detail: "primary K0 setup exceeded its admitted scratch limit",
                            })?,
                    };
                    k0_general_reverse_inner::SearchSession::try_new(
                        plan,
                        &k0.automaton,
                        &session,
                        residual,
                    )?
                } else {
                    None
                };
                let aggregate_setup = reverse_inner.as_ref().map_or(Ok(primary_setup), |sidecar| {
                    session.aggregate_construction_accounting(
                        sidecar.prefix_session(),
                        k0_general_reverse_inner::SearchSession::owner_publication_work(),
                        k0_general_reverse_inner::SearchSession::owner_bytes(),
                    )
                })?;
                if aggregate_setup.work() > limits.max_setup_work
                    || aggregate_setup.retained_bytes() > limits.max_scratch_bytes
                {
                    return Err(K0SearchError::InternalInvariant {
                        detail: "aggregate K0 setup exceeded its residual admission",
                    }
                    .into());
                }
                PortableSearchSessionPlan::K0 {
                    session,
                    aggregate_setup,
                    k0_plan: k0,
                    line_total_grep_plan: self.line_total_grep_plan,
                    reverse_inner,
                    lazy_delimited_repeat: k0.lazy_delimited_repeat.as_ref(),
                    greedy_class_literal_tail: k0.greedy_class_literal_tail.as_ref(),
                    mandatory_suffix: k0.mandatory_suffix.as_ref(),
                    mandatory_cut: k0.mandatory_cut.as_ref(),
                    negative_prefilter: k0.negative_prefilter.as_deref(),
                    exclusive_route_state: K0ExclusiveRouteState::for_plan(&k0.exclusive),
                    mandatory_suffix_exists_state: K0NegativePrefilterState::default(),
                    mandatory_suffix_span_state: K0NegativePrefilterState::default(),
                    negative_prefilter_exists_state: K0NegativePrefilterState::default(),
                    negative_prefilter_span_state: K0NegativePrefilterState::default(),
                }
            }
            PortablePlan::ExactLiteral(plan) => PortableSearchSessionPlan::ExactLiteral {
                regex: self,
                plan,
            },
            PortablePlan::FixedPredicateWord64(plan) => {
                PortableSearchSessionPlan::FixedPredicateWord64 {
                    regex: self,
                    plan,
                }
            }
            _ => PortableSearchSessionPlan::Native(self),
        };
        Ok(PortableSearchSession { plan })
    }

    /// Return whether this regex matches anywhere in `haystack`.
    ///
    /// This is the Rust-compatible convenience API. Search work has no
    /// caller-visible quota, and generic K0 plans automatically retain a
    /// source-free workspace in this immutable matcher. Its admitted ceiling
    /// is derived from the construction-bounded automaton, while retained
    /// cache capacity may grow transactionally as operations demand it.
    ///
    /// Use [`Self::is_match_with_limits`] when a recoverable work or scratch
    /// refusal is required, and [`Self::is_match_accounted`] when the exact
    /// execution receipt is also required.
    ///
    /// # Panics
    ///
    /// Panics if fallible scratch allocation fails or a validated internal
    /// invariant is violated. These failures are never converted into a
    /// negative match result.
    #[must_use]
    #[inline]
    pub fn is_match(&self, haystack: &[u8]) -> bool {
        self.try_is_match_ordinary(haystack)
            .unwrap_or_else(|error| panic!("PortableRegex::is_match failed: {error}"))
    }

    #[inline]
    fn try_is_match_ordinary(&self, haystack: &[u8]) -> Result<bool, SearchError> {
        match &self.plan {
            PortablePlan::BoundedWordClass(plan) => {
                if let Some(matched) = plan.ordinary_is_match_full_unmetered(haystack) {
                    return Ok(matched);
                }
            }
            PortablePlan::ForwardAnchored(plan) => {
                if let Some(result) = plan.ordinary_is_match_full_unmetered(haystack) {
                    #[cfg(test)]
                    forward_anchored_ordinary_facade_probe::record_exists();
                    return result.map_err(SearchError::from);
                }
            }
            PortablePlan::DispatchedForwardAnchored(plan) => {
                if let Some(result) = plan.ordinary_is_match_full_unmetered(haystack) {
                    #[cfg(test)]
                    forward_anchored_ordinary_facade_probe::record_exists();
                    return result.map_err(SearchError::from);
                }
            }
            PortablePlan::ForwardEndFixed(plan) => {
                if let Some(result) = plan.ordinary_is_match_full_unmetered(haystack) {
                    #[cfg(test)]
                    forward_anchored_ordinary_facade_probe::record_exists();
                    return result.map_err(SearchError::from);
                }
            }
            // Every other family deliberately keeps its existing ordinary
            // fallback.
            _ => {}
        }
        let window = SearchWindow::full(haystack);
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                #[cfg(test)]
                exact_literal_ordinary_facade_probe::record_exists();
                if let Some(executor) = literal.ordinary_executor() {
                    executor
                        .exists_window_value(haystack, LiteralWindow::full(haystack))
                        .map_err(SearchError::from)
                } else {
                    literal
                        .find_full_value(haystack, literal_limits(SearchLimits::unlimited()))
                        .map(|matched| matched.is_some())
                        .map_err(SearchError::from)
                }
            }
            PortablePlan::K0(k0) => {
                if let Some(plan) = k0.exclusive.line()
                    && haystack.len() >= plan.minimum_input_bytes()
                    && let Some(matched) = plan.try_ordinary_is_match_full(haystack)
                {
                    return Ok(matched);
                }
                if let Some(plan) = k0.uri_exists
                    && let Some(matched) = plan.try_ordinary_is_match_full(haystack)
                {
                    return Ok(matched);
                }
                let window_bytes = haystack.len();
                let compact_prepared = window_bytes
                    >= PREPARED_COMPACT_ORDINARY_EXISTS_MIN_WINDOW_BYTES
                    && window_bytes < PREPARED_ORDINARY_EXISTS_MIN_WINDOW_BYTES
                    // Below this floor the generic mandatory-cut predecessor
                    // is a pure decline, so it is safe to enter the pooled
                    // prepared executor before the general sidecar dispatcher.
                    && window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
                    && matches!(self.report.minimum_match_bytes, Some(minimum) if minimum > 0)
                    && k0.absolute_end_proof.is_none()
                    && k0
                        .automaton
                        .can_use_pooled_compact_ordinary_exists_projection();
                if compact_prepared {
                    #[cfg(test)]
                    k0_ordinary_exists_route_probe::record_direct_prepared();
                    if let Some(value) = k0
                        .automaton
                        .search_window_with_optional_pooled_ordinary_exists_value(
                            haystack,
                            window,
                            SearchSessionLimits::unlimited(),
                            true,
                            false,
                        )?
                    {
                        return Ok(value);
                    }
                } else {
                    match k0.pooled_value(
                        K0PooledValueOperation::Exists,
                        K0PooledValueExecution::OrdinaryExists,
                        haystack,
                        window,
                        SearchLimits::unlimited(),
                        SearchSessionLimits::unlimited(),
                        self.report.minimum_match_bytes,
                    )? {
                        Some(K0PooledValue::Exists(value)) => return Ok(value),
                        Some(K0PooledValue::Span(_)) => {
                            unreachable!("existence pool returned a span")
                        }
                        None => {}
                    }
                }
                k0.automaton
                    .prepare::<Exists>()
                    .search_window(haystack, window, SearchLimits::unlimited())
                    .map(|report| report.into_output())
                    .map_err(SearchError::from)
            },
            PortablePlan::LiteralClassRunLiteral(plan) => plan
                .is_match_full_ordinary_value(haystack)
                .map_err(SearchError::from),
            PortablePlan::ReverseInner(plan) => {
                if let Some(matched) = plan
                    .ordinary_is_match_full_unmetered(haystack)
                    .map_err(SearchError::from)?
                {
                    #[cfg(test)]
                    reverse_inner_ordinary_facade_probe::record_exists();
                    return Ok(matched);
                }
                self.is_match_window_value(haystack, window, SearchLimits::unlimited())
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                if let Some(ordinary) =
                    literal_set.try_ordinary_full_window_executor(haystack.len())
                {
                    #[cfg(test)]
                    packed_literal_set_ordinary_facade_probe::record_exists();
                    ordinary
                        .exists_window_value(haystack, literal_window)
                        .map_err(SearchError::from)
                } else {
                    literal_set
                        .is_match_window_value(
                            haystack,
                            literal_window,
                            PackedLiteralSetSearchLimits::unlimited(),
                        )
                        .map_err(SearchError::from)
                }
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                if let Some(ordinary) =
                    literal_set.ordinary_ascii_folded_for_input(haystack.len())
                {
                    #[cfg(test)]
                    {
                        literal_set_dfa_ordinary_facade_probe::record_exists();
                        ascii_folded_literal_set_ordinary_facade_probe::record_exists();
                    }
                    ordinary
                        .is_match_full_value(haystack)
                        .map_err(SearchError::from)
                } else if let Some(ordinary) = literal_set.ordinary_executor() {
                    #[cfg(test)]
                    literal_set_dfa_ordinary_facade_probe::record_exists();
                    ordinary
                        .exists_window_value(haystack, literal_window)
                        .map_err(SearchError::from)
                } else {
                    literal_set
                        .find_window(
                            haystack,
                            literal_window,
                            LiteralSetSearchLimits::unlimited(),
                        )
                        .map(|(matched, _)| matched.is_some())
                        .map_err(SearchError::from)
                }
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                #[cfg(test)]
                literal_set_compact_ordinary_facade_probe::record_exists();
                literal_set
                    .ordinary_executor()
                    .exists_window_value(haystack, LiteralWindow::full(haystack))
                    .map_err(SearchError::from)
            }
            PortablePlan::RequiredLiteral(required) => {
                required
                    .exists_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map_err(SearchError::from)
            }
            PortablePlan::DispatchedRequiredLiteral(required) => {
                required
                    .exists_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map_err(SearchError::from)
            }
            PortablePlan::BoundedRequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                #[cfg(test)]
                bounded_required_literal_ordinary_facade_probe::record_exists();
                required
                    .find_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map(|matched| matched.is_some())
                    .map_err(SearchError::from)
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                #[cfg(test)]
                bounded_required_literal_ordinary_facade_probe::record_exists();
                required
                    .find_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map(|matched| matched.is_some())
                    .map_err(SearchError::from)
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                if let Some(matched) = plan.ordinary_is_match_full_unmetered(haystack) {
                    #[cfg(test)]
                    prefix_class_alternation_ordinary_facade_probe::record_exists();
                    Ok(matched)
                } else {
                    plan.is_match_in(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        prefix_class_alternation_search_limits(SearchLimits::unlimited()),
                    )
                    .map(|(matched, _)| matched)
                    .map_err(SearchError::from)
                }
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                if let Some(matched) = plan.ordinary_is_match_full_unmetered(haystack) {
                    #[cfg(test)]
                    prefix_class_alternation_ordinary_facade_probe::record_exists();
                    Ok(matched)
                } else {
                    plan.is_match_in(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        prefix_class_alternation_search_limits(SearchLimits::unlimited()),
                    )
                    .map(|(matched, _)| matched)
                    .map_err(SearchError::from)
                }
            }
            PortablePlan::NullableOptionalChain(plan) => plan
                .is_match_full_unlimited_value(haystack)
                .unwrap_or_else(|| {
                    plan.is_match_window_value(haystack, window, SearchLimits::unlimited())
                })
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::NullableFiniteTokenRepeat(plan) => plan
                .is_match_full_unlimited_value(haystack)
                .unwrap_or_else(|| {
                    plan.is_match_window_value(haystack, window, SearchLimits::unlimited())
                })
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::PureByteClassRepeat(plan) => {
                Ok(plan.ordinary_is_match_full_unmetered(haystack))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(SearchLimits::unlimited()),
                )
                .map_err(SearchError::from),
            PortablePlan::LineDomainByteAtoms(plan) => plan
                .is_match_window_value(haystack, window, SearchLimits::unlimited())
                .map_err(SearchError::from),
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => plan
                .is_match_window_value(
                    haystack,
                    window,
                    required_literal_limits(SearchLimits::unlimited()),
                )
                .map_err(SearchError::from),
            _ => self.is_match_window_value(haystack, window, SearchLimits::unlimited()),
        }
    }

    /// Whether a selected match exists, with selected execution limits and an
    /// exact accounting receipt.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    pub fn is_match_accounted(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        self.is_match_window(haystack, SearchWindow::full(haystack), limits)
    }

    /// Whether a selected match exists under explicit work and scratch
    /// limits, without constructing facade diagnostic accounting.
    ///
    /// This is the finite value-only counterpart to [`Self::is_match`]. It
    /// preserves the same selected plan, checked execution limits and typed failures,
    /// while keeping callers that only consume the boolean outside the
    /// [`SearchAccounting`] projection boundary. Under the default limits,
    /// generic K0 plans automatically retain bounded scratch in this immutable
    /// matcher and reuse it on later calls; callers do not need to construct a
    /// search session.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    pub fn is_match_with_limits(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        self.is_match_window_value(haystack, SearchWindow::full(haystack), limits)
    }

    /// Compatibility alias for [`Self::is_match_with_limits`].
    pub fn is_match_value(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        self.is_match_with_limits(haystack, limits)
    }

    /// Whether a selected match exists at or after `start`.
    ///
    /// Assertions inspect the complete original haystack. Unlike the pinned
    /// Rust API, an out-of-bounds `start` is returned as a typed error instead
    /// of panicking.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid start or a resource refusal.
    pub fn is_match_at(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        self.is_match_window(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Whether a selected match exists at or after `start` without
    /// constructing facade diagnostic accounting on the success path.
    ///
    /// Assertions inspect the complete original haystack. Range validation,
    /// execution limits and typed failures are identical to
    /// [`Self::is_match_at`].
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid start or a resource refusal.
    pub fn is_match_value_at(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        self.is_match_window_value(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Whether a selected match exists wholly inside a search range.
    ///
    /// Assertions retain original-haystack context. K0 executes its typed
    /// existence contract directly instead of materializing a match span.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid window or a resource refusal.
    #[allow(
        clippy::too_many_lines,
        reason = "each authenticated native owner projects the same operation-specific accounting without erasing its concrete type"
    )]
    pub fn is_match_window(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) =
                    literal.find_window(haystack, literal_window, literal_limits(limits))?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    packed_literal_set_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::PackedLiteralSet(accounting),
                ))
            }
            PortablePlan::GuardedLiteralSet(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::GuardedLiteralSet(accounting),
                ))
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    literal_set_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    literal_set_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::RequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::BoundedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    window,
                    required_literal_limits(limits),
                )?;
                Ok((matched, SearchAccounting::RequiredLiteral(accounting)))
            }
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    window,
                    required_literal_limits(limits),
                )?;
                Ok((matched, SearchAccounting::RequiredLiteral(accounting)))
            }
            PortablePlan::LiteralClassRunLiteral(plan) => {
                let (matched, accounting) = plan.shortest_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::LiteralClassRunSearch(plan) => {
                let (matched, accounting) = plan.shortest_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::BoundedLiteralClassRun(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((
                    matched,
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::ReverseInner(plan) => {
                let (matched, accounting) = plan.is_match_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    reverse_inner_search_limits(limits),
                )?;
                Ok((matched, SearchAccounting::ReverseInner(accounting)))
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                let (matched, accounting) = plan.is_match_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((matched, SearchAccounting::PrefixClassAlternation(accounting)))
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                let (matched, accounting) = plan.is_match_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((matched, SearchAccounting::PrefixClassAlternation(accounting)))
            }
            PortablePlan::PureByteClassRepeat(plan) => {
                let (matched, accounting) = plan.is_match_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassRepeat(plan) => {
                let (matched, accounting) = plan.is_match_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassSequence(plan) => {
                let (matched, accounting) = plan
                    .is_match_window(haystack, window, limits)
                    .map_err(SearchError::BoundedByteClassSequence)?;
                Ok((
                    matched,
                    SearchAccounting::BoundedByteClassSequence(accounting),
                ))
            }
            PortablePlan::NullableOptionalChain(plan) => {
                let (matched, accounting) = plan
                    .is_match_window(haystack, window, limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((
                    matched,
                    SearchAccounting::NullableOptionalChain(accounting),
                ))
            }
            PortablePlan::NullableFiniteTokenRepeat(plan) => {
                let (matched, accounting) = plan
                    .is_match_window(haystack, window, limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((
                    matched,
                    SearchAccounting::NullableOptionalChain(accounting),
                ))
            }
            PortablePlan::ForwardAnchored(forward) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = forward.find_window(
                    haystack,
                    literal_window,
                    forward_anchored_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::DispatchedForwardAnchored(forward) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = forward.find_window(
                    haystack,
                    literal_window,
                    forward_anchored_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::ForwardEndFixed(fixed) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) =
                    fixed.find_window(haystack, literal_window, forward_anchored_limits(limits))?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(limits),
                )?;
                Ok((
                    matched,
                    SearchAccounting::UnicodeFoldedLiteral(accounting.actual),
                ))
            }
            PortablePlan::K0(k0) => {
                let report = k0
                    .automaton
                    .prepare::<Exists>()
                    .search_window(haystack, window, limits)?;
                let accounting = report.accounting();
                Ok((report.into_output(), SearchAccounting::K0(accounting)))
            }
            PortablePlan::UnicodeWordRun(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::AsciiWordRun(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::BoundedWordClass(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::FixedPredicateWord64(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((matched, SearchAccounting::FixedPredicateWord64(accounting)))
            }
            PortablePlan::UnicodeScalarRun(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    fre_kernels::Window::new(window.start(), window.end()),
                    unicode_scalar_search_limits(limits),
                )?;
                Ok((matched, SearchAccounting::UnicodeScalarRun(accounting)))
            }
            PortablePlan::LineDomainByteAtoms(plan) => {
                let (matched, accounting) = plan.is_match_window(haystack, window, limits)?;
                Ok((
                    matched,
                    SearchAccounting::LineDomainByteAtoms(accounting),
                ))
            }
        }
    }

    /// Whether a selected match exists wholly inside a search range without
    /// constructing facade diagnostic accounting on the success path.
    ///
    /// Assertions retain original-haystack context and every plan executes
    /// the same existence operation as [`Self::is_match_window`].
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid window or a resource refusal.
    #[allow(
        clippy::too_many_lines,
        reason = "each native owner retains its direct value-only existence projection"
    )]
    pub fn is_match_window_value(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => literal
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::PackedLiteralSet(literal_set) => literal_set
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    packed_literal_set_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::GuardedLiteralSet(plan) => plan
                .find_window_value(haystack, window, limits)
                .map(|matched| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::LiteralSetDfa(literal_set) => literal_set
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_set_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::LiteralSetCompact(literal_set) => literal_set
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_set_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::RequiredLiteral(required) => required
                .exists_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::DispatchedRequiredLiteral(required) => required
                .exists_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::BoundedRequiredLiteral(required) => required
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => required
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => plan
                .is_match_window_value(haystack, window, required_literal_limits(limits))
                .map_err(SearchError::from),
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => {
                bounded_delimited_segment_is_match_window_value(plan, haystack, window, limits)
            }
            PortablePlan::LiteralClassRunLiteral(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::LiteralClassRunSearch(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::BoundedLiteralClassRun(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::ReverseInner(plan) => plan
                .is_match_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    reverse_inner_search_limits(limits),
                )
                .map(|(matched, _)| matched)
                .map_err(SearchError::from),
            PortablePlan::PrefixClassAlternation(plan) => plan
                .is_match_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )
                .map(|(matched, _)| matched)
                .map_err(SearchError::from),
            PortablePlan::DispatchedPrefixClassAlternation(plan) => plan
                .is_match_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )
                .map(|(matched, _)| matched)
                .map_err(SearchError::from),
            PortablePlan::PureByteClassRepeat(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::BoundedByteClassRepeat(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::BoundedByteClassSequence(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::BoundedByteClassSequence),
            PortablePlan::NullableOptionalChain(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::NullableFiniteTokenRepeat(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::ForwardAnchored(forward) => forward
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    forward_anchored_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::DispatchedForwardAnchored(forward) => forward
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    forward_anchored_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::ForwardEndFixed(fixed) => fixed
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    forward_anchored_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::UnicodeFoldedLiteral(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::K0(k0) => match k0.pooled_value(
                K0PooledValueOperation::Exists,
                K0PooledValueExecution::Canonical,
                haystack,
                window,
                limits,
                SearchSessionLimits::default(),
                self.report.minimum_match_bytes,
            )? {
                Some(K0PooledValue::Exists(value)) => Ok(value),
                Some(K0PooledValue::Span(_)) => unreachable!("existence pool returned a span"),
                None => k0
                    .automaton
                    .prepare::<Exists>()
                    .search_window(haystack, window, limits)
                    .map(fre_automata::SearchReport::into_output)
                    .map_err(SearchError::from),
            },
            PortablePlan::UnicodeWordRun(plan) => {
                if window.start() == 0
                    && window.end() == haystack.len()
                    && limits == SearchLimits::unlimited()
                {
                    return Ok(plan.is_match_full_prepared(haystack));
                }
                plan.find_window(haystack, window, limits)
                    .map(|(matched, _)| matched.is_some())
                    .map_err(SearchError::from)
            }
            PortablePlan::AsciiWordRun(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::BoundedWordClass(plan)
                if limits.max_work == u64::MAX
                    && window.start() <= window.end()
                    && window.end() <= haystack.len() =>
            {
                plan.shortest_window(haystack, window, limits)
                    .map(|(end, _)| end.is_some())
                    .map_err(SearchError::from)
            }
            PortablePlan::BoundedWordClass(plan) => plan
                .find_window(haystack, window, limits)
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortablePlan::FixedPredicateWord64(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::UnicodeScalarRun(plan) => plan
                .is_match_window_value(
                    haystack,
                    fre_kernels::Window::new(window.start(), window.end()),
                    unicode_scalar_search_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::LineDomainByteAtoms(plan) => plan
                .is_match_window_value(haystack, window, limits)
                .map_err(SearchError::from),
        }
    }

    /// Return the end offset at the first boundary where a match is detected.
    ///
    /// Like the pinned Rust bytes API, this may be shorter than the end of the
    /// leftmost-first match returned by [`Self::find`].
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    pub fn shortest_match(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        self.shortest_match_window(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return the first detected match end at or after `start`.
    ///
    /// Assertions inspect the complete original haystack and the returned
    /// offset remains relative to it. Unlike the pinned Rust API, an
    /// out-of-bounds `start` is returned as a typed error instead of panicking.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid start or a resource refusal.
    pub fn shortest_match_at(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        self.shortest_match_window(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Return only the first detected match end.
    ///
    /// Reusable callers should prefer
    /// [`PortableSearchSession::shortest_match_value`], which can retain
    /// operation-local K0 acceleration state across haystacks.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as [`Self::shortest_match`].
    pub fn shortest_match_value(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        self.shortest_match_window_value(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return only the first detected match end at or after `start`.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as [`Self::shortest_match_at`].
    pub fn shortest_match_at_value(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        self.shortest_match_window_value(
            haystack,
            SearchWindow::new(start, haystack.len()),
            limits,
        )
    }

    #[inline]
    fn shortest_match_window_value(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => literal
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )
                .map(|(matched, _accounting)| matched.map(|(_start, end)| end))
                .map_err(SearchError::from),
            PortablePlan::UnicodeScalarRun(plan) => plan
                .shortest_match_window_value(
                    haystack,
                    fre_kernels::Window::new(window.start(), window.end()),
                    unicode_scalar_search_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::LiteralClassRunSearch(plan) => plan
                .shortest_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::BoundedLiteralClassRun(plan) => plan
                .shortest_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map_err(SearchError::from),
            PortablePlan::PureByteClassRepeat(plan) => plan
                .earliest_end_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::BoundedByteClassRepeat(plan) => plan
                .earliest_end_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::NullableOptionalChain(plan) => plan
                .earliest_end_window_value(haystack, window, limits)
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::NullableFiniteTokenRepeat(plan) => plan
                .earliest_end_window_value(haystack, window, limits)
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::K0(k0) => match k0.pooled_earliest_end_value(
                haystack,
                window,
                limits,
                SearchSessionLimits::default(),
                self.report.minimum_match_bytes,
            )? {
                Some(end) => Ok(end),
                None => self
                    .shortest_match_window(haystack, window, limits)
                    .map(|(output, _)| output),
            },
            PortablePlan::FixedPredicateWord64(plan) => plan
                .earliest_end_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map_err(SearchError::from),
            _ => {
                if limits == SearchLimits::unlimited()
                    && let PortablePlan::BoundedByteClassSequence(plan) = &self.plan
                {
                    return plan
                        .earliest_end_window_value(haystack, window, limits)
                        .map_err(SearchError::BoundedByteClassSequence);
                }
                self.shortest_match_window(haystack, window, limits)
                    .map(|(output, _)| output)
            }
        }
    }

    #[allow(
        clippy::too_many_lines,
        reason = "each authenticated native owner projects the same operation-specific accounting without erasing its concrete type"
    )]
    fn shortest_match_window(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) =
                    literal.find_window(haystack, literal_window, literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    packed_literal_set_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::PackedLiteralSet(accounting),
                ))
            }
            PortablePlan::GuardedLiteralSet(plan) => {
                let (end, accounting) = plan.shortest_window(haystack, window, limits)?;
                Ok((end, SearchAccounting::GuardedLiteralSet(accounting)))
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    literal_set_limits(limits),
                )?;
                let end = if self.report.minimum_match_bytes == Some(0) {
                    Some(window.start())
                } else {
                    matched.map(|(_, end)| end)
                };
                Ok((end, SearchAccounting::LiteralSetDfa(accounting)))
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    literal_set_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::RequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::BoundedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    window,
                    required_literal_limits(limits),
                )?;
                Ok((end, SearchAccounting::RequiredLiteral(accounting)))
            }
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    window,
                    required_literal_limits(limits),
                )?;
                Ok((end, SearchAccounting::RequiredLiteral(accounting)))
            }
            PortablePlan::LiteralClassRunLiteral(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((end, SearchAccounting::LiteralClassRunLiteral(accounting)))
            }
            PortablePlan::LiteralClassRunSearch(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((end, SearchAccounting::LiteralClassRunLiteral(accounting)))
            }
            PortablePlan::BoundedLiteralClassRun(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((end, SearchAccounting::LiteralClassRunLiteral(accounting)))
            }
            PortablePlan::ReverseInner(plan) => {
                let (end, accounting) = plan.shortest_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    reverse_inner_search_limits(limits),
                )?;
                Ok((end, SearchAccounting::ReverseInner(accounting)))
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                let (end, accounting) = plan.shortest_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((end, SearchAccounting::PrefixClassAlternation(accounting)))
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                let (end, accounting) = plan.shortest_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((end, SearchAccounting::PrefixClassAlternation(accounting)))
            }
            PortablePlan::PureByteClassRepeat(plan) => {
                let (end, accounting) = plan.earliest_end_window(haystack, window, limits)?;
                Ok((end, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassRepeat(plan) => {
                let (end, accounting) = plan.earliest_end_window(haystack, window, limits)?;
                Ok((end, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassSequence(plan) => {
                let (end, accounting) = plan
                    .earliest_end_window(haystack, window, limits)
                    .map_err(SearchError::BoundedByteClassSequence)?;
                Ok((
                    end,
                    SearchAccounting::BoundedByteClassSequence(accounting),
                ))
            }
            PortablePlan::NullableOptionalChain(plan) => {
                let (end, accounting) = plan
                    .earliest_end_window(haystack, window, limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((end, SearchAccounting::NullableOptionalChain(accounting)))
            }
            PortablePlan::NullableFiniteTokenRepeat(plan) => {
                let (end, accounting) = plan
                    .earliest_end_window(haystack, window, limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((end, SearchAccounting::NullableOptionalChain(accounting)))
            }
            PortablePlan::ForwardAnchored(forward) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = forward.find_window(
                    haystack,
                    literal_window,
                    forward_anchored_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::DispatchedForwardAnchored(forward) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = forward.find_window(
                    haystack,
                    literal_window,
                    forward_anchored_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::ForwardEndFixed(fixed) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) =
                    fixed.find_window(haystack, literal_window, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(limits),
                )?;
                Ok((
                    end,
                    SearchAccounting::UnicodeFoldedLiteral(accounting.actual),
                ))
            }
            PortablePlan::K0(k0) => {
                let report = k0
                    .automaton
                    .prepare::<EarliestEnd>()
                    .search_window(haystack, window, limits)?;
                let accounting = report.accounting();
                Ok((report.into_output(), SearchAccounting::K0(accounting)))
            }
            PortablePlan::UnicodeWordRun(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::AsciiWordRun(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::BoundedWordClass(plan) => {
                let (end, accounting) = plan.shortest_window(haystack, window, limits)?;
                Ok((end, SearchAccounting::UnicodeWordRun(accounting)))
            }
            PortablePlan::FixedPredicateWord64(plan) => {
                let (end, accounting) = plan.earliest_end_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((end, SearchAccounting::FixedPredicateWord64(accounting)))
            }
            PortablePlan::UnicodeScalarRun(plan) => {
                let (end, accounting) = plan.shortest_match_window(
                    haystack,
                    fre_kernels::Window::new(window.start(), window.end()),
                    unicode_scalar_search_limits(limits),
                )?;
                Ok((end, SearchAccounting::UnicodeScalarRun(accounting)))
            }
            PortablePlan::LineDomainByteAtoms(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    window,
                    limits,
                    fre_kernels::LineDomainByteAtomsOperation::EarliestEnd,
                )?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::LineDomainByteAtoms(accounting),
                ))
            }
        }
    }

    /// Return the selected match end without materializing its start.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    #[allow(
        clippy::too_many_lines,
        reason = "each native owner projects its selected endpoint and concrete accounting explicitly"
    )]
    pub fn selected_end_accounted(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                let (matched, accounting) = literal.find(haystack, literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let (matched, accounting) =
                    literal_set.find(haystack, packed_literal_set_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::PackedLiteralSet(accounting),
                ))
            }
            PortablePlan::GuardedLiteralSet(plan) => {
                let (end, accounting) = plan.shortest_window(
                    haystack,
                    SearchWindow::full(haystack),
                    limits,
                )?;
                Ok((end, SearchAccounting::GuardedLiteralSet(accounting)))
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let (matched, accounting) =
                    literal_set.find(haystack, literal_set_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                let (matched, accounting) =
                    literal_set.find(haystack, literal_set_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::RequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find(haystack, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedRequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find(haystack, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::BoundedRequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find(haystack, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find(haystack, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::full(haystack),
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::full(haystack),
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::LiteralClassRunLiteral(plan) => {
                let (matched, accounting) =
                    plan.find(haystack, literal_class_run_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::LiteralClassRunSearch(plan) => {
                let (matched, accounting) =
                    plan.find(haystack, literal_class_run_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::BoundedLiteralClassRun(plan) => {
                let (matched, accounting) =
                    plan.find(haystack, literal_class_run_literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::ReverseInner(plan) => {
                let (matched, accounting) =
                    plan.find(haystack, reverse_inner_search_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ReverseInner(accounting),
                ))
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                let (matched, accounting) =
                    plan.find(haystack, prefix_class_alternation_search_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::PrefixClassAlternation(accounting),
                ))
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                let (matched, accounting) =
                    plan.find(haystack, prefix_class_alternation_search_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::PrefixClassAlternation(accounting),
                ))
            }
            PortablePlan::PureByteClassRepeat(plan) => {
                let (end, accounting) =
                    plan.selected_end_window(haystack, SearchWindow::full(haystack), limits)?;
                Ok((end, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassRepeat(plan) => {
                let (end, accounting) =
                    plan.selected_end_window(haystack, SearchWindow::full(haystack), limits)?;
                Ok((end, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassSequence(plan) => {
                let (end, accounting) = plan
                    .selected_end_window(haystack, SearchWindow::full(haystack), limits)
                    .map_err(SearchError::BoundedByteClassSequence)?;
                Ok((
                    end,
                    SearchAccounting::BoundedByteClassSequence(accounting),
                ))
            }
            PortablePlan::NullableOptionalChain(plan) => {
                let (end, accounting) = plan
                    .selected_end_window(haystack, SearchWindow::full(haystack), limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((end, SearchAccounting::NullableOptionalChain(accounting)))
            }
            PortablePlan::NullableFiniteTokenRepeat(plan) => {
                let (end, accounting) = plan
                    .selected_end_window(haystack, SearchWindow::full(haystack), limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((end, SearchAccounting::NullableOptionalChain(accounting)))
            }
            PortablePlan::ForwardAnchored(forward) => {
                let (matched, accounting) =
                    forward.find(haystack, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::DispatchedForwardAnchored(forward) => {
                let (matched, accounting) =
                    forward.find(haystack, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::ForwardEndFixed(fixed) => {
                let (matched, accounting) =
                    fixed.find(haystack, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::full(haystack),
                    unicode_folded_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|candidate| candidate.end()),
                    SearchAccounting::UnicodeFoldedLiteral(accounting.actual),
                ))
            }
            PortablePlan::K0(k0) => {
                let report = k0
                    .automaton
                    .prepare::<SelectedEnd>()
                    .search(haystack, limits)?;
                let accounting = report.accounting();
                Ok((report.into_output(), SearchAccounting::K0(accounting)))
            }
            PortablePlan::UnicodeWordRun(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::full(haystack), limits)?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::AsciiWordRun(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::full(haystack), limits)?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::BoundedWordClass(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::full(haystack), limits)?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::UnicodeWordRun(accounting),
                ))
            }
            PortablePlan::FixedPredicateWord64(plan) => {
                let (end, accounting) =
                    plan.selected_end(haystack, fixed_predicate_word64_search_limits(limits))?;
                Ok((end, SearchAccounting::FixedPredicateWord64(accounting)))
            }
            PortablePlan::UnicodeScalarRun(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    fre_kernels::Window::full(haystack),
                    unicode_scalar_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::UnicodeScalarRun(accounting),
                ))
            }
            PortablePlan::LineDomainByteAtoms(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::full(haystack),
                    limits,
                    fre_kernels::LineDomainByteAtomsOperation::SelectedEnd,
                )?;
                Ok((
                    matched.map(Match::end),
                    SearchAccounting::LineDomainByteAtoms(accounting),
                ))
            }
        }
    }

    /// Compatibility alias for [`Self::selected_end_accounted`].
    pub fn selected_end(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        self.selected_end_accounted(haystack, limits)
    }

    /// Return only the profile-selected match end.
    ///
    /// This value-only projection shares the exact selected-span path with
    /// [`Self::find_value`] and therefore does not construct facade diagnostic
    /// accounting. Its automatic scratch lifetime is the same as
    /// [`Self::find_value`].
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as [`Self::selected_end`].
    pub fn selected_end_value(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        self.find_value(haystack, limits)
            .map(|matched| matched.map(Match::end))
    }

    /// Return the profile-selected leftmost-first match.
    ///
    /// This is the Rust-compatible convenience API. Search work has no
    /// caller-visible quota. Generic K0 scratch is admitted from the
    /// construction-bounded automaton and retained automatically; cache
    /// capacity may grow transactionally as later operations demand it.
    ///
    /// Use [`Self::find_with_limits`] when a recoverable work or scratch
    /// refusal is required, and [`Self::find_accounted`] when the exact
    /// execution receipt is also required.
    ///
    /// # Panics
    ///
    /// Panics if fallible scratch allocation fails or a validated internal
    /// invariant is violated. These failures are never converted into no
    /// match.
    #[must_use]
    #[inline]
    pub fn find(&self, haystack: &[u8]) -> Option<Match> {
        self.try_find_ordinary(haystack)
            .unwrap_or_else(|error| panic!("PortableRegex::find failed: {error}"))
    }

    #[inline]
    fn try_find_ordinary(&self, haystack: &[u8]) -> Result<Option<Match>, SearchError> {
        match &self.plan {
            PortablePlan::BoundedWordClass(plan) => {
                if let Some(matched) = plan.ordinary_find_full_unmetered(haystack) {
                    return Ok(matched);
                }
            }
            PortablePlan::UnicodeScalarRun(plan) => {
                if let Some(matched) = plan.ordinary_find_full_unmetered(haystack) {
                    #[cfg(test)]
                    unicode_scalar_run_ordinary_facade_probe::record_span();
                    return Ok(matched.map(|(start, end)| Match { start, end }));
                }
            }
            PortablePlan::ForwardAnchored(plan) => {
                if let Some(result) = plan.ordinary_find_full_unmetered(haystack) {
                    #[cfg(test)]
                    forward_anchored_ordinary_facade_probe::record_span();
                    return result
                        .map(|matched| matched.map(|(start, end)| Match { start, end }))
                        .map_err(SearchError::from);
                }
            }
            PortablePlan::DispatchedForwardAnchored(plan) => {
                if let Some(result) = plan.ordinary_find_full_unmetered(haystack) {
                    #[cfg(test)]
                    forward_anchored_ordinary_facade_probe::record_span();
                    return result
                        .map(|matched| matched.map(|(start, end)| Match { start, end }))
                        .map_err(SearchError::from);
                }
            }
            PortablePlan::ForwardEndFixed(plan) => {
                if let Some(result) = plan.ordinary_find_full_unmetered(haystack) {
                    #[cfg(test)]
                    forward_anchored_ordinary_facade_probe::record_span();
                    return result
                        .map(|matched| matched.map(|(start, end)| Match { start, end }))
                        .map_err(SearchError::from);
                }
            }
            PortablePlan::K0(k0) => {
                if let Some(plan) = k0.exclusive.line()
                    && haystack.len() >= plan.minimum_input_bytes()
                    && let Some(matched) = plan.try_ordinary_find_full(haystack)
                {
                    return Ok(matched.map(|(start, end)| Match { start, end }));
                }
                if let Some(plan) = k0.uri_exists
                    && let Some(matched) = plan.try_ordinary_find_full(haystack)
                {
                    return Ok(matched.map(|(start, end)| Match { start, end }));
                }
            }
            // Every other family deliberately keeps its existing ordinary
            // fallback.
            _ => {}
        }
        let window = SearchWindow::full(haystack);
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                #[cfg(test)]
                exact_literal_ordinary_facade_probe::record_span();
                if let Some(executor) = literal.ordinary_executor() {
                    executor
                        .find_window_value(haystack, LiteralWindow::full(haystack))
                        .map(|matched| matched.map(|(start, end)| Match { start, end }))
                        .map_err(SearchError::from)
                } else {
                    literal
                        .find_full_value(haystack, literal_limits(SearchLimits::unlimited()))
                        .map(|matched| matched.map(|(start, end)| Match { start, end }))
                        .map_err(SearchError::from)
                }
            }
            PortablePlan::K0(k0) => match k0.pooled_value(
                K0PooledValueOperation::Span,
                K0PooledValueExecution::OrdinarySpan,
                haystack,
                window,
                SearchLimits::unlimited(),
                SearchSessionLimits::unlimited(),
                self.report.minimum_match_bytes,
            )? {
                Some(K0PooledValue::Span(value)) => Ok(value.map(|span| Match {
                    start: span.start(),
                    end: span.end(),
                })),
                Some(K0PooledValue::Exists(_)) => unreachable!("span pool returned existence"),
                None => k0
                    .automaton
                    .prepare::<Span>()
                    .search_window(haystack, window, SearchLimits::unlimited())
                    .map(|report| {
                        report.into_output().map(|span| Match {
                            start: span.start(),
                            end: span.end(),
                        })
                    })
                    .map_err(SearchError::from),
            },
            PortablePlan::LiteralClassRunLiteral(plan) => {
                #[cfg(test)]
                literal_class_run_literal_ordinary_find_probe::record();
                plan.find_full_ordinary_value(haystack)
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::LiteralClassRunSearch(plan)
                if plan.boundary_semantics()
                    == LiteralClassRunLiteralBoundarySemantics::CompleteAsciiWordRun =>
            {
                #[cfg(test)]
                literal_class_run_search_ordinary_facade_probe::record_span();
                plan.find_ascii_word_suffix_full_ordinary_value(haystack)
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::ReverseInner(plan) => {
                if let Some(matched) = plan
                    .ordinary_find_full_unmetered(haystack)
                    .map_err(SearchError::from)?
                {
                    #[cfg(test)]
                    reverse_inner_ordinary_facade_probe::record_span();
                    return Ok(matched.map(|(start, end)| Match { start, end }));
                }
                self.find_window_value(haystack, window, SearchLimits::unlimited())
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let matched = if let Some(ordinary) =
                    literal_set.try_ordinary_full_window_executor(haystack.len())
                {
                    #[cfg(test)]
                    packed_literal_set_ordinary_facade_probe::record_span();
                    ordinary.find_window_value(haystack, literal_window)
                } else {
                    literal_set.find_window_value(
                        haystack,
                        literal_window,
                        PackedLiteralSetSearchLimits::unlimited(),
                    )
                }?;
                Ok(matched.map(|(start, end)| Match { start, end }))
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                #[cfg(test)]
                literal_set_compact_ordinary_facade_probe::record_span();
                literal_set
                    .ordinary_executor()
                    .find_window_value(haystack, LiteralWindow::full(haystack))
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let matched = if let Some(ordinary) =
                    literal_set.ordinary_ascii_folded_for_input(haystack.len())
                {
                    #[cfg(test)]
                    {
                        literal_set_dfa_ordinary_facade_probe::record_span();
                        ascii_folded_literal_set_ordinary_facade_probe::record_span();
                    }
                    ordinary
                        .find_full_value(haystack)
                        .map_err(SearchError::from)
                } else if let Some(ordinary) = literal_set.ordinary_executor() {
                    #[cfg(test)]
                    literal_set_dfa_ordinary_facade_probe::record_span();
                    ordinary
                        .find_window_value(haystack, literal_window)
                        .map_err(SearchError::from)
                } else {
                    literal_set
                        .find_window(
                            haystack,
                            literal_window,
                            LiteralSetSearchLimits::unlimited(),
                        )
                        .map(|(matched, _)| matched)
                        .map_err(SearchError::from)
                }?;
                Ok(matched.map(|(start, end)| Match { start, end }))
            }
            PortablePlan::RequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                #[cfg(test)]
                required_literal_ordinary_find_facade_probe::record();
                required
                    .find_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::DispatchedRequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                #[cfg(test)]
                required_literal_ordinary_find_facade_probe::record();
                required
                    .find_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::UnicodeWordRun(plan) => Ok(plan.find_full_prepared(haystack)),
            PortablePlan::AsciiWordRun(plan) => Ok(plan.find_full_prepared(haystack)),
            PortablePlan::BoundedRequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                #[cfg(test)]
                bounded_required_literal_ordinary_facade_probe::record_span();
                required
                    .find_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required)
                if !required.anchors().start && !required.anchors().end =>
            {
                #[cfg(test)]
                bounded_required_literal_ordinary_facade_probe::record_span();
                required
                    .find_window_value(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        required_literal_limits(SearchLimits::unlimited()),
                    )
                    .map(|matched| matched.map(|(start, end)| Match { start, end }))
                    .map_err(SearchError::from)
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                if let Some(matched) = plan.ordinary_find_full_unmetered(haystack) {
                    #[cfg(test)]
                    prefix_class_alternation_ordinary_facade_probe::record_span();
                    Ok(matched.map(|(start, end)| Match { start, end }))
                } else {
                    plan.find_in(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        prefix_class_alternation_search_limits(SearchLimits::unlimited()),
                    )
                    .map(|(matched, _)| {
                        matched.map(|(start, end)| Match { start, end })
                    })
                    .map_err(SearchError::from)
                }
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                if let Some(matched) = plan.ordinary_find_full_unmetered(haystack) {
                    #[cfg(test)]
                    prefix_class_alternation_ordinary_facade_probe::record_span();
                    Ok(matched.map(|(start, end)| Match { start, end }))
                } else {
                    plan.find_in(
                        haystack,
                        LiteralWindow::new(window.start(), window.end()),
                        prefix_class_alternation_search_limits(SearchLimits::unlimited()),
                    )
                    .map(|(matched, _)| {
                        matched.map(|(start, end)| Match { start, end })
                    })
                    .map_err(SearchError::from)
                }
            }
            PortablePlan::PureByteClassRepeat(plan) => {
                Ok(plan.ordinary_find_full_unmetered(haystack))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(SearchLimits::unlimited()),
                )
                .map(|matched| {
                    matched.map(|candidate| Match {
                        start: candidate.start(),
                        end: candidate.end(),
                    })
                })
                .map_err(SearchError::from),
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => plan
                .find_window_value(
                    haystack,
                    window,
                    required_literal_limits(SearchLimits::unlimited()),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::NullableFiniteTokenRepeat(plan) => plan
                .find_full_ordinary_value(haystack)
                .map_err(SearchError::NullableOptionalChain),
            _ => self.find_window_value(haystack, window, SearchLimits::unlimited()),
        }
    }

    /// Return the selected match with explicit limits and accounting.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    pub fn find_accounted(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<Match>, SearchAccounting), SearchError> {
        self.find_window(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return only the profile-selected leftmost-first match under explicit
    /// work and scratch limits.
    ///
    /// This is the finite value-only counterpart to [`Self::find`]. It preserves the
    /// same selected plan, checked execution limits and typed failures. K0
    /// stays outside the facade [`SearchAccounting`] projection boundary;
    /// native owners retain their existing concrete search implementations.
    /// Under the default limits, generic K0 plans automatically retain bounded
    /// scratch in this immutable matcher and reuse it on later calls; callers
    /// do not need to construct a search session.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    pub fn find_with_limits(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        self.find_window_value(haystack, SearchWindow::full(haystack), limits)
    }

    /// Compatibility alias for [`Self::find_with_limits`].
    pub fn find_value(
        &self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        self.find_with_limits(haystack, limits)
    }

    /// Return the profile-selected leftmost-first match while retaining the
    /// exact original haystack.
    ///
    /// This is the borrowed-byte companion to [`Self::find_accounted`]. It preserves the
    /// same selected span and execution accounting, while [`ByteMatch`]
    /// supplies the pinned Rust bytes match accessors and conversions.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if scratch/work limits refuse the operation.
    pub fn find_borrowed<'h>(
        &self,
        haystack: &'h [u8],
        limits: SearchLimits,
    ) -> Result<(Option<ByteMatch<'h>>, SearchAccounting), SearchError> {
        let (matched, accounting) = self.find_accounted(haystack, limits)?;
        Ok((matched.map(|span| ByteMatch { haystack, span }), accounting))
    }

    /// Return only the profile-selected leftmost-first match while retaining
    /// the exact original haystack.
    ///
    /// This is the value-only companion to [`Self::find_borrowed`]. It uses
    /// the exact selected-span route and automatic scratch lifetime of
    /// [`Self::find_value`] without constructing facade diagnostic accounting.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same work and scratch limits as
    /// [`Self::find_value`].
    pub fn find_borrowed_value<'h>(
        &self,
        haystack: &'h [u8],
        limits: SearchLimits,
    ) -> Result<Option<ByteMatch<'h>>, SearchError> {
        self.find_value(haystack, limits)
            .map(|matched| matched.map(|span| ByteMatch { haystack, span }))
    }

    /// Iterate over every non-overlapping match with Rust bytes empty-match
    /// progress and original-haystack assertion context.
    ///
    /// K0 prepares one reusable adaptive workspace before iteration and may
    /// grow its cache transactionally during contextual searches. Native plans
    /// retain their selected dispatch. Iterator items are errors so a resource
    /// refusal is never silently treated as exhaustion.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if reusable K0 workspace construction exceeds
    /// `limits.session`. Per-search and whole-iterator failures are yielded as
    /// [`PortableFindIterError`] items.
    pub fn find_iter<'r, 'h>(
        &'r self,
        haystack: &'h [u8],
        limits: PortableFindIterLimits,
    ) -> Result<PortableMatches<'r, 'h>, SearchError> {
        self.find_iter_with_progress(haystack, limits, EmptyMatchProgress::Byte)
    }

    /// Iterate over every non-overlapping byte match through the value-only
    /// selected-span route.
    ///
    /// This retains the search-call cap and Rust bytes empty-match progress of
    /// [`Self::find_iter`], but deliberately does not aggregate or expose
    /// unified per-iterator search accounting. That permits value-only K0
    /// accelerators to participate without requiring facade receipts. The
    /// fresh adaptive K0 session may grow retained cache capacity during
    /// iteration under `limits.search`, but this value-only API deliberately
    /// does not expose an aggregate growth receipt. Use [`Self::find_iter`]
    /// when reported iterator accounting is required.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if reusable session construction exceeds
    /// `limits.session`. Per-search failures and the whole-iterator call cap
    /// are yielded as [`PortableFindIterError`] items.
    pub fn find_iter_value<'r, 'h>(
        &'r self,
        haystack: &'h [u8],
        limits: PortableFindIterLimits,
    ) -> Result<PortableValueMatches<'r, 'h>, SearchError> {
        self.find_iter_value_at(haystack, 0, limits)
    }

    /// Iterate over every non-overlapping byte match at or after `start`
    /// through the value-only selected-span route.
    ///
    /// Assertions inspect the complete original haystack and returned offsets
    /// remain relative to it. Empty-match progress and resource behavior are
    /// identical to [`Self::find_iter_value`]. An invalid `start` is yielded
    /// as a [`PortableFindIterError`] item after the iterator-level search-call
    /// cap admits that search, matching the zero-origin iterator's resource
    /// precedence.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if reusable session construction exceeds
    /// `limits.session`. Per-search failures and the whole-iterator call cap
    /// are yielded as [`PortableFindIterError`] items.
    pub fn find_iter_value_at<'r, 'h>(
        &'r self,
        haystack: &'h [u8],
        start: usize,
        limits: PortableFindIterLimits,
    ) -> Result<PortableValueMatches<'r, 'h>, SearchError> {
        let native_cursor = self.native_search_cursor(haystack);
        let session = self.search_session(limits.session)?;
        Ok(PortableValueMatches {
            session,
            state: PortableValueMatchIterState::new_at(
                haystack,
                start,
                limits.run(),
                native_cursor,
            ),
        })
    }

    /// Visit every complete non-overlapping match when the selected plan has
    /// a direct bounded traversal.
    ///
    /// `Ok(None)` means this selected plan has no direct visitor; the callback
    /// is not invoked and callers may fall back to [`Self::find_iter_value`].
    /// Supported plans preflight the complete source-independent resource
    /// envelope before reading the haystack or invoking the first callback.
    ///
    /// # Errors
    ///
    /// Returns a typed operation-specific refusal for a supported plan. A
    /// refusal occurs before the first callback.
    pub fn try_visit_spans<F>(
        &self,
        haystack: &[u8],
        limits: PortableSpanVisitLimits,
        mut visitor: F,
    ) -> Result<Option<PortableSpanVisitResult>, PortableSpanVisitError>
    where
        F: FnMut(Match),
    {
        match &self.plan {
            PortablePlan::ExactLiteral(plan) => {
                let result = plan.visit_spans(haystack, limits.exact_literal, |span| {
                    visitor(Match {
                        start: span.start,
                        end: span.end,
                    });
                })?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::ExactLiteral(result.accounting),
                }))
            }
            PortablePlan::LiteralClassRunLiteral(plan) => {
                let result = plan.visit_spans(
                    haystack,
                    limits.literal_class_run_literal,
                    |span| {
                        visitor(Match {
                            start: span.start,
                            end: span.end,
                        });
                    },
                )?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::LiteralClassRunLiteral(
                        result.accounting,
                    ),
                }))
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                let result = plan.visit_spans(
                    haystack,
                    limits.prefix_class_alternation,
                    |span| {
                        visitor(Match {
                            start: span.start,
                            end: span.end,
                        });
                    },
                )?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::PrefixClassAlternation(
                        result.accounting,
                    ),
                }))
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                let result = plan.visit_spans(
                    haystack,
                    limits.prefix_class_alternation,
                    |span| {
                        visitor(Match {
                            start: span.start,
                            end: span.end,
                        });
                    },
                )?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::PrefixClassAlternation(
                        result.accounting,
                    ),
                }))
            }
            PortablePlan::K0(plan) => {
                if let Some(casefold) = plan.k0_casefold_prefix_class_span {
                    let result = k0_casefold_prefix_class_span::visit(
                        casefold,
                        haystack,
                        limits.k0_casefold_prefix_class,
                        |start, end| visitor(Match { start, end }),
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::K0CasefoldPrefixClass(
                            result.accounting,
                        ),
                    }));
                }
                if let Some(lazy) = plan.lazy_delimited_repeat.as_ref() {
                    let result = lazy.visit_spans(
                        haystack,
                        limits.lazy_delimited_repeat,
                        |span| {
                            visitor(Match {
                                start: span.start,
                                end: span.end,
                            });
                        },
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::LazyDelimitedRepeat(
                            result.accounting,
                        ),
                    }));
                }
                if let Some(corridor) = plan.greedy_delimited_corridor.as_deref() {
                    let result = corridor.visit_spans(
                        haystack,
                        limits.greedy_delimited_corridor,
                        |span| {
                            visitor(Match {
                                start: span.start,
                                end: span.end,
                            });
                        },
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::GreedyDelimitedCorridor(
                            result.accounting,
                        ),
                    }));
                }
                if let Some(phrase) = plan.unicode_token_phrase {
                    let result = phrase.visit_spans(
                        haystack,
                        limits.unicode_token_phrase,
                        |span| {
                            visitor(Match {
                                start: span.start,
                                end: span.end,
                            });
                        },
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::UnicodeTokenPhrase(
                            result.accounting,
                        ),
                    }));
                }
                let Some(greedy) = plan.greedy_class_literal_tail.as_ref() else {
                    return Ok(None);
                };
                let result = greedy.visit_spans(
                    haystack,
                    limits.greedy_class_literal_tail,
                    |span| {
                        visitor(Match {
                            start: span.start,
                            end: span.end,
                        });
                    },
                )?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::GreedyClassLiteralTail(
                        result.accounting,
                    ),
                }))
            }
            _ => Ok(None),
        }
    }

    pub(crate) fn find_iter_utf8<'r, 'h>(
        &'r self,
        haystack: &'h str,
        limits: PortableFindIterLimits,
    ) -> Result<PortableMatches<'r, 'h>, SearchError> {
        self.find_iter_with_progress(haystack.as_bytes(), limits, EmptyMatchProgress::Utf8Scalar)
    }

    fn find_iter_with_progress<'r, 'h>(
        &'r self,
        haystack: &'h [u8],
        limits: PortableFindIterLimits,
        empty_match_progress: EmptyMatchProgress,
    ) -> Result<PortableMatches<'r, 'h>, SearchError> {
        let native_cursor = self.native_search_cursor(haystack);
        let session = self.search_session(limits.session)?;
        Ok(PortableMatches {
            session,
            state: PortableMatchIterState::new(
                haystack,
                limits.run(),
                empty_match_progress,
                native_cursor,
            ),
        })
    }

    /// Iterate over every non-overlapping match while retaining the exact
    /// original haystack in each emitted [`ByteMatch`].
    ///
    /// Selection, empty-match progress, workspace reuse, resource limits and
    /// accounting are identical to [`Self::find_iter`]. The companion
    /// [`PortableByteMatches`] iterator only projects each selected span into
    /// the pinned Rust bytes match-value contract.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same construction contract as
    /// [`Self::find_iter`]. Per-search and whole-iterator failures are yielded
    /// as [`PortableFindIterError`] items.
    pub fn find_iter_borrowed<'r, 'h>(
        &'r self,
        haystack: &'h [u8],
        limits: PortableFindIterLimits,
    ) -> Result<PortableByteMatches<'r, 'h>, SearchError> {
        Ok(PortableByteMatches {
            inner: self.find_iter(haystack, limits)?,
        })
    }

    /// Return the selected match at or after `start`.
    ///
    /// Assertions inspect the complete original haystack and returned offsets
    /// remain relative to it. Unlike the pinned Rust API, an out-of-bounds
    /// `start` is returned as a typed error instead of panicking.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid start or a resource refusal.
    pub fn find_at(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, SearchAccounting), SearchError> {
        self.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Return only the selected match at or after `start`.
    ///
    /// Assertions inspect the complete original haystack. Range validation,
    /// execution limits and typed failures are identical to [`Self::find_at`].
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid start or a resource refusal.
    pub fn find_at_value(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        self.find_window_value(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Return the selected match at or after `start` while retaining the
    /// complete original haystack.
    ///
    /// This is the ranged companion to [`Self::find_borrowed`]. Assertions
    /// still inspect bytes before `start`, and [`ByteMatch`] offsets and bytes
    /// are both relative to the unsliced original haystack.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`Self::find_at`].
    pub fn find_at_borrowed<'h>(
        &self,
        haystack: &'h [u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<ByteMatch<'h>>, SearchAccounting), SearchError> {
        let (matched, accounting) = self.find_at(haystack, start, limits)?;
        Ok((matched.map(|span| ByteMatch { haystack, span }), accounting))
    }

    /// Return only the selected match at or after `start` while retaining the
    /// complete original haystack.
    ///
    /// This is the ranged value-only companion to
    /// [`Self::find_at_borrowed`]. It preserves the exact range validation,
    /// original-haystack assertion context and automatic scratch lifetime of
    /// [`Self::find_at_value`] without constructing facade diagnostic
    /// accounting.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`Self::find_at_value`].
    pub fn find_at_borrowed_value<'h>(
        &self,
        haystack: &'h [u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<ByteMatch<'h>>, SearchError> {
        self.find_at_value(haystack, start, limits)
            .map(|matched| matched.map(|span| ByteMatch { haystack, span }))
    }

    /// Search a range while assertions retain original-haystack context.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid window or a resource refusal.
    #[allow(
        clippy::too_many_lines,
        reason = "each authenticated native owner projects the same operation-specific accounting without erasing its concrete type"
    )]
    pub fn find_window(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, SearchAccounting), SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) =
                    literal.find_window(haystack, literal_window, literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    packed_literal_set_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::PackedLiteralSet(accounting),
                ))
            }
            PortablePlan::GuardedLiteralSet(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((
                    matched,
                    SearchAccounting::GuardedLiteralSet(accounting),
                ))
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    literal_set_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = literal_set.find_window(
                    haystack,
                    literal_window,
                    literal_set_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::LiteralSetDfa(accounting),
                ))
            }
            PortablePlan::RequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::BoundedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = required.find_window(
                    haystack,
                    literal_window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    window,
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::RequiredLiteral(accounting),
                ))
            }
            PortablePlan::LiteralClassRunLiteral(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::LiteralClassRunSearch(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::BoundedLiteralClassRun(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::LiteralClassRunLiteral(accounting),
                ))
            }
            PortablePlan::ReverseInner(plan) => {
                let (matched, accounting) = plan.find_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    reverse_inner_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::ReverseInner(accounting),
                ))
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                let (matched, accounting) = plan.find_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::PrefixClassAlternation(accounting),
                ))
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                let (matched, accounting) = plan.find_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::PrefixClassAlternation(accounting),
                ))
            }
            PortablePlan::PureByteClassRepeat(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassRepeat(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::PureByteClassRepeat(accounting)))
            }
            PortablePlan::BoundedByteClassSequence(plan) => {
                let (matched, accounting) = plan
                    .find_window(haystack, window, limits)
                    .map_err(SearchError::BoundedByteClassSequence)?;
                Ok((
                    matched,
                    SearchAccounting::BoundedByteClassSequence(accounting),
                ))
            }
            PortablePlan::NullableOptionalChain(plan) => {
                let (matched, accounting) = plan
                    .find_window(haystack, window, limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((
                    matched,
                    SearchAccounting::NullableOptionalChain(accounting),
                ))
            }
            PortablePlan::NullableFiniteTokenRepeat(plan) => {
                let (matched, accounting) = plan
                    .find_window(haystack, window, limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((
                    matched,
                    SearchAccounting::NullableOptionalChain(accounting),
                ))
            }
            PortablePlan::ForwardAnchored(forward) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = forward.find_window(
                    haystack,
                    literal_window,
                    forward_anchored_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::DispatchedForwardAnchored(forward) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) = forward.find_window(
                    haystack,
                    literal_window,
                    forward_anchored_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::ForwardEndFixed(fixed) => {
                let literal_window = LiteralWindow::new(window.start(), window.end());
                let (matched, accounting) =
                    fixed.find_window(haystack, literal_window, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::ForwardAnchored(accounting),
                ))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|candidate| Match {
                        start: candidate.start(),
                        end: candidate.end(),
                    }),
                    SearchAccounting::UnicodeFoldedLiteral(accounting.actual),
                ))
            }
            PortablePlan::K0(k0) => {
                let report = k0
                    .automaton
                    .prepare::<Span>()
                    .search_window(haystack, window, limits)?;
                let accounting = report.accounting();
                let matched = report.into_output().map(|span| Match {
                    start: span.start(),
                    end: span.end(),
                });
                Ok((matched, SearchAccounting::K0(accounting)))
            }
            PortablePlan::UnicodeWordRun(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::UnicodeWordRun(accounting)))
            }
            PortablePlan::AsciiWordRun(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::UnicodeWordRun(accounting)))
            }
            PortablePlan::BoundedWordClass(plan) => {
                let (matched, accounting) = plan.find_window(haystack, window, limits)?;
                Ok((matched, SearchAccounting::UnicodeWordRun(accounting)))
            }
            PortablePlan::FixedPredicateWord64(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::FixedPredicateWord64(accounting),
                ))
            }
            PortablePlan::UnicodeScalarRun(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    fre_kernels::Window::new(window.start(), window.end()),
                    unicode_scalar_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::UnicodeScalarRun(accounting),
                ))
            }
            PortablePlan::LineDomainByteAtoms(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    window,
                    limits,
                    fre_kernels::LineDomainByteAtomsOperation::Span,
                )?;
                Ok((
                    matched,
                    SearchAccounting::LineDomainByteAtoms(accounting),
                ))
            }
        }
    }

    /// Return only the selected match wholly inside a search range.
    ///
    /// Assertions retain original-haystack context. K0 executes its typed span
    /// contract directly; native plans retain their existing concrete search
    /// implementations.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid window or a resource refusal.
    #[allow(
        clippy::too_many_lines,
        reason = "each native owner retains its direct value-only span projection"
    )]
    pub fn find_window_value(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => literal
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::LiteralSetCompact(literal_set) => literal_set
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_set_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::PackedLiteralSet(literal_set) => literal_set
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    packed_literal_set_limits(limits),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::GuardedLiteralSet(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::LiteralSetDfa(literal_set) => literal_set
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_set_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::RequiredLiteral(required) => required
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::DispatchedRequiredLiteral(required) => required
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::BoundedRequiredLiteral(required) => required
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => required
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    required_literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => plan
                .find_window_value(haystack, window, required_literal_limits(limits))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => plan
                .find_window_value(haystack, window, required_literal_limits(limits))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::LiteralClassRunLiteral(plan) => plan
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::LiteralClassRunSearch(plan) => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::BoundedLiteralClassRun(plan) => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_class_run_literal_limits(limits),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::ReverseInner(plan) => plan
                .find_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    reverse_inner_search_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::PrefixClassAlternation(plan) => plan
                .find_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::DispatchedPrefixClassAlternation(plan) => plan
                .find_in(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    prefix_class_alternation_search_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::PureByteClassRepeat(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::ForwardAnchored(forward) => forward
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    forward_anchored_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::DispatchedForwardAnchored(forward) => forward
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    forward_anchored_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::ForwardEndFixed(fixed) => fixed
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    forward_anchored_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::K0(k0) => match k0.pooled_value(
                K0PooledValueOperation::Span,
                K0PooledValueExecution::Canonical,
                haystack,
                window,
                limits,
                SearchSessionLimits::default(),
                self.report.minimum_match_bytes,
            )? {
                Some(K0PooledValue::Span(value)) => Ok(value.map(|span| Match {
                    start: span.start(),
                    end: span.end(),
                })),
                Some(K0PooledValue::Exists(_)) => unreachable!("span pool returned existence"),
                None => k0
                    .automaton
                    .prepare::<Span>()
                    .search_window(haystack, window, limits)
                    .map(|report| {
                        report.into_output().map(|span| Match {
                            start: span.start(),
                            end: span.end(),
                        })
                    })
                    .map_err(SearchError::from),
            },
            PortablePlan::UnicodeFoldedLiteral(plan) => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    unicode_folded_literal_limits(limits),
                )
                .map(|matched| {
                    matched.map(|candidate| Match {
                        start: candidate.start(),
                        end: candidate.end(),
                    })
                })
                .map_err(SearchError::from),
            PortablePlan::UnicodeWordRun(plan) => plan
                .find_window(haystack, window, limits)
                .map(|(matched, _)| matched)
                .map_err(SearchError::from),
            PortablePlan::AsciiWordRun(plan) => plan
                .find_window(haystack, window, limits)
                .map(|(matched, _)| matched)
                .map_err(SearchError::from),
            PortablePlan::BoundedWordClass(plan) => plan
                .find_window(haystack, window, limits)
                .map(|(matched, _)| matched)
                .map_err(SearchError::from),
            PortablePlan::BoundedByteClassRepeat(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            PortablePlan::BoundedByteClassSequence(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::BoundedByteClassSequence),
            PortablePlan::NullableOptionalChain(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::NullableFiniteTokenRepeat(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::NullableOptionalChain),
            PortablePlan::FixedPredicateWord64(plan) => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::UnicodeScalarRun(plan) => plan
                .find_window_value(
                    haystack,
                    fre_kernels::Window::new(window.start(), window.end()),
                    unicode_scalar_search_limits(limits),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortablePlan::LineDomainByteAtoms(plan) => plan
                .find_window_value(haystack, window, limits)
                .map_err(SearchError::from),
        }
    }

    fn native_search_cursor<'r, 'h>(
        &'r self,
        haystack: &'h [u8],
    ) -> Option<PortableNativeSearchCursor<'r, 'h>> {
        match &self.plan {
            #[cfg(not(feature = "static-dispatch"))]
            PortablePlan::PackedLiteralSet(plan) => plan
                .search_cursor(haystack)
                .map(PortableNativeSearchCursor::PackedLiteralSet),
            PortablePlan::FixedPredicateWord64(plan) => Some(
                PortableNativeSearchCursor::FixedPredicate(plan.search_cursor(haystack)),
            ),
            PortablePlan::PrefixClassAlternation(plan) => Some(
                PortableNativeSearchCursor::PrefixClass(plan.search_cursor(haystack)),
            ),
            PortablePlan::DispatchedPrefixClassAlternation(plan) => Some(
                PortableNativeSearchCursor::DispatchedPrefixClass(plan.search_cursor(haystack)),
            ),
            PortablePlan::UnicodeScalarRun(plan) => Some(
                PortableNativeSearchCursor::UnicodeScalarRun(plan.search_cursor(haystack)),
            ),
            PortablePlan::LineDomainByteAtoms(plan) => Some(
                PortableNativeSearchCursor::LineDomainByteAtoms(plan.search_cursor(haystack)),
            ),
            _ => None,
        }
    }

    #[allow(
        clippy::too_many_lines,
        reason = "each native owner projects its span and exact iterator work without facade accounting"
    )]
    fn find_iter_at(
        &self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, u64), SearchError> {
        let window = LiteralWindow::new(start, haystack.len());
        match &self.plan {
            PortablePlan::ExactLiteral(literal) => {
                let (matched, accounting) =
                    literal.find_window(haystack, window, literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.linear_terms).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::PackedLiteralSet(literal_set) => {
                let (matched, accounting) =
                    literal_set.find_window(haystack, window, packed_literal_set_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.work_upper_bound).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::GuardedLiteralSet(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::new(start, haystack.len()),
                    limits,
                )?;
                Ok((
                    matched,
                    u64::try_from(accounting.upper_bounds.total_work).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::LiteralSetDfa(literal_set) => {
                let (matched, accounting) =
                    literal_set.find_window(haystack, window, literal_set_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.transitions_upper_bound).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::LiteralSetCompact(literal_set) => {
                let (matched, accounting) =
                    literal_set.find_window(haystack, window, literal_set_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.transitions_upper_bound).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::RequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find_window(haystack, window, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::DispatchedRequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find_window(haystack, window, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::BoundedRequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find_window(haystack, window, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => {
                let (matched, accounting) =
                    required.find_window(haystack, window, required_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::UniversalFiniteGreedyCorridor(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::new(start, haystack.len()),
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::BoundedDelimitedSegmentRepeat(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::new(start, haystack.len()),
                    required_literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::LiteralClassRunLiteral(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, window, literal_class_run_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::LiteralClassRunSearch(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, window, literal_class_run_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::BoundedLiteralClassRun(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, window, literal_class_run_literal_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::ReverseInner(plan) => {
                let (matched, accounting) = plan.find_in(
                    haystack,
                    window,
                    reverse_inner_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.upper_bounds.work).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::PrefixClassAlternation(plan) => {
                let (matched, accounting) = plan.find_in(
                    haystack,
                    window,
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.upper_bounds.work).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::DispatchedPrefixClassAlternation(plan) => {
                let (matched, accounting) = plan.find_in(
                    haystack,
                    window,
                    prefix_class_alternation_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.upper_bounds.work).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::PureByteClassRepeat(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)?;
                Ok((matched, accounting.actual_work))
            }
            PortablePlan::BoundedByteClassRepeat(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)?;
                Ok((matched, accounting.actual_work))
            }
            PortablePlan::BoundedByteClassSequence(plan) => {
                let (matched, accounting) = plan
                    .find_window(haystack, SearchWindow::new(start, haystack.len()), limits)
                    .map_err(SearchError::BoundedByteClassSequence)?;
                Ok((matched, accounting.actual_work))
            }
            PortablePlan::NullableOptionalChain(plan) => {
                let (matched, accounting) = plan
                    .find_window(haystack, SearchWindow::new(start, haystack.len()), limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((matched, accounting.actual_work))
            }
            PortablePlan::NullableFiniteTokenRepeat(plan) => {
                let (matched, accounting) = plan
                    .find_window(haystack, SearchWindow::new(start, haystack.len()), limits)
                    .map_err(SearchError::NullableOptionalChain)?;
                Ok((matched, accounting.actual_work))
            }
            PortablePlan::ForwardAnchored(forward) => {
                let (matched, accounting) =
                    forward.find_window(haystack, window, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::DispatchedForwardAnchored(forward) => {
                let (matched, accounting) =
                    forward.find_window(haystack, window, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::ForwardEndFixed(fixed) => {
                let (matched, accounting) =
                    fixed.find_window(haystack, window, forward_anchored_limits(limits))?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.work_upper_bound,
                ))
            }
            PortablePlan::UnicodeFoldedLiteral(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, window, unicode_folded_literal_limits(limits))?;
                Ok((
                    matched.map(|candidate| Match {
                        start: candidate.start(),
                        end: candidate.end(),
                    }),
                    u64::try_from(accounting.actual.work).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::UnicodeWordRun(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)?;
                Ok((matched, accounting.work()))
            }
            PortablePlan::AsciiWordRun(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)?;
                Ok((matched, accounting.work()))
            }
            PortablePlan::BoundedWordClass(plan) => {
                let (matched, accounting) =
                    plan.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)?;
                Ok((matched, accounting.work()))
            }
            PortablePlan::FixedPredicateWord64(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(start, haystack.len()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.actual.work,
                ))
            }
            PortablePlan::UnicodeScalarRun(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    fre_kernels::Window::new(start, haystack.len()),
                    unicode_scalar_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.actual.work).unwrap_or(u64::MAX),
                ))
            }
            PortablePlan::LineDomainByteAtoms(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    SearchWindow::new(start, haystack.len()),
                    limits,
                    fre_kernels::LineDomainByteAtomsOperation::Iterate,
                )?;
                Ok((matched, accounting.actual.work))
            }
            PortablePlan::K0(_) => {
                let (matched, accounting) =
                    self.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)?;
                Ok((matched, accounting.work_or_linear_terms()))
            }
        }
    }

    /// Produce the complete equality key for a required-literal operation.
    ///
    /// `None` means this matcher selected another plan family. Search limits
    /// are included deliberately so cached qualification records cannot mix
    /// distinct refusal contracts.
    #[must_use]
    pub fn required_literal_cache_identity(
        &self,
        operation: CaptureFreeOperation,
        search_limits: SearchLimits,
    ) -> Option<RequiredLiteralCacheIdentity> {
        match &self.plan {
            PortablePlan::RequiredLiteral(required) => Some(RequiredLiteralCacheIdentity {
                schema_version: EXPLAIN_SCHEMA_VERSION,
                plan_id: required.plan_id(),
                profile: self.profile.clone(),
                operation,
                anchors: required.anchors(),
                class_words: required.class().words(),
                repeat: RequiredLiteralClassRepeat::one_or_more(),
                suffix: required.suffix().to_vec(),
                run_scanner_selection: None,
                build_limits: self.limits,
                search_limits,
            }),
            PortablePlan::DispatchedRequiredLiteral(required) => {
                Some(RequiredLiteralCacheIdentity {
                    schema_version: EXPLAIN_SCHEMA_VERSION,
                    plan_id: required.plan_id(),
                    profile: self.profile.clone(),
                    operation,
                    anchors: required.anchors(),
                    class_words: required.class().words(),
                    repeat: RequiredLiteralClassRepeat::one_or_more(),
                    suffix: required.suffix().to_vec(),
                    run_scanner_selection: required.run_scanner_selection(),
                    build_limits: self.limits,
                    search_limits,
                })
            }
            PortablePlan::BoundedRequiredLiteral(required) => Some(RequiredLiteralCacheIdentity {
                schema_version: EXPLAIN_SCHEMA_VERSION,
                plan_id: required.plan_id(),
                profile: self.profile.clone(),
                operation,
                anchors: required.anchors(),
                class_words: required.class().words(),
                repeat: required.repeat(),
                suffix: required.suffix().to_vec(),
                run_scanner_selection: None,
                build_limits: self.limits,
                search_limits,
            }),
            PortablePlan::DispatchedBoundedRequiredLiteral(required) => {
                Some(RequiredLiteralCacheIdentity {
                    schema_version: EXPLAIN_SCHEMA_VERSION,
                    plan_id: required.plan_id(),
                    profile: self.profile.clone(),
                    operation,
                    anchors: required.anchors(),
                    class_words: required.class().words(),
                    repeat: required.repeat(),
                    suffix: required.suffix().to_vec(),
                    run_scanner_selection: required.run_scanner_selection(),
                    build_limits: self.limits,
                    search_limits,
                })
            }
            _ => None,
        }
    }

    /// Produce the complete equality key for a forward-anchored operation.
    ///
    /// `None` means this matcher selected another plan family. The key is
    /// deliberately distinct from the required-literal candidate.
    #[must_use]
    pub fn forward_anchored_cache_identity(
        &self,
        operation: CaptureFreeOperation,
        search_limits: SearchLimits,
    ) -> Option<ForwardAnchoredCacheIdentity> {
        match &self.plan {
            PortablePlan::ForwardAnchored(forward) => Some(ForwardAnchoredCacheIdentity {
                schema_version: EXPLAIN_SCHEMA_VERSION,
                plan_id: forward.plan_id(),
                profile: self.profile.clone(),
                operation,
                anchors: forward.anchors(),
                class_words: forward.class().words(),
                suffix: forward.suffix().to_vec(),
                implementation: forward.implementation(),
                build_limits: self.limits,
                search_limits,
            }),
            PortablePlan::DispatchedForwardAnchored(forward) => {
                Some(ForwardAnchoredCacheIdentity {
                    schema_version: EXPLAIN_SCHEMA_VERSION,
                    plan_id: forward.plan_id(),
                    profile: self.profile.clone(),
                    operation,
                    anchors: forward.anchors(),
                    class_words: forward.class().words(),
                    suffix: forward.suffix().to_vec(),
                    implementation: forward.implementation(),
                    build_limits: self.limits,
                    search_limits,
                })
            }
            PortablePlan::ForwardEndFixed(fixed) => Some(ForwardAnchoredCacheIdentity {
                schema_version: EXPLAIN_SCHEMA_VERSION,
                plan_id: fixed.plan_id(),
                profile: self.profile.clone(),
                operation,
                anchors: fixed.anchors(),
                class_words: fixed.class().words(),
                suffix: fixed.suffix().to_vec(),
                implementation: fixed.implementation(),
                build_limits: self.limits,
                search_limits,
            }),
            _ => None,
        }
    }
}

/// Exact source-free setup accounting for the optional immutable K0
/// start-filter proof.
///
/// The proof owner belongs to the regex and may outlive the session that
/// prepared it. `newly_retained_owner_bytes` therefore reports allocation by
/// this call, while `retained_owner_bytes` reports the regex's complete live
/// proof payload after preparation. The aggregate retained value includes the
/// caller-owned session workspaces and is checked against the same explicit
/// setup scratch envelope before this receipt is published.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PortableK0StartFilterSetupAccounting {
    work_completed: u64,
    total_setup_work: u64,
    newly_retained_owner_bytes: usize,
    retained_owner_bytes: usize,
    aggregate_retained_bytes: usize,
    cap_declined: bool,
}

impl PortableK0StartFilterSetupAccounting {
    /// Complete immutable owner payload that callers must reserve before
    /// permitting one previously unsettled proof publication.
    #[doc(hidden)]
    pub const MAX_RETAINED_OWNER_BYTES: usize =
        K0StartFilterPreparationReceipt::MAX_RETAINED_OWNER_BYTES;

    /// Exact graph derivation and owner-publication work completed by this
    /// call.
    #[must_use]
    pub const fn work_completed(self) -> u64 {
        self.work_completed
    }

    /// Session construction plus proof-preparation work under the caller's
    /// total setup-work cap.
    #[must_use]
    pub const fn total_setup_work(self) -> u64 {
        self.total_setup_work
    }

    /// Exact proof payload newly allocated, initialized and retained by this
    /// call.
    #[must_use]
    pub const fn newly_retained_owner_bytes(self) -> usize {
        self.newly_retained_owner_bytes
    }

    /// Complete immutable proof payload currently retained by the regex.
    #[must_use]
    pub const fn retained_owner_bytes(self) -> usize {
        self.retained_owner_bytes
    }

    /// Complete session workspace plus regex proof payload after preparation.
    #[must_use]
    pub const fn aggregate_retained_bytes(self) -> usize {
        self.aggregate_retained_bytes
    }

    /// Whether the residual setup work or retained-byte envelope selected
    /// permanent ordinary K0 before graph traversal.
    #[must_use]
    pub const fn cap_declined(self) -> bool {
        self.cap_declined
    }
}

/// Operation-local reusable search state for one immutable portable matcher.
///
/// This keeps construction-selected specialized plans unchanged. Exact
/// literals and fixed-predicate words bind their immutable selected plan once
/// so steady calls do not redispatch through the complete portable-plan enum.
/// Only K0 owns mutable state, consisting of its primary admitted workspace,
/// one optional immutable-plan-bound prefix workspace, and bounded
/// performance-only histories whose sizes are determined entirely by the
/// validated plan. The primary workspace is either demand-grown or fully
/// allocated at construction according to the API that created the session.
/// Neither workspace retains source positions or results.
#[derive(Debug)]
pub struct PortableSearchSession<'a> {
    plan: PortableSearchSessionPlan<'a>,
}

/// Worker-owned state for ordinary unlimited portable searches.
///
/// Positive exact literals bind their already prepared finder without a worker
/// allocation. K0 matchers bind one source-free executor, including its
/// immutable capabilities and reusable workspace, when this session is
/// constructed. Unanchored required-literal matchers bind their value-only
/// projection once while retaining the native regex owner for spans.
/// A legacy literal/class-run owner retains its direct reducer beside the
/// canonical binding so exhaustive positive-width counts need one traversal.
/// A positive leftmost-first literal set similarly binds one compact span
/// executor and leaves its endpoint-only sidecar unbound. The first Exists
/// call settles that sidecar once, caching both a qualified AArch64 ASCII-root
/// engine and an unavailable result. A qualified engine still prepares its
/// classifier only when a call first reaches the branch that can use it. Span
/// visitation and count-only calls leave the sidecar unbound.
/// Other matcher families retain only their compact binding. No method on this
/// type accepts finite limits or publishes accounting; callers that need
/// either contract should use [`PortableSearchSession`] instead.
///
/// A session never retains a haystack. It can therefore be reused across
/// unrelated sources by one mutable, thread-confined worker. An eligible
/// uniform-standard literal-set owner retains one performance-only boolean
/// saying that the immediately preceding endpoint or selected-span call
/// observed a near acceptance. It retains neither that endpoint nor any source
/// identity, and a miss, far acceptance, or error clears it. A following
/// span-iteration or count operation may spend it on one bounded initial tail
/// probe. Only exhaustive success that accepts a current-call span with near
/// final selected-end spacing and a near terminal gap may recommend one
/// bounded probe for the next operation; a miss, callback stop, callback
/// error, or search error clears the observation.
#[derive(Debug)]
pub struct PortableOrdinarySession<'a> {
    plan: PortableOrdinarySessionPlan<'a>,
}

#[derive(Debug)]
enum PortableOrdinaryLiteralSetExists<'a> {
    Unbound,
    Unavailable,
    Bound(LiteralSetOrdinaryEngine<'a>),
}

impl<'a> PortableOrdinaryLiteralSetExists<'a> {
    #[inline]
    fn get_or_bind(
        &mut self,
        executor: LiteralSetOrdinaryExecutor<'a>,
    ) -> Option<&mut LiteralSetOrdinaryEngine<'a>> {
        if matches!(self, Self::Unbound) {
            #[cfg(test)]
            literal_set_dfa_ordinary_exists_bind_probe::record();
            *self = match executor.bind_engine() {
                Some(engine) => Self::Bound(engine),
                None => Self::Unavailable,
            };
        }
        match self {
            Self::Bound(engine) => Some(engine),
            Self::Unbound | Self::Unavailable => None,
        }
    }
}

#[derive(Debug)]
enum PortableOrdinarySessionPlan<'a> {
    K0 {
        executor: K0OrdinaryExecutor<'a>,
        positive: bool,
    },
    Canonical(PortableOrdinaryCanonical<'a>),
    RequiredLiteral {
        projection: PortableOrdinaryRequiredLiteral<'a>,
        regex: &'a PortableRegex,
    },
    PackedLiteralSet {
        executor: PackedLiteralSetOrdinaryExecutor<'a>,
    },
    LiteralSetDfa {
        executor: LiteralSetOrdinaryExecutor<'a>,
        /// A lazily sealed endpoint-only projection. Keeping it beside the
        /// incumbent span executor lets find, visit and count retain their
        /// exact established facade arm without binding the unused sidecar.
        ascii_exists: PortableOrdinaryLiteralSetExists<'a>,
    },
    LiteralSetUniformStandardDfa {
        executor: LiteralSetUniformStandardOrdinaryExecutor<'a>,
        direct_next: bool,
    },
    /// Append this direct binding so established ordinary-session variant
    /// discriminants and their common dispatch order remain stable.
    ExactLiteral {
        executor: ExactLiteralOrdinaryExecutor<'a>,
    },
    /// Appended to preserve every established ordinary-session discriminant.
    LiteralSetCompact {
        executor: LiteralSetCompactOrdinaryExecutor<'a>,
    },
}

/// Compact binding for ordinary fallbacks that construction has already
/// proved cannot require mutable K0 workspace.
///
/// This mirrors source-free non-K0 projections of
/// [`PortableSearchSessionPlan`] without inheriting that enum's inline K0
/// payload. It fits inside the space already required by the outer K0 variant,
/// so canonical construction needs no separate allocation and does not
/// enlarge the ordinary session.
#[derive(Debug)]
pub(crate) enum PortableOrdinaryCanonical<'a> {
    Native(&'a PortableRegex),
    ExactLiteral(&'a LiteralPlan),
    FixedPredicateWord64(&'a FixedPredicateWord64Plan),
    /// Appended to preserve every established compact-binding discriminant.
    LiteralClassRunLiteral {
        regex: &'a PortableRegex,
        plan: &'a LiteralClassRunLiteralPlan,
    },
}

impl<'a> PortableOrdinaryCanonical<'a> {
    pub(crate) fn try_new(regex: &'a PortableRegex) -> Result<Self, SearchError> {
        match &regex.plan {
            PortablePlan::K0(_) => Err(SearchError::K0(K0SearchError::InternalInvariant {
                detail: "ordinary canonical binding unexpectedly selected K0",
            })),
            PortablePlan::ExactLiteral(plan) => Ok(Self::ExactLiteral(plan)),
            PortablePlan::FixedPredicateWord64(plan) => Ok(Self::FixedPredicateWord64(plan)),
            PortablePlan::LiteralClassRunLiteral(plan) => {
                Ok(Self::LiteralClassRunLiteral { regex, plan })
            }
            _ => Ok(Self::Native(regex)),
        }
    }

    #[inline]
    pub(crate) fn is_match_window(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        match self {
            Self::ExactLiteral(plan) => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            Self::FixedPredicateWord64(plan) => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((
                    matched,
                    SearchAccounting::FixedPredicateWord64(accounting),
                ))
            }
            Self::Native(regex) | Self::LiteralClassRunLiteral { regex, .. } => {
                regex.is_match_window(haystack, window, limits)
            }
        }
    }

    #[inline]
    pub(crate) fn is_match_window_value(
        &self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        match self {
            Self::ExactLiteral(plan) => {
                let window = LiteralWindow::new(window.start(), window.end());
                if limits == SearchLimits::unlimited()
                    && let Some(executor) = plan.ordinary_executor()
                {
                    return executor
                        .exists_window_value(haystack, window)
                        .map_err(SearchError::from);
                }
                plan.find_window(haystack, window, literal_limits(limits))
                    .map(|(matched, _)| matched.is_some())
                    .map_err(SearchError::from)
            }
            Self::FixedPredicateWord64(plan) => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map_err(SearchError::from),
            Self::Native(regex) | Self::LiteralClassRunLiteral { regex, .. } => {
                regex.is_match_window_value(haystack, window, limits)
            }
        }
    }

    #[inline]
    fn shortest_match_at_value(
        &self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<usize>, SearchError> {
        let window = SearchWindow::new(start, haystack.len());
        match self {
            Self::ExactLiteral(plan) => plan
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(SearchLimits::unlimited()),
                )
                .map(|(matched, _)| matched.map(|(_, end)| end))
                .map_err(SearchError::from),
            Self::FixedPredicateWord64(plan) => plan
                .earliest_end_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(SearchLimits::unlimited()),
                )
                .map(|(end, _)| end)
                .map_err(SearchError::from),
            Self::Native(regex) | Self::LiteralClassRunLiteral { regex, .. } => regex
                .shortest_match_window_value(haystack, window, SearchLimits::unlimited()),
        }
    }

    #[inline]
    fn find_at_value(
        &self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<Match>, SearchError> {
        let window = SearchWindow::new(start, haystack.len());
        match self {
            Self::ExactLiteral(plan) => plan
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(SearchLimits::unlimited()),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            Self::FixedPredicateWord64(plan) => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(SearchLimits::unlimited()),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            Self::Native(regex) | Self::LiteralClassRunLiteral { regex, .. } => {
                regex.find_window_value(haystack, window, SearchLimits::unlimited())
            }
        }
    }

    #[inline]
    fn try_visit_spans_at<F, E>(
        &self,
        haystack: &[u8],
        start: usize,
        visitor: F,
    ) -> Result<Result<(), E>, PortableFindIterError>
    where
        F: FnMut(Match) -> Result<bool, E>,
    {
        // Preserve the construction-selected source cursor when this native
        // plan exposes one. The cursor is bound only for this call, so the
        // compact session remains source-free while repeated matches retain
        // their monotone native traversal.
        if let Self::Native(regex) = self
            && let Some(mut cursor) = regex.native_search_cursor(haystack)
        {
            return try_visit_ordinary_spans_at(
                haystack.len(),
                start,
                |search_start| {
                    cursor
                        .find_at_value(search_start, SearchLimits::unlimited())
                        .map_err(PortableFindIterError::Search)
                },
                visitor,
            );
        }
        try_visit_ordinary_spans_at(
            haystack.len(),
            start,
            |search_start| {
                self.find_at_value(haystack, search_start)
                    .map_err(PortableFindIterError::Search)
            },
            visitor,
        )
    }
}

// One mistaken density promotion can scan at most one byte alphabet and eight
// fixed-width words before returning to the construction-selected prefilter.
// A near acceptance within two words is enough evidence to spend that bounded
// probe on the next ordinary call, independent of its remaining window size.
const LITERAL_SET_DFA_DIRECT_MAX_PROBE_BYTES: usize = 256;
const LITERAL_SET_DFA_DIRECT_NEAR_WIDTHS: usize = 2;
const LITERAL_SET_DFA_DIRECT_PROBE_WIDTHS: usize = 8;

#[derive(Clone, Copy, Debug)]
enum PortableOrdinaryRequiredLiteral<'a> {
    Scalar(&'a RequiredLiteralPlan),
    Dispatched(&'a DispatchedRequiredLiteralPlan),
}

impl PortableOrdinaryRequiredLiteral<'_> {
    #[inline]
    fn is_match_at(self, haystack: &[u8], start: usize) -> Result<bool, SearchError> {
        let window = LiteralWindow::new(start, haystack.len());
        let limits = required_literal_limits(SearchLimits::unlimited());
        match self {
            Self::Scalar(plan) => plan
                .exists_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            Self::Dispatched(plan) => plan
                .exists_window_value(haystack, window, limits)
                .map_err(SearchError::from),
        }
    }

    #[inline]
    fn first_acceptance_at(
        self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<usize>, SearchError> {
        let window = LiteralWindow::new(start, haystack.len());
        let limits = required_literal_limits(SearchLimits::unlimited());
        match self {
            Self::Scalar(plan) => plan
                .first_acceptance_window_value(haystack, window, limits)
                .map_err(SearchError::from),
            Self::Dispatched(plan) => plan
                .first_acceptance_window_value(haystack, window, limits)
                .map_err(SearchError::from),
        }
    }
}

#[cfg(test)]
mod required_literal_ordinary_session_probe {
    use std::cell::Cell;

    std::thread_local! {
        static CALLS: Cell<usize> = const { Cell::new(0) };
        static ENDPOINT_CALLS: Cell<usize> = const { Cell::new(0) };
    }

    pub(super) fn reset() {
        CALLS.set(0);
        ENDPOINT_CALLS.set(0);
    }

    pub(super) fn record() {
        CALLS.set(CALLS.get().saturating_add(1));
    }

    pub(super) fn calls() -> usize {
        CALLS.get()
    }

    pub(super) fn record_endpoint() {
        ENDPOINT_CALLS.set(ENDPOINT_CALLS.get().saturating_add(1));
    }

    pub(super) fn endpoint_calls() -> usize {
        ENDPOINT_CALLS.get()
    }
}

#[cfg(test)]
mod literal_set_dfa_ordinary_exists_bind_probe {
    use std::cell::Cell;

    std::thread_local! {
        static CALLS: Cell<usize> = const { Cell::new(0) };
    }

    pub(super) fn reset() {
        CALLS.set(0);
    }

    pub(super) fn record() {
        CALLS.set(CALLS.get().saturating_add(1));
    }

    pub(super) fn calls() -> usize {
        CALLS.get()
    }
}

#[cfg(test)]
mod literal_set_dfa_ordinary_route_probe {
    use std::cell::Cell;

    std::thread_local! {
        static PREFILTERED_CALLS: Cell<usize> = const { Cell::new(0) };
        static DIRECT_CALLS: Cell<usize> = const { Cell::new(0) };
    }

    pub(super) fn reset() {
        PREFILTERED_CALLS.set(0);
        DIRECT_CALLS.set(0);
    }

    pub(super) fn record(direct: bool) {
        let counter = if direct {
            &DIRECT_CALLS
        } else {
            &PREFILTERED_CALLS
        };
        counter.set(counter.get().saturating_add(1));
    }

    pub(super) fn calls() -> (usize, usize) {
        (PREFILTERED_CALLS.get(), DIRECT_CALLS.get())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PortableSearchSessionStorage {
    Adaptive,
    Fixed,
}

/// Source-independent admission for repeated value-only existence searches.
///
/// The token binds the original finite per-invocation limits and, when the
/// selected matcher is an exact empty literal, construction-proved line-total,
/// exact byte-class delimiter, class-guarded literal corridor, absolute-start
/// scalar corridor, assertion-free warm-capable K0, or exact word-run plan, a
/// conservative maximum input length. Calls outside that exact envelope replay
/// the ordinary facade path with the retained finite limits. The admitted warm
/// route still runs one complete semantic K0 existence search. The direct
/// routes execute their complete structural semantics after their per-byte
/// work envelopes are admitted. All routes only omit work already settled by
/// the immutable plan, workspace, and token.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PortableIsMatchValueToken {
    limits: SearchLimits,
    route: PortableIsMatchValueTokenRoute,
}

/// A construction-bound byte-class delimiter matcher for repeated value-only
/// searches.
///
/// This handle is created only after a [`PortableIsMatchValueToken`] has been
/// authenticated against the session that produced it. It retains the exact
/// immutable plan, so repeated calls do not need to replay the session and
/// plan identity checks. Calls above the source-independent input envelope
/// return `None` and may be retried through the ordinary session API.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PortableBoundByteClassDelimiterMatcher {
    plan: k0_class_delimiter_exists::Plan,
    maximum_input_bytes: usize,
}

impl PortableBoundByteClassDelimiterMatcher {
    /// Evaluate one input when it fits the authenticated envelope.
    #[must_use]
    #[inline]
    pub fn try_is_match(self, haystack: &[u8]) -> Option<bool> {
        (haystack.len() <= self.maximum_input_bytes)
            .then(|| self.plan.is_match_full(haystack))
    }
}

/// A construction-bound whole-line matcher for repeated value-only searches.
///
/// This handle is created only after a [`PortableIsMatchValueToken`] has been
/// authenticated against the session that produced it. Repeated calls retain
/// the token's finite input envelope without replaying session and plan
/// identity checks. Inputs containing LF or exceeding the envelope return
/// `None` and may be retried through the ordinary session API.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PortableBoundLineTotalMatcher {
    maximum_input_bytes: usize,
}

impl PortableBoundLineTotalMatcher {
    /// Return whether an input length fits the authenticated finite envelope.
    ///
    /// This is only a resource-admission predicate. It does not assert that
    /// any source has the whole-line semantics proved by this handle.
    #[must_use]
    #[inline]
    pub const fn admits_input_len(self, input_len: usize) -> bool {
        input_len <= self.maximum_input_bytes
    }

    /// Evaluate one complete LF-free input when it fits the authenticated
    /// envelope.
    #[must_use]
    #[inline]
    pub fn try_is_match(self, haystack: &[u8]) -> Option<bool> {
        (self.admits_input_len(haystack.len()) && memchr(b'\n', haystack).is_none())
            .then_some(true)
    }
}

/// A session-bound generic K0 token for repeated value-only searches.
///
/// Binding authenticates the immutable automaton and warm-executor capability
/// once. The handle retains the automaton identity so use with any other
/// session replays the ordinary path. Each owner call still performs one
/// complete semantic K0 existence search over its supplied source. Inputs
/// outside the original source-independent work envelope also replay the
/// ordinary finite-limit path.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PortableBoundK0WarmIsMatchValueToken {
    limits: SearchLimits,
    automaton_identity: u64,
    maximum_input_bytes: usize,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PortableIsMatchValueTokenRoute {
    Incumbent,
    EmptyLiteral {
        maximum_input_bytes: usize,
    },
    LineTotal {
        automaton_identity: u64,
        plan_identity: [u8; 4],
        maximum_input_bytes: usize,
    },
    K0Warm {
        automaton_identity: u64,
        maximum_input_bytes: usize,
    },
    ByteClassDelimiter {
        automaton_identity: u64,
        plan_identity: k0_class_delimiter_exists::Identity,
        maximum_input_bytes: usize,
    },
    BoundedDelimited {
        automaton_identity: u64,
        plan_identity: k0_bounded_delimited_exists::Identity,
        maximum_input_bytes: usize,
    },
    UriLike {
        automaton_identity: u64,
        plan_identity: k0_uri_exists::Identity,
        maximum_input_bytes: usize,
    },
    FusedUriLikeComposite {
        automaton_identity: u64,
        plan_identity: k0_uri_exists::Identity,
        maximum_input_bytes: usize,
    },
    AnchoredScalarCorridor {
        automaton_identity: u64,
        plan_identity: k0_anchored_scalar_corridor_exists::Identity,
        maximum_input_bytes: usize,
    },
    LiteralPrefixClass {
        automaton_identity: u64,
        plan_identity: k0_literal_prefix_class_exists::Identity,
        maximum_input_bytes: usize,
    },
    UnicodeWordRun {
        identity: unicode_word_run::AggregateOperationIdentity,
        maximum_input_bytes: usize,
    },
}

impl PortableIsMatchValueToken {
    /// Whether this token admitted an exact empty-literal existence route.
    #[must_use]
    pub const fn uses_empty_literal_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::EmptyLiteral { .. }
        )
    }

    /// Whether this token admitted a construction-proved whole-line route.
    #[must_use]
    pub const fn uses_line_total_route(self) -> bool {
        matches!(self.route, PortableIsMatchValueTokenRoute::LineTotal { .. })
    }

    /// Whether this token admitted an authenticated direct K0 route.
    #[must_use]
    pub const fn uses_k0_warm_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::LineTotal { .. }
                | PortableIsMatchValueTokenRoute::K0Warm { .. }
        )
    }

    /// Whether this token admitted any authenticated prepared route.
    #[must_use]
    pub const fn uses_prepared_route(self) -> bool {
        !matches!(self.route, PortableIsMatchValueTokenRoute::Incumbent)
    }

    /// Whether this token admitted an exact Unicode word-run route.
    #[must_use]
    pub const fn uses_unicode_word_run_route(self) -> bool {
        matches!(self.route, PortableIsMatchValueTokenRoute::UnicodeWordRun { .. })
    }

    /// Whether this token admitted an exact byte-class delimiter route.
    #[must_use]
    pub const fn uses_byte_class_delimiter_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::ByteClassDelimiter { .. }
        )
    }

    /// Whether this token admitted an exact bounded delimited-field route.
    #[must_use]
    pub const fn uses_bounded_delimited_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::BoundedDelimited { .. }
        )
    }

    /// Whether this token admitted an exact class-guarded literal route.
    #[must_use]
    pub const fn uses_uri_like_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::UriLike { .. }
                | PortableIsMatchValueTokenRoute::FusedUriLikeComposite { .. }
        )
    }

    /// Whether this token admitted the fused two-branch class-guarded literal
    /// and byte-class delimiter route.
    #[must_use]
    pub const fn uses_fused_uri_like_composite_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::FusedUriLikeComposite { .. }
        )
    }

    /// Whether this token admitted an exact absolute-start scalar-corridor
    /// predicate.
    #[must_use]
    pub const fn uses_anchored_scalar_corridor_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::AnchoredScalarCorridor { .. }
        )
    }

    /// Whether this token admitted an exact literal-prefix/fixed-class route.
    #[must_use]
    pub const fn uses_literal_prefix_class_route(self) -> bool {
        matches!(
            self.route,
            PortableIsMatchValueTokenRoute::LiteralPrefixClass { .. }
        )
    }

    /// Largest complete input admitted by the direct route.
    ///
    /// `None` means every call replays the ordinary finite-limit facade.
    #[must_use]
    pub const fn maximum_warm_input_bytes(self) -> Option<usize> {
        match self.route {
            PortableIsMatchValueTokenRoute::Incumbent => None,
            PortableIsMatchValueTokenRoute::EmptyLiteral {
                maximum_input_bytes,
            }
            | PortableIsMatchValueTokenRoute::LineTotal {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::K0Warm {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::ByteClassDelimiter {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::BoundedDelimited {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::UriLike {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::FusedUriLikeComposite {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::AnchoredScalarCorridor {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::LiteralPrefixClass {
                maximum_input_bytes,
                ..
            }
            | PortableIsMatchValueTokenRoute::UnicodeWordRun {
                maximum_input_bytes,
                ..
            } => Some(maximum_input_bytes),
        }
    }
}

fn class_delimiter_prepared_maximum_input_bytes(
    requested: usize,
    max_work: u64,
) -> usize {
    // One monotone delimiter scan services at most every source byte and each
    // candidate performs at most two adjacent byte-class membership tests.
    let admitted = max_work / 3;
    requested.min(usize::try_from(admitted).unwrap_or(usize::MAX))
}

fn uri_like_prepared_maximum_input_bytes(
    requested: usize,
    max_work: u64,
    work_per_input_byte: u64,
) -> usize {
    let admitted = max_work / work_per_input_byte;
    requested.min(usize::try_from(admitted).unwrap_or(usize::MAX))
}

fn bounded_delimited_prepared_maximum_input_bytes(
    requested: usize,
    max_work: u64,
    work_per_input_byte: u64,
) -> usize {
    let admitted = max_work / work_per_input_byte;
    requested.min(usize::try_from(admitted).unwrap_or(usize::MAX))
}

fn anchored_scalar_corridor_prepared_maximum_input_bytes(
    requested: usize,
    max_work: u64,
    work_per_input_byte: u64,
) -> usize {
    let admitted = max_work / work_per_input_byte;
    requested.min(usize::try_from(admitted).unwrap_or(usize::MAX))
}

fn literal_prefix_class_prepared_maximum_input_bytes(
    automaton: &Automaton,
    requested: usize,
    max_work: u64,
    work_per_input_byte: u64,
) -> Option<usize> {
    let direct = requested.min(
        usize::try_from(max_work / work_per_input_byte).unwrap_or(usize::MAX),
    );
    k0_reused_exists_maximum_input_bytes(automaton, requested, max_work)
        .map(|incumbent| incumbent.min(direct))
}

fn unicode_word_run_prepared_maximum_input_bytes(
    identity: unicode_word_run::AggregateOperationIdentity,
    requested: usize,
    max_work: u64,
) -> usize {
    debug_assert!(identity.unicode);
    let admitted = max_work / 2;
    requested.min(usize::try_from(admitted).unwrap_or(usize::MAX))
}

fn k0_reused_exists_maximum_input_bytes(
    automaton: &Automaton,
    requested_maximum: usize,
    max_work: u64,
) -> Option<usize> {
    let admitted = |input_bytes| {
        automaton
            .conservative_reused_work_bound(input_bytes)
            .is_ok_and(|required| required <= max_work)
    };
    if !admitted(0) {
        return None;
    }
    if admitted(requested_maximum) {
        return Some(requested_maximum);
    }

    // The conservative K0 certificate is an affine, nondecreasing function
    // of input length. Find the largest prefix of the caller's requested
    // domain whose complete ordinary-search work fits the retained cap.
    let mut low = 0_usize;
    let mut high = requested_maximum;
    while low < high {
        let distance = high - low;
        let middle = low + distance / 2 + distance % 2;
        if admitted(middle) {
            low = middle;
        } else {
            high = middle - 1;
        }
    }
    Some(low)
}

/// One explicit-session K0 invocation after reserving facade-retained
/// sidecars from the caller's aggregate scratch cap.
#[derive(Clone, Copy, Debug)]
struct K0AggregateInvocation {
    primary_limits: SearchLimits,
    external_scratch_bytes: usize,
    aggregate_scratch_limit: usize,
}

impl K0AggregateInvocation {
    fn admit(
        session: &K0SearchSession<'_>,
        aggregate_setup: SearchSessionSetupAccounting,
        limits: SearchLimits,
    ) -> Result<Self, SearchError> {
        let primary_setup_bytes = session.construction_accounting().retained_bytes();
        let external_scratch_bytes = aggregate_setup
            .retained_bytes()
            .checked_sub(primary_setup_bytes)
            .ok_or(K0SearchError::InternalInvariant {
                detail: "aggregate K0 setup retained fewer bytes than its primary session",
            })?;
        let aggregate_retained_bytes = session
            .retained_scratch_bytes()
            .checked_add(external_scratch_bytes)
            .ok_or(K0SearchError::ArithmeticOverflow {
                computation: "aggregate K0 retained scratch",
            })?;
        let primary_scratch_limit = if limits.max_scratch_bytes == usize::MAX {
            // Preserve the exact unlimited sentinel used by optional K0 route
            // selection. There is no finite aggregate ceiling to residualize.
            usize::MAX
        } else if let Some(limit) = limits
            .max_scratch_bytes
            .checked_sub(external_scratch_bytes)
        {
            limit
        } else {
            return Err(K0SearchError::ResourceLimit {
                resource: fre_automata::ResourceKind::ScratchBytes,
                needed: aggregate_retained_bytes,
                limit: limits.max_scratch_bytes,
            }
            .into());
        };
        if aggregate_retained_bytes > limits.max_scratch_bytes {
            return Err(K0SearchError::ResourceLimit {
                resource: fre_automata::ResourceKind::ScratchBytes,
                needed: aggregate_retained_bytes,
                limit: limits.max_scratch_bytes,
            }
            .into());
        }
        Ok(Self {
            primary_limits: SearchLimits {
                max_work: limits.max_work,
                max_scratch_bytes: primary_scratch_limit,
            },
            external_scratch_bytes,
            aggregate_scratch_limit: limits.max_scratch_bytes,
        })
    }

    const fn primary_limits(self) -> SearchLimits {
        self.primary_limits
    }

    fn map_k0_error(self, error: K0SearchError) -> SearchError {
        match error {
            K0SearchError::ResourceLimit {
                resource: fre_automata::ResourceKind::ScratchBytes,
                needed,
                ..
            } => match needed.checked_add(self.external_scratch_bytes) {
                Some(needed) => K0SearchError::ResourceLimit {
                    resource: fre_automata::ResourceKind::ScratchBytes,
                    needed,
                    limit: self.aggregate_scratch_limit,
                }
                .into(),
                None => K0SearchError::ArithmeticOverflow {
                    computation: "aggregate K0 scratch refusal",
                }
                .into(),
            },
            error => error.into(),
        }
    }

    fn map_error(self, error: SearchError) -> SearchError {
        match error {
            SearchError::K0(error) => self.map_k0_error(error),
            error => error,
        }
    }

    fn accounting(
        self,
        accounting: fre_automata::SearchAccounting,
    ) -> Result<fre_automata::SearchAccounting, SearchError> {
        accounting
            .with_external_scratch_bytes(self.external_scratch_bytes)
            .map_err(SearchError::from)
    }
}

/// Run the primary report-free K0 lane under one aggregate invocation.
fn try_k0_warm_exists_value_with_aggregate_limits(
    session: &mut K0SearchSession<'_>,
    aggregate_setup: SearchSessionSetupAccounting,
    haystack: &[u8],
    limits: SearchLimits,
) -> Result<Option<bool>, SearchError> {
    let invocation = K0AggregateInvocation::admit(session, aggregate_setup, limits)?;
    match session.try_search_warm_exists_value_with_limits(
        haystack,
        SearchWindow::full(haystack),
        invocation.primary_limits(),
    ) {
        Ok(output) => Ok(output),
        Err(error) => Err(invocation.map_k0_error(error)),
    }
}

#[repr(u8)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0ValueIterRoute {
    General,
    SourceBound,
    Unknown,
}

#[cold]
#[inline(never)]
fn classify_and_cache_k0_value_iter_route(
    session: &K0SearchSession<'_>,
    sidecars_absent: bool,
    route_state: &mut K0ExclusiveRouteState,
) -> K0ValueIterRoute {
    let route = if !sidecars_absent {
        K0ValueIterRoute::General
    } else {
        match session.retained_span_value_cursor_eligibility() {
            Some(true) => K0ValueIterRoute::SourceBound,
            Some(false) => K0ValueIterRoute::General,
            None => K0ValueIterRoute::Unknown,
        }
    };
    route_state.set_value_iter_route(route);
    route
}

#[derive(Debug)]
#[allow(
    clippy::large_enum_variant,
    reason = "boxing K0 would add a second allocation and falsify workspace setup accounting"
)]
enum PortableSearchSessionPlan<'a> {
    Native(&'a PortableRegex),
    K0 {
        session: K0SearchSession<'a>,
        aggregate_setup: SearchSessionSetupAccounting,
        k0_plan: &'a PortableK0Plan,
        line_total_grep_plan: Option<line_total_grep::Plan>,
        reverse_inner: Option<Box<k0_general_reverse_inner::SearchSession<'a>>>,
        lazy_delimited_repeat: Option<&'a lazy_delimited_repeat::Plan>,
        greedy_class_literal_tail: Option<&'a greedy_class_literal_tail::Plan>,
        mandatory_suffix: Option<&'a K0MandatorySuffixPlan>,
        mandatory_cut: Option<&'a K0MandatoryCutPlan>,
        negative_prefilter: Option<&'a K0NegativePrefilterPlan>,
        exclusive_route_state: K0ExclusiveRouteState,
        mandatory_suffix_exists_state: K0NegativePrefilterState,
        mandatory_suffix_span_state: K0NegativePrefilterState,
        negative_prefilter_exists_state: K0NegativePrefilterState,
        negative_prefilter_span_state: K0NegativePrefilterState,
    },
    /// Keep this new specialized route after the two established variants so
    /// their discriminants and common steady-state dispatch remain stable.
    /// The immutable semantic owner remains available for diagnostics while
    /// steady searches bind the selected literal plan exactly once here.
    ExactLiteral {
        regex: &'a PortableRegex,
        plan: &'a LiteralPlan,
    },
    /// Append new direct native bindings so established discriminants and the
    /// common steady-state dispatch order remain stable.
    FixedPredicateWord64 {
        regex: &'a PortableRegex,
        plan: &'a FixedPredicateWord64Plan,
    },
}

#[inline]
fn validate_k0_facade_window(
    haystack_len: usize,
    window: SearchWindow,
) -> Result<(), SearchError> {
    if window.start() > window.end() || window.end() > haystack_len {
        return Err(SearchError::K0(K0SearchError::InvalidWindow {
            start: window.start(),
            end: window.end(),
            haystack_len,
        }));
    }
    Ok(())
}

#[inline]
fn k0_absolute_end_window_is_proven_empty(
    proof: Option<K0AbsoluteEndProof>,
    haystack_len: usize,
    window: SearchWindow,
) -> bool {
    // Validate the complete public range before using this O(1) theorem.
    // Invalid windows must still reach ordinary K0's authoritative error.
    proof.is_some()
        && window.start() <= window.end()
        && window.end() <= haystack_len
        && (window.start() == window.end() || window.end() < haystack_len)
}

#[inline]
fn k0_finite_minimum_window_is_proven_empty(
    suffix: Option<&K0MandatorySuffixPlan>,
    haystack_len: usize,
    window: SearchWindow,
) -> bool {
    // Validate the complete public range before using this O(1) theorem.
    // Invalid windows must still reach ordinary K0's authoritative error.
    window.start() <= window.end()
        && window.end() <= haystack_len
        && suffix
            .and_then(K0MandatorySuffixPlan::finite_minimum_match_bytes)
            .is_some_and(|minimum| window.end() - window.start() < minimum)
}

#[inline]
fn try_k0_absolute_end_exists(
    session: &mut K0SearchSession<'_>,
    proof: Option<K0AbsoluteEndProof>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
) -> Result<Option<bool>, SearchError> {
    let Some(proof) = proof else {
        return Ok(None);
    };
    if limits != SearchLimits::unlimited()
        || window.start() > window.end()
        || window.end() > haystack.len()
    {
        return Ok(None);
    }
    if window.end() < haystack.len() {
        return Ok(Some(false));
    }
    let verifier_window = proof.verifier_window(window);
    let window_bytes = verifier_window
        .end()
        .saturating_sub(verifier_window.start());
    let Some(work_certificate) = session.positive_end_verifier_work_certificate(window_bytes)
    else {
        return Ok(None);
    };

    // The immutable ordinary-K0 certificate bounds speculative verifier
    // work; one source-window pass independently caps reverse byte traffic.
    let reverse_limits = K0PositiveEndLimits::new(work_certificate, window_bytes);
    let verification = session
        .try_positive_match_ending_at(haystack, verifier_window, window.end(), reverse_limits)
        .map_err(SearchError::from)?;
    debug_assert!(verification.receipt().work() <= reverse_limits.max_work());
    debug_assert!(
        verification.receipt().reverse_source_bytes() <= reverse_limits.max_reverse_bytes()
    );
    match verification.outcome() {
        K0PositiveEndOutcome::Matched => Ok(Some(true)),
        K0PositiveEndOutcome::Rejected => Ok(Some(false)),
        K0PositiveEndOutcome::Declined => Ok(None),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0AbsoluteEndSpanAttempt {
    Declined,
    Complete(Option<Match>),
}

#[inline]
fn try_k0_absolute_end_span(
    session: &mut K0SearchSession<'_>,
    proof: Option<K0AbsoluteEndProof>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
) -> Result<K0AbsoluteEndSpanAttempt, SearchError> {
    let Some(proof) = proof else {
        return Ok(K0AbsoluteEndSpanAttempt::Declined);
    };
    if limits != SearchLimits::unlimited()
        || window.start() > window.end()
        || window.end() > haystack.len()
    {
        return Ok(K0AbsoluteEndSpanAttempt::Declined);
    }
    if window.end() < haystack.len() {
        return Ok(K0AbsoluteEndSpanAttempt::Complete(None));
    }
    let verifier_window = proof.verifier_window(window);
    let window_bytes = verifier_window
        .end()
        .saturating_sub(verifier_window.start());
    let Some(work_certificate) = session.positive_end_verifier_work_certificate(window_bytes)
    else {
        return Ok(K0AbsoluteEndSpanAttempt::Declined);
    };

    let reverse_limits = K0PositiveEndLimits::new(work_certificate, window_bytes);
    let verification = session
        .try_earliest_start_ending_at(haystack, verifier_window, window.end(), reverse_limits)
        .map_err(SearchError::from)?;
    debug_assert!(verification.receipt().work() <= reverse_limits.max_work());
    debug_assert!(
        verification.receipt().reverse_source_bytes() <= reverse_limits.max_reverse_bytes()
    );
    match verification.outcome() {
        K0PositiveEndStartOutcome::Matched { start } => {
            if start < verifier_window.start() || start >= window.end() {
                return Err(SearchError::K0(K0SearchError::InternalInvariant {
                    detail: "absolute-end verifier start escaped its positive window",
                }));
            }
            Ok(K0AbsoluteEndSpanAttempt::Complete(Some(Match {
                start,
                end: window.end(),
            })))
        }
        K0PositiveEndStartOutcome::Rejected => Ok(K0AbsoluteEndSpanAttempt::Complete(None)),
        K0PositiveEndStartOutcome::Declined => Ok(K0AbsoluteEndSpanAttempt::Declined),
    }
}

const K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS: usize = 4;
const K0_PACKED_FRONTIER_DIRECT_EPOCH_CALLS: u8 = 8;
const K0_PACKED_FRONTIER_STRUCTURAL_EPOCH_CALLS: [u8; 4] = [8, 16, 32, 64];
const K0_PACKED_FRONTIER_DIRECT_LOSS_BACKOFF_CALLS: u8 = 8;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0PackedFrontierExistsPreference {
    ObserveColdPacked,
    RetainExactFloor,
    TrialIncumbent,
    RetainIncumbent,
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct K0PackedFrontierExistsClassState {
    window: SearchWindow,
    packed_residual_work: u64,
}

impl K0PackedFrontierExistsClassState {
    const EMPTY: Self = Self {
        window: SearchWindow::new(0, 0),
        packed_residual_work: 0,
    };
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct K0PackedFrontierExactWitness {
    start: usize,
    bytes: u32,
    length: u8,
}

impl K0PackedFrontierExactWitness {
    fn from_match(haystack: &[u8], start: usize, end: usize) -> Option<Self> {
        let matched = haystack.get(start..end)?;
        if matched.is_empty() || matched.len() > core::mem::size_of::<u32>() {
            return None;
        }
        let mut bytes = [0_u8; core::mem::size_of::<u32>()];
        bytes[..matched.len()].copy_from_slice(matched);
        Some(Self {
            start,
            bytes: u32::from_le_bytes(bytes),
            length: u8::try_from(matched.len()).ok()?,
        })
    }

    fn is_present(self, haystack: &[u8], window: SearchWindow) -> bool {
        let length = usize::from(self.length);
        let Some(end) = self.start.checked_add(length) else {
            return false;
        };
        if length == 0 || self.start < window.start() || end > window.end() {
            return false;
        }
        let expected = self.bytes.to_le_bytes();
        haystack.get(self.start..end) == Some(&expected[..length])
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0PackedFrontierExistsRoute {
    Packed { class_index: usize },
    Incumbent {
        class_index: usize,
        packed_positive: K0PackedFrontierPositiveObservation,
        trial: bool,
    },
}

/// Four exact-window classes without `Option` inflation. The immutable K0 plan
/// selects this state only for its mutually exclusive packed-frontier route;
/// on 64-bit targets its 160-byte layout is no larger than the correlated
/// Exists policy it replaces in the session.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct K0PackedFrontierExistsState {
    classes: [K0PackedFrontierExistsClassState; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
    exact_floor_witness_starts: [usize; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
    exact_floor_witness_bytes: [u32; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
    exact_floor_witness_lengths: [u8; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
    // Low four bits are occupied classes. High four bits mark classes whose
    // most recent non-decisive packed observation was structurally shallow.
    occupied: u8,
    preferences: u8,
    direct_remaining: [u8; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
    structural_epoch_stage: [u8; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
    next_replacement: u8,
}

impl Default for K0PackedFrontierExistsState {
    fn default() -> Self {
        Self {
            classes: [K0PackedFrontierExistsClassState::EMPTY;
                K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
            exact_floor_witness_starts: [0; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
            exact_floor_witness_bytes: [0; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
            exact_floor_witness_lengths: [0; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
            occupied: 0,
            preferences: 0,
            direct_remaining: [0; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
            structural_epoch_stage: [0; K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS],
            next_replacement: 0,
        }
    }
}

impl K0PackedFrontierExistsState {
    fn is_occupied(&self, index: usize) -> bool {
        self.occupied & (1_u8 << index) != 0
    }

    fn is_structural_direct(&self, index: usize) -> bool {
        self.occupied
            & (1_u8 << (index + K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS))
            != 0
    }

    fn set_structural_direct(&mut self, index: usize, enabled: bool) {
        let mask = 1_u8 << (index + K0_PACKED_FRONTIER_EXISTS_STATE_SLOTS);
        if enabled {
            self.occupied |= mask;
        } else {
            self.occupied &= !mask;
        }
    }

    fn exact_floor_witness(&self, index: usize) -> Option<K0PackedFrontierExactWitness> {
        let length = self.exact_floor_witness_lengths[index];
        (length != 0).then_some(K0PackedFrontierExactWitness {
            start: self.exact_floor_witness_starts[index],
            bytes: self.exact_floor_witness_bytes[index],
            length,
        })
    }

    fn set_exact_floor_witness(
        &mut self,
        index: usize,
        witness: Option<K0PackedFrontierExactWitness>,
    ) {
        if let Some(witness) = witness {
            self.exact_floor_witness_starts[index] = witness.start;
            self.exact_floor_witness_bytes[index] = witness.bytes;
            self.exact_floor_witness_lengths[index] = witness.length;
        } else {
            self.exact_floor_witness_starts[index] = 0;
            self.exact_floor_witness_bytes[index] = 0;
            self.exact_floor_witness_lengths[index] = 0;
        }
    }

    fn preference(&self, index: usize) -> K0PackedFrontierExistsPreference {
        match (self.preferences >> (index * 2)) & 0b11 {
            0 => K0PackedFrontierExistsPreference::ObserveColdPacked,
            1 => K0PackedFrontierExistsPreference::RetainExactFloor,
            2 => K0PackedFrontierExistsPreference::TrialIncumbent,
            3 => K0PackedFrontierExistsPreference::RetainIncumbent,
            _ => unreachable!("two policy bits have exactly four values"),
        }
    }

    fn set_preference(&mut self, index: usize, preference: K0PackedFrontierExistsPreference) {
        let shift = index * 2;
        let mask = 0b11_u8 << shift;
        let value = match preference {
            K0PackedFrontierExistsPreference::ObserveColdPacked => 0,
            K0PackedFrontierExistsPreference::RetainExactFloor => 1,
            K0PackedFrontierExistsPreference::TrialIncumbent => 2,
            K0PackedFrontierExistsPreference::RetainIncumbent => 3,
        };
        self.preferences = (self.preferences & !mask) | (value << shift);
    }

    fn next_direct_epoch_calls(&mut self, index: usize) -> u8 {
        if !self.is_structural_direct(index) {
            return K0_PACKED_FRONTIER_DIRECT_EPOCH_CALLS;
        }
        let stage = usize::from(self.structural_epoch_stage[index])
            .min(K0_PACKED_FRONTIER_STRUCTURAL_EPOCH_CALLS.len() - 1);
        self.structural_epoch_stage[index] = u8::try_from(
            stage
                .saturating_add(1)
                .min(K0_PACKED_FRONTIER_STRUCTURAL_EPOCH_CALLS.len() - 1),
        )
        .expect("bounded structural Direct stage fits u8");
        K0_PACKED_FRONTIER_STRUCTURAL_EPOCH_CALLS[stage]
    }

    fn reset_direct_stability(&mut self, index: usize) {
        self.structural_epoch_stage[index] = 0;
    }

    fn reset_class(&mut self, index: usize, window: SearchWindow) {
        self.classes[index] = K0PackedFrontierExistsClassState {
            window,
            packed_residual_work: 0,
        };
        self.occupied |= 1_u8 << index;
        self.set_structural_direct(index, false);
        self.set_exact_floor_witness(index, None);
        self.set_preference(
            index,
            K0PackedFrontierExistsPreference::ObserveColdPacked,
        );
        self.direct_remaining[index] = 0;
        self.reset_direct_stability(index);
    }

    fn class_for(&mut self, window: SearchWindow) -> usize {
        if let Some(index) = (0..self.classes.len())
            .find(|&index| self.is_occupied(index) && self.classes[index].window == window)
        {
            return index;
        }
        if let Some(index) = (0..self.classes.len()).find(|&index| !self.is_occupied(index)) {
            self.reset_class(index, window);
            return index;
        }
        let index = usize::from(self.next_replacement) % self.classes.len();
        self.next_replacement = self.next_replacement.wrapping_add(1)
            % u8::try_from(self.classes.len()).expect("packed Exists state count fits u8");
        self.reset_class(index, window);
        index
    }

    fn select(&mut self, window: SearchWindow) -> K0PackedFrontierExistsRoute {
        let class_index = self.class_for(window);
        match self.preference(class_index) {
            K0PackedFrontierExistsPreference::ObserveColdPacked => {
                K0PackedFrontierExistsRoute::Packed { class_index }
            }
            preference @ (K0PackedFrontierExistsPreference::RetainExactFloor
            | K0PackedFrontierExistsPreference::TrialIncumbent
            | K0PackedFrontierExistsPreference::RetainIncumbent) => {
                let packed_positive = K0PackedFrontierPositiveObservation {
                    residual_work: self.classes[class_index].packed_residual_work,
                };
                // A selected trial is speculative until its authoritative
                // executor succeeds and publishes a measured win below.
                let trial = preference == K0PackedFrontierExistsPreference::TrialIncumbent;
                if trial {
                    self.set_preference(
                        class_index,
                        K0PackedFrontierExistsPreference::ObserveColdPacked,
                    );
                    self.direct_remaining[class_index] = 0;
                } else {
                    self.direct_remaining[class_index] =
                        self.direct_remaining[class_index].saturating_sub(1);
                    if self.direct_remaining[class_index] == 0 {
                        self.set_preference(
                            class_index,
                            K0PackedFrontierExistsPreference::ObserveColdPacked,
                        );
                    }
                }
                K0PackedFrontierExistsRoute::Incumbent {
                    class_index,
                    packed_positive,
                    trial,
                }
            }
        }
    }

    #[inline]
    fn retained_exact_floor(&self, window: SearchWindow) -> Option<usize> {
        let low_bits = self.preferences & 0x55;
        let high_bits = (self.preferences >> 1) & 0x55;
        let exact_bits = low_bits & !high_bits;
        if exact_bits == 0 {
            return None;
        }
        let class_index = (0..self.classes.len()).find(|&index| {
            self.is_occupied(index)
                && self.classes[index].window == window
                && self.preference(index)
                    == K0PackedFrontierExistsPreference::RetainExactFloor
                && self.direct_remaining[index] != 0
        })?;
        Some(class_index)
    }

    #[inline]
    fn retained_incumbent(
        &self,
        window: SearchWindow,
    ) -> Option<(usize, K0PackedFrontierPositiveObservation, bool)> {
        let low_bits = self.preferences & 0x55;
        let high_bits = (self.preferences >> 1) & 0x55;
        if low_bits & high_bits == 0 {
            return None;
        }
        let class_index = (0..self.classes.len()).find(|&index| {
            self.is_occupied(index)
                && self.classes[index].window == window
                && self.preference(index)
                    == K0PackedFrontierExistsPreference::RetainIncumbent
                && self.direct_remaining[index] != 0
        })?;
        Some((
            class_index,
            K0PackedFrontierPositiveObservation {
                residual_work: self.classes[class_index].packed_residual_work,
            },
            self.is_structural_direct(class_index),
        ))
    }

    #[inline]
    fn observe_retained_incumbent(
        &mut self,
        class_index: usize,
        packed_positive: K0PackedFrontierPositiveObservation,
        observation: K0PackedFrontierIncumbentObservation,
    ) -> bool {
        debug_assert_eq!(
            self.preference(class_index),
            K0PackedFrontierExistsPreference::RetainIncumbent,
        );
        debug_assert_ne!(self.direct_remaining[class_index], 0);
        self.direct_remaining[class_index] =
            self.direct_remaining[class_index].saturating_sub(1);
        let expired = self.direct_remaining[class_index] == 0;
        if expired {
            self.set_preference(
                class_index,
                K0PackedFrontierExistsPreference::ObserveColdPacked,
            );
        }
        self.observe_incumbent(class_index, packed_positive, false, observation);
        expired
    }

    fn observe_retained_exact_floor(
        &mut self,
        class_index: usize,
        haystack: &[u8],
        window: SearchWindow,
    ) {
        debug_assert_eq!(
            self.preference(class_index),
            K0PackedFrontierExistsPreference::RetainExactFloor,
        );
        debug_assert_ne!(self.direct_remaining[class_index], 0);
        self.direct_remaining[class_index] =
            self.direct_remaining[class_index].saturating_sub(1);
        if self.direct_remaining[class_index] != 0 {
            return;
        }
        self.set_preference(
            class_index,
            K0PackedFrontierExistsPreference::ObserveColdPacked,
        );
        if self
            .exact_floor_witness(class_index)
            .is_some_and(|witness| witness.is_present(haystack, window))
        {
            self.renew_exact_floor_direct(class_index);
        } else {
            self.expire_exact_floor_direct(class_index);
        }
    }

    fn renew_exact_floor_direct(&mut self, class_index: usize) {
        debug_assert_eq!(
            self.preference(class_index),
            K0PackedFrontierExistsPreference::ObserveColdPacked,
        );
        debug_assert_eq!(self.direct_remaining[class_index], 0);
        debug_assert!(self.is_structural_direct(class_index));
        debug_assert!(self.exact_floor_witness(class_index).is_some());
        self.set_preference(
            class_index,
            K0PackedFrontierExistsPreference::RetainExactFloor,
        );
        self.direct_remaining[class_index] = self.next_direct_epoch_calls(class_index);
    }

    fn expire_exact_floor_direct(&mut self, class_index: usize) {
        self.classes[class_index].packed_residual_work = 0;
        self.set_structural_direct(class_index, false);
        self.set_exact_floor_witness(class_index, None);
        self.set_preference(
            class_index,
            K0PackedFrontierExistsPreference::ObserveColdPacked,
        );
        self.direct_remaining[class_index] = 0;
        self.reset_direct_stability(class_index);
    }

    fn observe_packed(
        &mut self,
        class_index: usize,
        window: SearchWindow,
        observation: K0PackedFrontierObservation,
    ) {
        debug_assert!(self.is_occupied(class_index));
        debug_assert_eq!(self.classes[class_index].window, window);
        let preference = self.preference(class_index);
        debug_assert!(matches!(
            preference,
            K0PackedFrontierExistsPreference::ObserveColdPacked
        ));
        let positive = match observation {
            K0PackedFrontierObservation::Absent
            | K0PackedFrontierObservation::ProductiveOrDeep => {
                // Decisive packed outcomes invalidate both numerical backoff
                // and a structural Direct preference immediately.
                self.classes[class_index].packed_residual_work = 0;
                self.set_structural_direct(class_index, false);
                self.set_exact_floor_witness(class_index, None);
                self.set_preference(
                    class_index,
                    K0PackedFrontierExistsPreference::ObserveColdPacked,
                );
                self.direct_remaining[class_index] = 0;
                self.reset_direct_stability(class_index);
                return;
            }
            K0PackedFrontierObservation::ExactFloorDirect { witness } => {
                // This packed-positive call executed the incumbent over the
                // exact original window after paying an additional packed
                // pass. Direct therefore dominates structurally without a
                // second measured call. Retain only the ordinary bounded
                // epoch so a same-address source mutation is still reprobed.
                self.classes[class_index].packed_residual_work = 0;
                self.set_structural_direct(class_index, true);
                self.set_exact_floor_witness(class_index, Some(witness));
                self.set_preference(
                    class_index,
                    K0PackedFrontierExistsPreference::RetainExactFloor,
                );
                self.direct_remaining[class_index] =
                    self.next_direct_epoch_calls(class_index);
                return;
            }
            K0PackedFrontierObservation::ShallowCompletion(positive) => {
                // No same-call replay: the completed packed call remains
                // authoritative, and exactly one Direct trial owns the next
                // call before entering the ordinary bounded epoch.
                self.classes[class_index].packed_residual_work =
                    positive.residual_work;
                self.set_structural_direct(class_index, true);
                self.set_exact_floor_witness(class_index, None);
                self.set_preference(
                    class_index,
                    K0PackedFrontierExistsPreference::TrialIncumbent,
                );
                self.direct_remaining[class_index] = 0;
                return;
            }
            K0PackedFrontierObservation::Comparable(positive) => positive,
        };
        // An exact floor has made no residual-K0 progress. Keep its numerical
        // receipt and remember the structural fact so a sidecar that completes
        // without comparable K0 work cannot turn the Direct trial into a false
        // loss. The packed-positive call already executed the exact incumbent
        // tail over the original window, so the next Direct trial is warm and
        // needs no redundant second packed observation.
        self.set_structural_direct(class_index, true);
        self.set_exact_floor_witness(class_index, None);
        if preference == K0PackedFrontierExistsPreference::ObserveColdPacked
            && self.direct_remaining[class_index] != 0
        {
            self.direct_remaining[class_index] =
                self.direct_remaining[class_index].saturating_sub(1);
            return;
        }
        self.classes[class_index].packed_residual_work = positive.residual_work;
        self.set_preference(
            class_index,
            K0PackedFrontierExistsPreference::TrialIncumbent,
        );
    }

    fn observe_incumbent(
        &mut self,
        class_index: usize,
        packed_positive: K0PackedFrontierPositiveObservation,
        trial: bool,
        observation: K0PackedFrontierIncumbentObservation,
    ) {
        if self.is_structural_direct(class_index) {
            if !trial {
                return;
            }
            if observation == K0PackedFrontierIncumbentObservation::SpecializedComplete {
                // This receipt excludes every sidecar-decline-plus-K0 path.
                // A sidecar that authoritatively completed after the shallow
                // packed observation may retain only this bounded epoch.
                self.set_preference(
                    class_index,
                    K0PackedFrontierExistsPreference::RetainIncumbent,
                );
                self.direct_remaining[class_index] =
                    self.next_direct_epoch_calls(class_index);
                return;
            }
        }
        debug_assert_eq!(
            self.classes[class_index].packed_residual_work,
            packed_positive.residual_work,
        );
        if matches!(
            observation,
            K0PackedFrontierIncumbentObservation::RawK0 { work }
                if work <= packed_positive.residual_work
        ) {
            // Equal K0 work is a Direct win because it omits the additional
            // packed-kernel pass. No sidecar work enters this comparison.
            if trial {
                self.set_preference(
                    class_index,
                    K0PackedFrontierExistsPreference::RetainIncumbent,
                );
                self.direct_remaining[class_index] =
                    self.next_direct_epoch_calls(class_index);
            }
        } else {
            // Incomparable execution includes every sidecar decline or
            // fallback followed by K0. Treat it, and every measured loss,
            // conservatively before another calibration.
            self.classes[class_index].packed_residual_work = 0;
            self.set_structural_direct(class_index, false);
            self.set_exact_floor_witness(class_index, None);
            self.reset_direct_stability(class_index);
            self.set_preference(
                class_index,
                K0PackedFrontierExistsPreference::ObserveColdPacked,
            );
            self.direct_remaining[class_index] =
                K0_PACKED_FRONTIER_DIRECT_LOSS_BACKOFF_CALLS;
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct K0CorrelatedRouteStates {
    exists: correlated_bounded_alternation::RouteState,
    earliest_end: correlated_bounded_alternation::RouteState,
    span: correlated_bounded_alternation::RouteState,
}

/// Operation routing state for construction-exclusive K0 accelerators. The
/// compact correlated bundle and packed policy share one inline slot, so no
/// packed-only payload is added to ordinary K0 sessions. Otherwise empty
/// ordinary tags retain the value-iterator route in that same slot.
#[repr(u8)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0ExclusiveRouteState {
    NoneGeneral = 0,
    Correlated(K0CorrelatedRouteStates) = 1,
    Packed(K0PackedFrontierExistsState) = 2,
    NoneSourceBound = 3,
    NoneUnknown = 4,
}

impl K0ExclusiveRouteState {
    fn for_plan(plan: &K0ExclusivePlan) -> Self {
        match plan {
            K0ExclusivePlan::Packed(_) => Self::Packed(K0PackedFrontierExistsState::default()),
            K0ExclusivePlan::Correlated(_) => Self::Correlated(K0CorrelatedRouteStates::default()),
            K0ExclusivePlan::None | K0ExclusivePlan::Line(_) => Self::NoneUnknown,
        }
    }

    const fn value_iter_route(&self) -> K0ValueIterRoute {
        match self {
            Self::NoneGeneral => K0ValueIterRoute::General,
            Self::NoneSourceBound => K0ValueIterRoute::SourceBound,
            Self::NoneUnknown => K0ValueIterRoute::Unknown,
            Self::Correlated(_) | Self::Packed(_) => K0ValueIterRoute::General,
        }
    }

    fn set_value_iter_route(&mut self, route: K0ValueIterRoute) {
        if matches!(
            self,
            Self::NoneGeneral | Self::NoneSourceBound | Self::NoneUnknown
        ) {
            *self = match route {
                K0ValueIterRoute::General => Self::NoneGeneral,
                K0ValueIterRoute::SourceBound => Self::NoneSourceBound,
                K0ValueIterRoute::Unknown => Self::NoneUnknown,
            };
        }
    }

    fn packed_mut(&mut self) -> Option<&mut K0PackedFrontierExistsState> {
        match self {
            Self::Packed(state) => Some(state),
            Self::NoneGeneral
            | Self::NoneSourceBound
            | Self::NoneUnknown
            | Self::Correlated(_) => None,
        }
    }

    fn correlated_mut(&mut self) -> Option<&mut K0CorrelatedRouteStates> {
        match self {
            Self::Correlated(state) => Some(state),
            Self::NoneGeneral
            | Self::NoneSourceBound
            | Self::NoneUnknown
            | Self::Packed(_) => None,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct K0PackedFrontierPositiveObservation {
    residual_work: u64,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
enum K0PackedFrontierIncumbentObservation {
    #[default]
    Incomparable,
    RawK0 { work: u64 },
    SpecializedComplete,
}

impl K0PackedFrontierIncumbentObservation {
    const fn raw_k0_work(self) -> Option<u64> {
        match self {
            Self::RawK0 { work } => Some(work),
            Self::Incomparable | Self::SpecializedComplete => None,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0PackedFrontierObservation {
    Absent,
    ExactFloorDirect { witness: K0PackedFrontierExactWitness },
    Comparable(K0PackedFrontierPositiveObservation),
    ShallowCompletion(K0PackedFrontierPositiveObservation),
    ProductiveOrDeep,
}

fn classify_k0_packed_frontier_positive(
    window_start: usize,
    witness: K0PackedFrontierExactWitness,
    floor: usize,
    minimum_useful_progress_bytes: usize,
    residual_work: u64,
) -> K0PackedFrontierObservation {
    let positive = K0PackedFrontierPositiveObservation { residual_work };
    let progress = floor
        .checked_sub(window_start)
        .expect("the packed-frontier floor was window-validated");
    if progress == 0 {
        K0PackedFrontierObservation::ExactFloorDirect { witness }
    } else if progress < minimum_useful_progress_bytes {
        K0PackedFrontierObservation::ShallowCompletion(positive)
    } else {
        K0PackedFrontierObservation::ProductiveOrDeep
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct K0PackedFrontierExistsAttempt {
    output: bool,
    observation: K0PackedFrontierObservation,
}

/// One replacement-only Exists call bound to one immutable K0 plan, its exact
/// mutable session, and one immutably borrowed source. The source-bearing
/// receipt is call-local. Only its window geometry and numeric floor/work
/// observation may enter policy state, and those coordinates are never used
/// to narrow a later search.
struct K0PackedFrontierExistsReceipt<'p, 's, 'a, 'h> {
    plan: &'p K0PackedFrontierPlan,
    session: &'s mut K0SearchSession<'a>,
    haystack: &'h [u8],
    window: SearchWindow,
    search_limits: SearchLimits,
    packed_limits: PackedLiteralSetSearchLimits,
}

impl<'p, 's, 'a, 'h> K0PackedFrontierExistsReceipt<'p, 's, 'a, 'h> {
    fn admit(
        k0_plan: &'p PortableK0Plan,
        session: &'s mut K0SearchSession<'a>,
        haystack: &'h [u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<Option<Self>, SearchError> {
        let Some(plan) = k0_plan.packed_frontier() else {
            return Ok(None);
        };
        if !plan.is_bound_to(&k0_plan.automaton)
            || !session.is_bound_to(&k0_plan.automaton)
        {
            return Err(SearchError::K0(K0SearchError::InternalInvariant {
                detail: "K0 packed-frontier receipt crossed immutable plans",
            }));
        }
        // Preserve the existing constant-time absolute-end theorem and the
        // public K0 error identity for invalid or explicitly limited calls.
        if k0_plan.absolute_end_proof.is_some()
            || limits != SearchLimits::unlimited()
            || window.start() > window.end()
            || window.end() > haystack.len()
        {
            return Ok(None);
        }
        let window_bytes = window
            .end()
            .checked_sub(window.start())
            .expect("the packed-frontier window was validated");
        if window_bytes < plan.minimum_window_bytes {
            return Ok(None);
        }
        Ok(Some(Self {
            plan,
            session,
            haystack,
            window,
            search_limits: limits,
            packed_limits: PackedLiteralSetSearchLimits::unlimited(),
        }))
    }

    fn execute_packed<F>(
        self,
        execute_incumbent: F,
    ) -> Result<K0PackedFrontierExistsAttempt, SearchError>
    where
        F: FnOnce(
            &mut K0SearchSession<'_>,
            &[u8],
            SearchWindow,
            SearchLimits,
            Option<&mut K0PackedFrontierIncumbentObservation>,
        ) -> Result<bool, SearchError>,
    {
        // The packed owner returns its first frontier occurrence. Thus the
        // added work of an early positive is bounded by that early prefix,
        // while complete absence is the case that earns a whole-window K0
        // replacement. Cheap fallbacks cannot enter the scaled-short range.
        let (found, _) = self.plan.packed.find_window(
            self.haystack,
            LiteralWindow::new(self.window.start(), self.window.end()),
            self.packed_limits,
        )?;
        let Some((literal_start, literal_end)) = found else {
            // The graph proof covers every accepting trace below its mandatory
            // root, so exact complete-window packed absence completes Exists.
            return Ok(K0PackedFrontierExistsAttempt {
                output: false,
                observation: K0PackedFrontierObservation::Absent,
            });
        };
        if literal_start < self.window.start()
            || literal_start >= self.window.end()
            || literal_end <= literal_start
            || literal_end > self.window.end()
        {
            return Err(SearchError::K0(K0SearchError::InternalInvariant {
                detail: "K0 packed-frontier kernel returned a match outside its window",
            }));
        }
        // If a selected match starts at s and reaches its mandatory root at c,
        // c - s <= M. The exact leftmost frontier occurrence p is no later
        // than c, hence p - M <= s. One nonrecursive incumbent tail over
        // [F, E) sees every possible match and is the only post-positive
        // executor. A false earlier occurrence only moves F earlier.
        let floor = literal_start
            .saturating_sub(self.plan.maximum_before_root)
            .max(self.window.start());
        let witness = K0PackedFrontierExactWitness::from_match(
            self.haystack,
            literal_start,
            literal_end,
        )
        .ok_or(SearchError::K0(K0SearchError::InternalInvariant {
            detail: "K0 packed-frontier witness exceeded its proved four-byte bound",
        }))?;
        let mut incumbent_observation =
            K0PackedFrontierIncumbentObservation::Incomparable;
        let measured_work = if floor == self.window.start() {
            None
        } else {
            Some(&mut incumbent_observation)
        };
        let output = execute_incumbent(
            self.session,
            self.haystack,
            SearchWindow::new(floor, self.window.end()),
            self.search_limits,
            measured_work,
        )?;
        let observation = classify_k0_packed_frontier_positive(
            self.window.start(),
            witness,
            floor,
            self.plan.minimum_useful_progress_bytes(),
            incumbent_observation.raw_k0_work().unwrap_or(0),
        );
        Ok(K0PackedFrontierExistsAttempt {
            output,
            observation,
        })
    }
}

#[inline(never)]
fn execute_k0_packed_frontier_exact_retained<F>(
    receipt: K0PackedFrontierExistsReceipt<'_, '_, '_, '_>,
    state: &mut K0PackedFrontierExistsState,
    class_index: usize,
    execute_incumbent: F,
) -> Result<bool, SearchError>
where
    F: FnOnce(
        &mut K0SearchSession<'_>,
        &[u8],
        SearchWindow,
        SearchLimits,
        Option<&mut K0PackedFrontierIncumbentObservation>,
    ) -> Result<bool, SearchError>,
{
    let output = execute_incumbent(
        &mut *receipt.session,
        receipt.haystack,
        receipt.window,
        receipt.search_limits,
        None,
    )?;
    state.observe_retained_exact_floor(class_index, receipt.haystack, receipt.window);
    Ok(output)
}

#[inline(never)]
fn execute_k0_packed_frontier_other_retained<F>(
    receipt: K0PackedFrontierExistsReceipt<'_, '_, '_, '_>,
    state: &mut K0PackedFrontierExistsState,
    class_index: usize,
    packed_positive: K0PackedFrontierPositiveObservation,
    structural_direct: bool,
    execute_incumbent: F,
) -> Result<bool, SearchError>
where
    F: FnOnce(
        &mut K0SearchSession<'_>,
        &[u8],
        SearchWindow,
        SearchLimits,
        Option<&mut K0PackedFrontierIncumbentObservation>,
    ) -> Result<bool, SearchError>,
{
    if structural_direct {
        let output = execute_incumbent(
            &mut *receipt.session,
            receipt.haystack,
            receipt.window,
            receipt.search_limits,
            None,
        )?;
        let _ = state.observe_retained_incumbent(
            class_index,
            packed_positive,
            K0PackedFrontierIncumbentObservation::Incomparable,
        );
        return Ok(output);
    }
    let mut incumbent_observation = K0PackedFrontierIncumbentObservation::Incomparable;
    let output = execute_incumbent(
        &mut *receipt.session,
        receipt.haystack,
        receipt.window,
        receipt.search_limits,
        Some(&mut incumbent_observation),
    )?;
    let _ = state.observe_retained_incumbent(
        class_index,
        packed_positive,
        incumbent_observation,
    );
    Ok(output)
}

#[inline(never)]
fn execute_k0_packed_frontier_exists_slow<F>(
    receipt: K0PackedFrontierExistsReceipt<'_, '_, '_, '_>,
    state: &mut K0PackedFrontierExistsState,
    execute_incumbent: F,
) -> Result<bool, SearchError>
where
    F: FnOnce(
        &mut K0SearchSession<'_>,
        &[u8],
        SearchWindow,
        SearchLimits,
        Option<&mut K0PackedFrontierIncumbentObservation>,
    ) -> Result<bool, SearchError>,
{
    // Route selection and observations remain speculative until the sole
    // authoritative executor succeeds. Errors preserve the complete policy
    // state, including a pending incumbent retry.
    let mut state_after_success = *state;
    let route = state_after_success.select(receipt.window);
    let output = match route {
        K0PackedFrontierExistsRoute::Packed { class_index } => {
            let window = receipt.window;
            let attempt = receipt.execute_packed(execute_incumbent)?;
            state_after_success.observe_packed(class_index, window, attempt.observation);
            attempt.output
        }
        K0PackedFrontierExistsRoute::Incumbent {
            class_index,
            packed_positive,
            trial,
        } => {
            let mut incumbent_observation =
                K0PackedFrontierIncumbentObservation::Incomparable;
            let output = execute_incumbent(
                &mut *receipt.session,
                receipt.haystack,
                receipt.window,
                receipt.search_limits,
                Some(&mut incumbent_observation),
            )?;
            state_after_success.observe_incumbent(
                class_index,
                packed_positive,
                trial,
                incumbent_observation,
            );
            output
        }
    };
    *state = state_after_success;
    Ok(output)
}

fn execute_k0_packed_frontier_exists_route<F>(
    receipt: K0PackedFrontierExistsReceipt<'_, '_, '_, '_>,
    state: &mut K0PackedFrontierExistsState,
    execute_incumbent: F,
) -> Result<bool, SearchError>
where
    F: FnOnce(
        &mut K0SearchSession<'_>,
        &[u8],
        SearchWindow,
        SearchLimits,
        Option<&mut K0PackedFrontierIncumbentObservation>,
    ) -> Result<bool, SearchError>,
{
    // A retained epoch is already bound to this immutable packed plan and
    // exact source window by the receipt. Tail-dispatch each retained kind so
    // the exact-floor hot path inherits no slow transaction frame.
    if let Some(class_index) = state.retained_exact_floor(receipt.window) {
        return execute_k0_packed_frontier_exact_retained(
            receipt,
            state,
            class_index,
            execute_incumbent,
        );
    }
    if let Some((class_index, packed_positive, structural_direct)) =
        state.retained_incumbent(receipt.window)
    {
        return execute_k0_packed_frontier_other_retained(
            receipt,
            state,
            class_index,
            packed_positive,
            structural_direct,
            execute_incumbent,
        );
    }
    execute_k0_packed_frontier_exists_slow(receipt, state, execute_incumbent)
}

// A negative literal pass pays for itself only on a reusable, sufficiently
// large window. Requiring four windows of needle width limits exposure for
// long needles whose first occurrence is early while retaining the broad
// absent-input case this sidecar is meant to accelerate.
const K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES: usize = 1_024;
const K0_NEGATIVE_PREFILTER_WINDOW_NEEDLE_FACTOR: usize = 4;
const K0_NEGATIVE_PREFILTER_PRESENT_STREAK_LIMIT: u8 = 8;
const K0_NEGATIVE_PREFILTER_MAX_DISABLED_CALLS: u8 = 64;
const K0_NEGATIVE_PREFILTER_SIZE_CLASS_STATES: usize = 4;
const K0_SUFFIX_FORWARD_FALLBACK_BYTES: usize = 1_024;
// Scalar recovery is needed only for high bytes because the exact ASCII
// subset is scanned in bulk. High-heavy inputs fail open instead of turning
// this optional separator proof into an unbounded reverse byte walk.
const K0_SUFFIX_HIGH_BYTE_BACKWARD_MAX: usize = 256;
const K0_SUFFIX_MAX_CANDIDATES: usize = 8;
const K0_SUFFIX_REVERSE_CREDIT_BYTES: usize = 1_024;
const K0_SUFFIX_REVERSE_PROGRESS_FACTOR: usize = 2;
// A finite-width reverse proof must be substantially narrower than the source
// window before it may replace an ordinary left-to-right K0 pass.
const K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR: usize = 4;
// Finite short suffixes and the incumbent cut/conjunctive prefilter are two
// adaptive alternatives. New size classes try the incumbent first: an absent
// incumbent remains the cheapest negative proof, while a present incumbent
// gives the exact suffix one opportunity to bypass its candidate frontier.
const K0_FINITE_SUFFIX_INCUMBENT_ROUTE: u8 = 0;
const K0_FINITE_SUFFIX_EXACT_ROUTE: u8 = 1;
// Mandatory-suffix state uses only route ordinals zero and one. Retain
// adaptive classifications in otherwise unused bits instead of widening
// every size-class record. A universal suffix absence first calibrates the
// independent mandatory-predicate prefilter. If that predicate also proves
// absence, it can own stable negative traffic with less suffix-route
// dispatch; a present or unavailable predicate retries only after bounded
// exact-route backoff. The highest bit remains the ordinary K0 direct-route
// receipt.
const K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION: u8 = 1 << 5;
const K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_ROUTE: u8 = 1 << 6;
// Keep a compact receipt beside the route bits whenever this finite-suffix
// class has a nonzero retry clock. The ordinary exact route can then reject
// every exceptional state with one byte load; only the outlined decoder pays
// to load and update the separate counter.
const K0_FINITE_SUFFIX_BACKOFF_ROUTE: u8 = 1 << 4;
const K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_MASK: u8 =
    K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION
        | K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_ROUTE;
const K0_FINITE_SUFFIX_EXCEPTIONAL_ROUTE_MASK: u8 = K0_FINITE_SUFFIX_BACKOFF_ROUTE
    | K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_MASK;
const K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE: u8 = 1 << 7;
// `next_replacement` needs only two low bits for four size-class records.
// Once a universal suffix schedules an independent-predicate trial, retain a
// monotonic high-bit receipt there. Positive-only sessions can then skip the
// adaptive route decode with one load instead of testing every route flag.
const K0_NEGATIVE_PREFILTER_UNIVERSAL_INCUMBENT_POSSIBLE: u8 = 1 << 7;

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct K0NegativePrefilterClassState {
    present_streak: u8,
    disabled_calls: u8,
    present_backoff: u8,
    next_predicate: u8,
    window_size_class: Option<u32>,
}

impl K0NegativePrefilterClassState {
    const fn observe_absent(&mut self) {
        self.present_streak = 0;
        self.disabled_calls = 0;
        self.present_backoff = 0;
    }

    fn observe_present(&mut self) {
        self.present_streak = self.present_streak.saturating_add(1);
        if self.present_streak >= K0_NEGATIVE_PREFILTER_PRESENT_STREAK_LIMIT {
            self.present_streak = K0_NEGATIVE_PREFILTER_PRESENT_STREAK_LIMIT - 1;
            self.present_backoff = if self.present_backoff == 0 {
                1
            } else {
                self.present_backoff
                    .saturating_mul(2)
                    .min(K0_NEGATIVE_PREFILTER_MAX_DISABLED_CALLS)
            };
            self.disabled_calls = self.present_backoff;
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct K0NegativePrefilterState {
    classes: [K0NegativePrefilterClassState; K0_NEGATIVE_PREFILTER_SIZE_CLASS_STATES],
    next_replacement: u8,
}

impl K0NegativePrefilterState {
    fn class_for(&mut self, window_size_class: u32) -> usize {
        if let Some(index) = self
            .classes
            .iter()
            .position(|state| state.window_size_class == Some(window_size_class))
        {
            return index;
        }
        if let Some(index) = self
            .classes
            .iter()
            .position(|state| state.window_size_class.is_none())
        {
            self.classes[index].window_size_class = Some(window_size_class);
            return index;
        }
        let retained_flags = self.next_replacement
            & K0_NEGATIVE_PREFILTER_UNIVERSAL_INCUMBENT_POSSIBLE;
        let replacement_ordinal = self.next_replacement
            & !K0_NEGATIVE_PREFILTER_UNIVERSAL_INCUMBENT_POSSIBLE;
        let index = usize::from(replacement_ordinal) % self.classes.len();
        let next_replacement = replacement_ordinal
            .wrapping_add(1)
            % u8::try_from(self.classes.len()).expect("size-class state count fits u8");
        self.next_replacement = retained_flags | next_replacement;
        self.classes[index] = K0NegativePrefilterClassState {
            window_size_class: Some(window_size_class),
            ..K0NegativePrefilterClassState::default()
        };
        index
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0FiniteSuffixRoute {
    Incumbent { may_switch_to_suffix: bool },
    ExactSuffix,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0FiniteSuffixDirectRoute {
    FreshClass { class_index: usize },
    ExactLossBackoff,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0UniversalFiniteSuffixIncumbentRoute {
    Calibration { class_index: usize },
    Retained { class_index: usize },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(u8)]
enum K0UniversalFiniteSuffixRouteDecision {
    ContinueExact,
    Fallback,
    Calibration,
    Retained,
}

#[inline]
fn consume_k0_finite_suffix_backoff(class: &mut K0NegativePrefilterClassState) {
    debug_assert_ne!(class.disabled_calls, 0);
    debug_assert_ne!(class.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE, 0);
    class.disabled_calls -= 1;
    if class.disabled_calls == 0 {
        class.next_predicate &= !K0_FINITE_SUFFIX_BACKOFF_ROUTE;
    }
}

#[inline(never)]
fn resolve_k0_universal_finite_suffix_route(
    class: &mut K0NegativePrefilterClassState,
) -> K0UniversalFiniteSuffixRouteDecision {
    let route = class.next_predicate;
    if route & K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_ROUTE != 0 {
        return K0UniversalFiniteSuffixRouteDecision::Retained;
    }
    if route & K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION != 0 {
        if class.disabled_calls == 0 {
            debug_assert_eq!(route & K0_FINITE_SUFFIX_BACKOFF_ROUTE, 0);
            return K0UniversalFiniteSuffixRouteDecision::Calibration;
        }
        consume_k0_finite_suffix_backoff(class);
        return K0UniversalFiniteSuffixRouteDecision::ContinueExact;
    }
    consume_k0_finite_suffix_backoff(class);
    K0UniversalFiniteSuffixRouteDecision::Fallback
}

#[allow(
    clippy::too_many_arguments,
    reason = "the inline route must close the same finite-sidecar admission envelope before mutating adaptive state"
)]
#[inline]
fn select_k0_finite_suffix_direct_route(
    session: &K0SearchSession<'_>,
    state: &mut K0NegativePrefilterState,
    maximum_match_bytes: usize,
    haystack_len: usize,
    window: SearchWindow,
    limits: SearchLimits,
    enforce_width_ratio: bool,
) -> Option<K0FiniteSuffixDirectRoute> {
    if limits != SearchLimits::unlimited()
        || maximum_match_bytes == 0
        || window.start() > window.end()
        || window.end() > haystack_len
    {
        return None;
    }
    let window_bytes = window.end().checked_sub(window.start())?;
    if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || (enforce_width_ratio
            && maximum_match_bytes > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR)
        || !session.positive_end_verifier_available()
    {
        return None;
    }

    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let Some(class_index) = state
        .classes
        .iter()
        .position(|class| class.window_size_class == Some(window_size_class))
    else {
        // A size class receives one pure incumbent observation before any
        // optional sidecar work. The retained class makes this a one-time
        // exploration cost: a subsequent call may compare the cut/suffix
        // route, while an early first match pays exactly the ordinary K0 path.
        let class_index = state.class_for(window_size_class);
        return Some(K0FiniteSuffixDirectRoute::FreshClass { class_index });
    };
    let class = &mut state.classes[class_index];
    if class.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE != 0 {
        // An exact-route loss has already compared the incumbent and suffix
        // for this size class. Consume its retry clock without entering
        // either outlined sidecar or the independent negative prefilter;
        // ordinary K0 is the selected route for the complete call.
        class.next_predicate &=
            K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE | K0_FINITE_SUFFIX_BACKOFF_ROUTE;
        consume_k0_finite_suffix_backoff(class);
        return Some(K0FiniteSuffixDirectRoute::ExactLossBackoff);
    }
    None
}

#[inline]
fn k0_finite_suffix_exact_loss_backoff_pending(
    state: &K0NegativePrefilterState,
    window: SearchWindow,
) -> bool {
    // A negative-first session never creates a suffix class, so keep that hot
    // path to one predictable load. Once a positive call has compared and
    // rejected the exact route, recover the incumbent's existing direct
    // backoff before entering an independent whole-window prefilter.
    if state.classes[0].window_size_class.is_none() {
        return false;
    }
    let Some(window_bytes) = window.end().checked_sub(window.start()) else {
        return false;
    };
    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    state.classes.iter().any(|class| {
        class.window_size_class == Some(window_size_class)
            && class.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE != 0
    })
}

fn select_k0_finite_suffix_route(
    state: &mut K0NegativePrefilterClassState,
) -> K0FiniteSuffixRoute {
    if state.next_predicate & K0_FINITE_SUFFIX_EXACT_ROUTE != 0
        && state.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE == 0
    {
        return K0FiniteSuffixRoute::ExactSuffix;
    }
    state.next_predicate &=
        K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE | K0_FINITE_SUFFIX_BACKOFF_ROUTE;
    if state.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE != 0 {
        consume_k0_finite_suffix_backoff(state);
        K0FiniteSuffixRoute::Incumbent {
            may_switch_to_suffix: false,
        }
    } else {
        K0FiniteSuffixRoute::Incumbent {
            may_switch_to_suffix: true,
        }
    }
}

fn observe_k0_finite_suffix_loss(state: &mut K0NegativePrefilterClassState) {
    // The incumbent already ran successfully before this exact-route trial.
    // One completed loss therefore compares both alternatives for this size
    // class; enter bounded retry backoff immediately instead of requiring
    // eight more speculative suffix passes to rediscover the same result.
    state.present_streak = K0_NEGATIVE_PREFILTER_PRESENT_STREAK_LIMIT - 1;
    state.observe_present();
    state.next_predicate &= K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE;
    debug_assert_ne!(state.disabled_calls, 0);
    state.next_predicate |= K0_FINITE_SUFFIX_BACKOFF_ROUTE;
}

fn observe_k0_finite_suffix_win(state: &mut K0NegativePrefilterClassState) {
    state.observe_absent();
    // A sidecar win supersedes the first incumbent observation. Do not let a
    // negative result from an earlier haystack bias a subsequently proven
    // exact-route win for this size class.
    // Re-prime the incumbent on every successful operation. The following
    // call can cheaply prove absence, retain a strong candidate-floor skip,
    // or immediately readmit the exact suffix when the incumbent leaves most
    // of the window exposed. This prevents a sparse success from pinning the
    // session permanently to reverse verification after the input changes.
    state.next_predicate = K0_FINITE_SUFFIX_INCUMBENT_ROUTE;
}

fn observe_k0_finite_suffix_span_completed_proof(
    state: &mut K0NegativePrefilterClassState,
) {
    state.observe_absent();
    // A completed bounded reverse proof is the exact Span strategy's
    // structural success signal. Keep it selected across calls, including
    // when the incumbent cut leaves a narrow residual. A later verifier,
    // candidate, or resource decline takes the ordinary loss path and clears
    // this bit before entering bounded backoff.
    state.next_predicate = K0_FINITE_SUFFIX_EXACT_ROUTE;
}

fn observe_k0_finite_suffix_span_replay_fallback(
    state: &mut K0NegativePrefilterState,
    window: SearchWindow,
) {
    let window_bytes = window
        .end()
        .checked_sub(window.start())
        .expect("validated finite Span window does not underflow");
    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let class_index = state
        .classes
        .iter()
        .position(|class| class.window_size_class == Some(window_size_class))
        .expect("completed finite Span proof retains its size class");
    // The reverse proof was sound, but exact-start selected-end replay did
    // not close its own receipt and used authoritative whole-window K0.
    // Preserve that output while learning an exact-route loss rather than a
    // persistent win.
    observe_k0_finite_suffix_loss(&mut state.classes[class_index]);
}

fn observe_k0_finite_suffix_direct_incumbent(
    state: &mut K0NegativePrefilterClassState,
    single_pass_negative: bool,
) {
    // The first call for a size class must run ordinary K0 anyway. Reuse that
    // completed call's exact boundary receipt instead of scheduling a second
    // warm probe. A zero-boundary negative from the small scanner family
    // immediately selects bounded incumbent backoff; every other result
    // leaves the exact sidecar eligible on the following call.
    state.next_predicate = if single_pass_negative {
        K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE
    } else {
        K0_FINITE_SUFFIX_INCUMBENT_ROUTE
    };
    if single_pass_negative {
        observe_k0_finite_suffix_loss(state);
    }
}

const fn k0_finite_suffix_incumbent_single_pass_negative(
    state: &K0NegativePrefilterClassState,
) -> bool {
    state.next_predicate & K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE != 0
}

#[allow(
    clippy::too_many_arguments,
    reason = "the incumbent must close the same immutable suffix, predicate, source, and search-limit envelope before it may run"
)]
fn k0_universal_finite_suffix_incumbent_admitted(
    session: &K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    negative_prefilter: Option<&K0NegativePrefilterPlan>,
    haystack_len: usize,
    window: SearchWindow,
    limits: SearchLimits,
) -> bool {
    if limits != SearchLimits::unlimited()
        || window.start() > window.end()
        || window.end() > haystack_len
    {
        return false;
    }
    let Some(window_bytes) = window.end().checked_sub(window.start()) else {
        return false;
    };
    let Some((minimum_match_bytes, maximum_match_bytes)) =
        suffix.universal_finite_match_byte_bounds()
    else {
        return false;
    };
    if minimum_match_bytes == 0
        || minimum_match_bytes > maximum_match_bytes
        || suffix.needle().len() > minimum_match_bytes
        || window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || maximum_match_bytes > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
        || !k0_negative_prefilter_admitted(
            mandatory_cut,
            negative_prefilter,
            haystack_len,
            window,
            limits,
        )
        || !session.negative_terminal_has_reused_work_certificate(window_bytes)
    {
        return false;
    }
    true
}

#[cfg(test)]
#[allow(
    clippy::too_many_arguments,
    reason = "the test selector exercises the complete production incumbent admission envelope"
)]
fn select_k0_universal_finite_suffix_incumbent(
    session: &K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    negative_prefilter: Option<&K0NegativePrefilterPlan>,
    state: &K0NegativePrefilterState,
    haystack_len: usize,
    window: SearchWindow,
    limits: SearchLimits,
) -> Option<K0UniversalFiniteSuffixIncumbentRoute> {
    if state.next_replacement & K0_NEGATIVE_PREFILTER_UNIVERSAL_INCUMBENT_POSSIBLE == 0 {
        return None;
    }
    let window_bytes = window.end().checked_sub(window.start())?;
    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let class_index = state
        .classes
        .iter()
        .position(|class| class.window_size_class == Some(window_size_class))?;
    let class = &state.classes[class_index];
    let route = class.next_predicate;
    let selected = if route & K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_ROUTE != 0 {
        K0UniversalFiniteSuffixIncumbentRoute::Retained { class_index }
    } else if route & K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION != 0
        && class.disabled_calls == 0
    {
        K0UniversalFiniteSuffixIncumbentRoute::Calibration { class_index }
    } else {
        return None;
    };
    k0_universal_finite_suffix_incumbent_admitted(
        session,
        suffix,
        mandatory_cut,
        negative_prefilter,
        haystack_len,
        window,
        limits,
    )
    .then_some(selected)
}

fn observe_k0_universal_finite_suffix_incumbent(
    state: &mut K0NegativePrefilterState,
    class_index: usize,
    prefilter_absent: bool,
) {
    let class = &mut state.classes[class_index];
    if prefilter_absent {
        class.observe_absent();
        class.next_predicate = K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_ROUTE;
    } else {
        // The independent predicate was present or unavailable. Keep the
        // exact suffix selected and retry that predicate only after
        // exponentially bounded backoff.
        observe_k0_finite_suffix_loss(class);
        class.next_predicate = K0_FINITE_SUFFIX_EXACT_ROUTE
            | K0_FINITE_SUFFIX_BACKOFF_ROUTE
            | K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION;
    }
}

fn finish_k0_universal_finite_suffix_incumbent_failure(
    state: &mut K0NegativePrefilterState,
    class_index: usize,
    prior_backoff: u8,
    found: bool,
    suffix_completed_exact_proof: bool,
) {
    if !found {
        let class = &mut state.classes[class_index];
        class.present_backoff = prior_backoff;
        class.disabled_calls = 0;
        observe_k0_universal_finite_suffix_incumbent(state, class_index, false);
    } else if suffix_completed_exact_proof {
        observe_k0_finite_suffix_span_completed_proof(&mut state.classes[class_index]);
    }
}

fn schedule_k0_universal_finite_suffix_incumbent_calibration(
    state: &mut K0NegativePrefilterState,
    window: SearchWindow,
) {
    let window_bytes = window
        .end()
        .checked_sub(window.start())
        .expect("validated universal Span window does not underflow");
    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let class = state
        .classes
        .iter_mut()
        .find(|class| class.window_size_class == Some(window_size_class))
        .expect("completed universal suffix proof retains its size class");
    if class.next_predicate & K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION == 0 {
        class.next_predicate = K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION;
    }
    state.next_replacement |= K0_NEGATIVE_PREFILTER_UNIVERSAL_INCUMBENT_POSSIBLE;
}

fn observe_k0_mandatory_suffix_loss(
    state: &mut K0NegativePrefilterClassState,
    finite_recovery: bool,
) {
    if finite_recovery {
        observe_k0_finite_suffix_loss(state);
    } else {
        state.observe_present();
    }
}

fn observe_k0_mandatory_suffix_win(
    state: &mut K0NegativePrefilterClassState,
    finite_recovery: bool,
) {
    if finite_recovery {
        observe_k0_finite_suffix_win(state);
    } else {
        state.observe_absent();
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0NegativePrefilterOutcome {
    Bypass,
    Absent,
    Present,
}

fn k0_candidate_floor_leaves_broad_residual(
    candidate_floor: Option<usize>,
    window: SearchWindow,
) -> bool {
    candidate_floor.is_none_or(|floor| {
        let skipped = floor.saturating_sub(window.start());
        let remaining = window.end().saturating_sub(floor);
        skipped < remaining
    })
}

fn observe_k0_finite_suffix_incumbent(
    state: &mut K0NegativePrefilterState,
    class_index: usize,
    may_switch_to_suffix: bool,
    outcome: K0NegativePrefilterOutcome,
    candidate_floor: Option<usize>,
    window: SearchWindow,
) -> bool {
    let class = &mut state.classes[class_index];
    debug_assert_eq!(class.disabled_calls, 0);
    debug_assert_eq!(class.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE, 0);
    class.next_predicate &= K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE;
    // A finite graph cut publishes a sound lower bound for every possible
    // match start. If that bound removes at least as much source as it leaves,
    // ordinary K0 already owns the smaller residual search. Otherwise the
    // exact suffix gets one immediate trial; its measured verification work
    // decides whether retries back off. `None` carries no structural progress
    // evidence and therefore leaves the exact alternative eligible.
    let use_exact = may_switch_to_suffix
        && outcome != K0NegativePrefilterOutcome::Absent
        && k0_candidate_floor_leaves_broad_residual(candidate_floor, window);
    if use_exact {
        class.next_predicate |= K0_FINITE_SUFFIX_EXACT_ROUTE;
    }
    use_exact
}

fn observe_k0_finite_suffix_span_incumbent(
    state: &mut K0NegativePrefilterState,
    class_index: usize,
    may_switch_to_suffix: bool,
    outcome: K0NegativePrefilterOutcome,
) -> bool {
    let class = &mut state.classes[class_index];
    debug_assert_eq!(class.disabled_calls, 0);
    debug_assert_eq!(class.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE, 0);
    class.next_predicate &= K0_FINITE_SUFFIX_SINGLE_PASS_NEGATIVE;
    // Span's exact route has a bounded candidate, reverse-byte, and verifier
    // envelope. After the one pure incumbent observation, let every
    // non-absent call trial that route once regardless of how much the
    // incumbent floor narrowed the source. Completion retains the route;
    // actual structural or resource decline installs bounded backoff.
    let use_exact = may_switch_to_suffix && outcome != K0NegativePrefilterOutcome::Absent;
    if use_exact {
        class.next_predicate |= K0_FINITE_SUFFIX_EXACT_ROUTE;
    }
    use_exact
}

#[derive(Clone, Copy, Debug)]
struct K0NegativePrefilterAttempt {
    outcome: K0NegativePrefilterOutcome,
    candidate_floor: Option<usize>,
    cut_first_member: Option<usize>,
    state_after_success: K0NegativePrefilterState,
}

fn k0_negative_prefilter_admitted(
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    plan: Option<&K0NegativePrefilterPlan>,
    haystack_len: usize,
    window: SearchWindow,
    limits: SearchLimits,
) -> bool {
    if mandatory_cut.is_none() && plan.is_none() {
        return false;
    }
    if limits != SearchLimits::unlimited()
        || window.start() > window.end()
        || window.end() > haystack_len
    {
        return false;
    }
    let window_bytes = window.end() - window.start();
    let maximum_needle_bytes = plan.map_or(1, |plan| plan.maximum_needle_bytes);
    let minimum_window_bytes = K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES.max(
        maximum_needle_bytes.saturating_mul(K0_NEGATIVE_PREFILTER_WINDOW_NEEDLE_FACTOR),
    );
    window_bytes >= minimum_window_bytes
}

fn run_k0_negative_prefilter(
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    plan: Option<&K0NegativePrefilterPlan>,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
) -> K0NegativePrefilterAttempt {
    let unchanged = |outcome| K0NegativePrefilterAttempt {
        outcome,
        candidate_floor: None,
        cut_first_member: None,
        state_after_success: state,
    };
    if !k0_negative_prefilter_admitted(
        mandatory_cut,
        plan,
        haystack.len(),
        window,
        limits,
    ) {
        return unchanged(K0NegativePrefilterOutcome::Bypass);
    }
    let window_bytes = window.end() - window.start();
    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let mut next_state = state;
    let class_index = next_state.class_for(window_size_class);
    let class_state = &mut next_state.classes[class_index];
    if class_state.disabled_calls != 0 {
        class_state.disabled_calls -= 1;
        return K0NegativePrefilterAttempt {
            outcome: K0NegativePrefilterOutcome::Bypass,
            candidate_floor: None,
            cut_first_member: None,
            state_after_success: next_state,
        };
    }
    let literal_count = plan.map_or(0, |plan| plan.literals.len());
    let cut_count = usize::from(mandatory_cut.is_some());
    let predicate_count = cut_count
        .checked_add(literal_count)
        .expect("bounded negative-predicate count cannot overflow");
    if predicate_count == 0 {
        return unchanged(K0NegativePrefilterOutcome::Bypass);
    }
    // K0 already derives its own graph-proved forward start filter. Start at
    // the cheap graph cut when available, then the longest structural literal;
    // conjunctive inspection publishes literals in descending length order.
    // The exact suffix is a mutually exclusive positive-verification route.
    // Keeping an equal literal here is intentional fallback coverage for calls
    // where suffix verification bypasses before scanning. One probe owns
    // exactly one whole-window pass; retaining an absent predicate's ordinal
    // makes subsequent calls reuse the useful proof instead of paying for
    // other conjuncts first.
    let predicate_ordinal = usize::from(class_state.next_predicate) % predicate_count;
    let mut candidate_floor = None;
    let mut cut_first_member = None;
    let present = if predicate_ordinal < cut_count {
        let cut = mandatory_cut
            .copied()
            .expect("cut ordinal requires a mandatory-cut plan");
        match cut.first_member(&haystack[window.start()..window.end()]) {
            Some(first_member) => {
                candidate_floor = cut.candidate_floor(window.start(), first_member);
                cut_first_member = Some(first_member);
                true
            }
            None => false,
        }
    } else {
        let plan = plan.expect("literal ordinal requires a literal plan");
        let literal_index = predicate_ordinal
            .checked_sub(cut_count)
            .expect("literal predicate ordinal follows the cut");
        let literal = &plan.literals[literal_index];
        match literal.find_window(
            haystack,
            LiteralWindow::new(window.start(), window.end()),
            LiteralSearchLimits::unlimited(),
        ) {
            Ok((found, _)) => found.is_some(),
            Err(_) => return unchanged(K0NegativePrefilterOutcome::Bypass),
        }
    };
    if !present {
        class_state.observe_absent();
        K0NegativePrefilterAttempt {
            outcome: K0NegativePrefilterOutcome::Absent,
            candidate_floor: None,
            cut_first_member: None,
            state_after_success: next_state,
        }
    } else {
        if candidate_floor.is_some()
            && !k0_candidate_floor_leaves_broad_residual(candidate_floor, window)
        {
            // A sound cut that discards at least half the window is useful
            // positive evidence, not a failed negative probe. Retain its
            // ordinal and keep it enabled for stable sparse searches.
            class_state.observe_absent();
        } else {
            class_state.next_predicate = u8::try_from(
                predicate_ordinal
                    .checked_add(1)
                    .expect("bounded predicate ordinal cannot overflow")
                    % predicate_count,
            )
            .expect("bounded predicate count fits u8");
            class_state.observe_present();
        }
        K0NegativePrefilterAttempt {
            outcome: K0NegativePrefilterOutcome::Present,
            candidate_floor,
            cut_first_member,
            state_after_success: next_state,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0MandatorySuffixOutcome {
    Bypass,
    GeometryBypass,
    Incumbent {
        class_index: usize,
        may_switch_to_suffix: bool,
    },
    Fallback,
    Found(bool),
}

#[derive(Clone, Copy, Debug)]
struct K0MandatorySuffixAttempt {
    outcome: K0MandatorySuffixOutcome,
    state_after_success: K0NegativePrefilterState,
}

fn k0_mandatory_suffix_completed_negative_is_useful(
    state: &K0NegativePrefilterClassState,
    window_bytes: usize,
    candidates: usize,
    verifier_work: u64,
) -> bool {
    // A zero-candidate suffix is normally the sidecar's ideal negative proof.
    // It is nevertheless redundant when the completed first incumbent call
    // expanded no automaton boundary and its immutable start proof used the
    // same cheap one-to-three-byte scanner family. Prefer the one-pass native
    // route in that case. Once endpoint verification begins, learn from two
    // disjoint costs outside the base suffix pass: one additional literal
    // dispatch per candidate and the verifier's complete work receipt. The
    // receipt already charges each reverse source byte, so do not count its
    // physical traffic again. Equality pays for one extra window-equivalent
    // pass; anything larger should let ordinary K0 run directly after the
    // existing streak threshold.
    if candidates == 0 {
        return !k0_finite_suffix_incumbent_single_pass_negative(state);
    }
    u64::try_from(window_bytes).is_ok_and(|window_work| {
        u64::try_from(candidates)
            .ok()
            .and_then(|candidate_work| candidate_work.checked_add(verifier_work))
            .is_some_and(|extra_work| extra_work <= window_work)
    })
}

#[cfg(test)]
fn observe_k0_mandatory_suffix_completed_negative(
    state: &mut K0NegativePrefilterClassState,
    window_bytes: usize,
    candidates: usize,
    verifier_work: u64,
) {
    if k0_mandatory_suffix_completed_negative_is_useful(
        state,
        window_bytes,
        candidates,
        verifier_work,
    ) {
        state.observe_absent();
    } else {
        state.observe_present();
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0MandatorySuffixSpanOutcome {
    Bypass,
    GeometryBypass,
    Incumbent {
        class_index: usize,
        may_switch_to_suffix: bool,
    },
    Fallback,
    Absent,
    ProvedAbsent,
    Narrowed(usize),
    ProvedSpan {
        start: usize,
        end: usize,
    },
    ProvedStart {
        start: usize,
        maximum_match_bytes: usize,
    },
    UniversalIncumbent {
        class_index: usize,
        calibration: bool,
    },
}

#[derive(Clone, Copy, Debug)]
struct K0MandatorySuffixSpanAttempt {
    outcome: K0MandatorySuffixSpanOutcome,
    state_after_success: K0NegativePrefilterState,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0ReverseSuffixSpanAttempt {
    Unattempted,
    Bypass,
    Declined,
    Complete(Option<Match>),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct K0ReverseSuffixSpanExecution {
    attempt: K0ReverseSuffixSpanAttempt,
    transient_loss: bool,
}

impl K0ReverseSuffixSpanExecution {
    const fn new(attempt: K0ReverseSuffixSpanAttempt, transient_loss: bool) -> Self {
        Self {
            attempt,
            transient_loss,
        }
    }
}

fn decline_k0_reverse_suffix_span(
    suffix: &K0MandatorySuffixPlan,
    window_bytes: usize,
) -> K0ReverseSuffixSpanAttempt {
    suffix.disable_reverse_suffix_span(window_bytes);
    K0ReverseSuffixSpanAttempt::Declined
}

fn k0_reverse_suffix_overhead_is_admitted(
    cumulative_overhead: u64,
    incumbent_search_start: usize,
    endpoint: usize,
) -> Result<bool, K0SearchError> {
    let progress = endpoint.checked_sub(incumbent_search_start).ok_or(
        K0SearchError::InternalInvariant {
            detail: "reverse-suffix endpoint preceded its incumbent search floor",
        },
    )?;
    let progress = u64::try_from(progress).map_err(|_| K0SearchError::ArithmeticOverflow {
        computation: "reverse-suffix residual progress conversion",
    })?;
    Ok(cumulative_overhead <= progress)
}

fn add_k0_reverse_suffix_candidate_overhead(
    cumulative_overhead: u64,
    verification: fre_automata::K0PositiveEndStartVerification,
) -> Result<u64, K0SearchError> {
    cumulative_overhead
        .checked_add(verification.receipt().work())
        .ok_or(K0SearchError::ArithmeticOverflow {
            computation: "cumulative reverse-suffix verifier overhead",
        })
}

fn add_k0_reverse_suffix_finder_dispatch(
    cumulative_overhead: u64,
) -> Result<u64, K0SearchError> {
    // The source ranges of the precompiled fast finder move monotonically.
    // One abstract work unit represents each invocation's non-telescoping
    // dispatch/confirmation cost. This is deliberately not LiteralAccounting:
    // its searched-byte term is a conservative resource certificate, not a
    // measure of the native finder's physical comparisons.
    cumulative_overhead
        .checked_add(1)
        .ok_or(K0SearchError::ArithmeticOverflow {
            computation: "cumulative reverse-suffix finder dispatches",
        })
}

/// Execute the unbounded reverse-suffix theorem after the caller has found
/// the first exact occurrence. Every soft refusal returns to the caller; no
/// rejected floor escapes this invocation, and only the caller chooses the
/// authoritative ordinary-K0 fallback window.
#[inline(never)]
fn execute_k0_reverse_suffix_span_from_first(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    haystack: &[u8],
    original_window: SearchWindow,
    incumbent_search_start: usize,
    limits: SearchLimits,
    first_occurrence: (usize, usize),
) -> Result<K0ReverseSuffixSpanExecution, K0SearchError> {
    if limits != SearchLimits::unlimited()
        || !suffix.has_reverse_suffix_span()
        || original_window.start() > original_window.end()
        || original_window.end() > haystack.len()
        || incumbent_search_start < original_window.start()
        || incumbent_search_start > original_window.end()
        || !session.positive_end_verifier_available()
    {
        return Ok(K0ReverseSuffixSpanExecution::new(
            K0ReverseSuffixSpanAttempt::Bypass,
            false,
        ));
    }
    let window_bytes = original_window.end() - original_window.start();
    if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || suffix.reverse_suffix_span_is_disabled(window_bytes)
    {
        return Ok(K0ReverseSuffixSpanExecution::new(
            K0ReverseSuffixSpanAttempt::Bypass,
            false,
        ));
    }

    let mut occurrence = Some(first_occurrence);
    let mut search_start = first_occurrence.0;
    // The first suffix candidate may inspect the complete preceding window.
    // After a rejection, a later candidate may inspect only source at or
    // after the rejected endpoint. If its live reverse frontier would cross
    // that boundary, the private verifier declines and ordinary K0 remains
    // authoritative. Completed negative regions are therefore disjoint and
    // total reverse source traffic is linear in the invocation window.
    let mut reverse_floor = incumbent_search_start;
    let mut cumulative_overhead = add_k0_reverse_suffix_finder_dispatch(0)?;
    loop {
        let Some((occurrence_start, endpoint)) = occurrence else {
            let transient_loss = !k0_reverse_suffix_overhead_is_admitted(
                cumulative_overhead,
                incumbent_search_start,
                original_window.end(),
            )?;
            // The result is already proved negative. Return a bounded
            // performance observation to the thin admission owner; this call
            // keeps its exact completed result.
            return Ok(K0ReverseSuffixSpanExecution::new(
                K0ReverseSuffixSpanAttempt::Complete(None),
                transient_loss,
            ));
        };
        if occurrence_start < search_start
            || endpoint != occurrence_start.saturating_add(suffix.needle().len())
            || endpoint > original_window.end()
            || endpoint <= original_window.start()
        {
            return Err(K0SearchError::InternalInvariant {
                detail: "reverse-suffix occurrence escaped its invocation window",
            });
        }
        if !k0_reverse_suffix_overhead_is_admitted(
            cumulative_overhead,
            incumbent_search_start,
            endpoint,
        )? {
            return Ok(K0ReverseSuffixSpanExecution::new(
                K0ReverseSuffixSpanAttempt::Bypass,
                true,
            ));
        }
        // Rust's reverse-suffix search retains overlapping literal
        // occurrences, but its limited reverse DFA falls back as soon as a
        // later candidate needs source before the prior endpoint. Make that
        // source-independent consequence explicit before resetting FRE's
        // verifier: no match at this endpoint can publish a start at or above
        // `reverse_floor` when the suffix itself begins before the floor.
        if occurrence_start < reverse_floor {
            return Ok(K0ReverseSuffixSpanExecution::new(
                K0ReverseSuffixSpanAttempt::Bypass,
                true,
            ));
        }
        let reverse_bytes = endpoint.checked_sub(reverse_floor).ok_or(
            K0SearchError::InternalInvariant {
                detail: "reverse-suffix endpoint preceded its monotone reverse floor",
            },
        )?;
        let Some(allowed_work) = session.positive_end_verifier_work_certificate(reverse_bytes)
        else {
            return Ok(K0ReverseSuffixSpanExecution::new(
                K0ReverseSuffixSpanAttempt::Bypass,
                false,
            ));
        };
        let verification = session
            .try_earliest_start_ending_at(
                haystack,
                SearchWindow::new(incumbent_search_start, endpoint),
                endpoint,
                K0PositiveEndLimits::new(allowed_work, reverse_bytes),
            )
            ?;
        match verification.outcome() {
            K0PositiveEndStartOutcome::Matched { start } => {
                if start < original_window.start() || start >= endpoint {
                    return Err(K0SearchError::InternalInvariant {
                        detail: "reverse-suffix verifier returned an invalid start",
                    });
                }
                if start < reverse_floor {
                    return Err(K0SearchError::InternalInvariant {
                        detail: "reverse-suffix verifier crossed its monotone reverse floor",
                    });
                }
                let replay_window = SearchWindow::new(start, original_window.end());
                let selected_end = session.search_proved_exact_start_selected_end_value(
                    haystack,
                    replay_window,
                    limits,
                )?;
                if let Some(end) = selected_end
                    && start < end
                    && end <= original_window.end()
                {
                    let completed_overhead = add_k0_reverse_suffix_candidate_overhead(
                        cumulative_overhead,
                        verification,
                    )?;
                    // The exact-start replay replaces the incumbent's tail
                    // from `start`; the successful reverse verification is
                    // the duplicate work. The fast literal source pass stays
                    // outside this source-normalized scalar, matching the
                    // route's static precompiled-finder premise. Keep this
                    // call's already-computed exact result, but cool down a
                    // shape whose verifier work exceeds the skipped prefix.
                    let transient_loss = !k0_reverse_suffix_overhead_is_admitted(
                        completed_overhead,
                        incumbent_search_start,
                        start,
                    )?;
                    return Ok(K0ReverseSuffixSpanExecution::new(
                        K0ReverseSuffixSpanAttempt::Complete(Some(Match { start, end })),
                        transient_loss,
                    ));
                }
                return Err(K0SearchError::InternalInvariant {
                    detail: "proved reverse-suffix start failed selected-end replay",
                });
            }
            K0PositiveEndStartOutcome::Declined => {
                // Exhausting the exact interval after a prior rejection is
                // source-dependent anti-quadratic evidence, not a plan-size
                // failure: let ordinary K0 own this call without poisoning
                // future haystacks in the same adaptive size class. An
                // earlier decline indicates an unavailable/resource-limited
                // verifier and permanently disables this size class.
                if verification.receipt().reverse_byte_limit_reached() {
                    return Ok(K0ReverseSuffixSpanExecution::new(
                        K0ReverseSuffixSpanAttempt::Bypass,
                        true,
                    ));
                }
                return Ok(K0ReverseSuffixSpanExecution::new(
                    decline_k0_reverse_suffix_span(suffix, window_bytes),
                    false,
                ));
            }
            K0PositiveEndStartOutcome::Rejected => {
                reverse_floor = endpoint;
                cumulative_overhead = add_k0_reverse_suffix_candidate_overhead(
                    cumulative_overhead,
                    verification,
                )?;
            }
        }
        search_start = occurrence_start.checked_add(1).ok_or(
            K0SearchError::ArithmeticOverflow {
                computation: "next overlapping reverse-suffix occurrence",
            },
        )?;
        occurrence = match suffix.find_window(haystack, search_start, original_window.end()) {
            Ok(occurrence) => occurrence,
            Err(_) => {
                return Ok(K0ReverseSuffixSpanExecution::new(
                    K0ReverseSuffixSpanAttempt::Bypass,
                    false,
                ));
            }
        };
        cumulative_overhead = add_k0_reverse_suffix_finder_dispatch(cumulative_overhead)?;
    }
}

#[cfg(test)]
fn try_execute_k0_reverse_suffix_span(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
) -> Result<K0ReverseSuffixSpanAttempt, K0SearchError> {
    try_execute_k0_reverse_suffix_span_after_incumbent(
        session,
        suffix,
        haystack,
        window,
        window.start(),
        window.start(),
        limits,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "the reverse theorem consumes the incumbent's two authenticated floors"
)]
fn try_execute_k0_reverse_suffix_span_after_incumbent(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    haystack: &[u8],
    window: SearchWindow,
    incumbent_search_start: usize,
    suffix_search_start: usize,
    limits: SearchLimits,
) -> Result<K0ReverseSuffixSpanAttempt, K0SearchError> {
    if limits != SearchLimits::unlimited()
        || !suffix.has_reverse_suffix_span()
        || window.start() > window.end()
        || window.end() > haystack.len()
        || incumbent_search_start < window.start()
        || incumbent_search_start > suffix_search_start
        || suffix_search_start > window.end()
        || window.end().saturating_sub(window.start()) < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || !session.positive_end_verifier_available()
        || !suffix.reverse_suffix_span_is_eligible(
            window.end().saturating_sub(window.start()),
        )
    {
        return Ok(K0ReverseSuffixSpanAttempt::Unattempted);
    }
    let window_bytes = window.end().saturating_sub(window.start());
    let Some(admission) = suffix.try_admit_reverse_suffix_span(window_bytes) else {
        return Ok(K0ReverseSuffixSpanAttempt::Unattempted);
    };
    let first = match suffix.find_window(haystack, suffix_search_start, window.end()) {
        Ok(Some(first)) => first,
        Ok(None) => return Ok(K0ReverseSuffixSpanAttempt::Complete(None)),
        Err(_) => return Ok(K0ReverseSuffixSpanAttempt::Bypass),
    };
    let execution = execute_k0_reverse_suffix_span_from_first(
        session,
        suffix,
        haystack,
        window,
        incumbent_search_start,
        limits,
        first,
    )?;
    if execution.transient_loss {
        admission.observe_loss();
    } else {
        drop(admission);
    }
    Ok(execution.attempt)
}

fn finish_k0_finite_mandatory_suffix_start(
    mut state: K0NegativePrefilterState,
    class_index: usize,
    start: usize,
    maximum_match_bytes: usize,
) -> K0MandatorySuffixSpanAttempt {
    // Reaching this point completed the bounded reverse proof over the exact
    // residual window. The incumbent's candidate floor is part of that proof,
    // not a byte-savings threshold: equality still authenticates `start` as
    // the globally earliest possible start. Preserve the proof for the
    // selected-end replay. Only structural/resource decline paths above learn
    // a loss and enter bounded incumbent backoff.
    observe_k0_finite_suffix_span_completed_proof(
        &mut state.classes[class_index],
    );
    K0MandatorySuffixSpanAttempt {
        outcome: K0MandatorySuffixSpanOutcome::ProvedStart {
            start,
            maximum_match_bytes,
        },
        state_after_success: state,
    }
}

fn finish_k0_universal_finite_mandatory_suffix_span(
    mut state: K0NegativePrefilterState,
    class_index: usize,
    start: usize,
    end: usize,
) -> K0MandatorySuffixSpanAttempt {
    observe_k0_finite_suffix_span_completed_proof(
        &mut state.classes[class_index],
    );
    K0MandatorySuffixSpanAttempt {
        outcome: K0MandatorySuffixSpanOutcome::ProvedSpan { start, end },
        state_after_success: state,
    }
}

fn finish_k0_finite_mandatory_suffix_absent(
    mut state: K0NegativePrefilterState,
    class_index: usize,
    window_bytes: usize,
    candidates: usize,
    verifier_work: u64,
) -> K0MandatorySuffixSpanAttempt {
    if k0_mandatory_suffix_completed_negative_is_useful(
        &state.classes[class_index],
        window_bytes,
        candidates,
        verifier_work,
    ) {
        observe_k0_finite_suffix_win(&mut state.classes[class_index]);
    } else {
        observe_k0_finite_suffix_loss(&mut state.classes[class_index]);
    }
    K0MandatorySuffixSpanAttempt {
        outcome: K0MandatorySuffixSpanOutcome::Absent,
        state_after_success: state,
    }
}

#[cold]
#[inline(never)]
#[allow(
    clippy::too_many_arguments,
    reason = "greedy endpoint refinement carries one already-authenticated corridor window"
)]
fn try_k0_universal_finite_greedy_suffix_endpoint(
    suffix: &K0MandatorySuffixPlan,
    haystack: &[u8],
    start: usize,
    proof_start: usize,
    search_start: usize,
    minimum_prefix_bytes: usize,
    maximum_prefix_bytes: usize,
    maximum_suffix_start: usize,
    window_end: usize,
) -> Result<Option<usize>, SearchError> {
    if start != proof_start {
        return Err(SearchError::K0(K0SearchError::InternalInvariant {
            detail: "near-floor greedy suffix did not retain the proved floor",
        }));
    }
    let reverse_end = maximum_suffix_start
        .checked_add(suffix.needle().len())
        .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
            computation: "universal finite greedy suffix horizon",
        }))?
        .min(window_end);
    if search_start > reverse_end {
        return Err(SearchError::K0(K0SearchError::InternalInvariant {
            detail: "universal finite greedy suffix window inverted",
        }));
    }
    let Ok(Some((selected_suffix_start, selected_endpoint))) =
        suffix.rfind_window(haystack, search_start, reverse_end)
    else {
        return Ok(None);
    };
    let selected_prefix_bytes = selected_suffix_start.checked_sub(start).ok_or(
        SearchError::K0(K0SearchError::InternalInvariant {
            detail: "greedy suffix preceded its proved start",
        }),
    )?;
    if selected_suffix_start < search_start
        || selected_suffix_start > maximum_suffix_start
        || selected_prefix_bytes < minimum_prefix_bytes
        || selected_prefix_bytes > maximum_prefix_bytes
        || selected_suffix_start.checked_add(suffix.needle().len()) != Some(selected_endpoint)
        || selected_endpoint > reverse_end
    {
        return Err(SearchError::K0(K0SearchError::InternalInvariant {
            detail: "universal finite greedy suffix escaped its proved horizon",
        }));
    }
    Ok(Some(selected_endpoint))
}

#[inline(never)]
#[allow(
    clippy::too_many_arguments,
    reason = "the universal finite corridor keeps its immutable geometry, floor, and adaptive state together"
)]
fn try_k0_universal_finite_mandatory_suffix_span_start<
    const ITERATOR_CONTINUATION: bool,
>(
    suffix: &K0MandatorySuffixPlan,
    minimum_match_bytes: usize,
    maximum_match_bytes: usize,
    greedy_corridor: bool,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixSpanAttempt, SearchError> {
    let unchanged = |outcome| K0MandatorySuffixSpanAttempt {
        outcome,
        state_after_success: state,
    };
    if limits != SearchLimits::unlimited()
        || minimum_match_bytes == 0
        || minimum_match_bytes > maximum_match_bytes
        || suffix.needle().len() > minimum_match_bytes
        || window.start() > window.end()
        || window.end() > haystack.len()
        || incumbent_candidate_floor
            .is_some_and(|floor| !(window.start()..=window.end()).contains(&floor))
    {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    }
    let Some(window_bytes) = window.end().checked_sub(window.start()) else {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    };
    if !ITERATOR_CONTINUATION
        && (window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
            || maximum_match_bytes > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR)
    {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::GeometryBypass));
    }

    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let mut next_state = state;
    let class_index = next_state.class_for(window_size_class);
    let class = &mut next_state.classes[class_index];
    if class.next_predicate & K0_FINITE_SUFFIX_EXCEPTIONAL_ROUTE_MASK != 0
        && !ITERATOR_CONTINUATION
    {
        let decision = resolve_k0_universal_finite_suffix_route(class);
        match decision {
            K0UniversalFiniteSuffixRouteDecision::ContinueExact => {}
            K0UniversalFiniteSuffixRouteDecision::Fallback => {
                // A literal/preflight or exact-replay loss clears the
                // calibration bit while retaining its bounded retry clock.
                // Honor that defensive state by selecting authoritative K0
                // until the clock expires instead of repeating suffix work.
                return Ok(K0MandatorySuffixSpanAttempt {
                    outcome: K0MandatorySuffixSpanOutcome::Fallback,
                    state_after_success: next_state,
                });
            }
            K0UniversalFiniteSuffixRouteDecision::Calibration => {
                return Ok(K0MandatorySuffixSpanAttempt {
                    outcome: K0MandatorySuffixSpanOutcome::UniversalIncumbent {
                        class_index,
                        calibration: true,
                    },
                    state_after_success: next_state,
                });
            }
            K0UniversalFiniteSuffixRouteDecision::Retained => {
                return Ok(K0MandatorySuffixSpanAttempt {
                    outcome: K0MandatorySuffixSpanOutcome::UniversalIncumbent {
                        class_index,
                        calibration: false,
                    },
                    state_after_success: next_state,
                });
            }
        }
    }

    let proof_start = incumbent_candidate_floor.unwrap_or(window.start());
    let minimum_prefix_bytes = minimum_match_bytes - suffix.needle().len();
    let maximum_prefix_bytes = maximum_match_bytes - suffix.needle().len();
    let search_start = proof_start
        .saturating_add(minimum_prefix_bytes)
        .min(window.end());
    let occurrence = match suffix.find_window(haystack, search_start, window.end()) {
        Ok(occurrence) => occurrence,
        Err(_) => {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        }
    };
    let Some((occurrence_start, endpoint)) = occurrence else {
        let class = &mut next_state.classes[class_index];
        if !ITERATOR_CONTINUATION
            && class.next_predicate
                & K0_FINITE_SUFFIX_UNIVERSAL_INCUMBENT_CALIBRATION
                != 0
        {
            // The exact suffix remains authoritative while a failed
            // incumbent calibration drains its bounded retry clock. Preserve
            // both that completed proof preference and the pending retry.
        } else {
            // Retain the exact proof by default. The facade schedules an
            // independent-predicate calibration only when that competing
            // plan is actually admitted for this operation.
            observe_k0_finite_suffix_span_completed_proof(class);
        }
        return Ok(K0MandatorySuffixSpanAttempt {
            // Mandatory-suffix absence plus the immutable universal corridor
            // is a complete language proof; no runtime reverse certificate is
            // required before publication.
            outcome: K0MandatorySuffixSpanOutcome::ProvedAbsent,
            state_after_success: next_state,
        });
    };

    // Let q be this first suffix start at or after F + minimum_prefix. Every
    // width in the certified prefix corridor is accepted for every byte
    // string, so max(F, q - maximum_prefix) is a real matching start. Any
    // match beginning at F or later ends in a suffix occurrence r >= q and
    // has prefix width at most maximum_prefix, hence cannot start earlier.
    let start = occurrence_start
        .saturating_sub(maximum_prefix_bytes)
        .max(proof_start);
    if occurrence_start.checked_add(suffix.needle().len()) != Some(endpoint)
        || endpoint > window.end()
        || start > occurrence_start
        || occurrence_start.saturating_sub(start) < minimum_prefix_bytes
        || occurrence_start.saturating_sub(start) > maximum_prefix_bytes
    {
        return Err(SearchError::K0(K0SearchError::InternalInvariant {
            detail: "universal finite mandatory-suffix occurrence escaped its proved corridor",
        }));
    }
    // There is a stronger endpoint corollary when q >= F + maximum_prefix.
    // Here the globally earliest start is q - maximum_prefix. The first
    // eligible occurrence q is the only suffix position that can terminate a
    // match at that start: any later q' would have q' - start greater than the
    // certified maximum prefix width. Thus q plus the literal suffix length
    // is the selected endpoint even for greedy, lazy, and ordered-alternation
    // plans. Equality at the horizon is sufficient. Below the horizon the
    // earliest start remains F, possibly for several suffix positions, so
    // exact-start selected-end replay remains necessary.
    let maximum_suffix_start = proof_start.checked_add(maximum_prefix_bytes).ok_or(
        SearchError::K0(K0SearchError::ArithmeticOverflow {
            computation: "universal finite suffix-start horizon",
        }),
    )?;
    if occurrence_start >= maximum_suffix_start {
        return Ok(finish_k0_universal_finite_mandatory_suffix_span(
            next_state,
            class_index,
            start,
            endpoint,
        ));
    }
    if greedy_corridor {
        if let Some(selected_endpoint) = try_k0_universal_finite_greedy_suffix_endpoint(
            suffix,
            haystack,
            start,
            proof_start,
            search_start,
            minimum_prefix_bytes,
            maximum_prefix_bytes,
            maximum_suffix_start,
            window.end(),
        )? {
            return Ok(finish_k0_universal_finite_mandatory_suffix_span(
                next_state,
                class_index,
                start,
                selected_endpoint,
            ));
        }
    }
    Ok(finish_k0_finite_mandatory_suffix_start(
        next_state,
        class_index,
        start,
        maximum_match_bytes,
    ))
}

#[inline(never)]
#[allow(
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "the finite-width proof keeps admission, exact caps, and adaptive publication in one transaction"
)]
fn try_k0_finite_mandatory_suffix_span_start(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    minimum_match_bytes: usize,
    maximum_match_bytes: usize,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixSpanAttempt, SearchError> {
    let unchanged = |outcome| K0MandatorySuffixSpanAttempt {
        outcome,
        state_after_success: state,
    };
    if limits != SearchLimits::unlimited()
        || minimum_match_bytes == 0
        || minimum_match_bytes > maximum_match_bytes
        || maximum_match_bytes == 0
        || suffix.needle().len() > minimum_match_bytes
        || window.start() > window.end()
        || window.end() > haystack.len()
        || incumbent_candidate_floor
            .is_some_and(|floor| !(window.start()..=window.end()).contains(&floor))
    {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    }
    let Some(window_bytes) = window.end().checked_sub(window.start()) else {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    };
    if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || maximum_match_bytes
            > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
        || !session.positive_end_verifier_available()
    {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    }

    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let mut next_state = state;
    let class_index = next_state.class_for(window_size_class);
    match select_k0_finite_suffix_route(&mut next_state.classes[class_index]) {
        K0FiniteSuffixRoute::Incumbent {
            may_switch_to_suffix,
        } => {
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Incumbent {
                    class_index,
                    may_switch_to_suffix,
                },
                state_after_success: next_state,
            });
        }
        K0FiniteSuffixRoute::ExactSuffix => {}
    }

    let proof_start = incumbent_candidate_floor.unwrap_or(window.start());
    let proof_window_bytes = window.end().saturating_sub(proof_start);
    // A required suffix of length `s` belonging to a match of at least `m`
    // bytes cannot begin before `proof_start + (m - s)`. Start the literal
    // finder at that authenticated horizon instead of enumerating impossible
    // early occurrences. Saturation and the window clamp only turn a
    // no-room-for-a-match case into an immediate completed-negative proof.
    let mut search_start = proof_start
        .saturating_add(minimum_match_bytes - suffix.needle().len())
        .min(window.end());
    let mut candidates = 0usize;
    let mut cumulative_work = 0u64;
    let mut cumulative_reverse_bytes = 0usize;
    let mut best_start = None;
    loop {
        // Once a matching start `best` is known, a later suffix endpoint at
        // or beyond `best + maximum_match_bytes` cannot lead to an earlier
        // start. Limit the next literal pass to that proof horizon instead of
        // scanning an irrelevant remainder of the caller's window. Saturation
        // only weakens the bound back to the validated window end.
        let search_end = best_start.map_or(window.end(), |best: usize| {
            best.saturating_add(maximum_match_bytes).min(window.end())
        });
        if search_start >= search_end {
            return Ok(if let Some(start) = best_start {
                finish_k0_finite_mandatory_suffix_start(
                    next_state,
                    class_index,
                    start,
                    maximum_match_bytes,
                )
            } else {
                // Rejecting the last suffix candidate advances the scan to
                // the ordinary half-open window end. That closes a valid
                // completed-negative proof; it is not a horizon invariant
                // failure merely because no earlier candidate matched.
                finish_k0_finite_mandatory_suffix_absent(
                    next_state,
                    class_index,
                    proof_window_bytes,
                    candidates,
                    cumulative_work,
                )
            });
        }
        let occurrence = match suffix.find_window(haystack, search_start, search_end) {
            Ok(occurrence) => occurrence,
            Err(_) => {
                observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
                return Ok(K0MandatorySuffixSpanAttempt {
                    outcome: K0MandatorySuffixSpanOutcome::Fallback,
                    state_after_success: next_state,
                });
            }
        };
        let Some((occurrence_start, endpoint)) = occurrence else {
            if let Some(start) = best_start {
                return Ok(finish_k0_finite_mandatory_suffix_start(
                    next_state,
                    class_index,
                    start,
                    maximum_match_bytes,
                ));
            }
            return Ok(finish_k0_finite_mandatory_suffix_absent(
                next_state,
                class_index,
                proof_window_bytes,
                candidates,
                cumulative_work,
            ));
        };

        candidates = candidates.saturating_add(1);
        let reverse_start = endpoint
            .saturating_sub(maximum_match_bytes)
            .max(proof_start);
        if let Some(best) = best_start {
            if reverse_start >= best {
                return Ok(finish_k0_finite_mandatory_suffix_start(
                    next_state,
                    class_index,
                    best,
                    maximum_match_bytes,
                ));
            }
        }
        let Some(progress) = endpoint.checked_sub(proof_start) else {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        // Without an incumbent floor, a near-prefix suffix is an incomplete
        // whole-window speculation and ordinary K0 should own it. A supplied
        // floor is an authenticated lower bound for every match start, so the
        // same short progress bounds the complete reverse window instead of
        // signaling missing source progress.
        if candidates > K0_SUFFIX_MAX_CANDIDATES {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        }
        debug_assert!(progress >= minimum_match_bytes);
        if incumbent_candidate_floor.is_none()
            && progress <= K0_SUFFIX_FORWARD_FALLBACK_BYTES
        {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        }

        let Some(allowed_reverse_bytes) = progress
            .checked_mul(K0_SUFFIX_REVERSE_PROGRESS_FACTOR)
            .and_then(|bytes| bytes.checked_add(K0_SUFFIX_REVERSE_CREDIT_BYTES))
        else {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(remaining_reverse_bytes) =
            allowed_reverse_bytes.checked_sub(cumulative_reverse_bytes)
        else {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(work_budget_bytes) = progress.checked_add(K0_SUFFIX_REVERSE_CREDIT_BYTES) else {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(allowed_work) =
            session.positive_end_verifier_work_certificate(work_budget_bytes)
        else {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(remaining_work) = allowed_work.checked_sub(cumulative_work) else {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let reverse_window = SearchWindow::new(reverse_start, endpoint);
        let verification = session
            .try_earliest_start_ending_at(
                haystack,
                reverse_window,
                endpoint,
                K0PositiveEndLimits::new(remaining_work, remaining_reverse_bytes),
            )
            .map_err(SearchError::from)?;
        cumulative_work = cumulative_work
            .checked_add(verification.receipt().work())
            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                computation: "cumulative finite mandatory-suffix verifier work",
            }))?;
        cumulative_reverse_bytes = cumulative_reverse_bytes
            .checked_add(verification.receipt().reverse_source_bytes())
            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                computation: "cumulative finite mandatory-suffix reverse bytes",
            }))?;
        match verification.outcome() {
            K0PositiveEndStartOutcome::Matched { start } => {
                if start < reverse_start || start >= endpoint {
                    return Err(SearchError::K0(K0SearchError::InternalInvariant {
                        detail: "finite mandatory-suffix verifier returned an invalid start",
                    }));
                }
                best_start = Some(best_start.map_or(start, |best: usize| best.min(start)));
            }
            K0PositiveEndStartOutcome::Rejected => {}
            K0PositiveEndStartOutcome::Declined => {
                observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
                return Ok(K0MandatorySuffixSpanAttempt {
                    outcome: K0MandatorySuffixSpanOutcome::Fallback,
                    state_after_success: next_state,
                });
            }
        }
        search_start = occurrence_start.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "next overlapping finite mandatory-suffix occurrence",
            },
        ))?;
    }
}

#[allow(
    clippy::too_many_arguments,
    reason = "finite suffix admission carries the incumbent's sound candidate-floor evidence"
)]
fn try_k0_mandatory_suffix_span_start(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    finite_incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixSpanAttempt, SearchError> {
    try_k0_mandatory_suffix_span_start_with_universal_admission::<false>(
        session,
        suffix,
        state,
        haystack,
        window,
        limits,
        finite_incumbent_candidate_floor,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "iteration retains the same suffix proof while relaxing only standalone performance geometry"
)]
fn try_k0_mandatory_suffix_span_start_for_iteration(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    finite_incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixSpanAttempt, SearchError> {
    try_k0_mandatory_suffix_span_start_with_universal_admission::<true>(
        session,
        suffix,
        state,
        haystack,
        window,
        limits,
        finite_incumbent_candidate_floor,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "finite suffix admission carries the incumbent's sound candidate-floor evidence"
)]
fn try_k0_mandatory_suffix_span_start_with_universal_admission<
    const ITERATOR_CONTINUATION: bool,
>(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    finite_incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixSpanAttempt, SearchError> {
    if let Some((minimum_match_bytes, maximum_match_bytes)) =
        suffix.universal_finite_match_byte_bounds()
    {
        return try_k0_universal_finite_mandatory_suffix_span_start::<ITERATOR_CONTINUATION>(
            suffix,
            minimum_match_bytes,
            maximum_match_bytes,
            suffix.has_universal_finite_greedy_corridor(),
            state,
            haystack,
            window,
            limits,
            finite_incumbent_candidate_floor,
        );
    }
    if let Some((minimum_match_bytes, maximum_match_bytes)) =
        suffix.finite_match_byte_bounds()
    {
        return try_k0_finite_mandatory_suffix_span_start(
            session,
            suffix,
            minimum_match_bytes,
            maximum_match_bytes,
            state,
            haystack,
            window,
            limits,
            finite_incumbent_candidate_floor,
        );
    }
    let unchanged = |outcome| K0MandatorySuffixSpanAttempt {
        outcome,
        state_after_success: state,
    };
    if limits != SearchLimits::unlimited()
        || !suffix.has_consumption_run()
        || window.start() > window.end()
        || window.end() > haystack.len()
    {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    }
    let window_bytes = window.end().saturating_sub(window.start());
    if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES {
        return Ok(unchanged(K0MandatorySuffixSpanOutcome::Bypass));
    }

    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let mut next_state = state;
    let class_index = next_state.class_for(window_size_class);
    if next_state.classes[class_index].disabled_calls != 0 {
        next_state.classes[class_index].disabled_calls -= 1;
        return Ok(K0MandatorySuffixSpanAttempt {
            outcome: K0MandatorySuffixSpanOutcome::Fallback,
            state_after_success: next_state,
        });
    }

    let occurrence = match suffix.find_window(haystack, window.start(), window.end()) {
        Ok(occurrence) => occurrence,
        Err(_) => {
            next_state.classes[class_index].observe_present();
            return Ok(K0MandatorySuffixSpanAttempt {
                outcome: K0MandatorySuffixSpanOutcome::Fallback,
                state_after_success: next_state,
            });
        }
    };
    let Some((occurrence_start, _)) = occurrence else {
        next_state.classes[class_index].observe_absent();
        return Ok(K0MandatorySuffixSpanAttempt {
            outcome: K0MandatorySuffixSpanOutcome::Absent,
            state_after_success: next_state,
        });
    };
    let narrowed = suffix.narrowed_start_before(haystack, window.start(), occurrence_start);
    let useful = narrowed
        .checked_sub(window.start())
        .is_some_and(|saved| saved >= K0_SUFFIX_FORWARD_FALLBACK_BYTES);
    if !useful {
        next_state.classes[class_index].observe_present();
        return Ok(K0MandatorySuffixSpanAttempt {
            outcome: K0MandatorySuffixSpanOutcome::Fallback,
            state_after_success: next_state,
        });
    }
    next_state.classes[class_index].observe_absent();
    Ok(K0MandatorySuffixSpanAttempt {
        outcome: K0MandatorySuffixSpanOutcome::Narrowed(narrowed),
        state_after_success: next_state,
    })
}

#[inline(never)]
#[allow(
    clippy::too_many_arguments,
    reason = "the universal finite corridor keeps its immutable geometry, floor, and adaptive state together"
)]
fn try_k0_universal_finite_mandatory_suffix_exists(
    suffix: &K0MandatorySuffixPlan,
    minimum_match_bytes: usize,
    maximum_match_bytes: usize,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixAttempt, SearchError> {
    let unchanged = |outcome| K0MandatorySuffixAttempt {
        outcome,
        state_after_success: state,
    };
    if limits != SearchLimits::unlimited()
        || minimum_match_bytes == 0
        || minimum_match_bytes > maximum_match_bytes
        || suffix.needle().len() > minimum_match_bytes
        || window.start() > window.end()
        || window.end() > haystack.len()
        || incumbent_candidate_floor
            .is_some_and(|floor| !(window.start()..=window.end()).contains(&floor))
    {
        return Ok(unchanged(K0MandatorySuffixOutcome::Bypass));
    }
    let Some(window_bytes) = window.end().checked_sub(window.start()) else {
        return Ok(unchanged(K0MandatorySuffixOutcome::Bypass));
    };
    if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || maximum_match_bytes > window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
    {
        return Ok(unchanged(K0MandatorySuffixOutcome::GeometryBypass));
    }

    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let mut next_state = state;
    let class_index = next_state.class_for(window_size_class);

    let proof_start = incumbent_candidate_floor.unwrap_or(window.start());
    let minimum_prefix_bytes = minimum_match_bytes - suffix.needle().len();
    let search_start = proof_start
        .saturating_add(minimum_prefix_bytes)
        .min(window.end());
    let found = match suffix.find_window(haystack, search_start, window.end()) {
        Ok(found) => found.is_some(),
        Err(_) => {
            observe_k0_finite_suffix_loss(&mut next_state.classes[class_index]);
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        }
    };
    observe_k0_finite_suffix_win(&mut next_state.classes[class_index]);
    Ok(K0MandatorySuffixAttempt {
        // Every admitted occurrence completes a match, and every match has
        // the mandatory suffix at or after this minimum-prefix horizon.
        outcome: K0MandatorySuffixOutcome::Found(found),
        state_after_success: next_state,
    })
}

#[inline(never)]
#[allow(
    clippy::too_many_arguments,
    reason = "finite suffix admission carries the incumbent's sound candidate-floor evidence"
)]
fn try_k0_mandatory_suffix_exists(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    state: K0NegativePrefilterState,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    finite_incumbent_candidate_floor: Option<usize>,
) -> Result<K0MandatorySuffixAttempt, SearchError> {
    if let Some((minimum_match_bytes, maximum_match_bytes)) =
        suffix.universal_finite_match_byte_bounds()
    {
        return try_k0_universal_finite_mandatory_suffix_exists(
            suffix,
            minimum_match_bytes,
            maximum_match_bytes,
            state,
            haystack,
            window,
            limits,
            finite_incumbent_candidate_floor,
        );
    }
    let finite_recovery = suffix.finite_exists_maximum_match_bytes().is_some();
    let finite_minimum_match_bytes = suffix.finite_minimum_match_bytes();
    let unchanged = |outcome| K0MandatorySuffixAttempt {
        outcome,
        state_after_success: state,
    };
    if limits != SearchLimits::unlimited()
        || window.start() > window.end()
        || window.end() > haystack.len()
        || finite_minimum_match_bytes
            .is_some_and(|minimum| suffix.needle().len() > minimum)
        || finite_incumbent_candidate_floor
            .is_some_and(|floor| !(window.start()..=window.end()).contains(&floor))
    {
        return Ok(unchanged(K0MandatorySuffixOutcome::Bypass));
    }
    let Some(window_bytes) = window.end().checked_sub(window.start()) else {
        return Ok(unchanged(K0MandatorySuffixOutcome::Bypass));
    };
    if window_bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
        || !session.positive_end_verifier_available()
    {
        return Ok(unchanged(K0MandatorySuffixOutcome::Bypass));
    }

    let window_size_class = usize::BITS - window_bytes.leading_zeros();
    let mut next_state = state;
    let class_index = next_state.class_for(window_size_class);
    if finite_recovery {
        match select_k0_finite_suffix_route(&mut next_state.classes[class_index]) {
            K0FiniteSuffixRoute::Incumbent {
                may_switch_to_suffix,
            } => {
                return Ok(K0MandatorySuffixAttempt {
                    outcome: K0MandatorySuffixOutcome::Incumbent {
                        class_index,
                        may_switch_to_suffix,
                    },
                    state_after_success: next_state,
                });
            }
            K0FiniteSuffixRoute::ExactSuffix => {}
        }
    } else if next_state.classes[class_index].disabled_calls != 0 {
        next_state.classes[class_index].disabled_calls -= 1;
        return Ok(K0MandatorySuffixAttempt {
            // This size class already learned that suffix speculation loses.
            // Run ordinary K0 directly instead of phase-locking a second
            // adaptive predicate while the suffix retry clock counts down.
            outcome: K0MandatorySuffixOutcome::Fallback,
            state_after_success: next_state,
        });
    }
    if !session.negative_terminal_has_reused_work_certificate(window_bytes) {
        return Ok(unchanged(K0MandatorySuffixOutcome::Bypass));
    }

    let proof_start = finite_incumbent_candidate_floor.unwrap_or(window.start());
    let proof_window = SearchWindow::new(proof_start, window.end());
    let proof_window_bytes = window.end().saturating_sub(proof_start);
    // Span-only finite recovery still carries the full language's minimum
    // width. Exists can use the same suffix-start horizon even though it does
    // not retain Span's exact-start replay route.
    let mut search_start = finite_minimum_match_bytes.map_or(proof_start, |minimum| {
        proof_start
            .saturating_add(minimum - suffix.needle().len())
            .min(window.end())
    });
    let mut candidates = 0usize;
    let mut cumulative_work = 0u64;
    let mut cumulative_reverse_bytes = 0usize;
    loop {
        let occurrence = match suffix.find_window(haystack, search_start, window.end()) {
            Ok(occurrence) => occurrence,
            Err(_) => {
                observe_k0_mandatory_suffix_loss(
                    &mut next_state.classes[class_index],
                    finite_recovery,
                );
                return Ok(K0MandatorySuffixAttempt {
                    outcome: K0MandatorySuffixOutcome::Fallback,
                    state_after_success: next_state,
                });
            }
        };
        let Some((occurrence_start, endpoint)) = occurrence else {
            if k0_mandatory_suffix_completed_negative_is_useful(
                &next_state.classes[class_index],
                proof_window_bytes,
                candidates,
                cumulative_work,
            ) {
                observe_k0_mandatory_suffix_win(
                    &mut next_state.classes[class_index],
                    finite_recovery,
                );
            } else {
                observe_k0_mandatory_suffix_loss(
                    &mut next_state.classes[class_index],
                    finite_recovery,
                );
            }
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Found(false),
                state_after_success: next_state,
            });
        };
        let Some(progress) = endpoint.checked_sub(proof_start) else {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        candidates = candidates.saturating_add(1);
        if candidates > K0_SUFFIX_MAX_CANDIDATES {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        }
        debug_assert!(finite_minimum_match_bytes.is_none_or(|minimum| progress >= minimum));
        if progress <= K0_SUFFIX_FORWARD_FALLBACK_BYTES {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        }
        let Some(allowed_reverse_bytes) = progress
            .checked_mul(K0_SUFFIX_REVERSE_PROGRESS_FACTOR)
            .and_then(|bytes| bytes.checked_add(K0_SUFFIX_REVERSE_CREDIT_BYTES))
        else {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(remaining_reverse_bytes) =
            allowed_reverse_bytes.checked_sub(cumulative_reverse_bytes)
        else {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(work_budget_bytes) = progress.checked_add(K0_SUFFIX_REVERSE_CREDIT_BYTES) else {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(allowed_work) =
            session.positive_end_verifier_work_certificate(work_budget_bytes)
        else {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let Some(remaining_work) = allowed_work.checked_sub(cumulative_work) else {
            observe_k0_mandatory_suffix_loss(
                &mut next_state.classes[class_index],
                finite_recovery,
            );
            return Ok(K0MandatorySuffixAttempt {
                outcome: K0MandatorySuffixOutcome::Fallback,
                state_after_success: next_state,
            });
        };
        let verification = session
            .try_positive_match_ending_at(
                haystack,
                proof_window,
                endpoint,
                K0PositiveEndLimits::new(remaining_work, remaining_reverse_bytes),
            )
            .map_err(SearchError::from)?;
        cumulative_work = cumulative_work
            .checked_add(verification.receipt().work())
            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                computation: "cumulative mandatory-suffix verifier work",
            }))?;
        cumulative_reverse_bytes = cumulative_reverse_bytes
            .checked_add(verification.receipt().reverse_source_bytes())
            .ok_or(SearchError::K0(
                K0SearchError::ArithmeticOverflow {
                    computation: "cumulative mandatory-suffix reverse bytes",
                },
            ))?;
        match verification.outcome() {
            K0PositiveEndOutcome::Matched => {
                let credited_progress = if finite_recovery {
                    finite_incumbent_candidate_floor.map_or(progress, |floor| {
                        endpoint.checked_sub(floor).unwrap_or(0)
                    })
                } else {
                    progress
                };
                let useful_work = (!finite_recovery
                    || credited_progress >= K0_SUFFIX_FORWARD_FALLBACK_BYTES)
                    && u64::try_from(credited_progress)
                        .is_ok_and(|progress| cumulative_work <= progress);
                if useful_work {
                    observe_k0_mandatory_suffix_win(
                        &mut next_state.classes[class_index],
                        finite_recovery,
                    );
                } else {
                    observe_k0_mandatory_suffix_loss(
                        &mut next_state.classes[class_index],
                        finite_recovery,
                    );
                }
                return Ok(K0MandatorySuffixAttempt {
                    outcome: K0MandatorySuffixOutcome::Found(true),
                    state_after_success: next_state,
                });
            }
            K0PositiveEndOutcome::Declined => {
                observe_k0_mandatory_suffix_loss(
                    &mut next_state.classes[class_index],
                    finite_recovery,
                );
                return Ok(K0MandatorySuffixAttempt {
                    outcome: K0MandatorySuffixOutcome::Fallback,
                    state_after_success: next_state,
                });
            }
            K0PositiveEndOutcome::Rejected => {}
        }
        search_start = occurrence_start.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "next overlapping mandatory-suffix occurrence",
            },
        ))?;
    }
}

fn replay_k0_finite_proved_start(
    session: &mut K0SearchSession<'_>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    start: usize,
    maximum_match_bytes: usize,
) -> Result<Option<Match>, SearchError> {
    replay_k0_finite_proved_start_with_exact_receipt(
        session,
        haystack,
        window,
        limits,
        start,
        maximum_match_bytes,
    )
    .map(|(output, _)| output)
}

fn replay_k0_finite_proved_start_with_exact_receipt(
    session: &mut K0SearchSession<'_>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    start: usize,
    maximum_match_bytes: usize,
) -> Result<(Option<Match>, bool), SearchError> {
    let replay_end = start
        .saturating_add(maximum_match_bytes)
        .min(window.end());
    let replay_window = SearchWindow::new(start, replay_end);
    match session
        .search_proved_exact_start_selected_end_value(haystack, replay_window, limits)
        .map_err(SearchError::from)?
    {
        Some(end) if start < end && end <= replay_end => {
            Ok((Some(Match { start, end }), true))
        }
        Some(_) | None => session
            .search_span_value(haystack, window, limits)
            .map(|found| {
                (
                    found.map(|span| Match {
                        start: span.start(),
                        end: span.end(),
                    }),
                    false,
                )
            })
            .map_err(SearchError::from),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0CorrelatedTerminalAttempt<T> {
    Bypass,
    Complete { output: T, won: bool },
}

fn k0_correlated_first_unproved_start(
    window_start: usize,
    terminal_position: usize,
    maximum_match_bytes: usize,
) -> usize {
    terminal_position
        .checked_sub(maximum_match_bytes)
        .and_then(|position| position.checked_add(1))
        .unwrap_or(window_start)
        .max(window_start)
}

fn k0_correlated_progress_budget(
    incumbent_transition_work: u64,
    progress: usize,
    window_bytes: usize,
) -> u64 {
    if window_bytes == 0 {
        return 0;
    }
    let scaled = u128::from(incumbent_transition_work)
        .saturating_mul(u128::try_from(progress).unwrap_or(u128::MAX))
        / u128::try_from(window_bytes).unwrap_or(u128::MAX);
    u64::try_from(scaled).unwrap_or(u64::MAX)
}

fn k0_correlated_sidecar_work(
    progress: usize,
    candidates: u64,
    verifier_work: u64,
) -> Option<u64> {
    u64::try_from(progress)
        .ok()?
        .checked_add(candidates)?
        .checked_add(verifier_work)
}

fn k0_correlated_geometry_allows(
    session: &K0SearchSession<'_>,
    plan: &correlated_bounded_alternation::Plan,
    haystack_len: usize,
    window: SearchWindow,
    limits: SearchLimits,
) -> bool {
    if limits != SearchLimits::unlimited()
        || window.start() > window.end()
        || window.end() > haystack_len
        || !session.positive_end_verifier_available()
    {
        return false;
    }
    let window_bytes = window.end().saturating_sub(window.start());
    plan.maximum_match_bytes() != 0
        && plan.maximum_match_bytes() <= window_bytes / K0_SUFFIX_FINITE_WIDTH_WINDOW_FACTOR
}

fn k0_correlated_exact_delimited_allows(
    plan: &correlated_bounded_alternation::Plan,
    haystack_len: usize,
    window: SearchWindow,
    limits: SearchLimits,
) -> bool {
    plan.is_exact_delimited()
        && limits == SearchLimits::unlimited()
        && window.start() <= window.end()
        && window.end() <= haystack_len
}

fn k0_correlated_fallback_exists(
    session: &mut K0SearchSession<'_>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    first_unproved_start: usize,
) -> Result<K0CorrelatedTerminalAttempt<bool>, SearchError> {
    let fallback = SearchWindow::new(first_unproved_start.min(window.end()), window.end());
    session
        .search_exists_value(haystack, fallback, limits)
        .map(|output| K0CorrelatedTerminalAttempt::Complete { output, won: false })
        .map_err(SearchError::from)
}

#[allow(
    clippy::too_many_arguments,
    reason = "the endpoint proof keeps its immutable plan, adaptive budget, and validated window together"
)]
fn try_k0_correlated_terminal_exists(
    session: &mut K0SearchSession<'_>,
    plan: &correlated_bounded_alternation::Plan,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_transition_work: u64,
) -> Result<K0CorrelatedTerminalAttempt<bool>, SearchError> {
    if !k0_correlated_geometry_allows(session, plan, haystack.len(), window, limits) {
        return Ok(K0CorrelatedTerminalAttempt::Bypass);
    }
    let window_bytes = window.end().saturating_sub(window.start());
    if plan.minimum_match_bytes() > window_bytes {
        return Ok(K0CorrelatedTerminalAttempt::Complete {
            output: false,
            won: true,
        });
    }
    let mut search_position = window
        .start()
        .checked_add(plan.minimum_match_bytes().saturating_sub(1))
        .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
            computation: "correlated terminal minimum endpoint",
        }))?;
    let mut candidates = 0u64;
    let mut verifier_work = 0u64;
    loop {
        let Some(terminal_position) =
            plan.seek_terminal(haystack, search_position, window.end())
        else {
            let allowed_work = k0_correlated_progress_budget(
                incumbent_transition_work,
                window_bytes,
                window_bytes,
            );
            return Ok(K0CorrelatedTerminalAttempt::Complete {
                output: false,
                won: k0_correlated_sidecar_work(
                    window_bytes,
                    candidates,
                    verifier_work,
                )
                .is_some_and(|work| work <= allowed_work),
            });
        };
        let endpoint = terminal_position.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal endpoint",
            },
        ))?;
        candidates = candidates.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal candidate count",
            },
        ))?;
        let progress = endpoint.saturating_sub(window.start());
        let allowed_work = k0_correlated_progress_budget(
            incumbent_transition_work,
            progress,
            window_bytes,
        );
        let Some(sidecar_work) = k0_correlated_sidecar_work(
            progress,
            candidates,
            verifier_work,
        ) else {
            let first_unproved = k0_correlated_first_unproved_start(
                window.start(),
                terminal_position,
                plan.maximum_match_bytes(),
            );
            return k0_correlated_fallback_exists(
                session,
                haystack,
                window,
                limits,
                first_unproved,
            );
        };
        let Some(remaining_work) = allowed_work.checked_sub(sidecar_work) else {
            let first_unproved = k0_correlated_first_unproved_start(
                window.start(),
                terminal_position,
                plan.maximum_match_bytes(),
            );
            return k0_correlated_fallback_exists(
                session,
                haystack,
                window,
                limits,
                first_unproved,
            );
        };
        let reverse_start = endpoint
            .saturating_sub(plan.maximum_match_bytes())
            .max(window.start());
        let verification = session
            .try_positive_match_ending_at(
                haystack,
                SearchWindow::new(reverse_start, endpoint),
                endpoint,
                K0PositiveEndLimits::new(remaining_work, endpoint - reverse_start),
            )
            .map_err(SearchError::from)?;
        verifier_work = verifier_work
            .checked_add(verification.receipt().work())
            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal verifier work",
            }))?;
        match verification.outcome() {
            K0PositiveEndOutcome::Matched => {
                return Ok(K0CorrelatedTerminalAttempt::Complete {
                    output: true,
                    won: true,
                });
            }
            K0PositiveEndOutcome::Rejected => {
                search_position = endpoint;
            }
            K0PositiveEndOutcome::Declined => {
                let first_unproved = k0_correlated_first_unproved_start(
                    window.start(),
                    terminal_position,
                    plan.maximum_match_bytes(),
                );
                return k0_correlated_fallback_exists(
                    session,
                    haystack,
                    window,
                    limits,
                    first_unproved,
                );
            }
        }
    }
}

fn k0_correlated_fallback_earliest_end(
    session: &mut K0SearchSession<'_>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    first_unproved_start: usize,
) -> Result<K0CorrelatedTerminalAttempt<Option<usize>>, SearchError> {
    let fallback = SearchWindow::new(first_unproved_start.min(window.end()), window.end());
    session
        .search_window::<EarliestEnd>(haystack, fallback, limits)
        .map(|report| K0CorrelatedTerminalAttempt::Complete {
            output: report.into_output(),
            won: false,
        })
        .map_err(SearchError::from)
}

#[allow(
    clippy::too_many_arguments,
    reason = "the endpoint proof keeps its immutable plan, adaptive budget, and validated window together"
)]
fn try_k0_correlated_terminal_earliest_end(
    session: &mut K0SearchSession<'_>,
    plan: &correlated_bounded_alternation::Plan,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_transition_work: u64,
) -> Result<K0CorrelatedTerminalAttempt<Option<usize>>, SearchError> {
    if !k0_correlated_geometry_allows(session, plan, haystack.len(), window, limits) {
        return Ok(K0CorrelatedTerminalAttempt::Bypass);
    }
    let window_bytes = window.end().saturating_sub(window.start());
    if plan.minimum_match_bytes() > window_bytes {
        return Ok(K0CorrelatedTerminalAttempt::Complete {
            output: None,
            won: true,
        });
    }
    let mut search_position = window
        .start()
        .checked_add(plan.minimum_match_bytes().saturating_sub(1))
        .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
            computation: "correlated terminal minimum earliest endpoint",
        }))?;
    let mut candidates = 0u64;
    let mut verifier_work = 0u64;
    loop {
        let Some(terminal_position) =
            plan.seek_terminal(haystack, search_position, window.end())
        else {
            let allowed_work = k0_correlated_progress_budget(
                incumbent_transition_work,
                window_bytes,
                window_bytes,
            );
            return Ok(K0CorrelatedTerminalAttempt::Complete {
                output: None,
                won: k0_correlated_sidecar_work(
                    window_bytes,
                    candidates,
                    verifier_work,
                )
                .is_some_and(|work| work <= allowed_work),
            });
        };
        let endpoint = terminal_position.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal earliest endpoint",
            },
        ))?;
        candidates = candidates.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal earliest candidate count",
            },
        ))?;
        let progress = endpoint.saturating_sub(window.start());
        let allowed_work = k0_correlated_progress_budget(
            incumbent_transition_work,
            progress,
            window_bytes,
        );
        let Some(sidecar_work) = k0_correlated_sidecar_work(
            progress,
            candidates,
            verifier_work,
        ) else {
            let first_unproved = k0_correlated_first_unproved_start(
                window.start(),
                terminal_position,
                plan.maximum_match_bytes(),
            );
            return k0_correlated_fallback_earliest_end(
                session,
                haystack,
                window,
                limits,
                first_unproved,
            );
        };
        let Some(remaining_work) = allowed_work.checked_sub(sidecar_work) else {
            let first_unproved = k0_correlated_first_unproved_start(
                window.start(),
                terminal_position,
                plan.maximum_match_bytes(),
            );
            return k0_correlated_fallback_earliest_end(
                session,
                haystack,
                window,
                limits,
                first_unproved,
            );
        };
        let reverse_start = endpoint
            .saturating_sub(plan.maximum_match_bytes())
            .max(window.start());
        let verification = session
            .try_positive_match_ending_at(
                haystack,
                SearchWindow::new(reverse_start, endpoint),
                endpoint,
                K0PositiveEndLimits::new(remaining_work, endpoint - reverse_start),
            )
            .map_err(SearchError::from)?;
        verifier_work = verifier_work
            .checked_add(verification.receipt().work())
            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal earliest verifier work",
            }))?;
        match verification.outcome() {
            K0PositiveEndOutcome::Matched => {
                return Ok(K0CorrelatedTerminalAttempt::Complete {
                    output: Some(endpoint),
                    won: true,
                });
            }
            K0PositiveEndOutcome::Rejected => {
                search_position = endpoint;
            }
            K0PositiveEndOutcome::Declined => {
                let first_unproved = k0_correlated_first_unproved_start(
                    window.start(),
                    terminal_position,
                    plan.maximum_match_bytes(),
                );
                return k0_correlated_fallback_earliest_end(
                    session,
                    haystack,
                    window,
                    limits,
                    first_unproved,
                );
            }
        }
    }
}

fn k0_correlated_fallback_span(
    session: &mut K0SearchSession<'_>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    first_unproved_start: usize,
) -> Result<K0CorrelatedTerminalAttempt<Option<Match>>, SearchError> {
    let fallback = SearchWindow::new(first_unproved_start.min(window.end()), window.end());
    session
        .search_span_value(haystack, fallback, limits)
        .map(|output| K0CorrelatedTerminalAttempt::Complete {
            output: output.map(|span| Match {
                start: span.start(),
                end: span.end(),
            }),
            won: false,
        })
        .map_err(SearchError::from)
}

#[allow(
    clippy::too_many_arguments,
    reason = "the endpoint proof keeps its immutable plan, adaptive budget, and validated window together"
)]
fn try_k0_correlated_terminal_span(
    session: &mut K0SearchSession<'_>,
    plan: &correlated_bounded_alternation::Plan,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_transition_work: u64,
) -> Result<K0CorrelatedTerminalAttempt<Option<Match>>, SearchError> {
    if !k0_correlated_geometry_allows(session, plan, haystack.len(), window, limits) {
        return Ok(K0CorrelatedTerminalAttempt::Bypass);
    }
    let window_bytes = window.end().saturating_sub(window.start());
    if plan.minimum_match_bytes() > window_bytes {
        return Ok(K0CorrelatedTerminalAttempt::Complete {
            output: None,
            won: true,
        });
    }
    let mut search_position = window
        .start()
        .checked_add(plan.minimum_match_bytes().saturating_sub(1))
        .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
            computation: "correlated terminal minimum span endpoint",
        }))?;
    let mut candidates = 0u64;
    let mut verifier_work = 0u64;
    let mut best_start = None;
    loop {
        let search_end = best_start.map_or(window.end(), |start: usize| {
            start
                .saturating_add(plan.maximum_match_bytes())
                .min(window.end())
        });
        let Some(terminal_position) = plan.seek_terminal(haystack, search_position, search_end)
        else {
            let progress = search_end.saturating_sub(window.start());
            let allowed_work = k0_correlated_progress_budget(
                incumbent_transition_work,
                progress,
                window_bytes,
            );
            let sidecar_work = k0_correlated_sidecar_work(
                progress,
                candidates,
                verifier_work,
            );
            if let Some(start) = best_start {
                let replay_bytes = start
                    .saturating_add(plan.maximum_match_bytes())
                    .min(window.end())
                    .saturating_sub(start);
                let replay_fits = session
                    .positive_end_verifier_work_certificate(replay_bytes)
                    .and_then(|work| sidecar_work?.checked_add(work))
                    .is_some_and(|total| total <= allowed_work);
                let (output, used_exact_replay) =
                    replay_k0_finite_proved_start_with_exact_receipt(
                        session,
                        haystack,
                        window,
                        limits,
                        start,
                        plan.maximum_match_bytes(),
                    )?;
                return Ok(K0CorrelatedTerminalAttempt::Complete {
                    output,
                    won: replay_fits && used_exact_replay,
                });
            }
            return Ok(K0CorrelatedTerminalAttempt::Complete {
                output: None,
                won: sidecar_work.is_some_and(|work| work <= allowed_work),
            });
        };
        let endpoint = terminal_position.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal span endpoint",
            },
        ))?;
        candidates = candidates.checked_add(1).ok_or(SearchError::K0(
            K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal span candidate count",
            },
        ))?;
        let progress = endpoint.saturating_sub(window.start());
        let allowed_work = k0_correlated_progress_budget(
            incumbent_transition_work,
            progress,
            window_bytes,
        );
        let Some(sidecar_work) = k0_correlated_sidecar_work(
            progress,
            candidates,
            verifier_work,
        ) else {
            let first_unproved = k0_correlated_first_unproved_start(
                window.start(),
                terminal_position,
                plan.maximum_match_bytes(),
            );
            if let Some(start) = best_start {
                if first_unproved > start {
                    let output = replay_k0_finite_proved_start(
                        session,
                        haystack,
                        window,
                        limits,
                        start,
                        plan.maximum_match_bytes(),
                    )?;
                    return Ok(K0CorrelatedTerminalAttempt::Complete {
                        output,
                        won: false,
                    });
                }
            }
            return k0_correlated_fallback_span(
                session,
                haystack,
                window,
                limits,
                first_unproved,
            );
        };
        if sidecar_work > allowed_work {
            let first_unproved = k0_correlated_first_unproved_start(
                window.start(),
                terminal_position,
                plan.maximum_match_bytes(),
            );
            if let Some(start) = best_start {
                if first_unproved > start {
                    let output = replay_k0_finite_proved_start(
                        session,
                        haystack,
                        window,
                        limits,
                        start,
                        plan.maximum_match_bytes(),
                    )?;
                    return Ok(K0CorrelatedTerminalAttempt::Complete {
                        output,
                        won: false,
                    });
                }
            }
            return k0_correlated_fallback_span(
                session,
                haystack,
                window,
                limits,
                first_unproved,
            );
        }
        let reverse_start = endpoint
            .saturating_sub(plan.maximum_match_bytes())
            .max(window.start());
        let remaining_work = allowed_work.saturating_sub(sidecar_work);
        let verification = session
            .try_earliest_start_ending_at(
                haystack,
                SearchWindow::new(reverse_start, endpoint),
                endpoint,
                K0PositiveEndLimits::new(remaining_work, endpoint - reverse_start),
            )
            .map_err(SearchError::from)?;
        verifier_work = verifier_work
            .checked_add(verification.receipt().work())
            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                computation: "correlated terminal span verifier work",
            }))?;
        match verification.outcome() {
            K0PositiveEndStartOutcome::Matched { start } => {
                if start < reverse_start || start >= endpoint {
                    return Err(SearchError::K0(K0SearchError::InternalInvariant {
                        detail: "correlated terminal verifier returned an invalid start",
                    }));
                }
                best_start = Some(best_start.map_or(start, |best: usize| best.min(start)));
            }
            K0PositiveEndStartOutcome::Rejected => {}
            K0PositiveEndStartOutcome::Declined => {
                if let Some(start) = best_start {
                    let first_unproved = k0_correlated_first_unproved_start(
                        window.start(),
                        terminal_position,
                        plan.maximum_match_bytes(),
                    );
                    if first_unproved > start {
                        let output = replay_k0_finite_proved_start(
                            session,
                            haystack,
                            window,
                            limits,
                            start,
                            plan.maximum_match_bytes(),
                        )?;
                        return Ok(K0CorrelatedTerminalAttempt::Complete {
                            output,
                            won: false,
                        });
                    }
                }
                let first_unproved = k0_correlated_first_unproved_start(
                    window.start(),
                    terminal_position,
                    plan.maximum_match_bytes(),
                );
                return k0_correlated_fallback_span(
                    session,
                    haystack,
                    window,
                    limits,
                    first_unproved,
                );
            }
        }
        search_position = endpoint;
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum K0FinitePrefixExistsHedge {
    Found,
    ResumeAt(usize),
}

fn k0_finite_prefix_hedge_window(
    window: SearchWindow,
    incumbent_candidate_floor: Option<usize>,
    maximum_match_bytes: usize,
    prefix_hedge_bytes: usize,
) -> (SearchWindow, usize, bool) {
    let search_start = incumbent_candidate_floor
        .unwrap_or(window.start())
        .max(window.start())
        .min(window.end());
    let first_unproved_start = search_start
        .saturating_add(prefix_hedge_bytes)
        .min(window.end());
    // A match beginning strictly before the first unproved start consumes at
    // most `maximum_match_bytes`, so this capped source window supplies its
    // complete forward proof and ordered endpoint. When the cap reaches the
    // original end, the hedge is the complete incumbent search.
    let scan_end = first_unproved_start
        .saturating_add(maximum_match_bytes)
        .min(window.end());
    (
        SearchWindow::new(search_start, scan_end),
        first_unproved_start,
        scan_end == window.end(),
    )
}

fn run_k0_finite_prefix_exists_hedge(
    session: &mut K0SearchSession<'_>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_candidate_floor: Option<usize>,
    maximum_match_bytes: usize,
    prefix_hedge_bytes: usize,
) -> Result<K0FinitePrefixExistsHedge, SearchError> {
    let (hedge_window, first_unproved_start, complete) = k0_finite_prefix_hedge_window(
        window,
        incumbent_candidate_floor,
        maximum_match_bytes,
        prefix_hedge_bytes,
    );
    if session
        .search_exists_value(haystack, hedge_window, limits)
        .map_err(SearchError::from)?
    {
        return Ok(K0FinitePrefixExistsHedge::Found);
    }
    Ok(K0FinitePrefixExistsHedge::ResumeAt(if complete {
        window.end()
    } else {
        first_unproved_start
    }))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(u8)]
enum K0UniversalFiniteSuffixIncumbentOutcome {
    GeometryBypass,
    ProvedAbsent,
    ProvedMatch,
}

#[allow(
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "the outlined incumbent transaction keeps its immutable plans, staged adaptive states, and exact search window together without widening the common caller"
)]
#[inline(never)]
fn try_k0_universal_finite_suffix_incumbent(
    session: &mut K0SearchSession<'_>,
    suffix: &K0MandatorySuffixPlan,
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    negative_prefilter: Option<&K0NegativePrefilterPlan>,
    mandatory_suffix_span_state: &mut K0NegativePrefilterState,
    mut suffix_state_after_success: K0NegativePrefilterState,
    negative_prefilter_span_state: &mut K0NegativePrefilterState,
    incumbent_route: K0UniversalFiniteSuffixIncumbentRoute,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    matched: &mut Match,
) -> Result<K0UniversalFiniteSuffixIncumbentOutcome, SearchError> {
    if !k0_universal_finite_suffix_incumbent_admitted(
        session,
        suffix,
        mandatory_cut,
        negative_prefilter,
        haystack.len(),
        window,
        limits,
    ) {
        return Ok(K0UniversalFiniteSuffixIncumbentOutcome::GeometryBypass);
    }
    let class_index = match incumbent_route {
        K0UniversalFiniteSuffixIncumbentRoute::Calibration { class_index }
        | K0UniversalFiniteSuffixIncumbentRoute::Retained { class_index } => class_index,
    };
    let attempt = run_k0_negative_prefilter(
        mandatory_cut,
        negative_prefilter,
        *negative_prefilter_span_state,
        haystack,
        window,
        limits,
    );
    let certified_absent = attempt.outcome == K0NegativePrefilterOutcome::Absent
        && window
            .end()
            .checked_sub(window.start())
            .is_some_and(|window_bytes| {
                session.negative_terminal_has_reused_work_certificate(window_bytes)
            });
    if certified_absent {
        if matches!(
            incumbent_route,
            K0UniversalFiniteSuffixIncumbentRoute::Calibration { .. }
        ) {
            observe_k0_universal_finite_suffix_incumbent(
                &mut suffix_state_after_success,
                class_index,
                true,
            );
        }
        *mandatory_suffix_span_state = suffix_state_after_success;
        *negative_prefilter_span_state = attempt.state_after_success;
        return Ok(K0UniversalFiniteSuffixIncumbentOutcome::ProvedAbsent);
    }

    let class = &mut suffix_state_after_success.classes[class_index];
    debug_assert_eq!(class.disabled_calls, 0);
    debug_assert_eq!(class.next_predicate & K0_FINITE_SUFFIX_BACKOFF_ROUTE, 0);
    let prior_backoff = class.present_backoff;
    // Let the exact suffix answer this same call before installing retry
    // backoff. Otherwise the universal helper would immediately consume the
    // clock that this failed calibration just created.
    class.next_predicate = K0_FINITE_SUFFIX_EXACT_ROUTE;
    let suffix_attempt = try_k0_mandatory_suffix_span_start(
        session,
        suffix,
        suffix_state_after_success,
        haystack,
        window,
        limits,
        attempt.candidate_floor,
    )?;
    suffix_state_after_success = suffix_attempt.state_after_success;
    if suffix_attempt.outcome == K0MandatorySuffixSpanOutcome::GeometryBypass {
        return Ok(K0UniversalFiniteSuffixIncumbentOutcome::GeometryBypass);
    }

    let mut suffix_completed_exact_proof = matches!(
        suffix_attempt.outcome,
        K0MandatorySuffixSpanOutcome::ProvedSpan { .. }
    );
    let outcome = match suffix_attempt.outcome {
        K0MandatorySuffixSpanOutcome::ProvedAbsent => {
            if k0_negative_prefilter_admitted(
                mandatory_cut,
                negative_prefilter,
                haystack.len(),
                window,
                limits,
            ) && window
                .end()
                .checked_sub(window.start())
                .is_some_and(|window_bytes| {
                    session.negative_terminal_has_reused_work_certificate(window_bytes)
                })
            {
                schedule_k0_universal_finite_suffix_incumbent_calibration(
                    &mut suffix_state_after_success,
                    window,
                );
            }
            K0UniversalFiniteSuffixIncumbentOutcome::ProvedAbsent
        }
        K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => {
            *matched = Match { start, end };
            K0UniversalFiniteSuffixIncumbentOutcome::ProvedMatch
        }
        K0MandatorySuffixSpanOutcome::ProvedStart {
            start,
            maximum_match_bytes,
        } => {
            let (output, exact_receipt) = replay_k0_finite_proved_start_with_exact_receipt(
                session,
                haystack,
                window,
                limits,
                start,
                maximum_match_bytes,
            )?;
            if !exact_receipt {
                observe_k0_finite_suffix_span_replay_fallback(
                    &mut suffix_state_after_success,
                    window,
                );
            }
            suffix_completed_exact_proof = exact_receipt;
            if let Some(output) = output {
                *matched = output;
                K0UniversalFiniteSuffixIncumbentOutcome::ProvedMatch
            } else {
                K0UniversalFiniteSuffixIncumbentOutcome::ProvedAbsent
            }
        }
        K0MandatorySuffixSpanOutcome::Fallback
        | K0MandatorySuffixSpanOutcome::Bypass
        | K0MandatorySuffixSpanOutcome::GeometryBypass
        | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. }
        | K0MandatorySuffixSpanOutcome::Absent
        | K0MandatorySuffixSpanOutcome::Narrowed(_)
        | K0MandatorySuffixSpanOutcome::Incumbent { .. } => {
            match session
                .search_span_value(haystack, window, limits)
                .map_err(SearchError::from)?
            {
                Some(span) => {
                    *matched = Match {
                        start: span.start(),
                        end: span.end(),
                    };
                    K0UniversalFiniteSuffixIncumbentOutcome::ProvedMatch
                }
                None => K0UniversalFiniteSuffixIncumbentOutcome::ProvedAbsent,
            }
        }
    };
    finish_k0_universal_finite_suffix_incumbent_failure(
        &mut suffix_state_after_success,
        class_index,
        prior_backoff,
        outcome == K0UniversalFiniteSuffixIncumbentOutcome::ProvedMatch,
        suffix_completed_exact_proof,
    );
    *mandatory_suffix_span_state = suffix_state_after_success;
    *negative_prefilter_span_state = attempt.state_after_success;
    Ok(outcome)
}

#[inline]
#[allow(
    clippy::too_many_arguments,
    reason = "the dispatcher preserves the incumbent's immutable sidecar envelope"
)]
fn execute_k0_exists_incumbent(
    session: &mut K0SearchSession<'_>,
    reverse_inner: &mut Option<Box<k0_general_reverse_inner::SearchSession<'_>>>,
    mandatory_suffix: Option<&K0MandatorySuffixPlan>,
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    negative_prefilter: Option<&K0NegativePrefilterPlan>,
    mandatory_suffix_exists_state: &mut K0NegativePrefilterState,
    negative_prefilter_exists_state: &mut K0NegativePrefilterState,
    absolute_end_proof: Option<K0AbsoluteEndProof>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    incumbent_observation: Option<&mut K0PackedFrontierIncumbentObservation>,
) -> Result<bool, SearchError> {
    // The deferred singleton-plus owner is Span-only. Remove it before every
    // Exists fast-path and learning decision so merely retaining that later
    // owner cannot outline raw K0 or suppress packed-incumbent observation.
    let mandatory_suffix = mandatory_suffix
        .filter(|suffix| !suffix.has_short_standalone_reverse_suffix_span());
    // A sidecar-free immutable plan has no policy state to stage or publish.
    // Dispatch it before entering the outlined transaction so steady raw K0
    // calls do not inherit the general suffix/prefilter/reverse frame.
    if reverse_inner.is_none()
        && mandatory_suffix.is_none()
        && mandatory_cut.is_none()
        && negative_prefilter.is_none()
        && absolute_end_proof.is_none()
    {
        return match incumbent_observation {
            Some(observation) => match session.search_window::<Exists>(haystack, window, limits) {
                Ok(report) => {
                    *observation = K0PackedFrontierIncumbentObservation::RawK0 {
                        work: report.accounting().work(),
                    };
                    Ok(report.into_output())
                }
                Err(error) => Err(SearchError::from(error)),
            },
            None => session
                .search_exists_value(haystack, window, limits)
                .map_err(SearchError::from),
        };
    }
    execute_k0_exists_incumbent_general(
        session,
        reverse_inner,
        mandatory_suffix,
        mandatory_cut,
        negative_prefilter,
        mandatory_suffix_exists_state,
        negative_prefilter_exists_state,
        absolute_end_proof,
        haystack,
        window,
        limits,
        incumbent_observation,
    )
}

#[inline(never)]
#[allow(
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "the incumbent closes one immutable K0 sidecar and transactional-state envelope"
)]
fn execute_k0_exists_incumbent_general(
    session: &mut K0SearchSession<'_>,
    reverse_inner: &mut Option<Box<k0_general_reverse_inner::SearchSession<'_>>>,
    mandatory_suffix: Option<&K0MandatorySuffixPlan>,
    mandatory_cut: Option<&K0MandatoryCutPlan>,
    negative_prefilter: Option<&K0NegativePrefilterPlan>,
    mandatory_suffix_exists_state: &mut K0NegativePrefilterState,
    negative_prefilter_exists_state: &mut K0NegativePrefilterState,
    absolute_end_proof: Option<K0AbsoluteEndProof>,
    haystack: &[u8],
    window: SearchWindow,
    limits: SearchLimits,
    mut incumbent_observation: Option<&mut K0PackedFrontierIncumbentObservation>,
) -> Result<bool, SearchError> {
    // Only raw K0 over the exact original window has work units directly
    // comparable with a packed-positive residual receipt. Any sidecar can add
    // source work that its value-only API does not report, so fail closed.
    let measure_full_window_k0 = incumbent_observation.is_some()
        && reverse_inner.is_none()
        && mandatory_suffix.is_none()
        && mandatory_cut.is_none()
        && negative_prefilter.is_none()
        && absolute_end_proof.is_none();

    let mut suffix_state_after_success = *mandatory_suffix_exists_state;
    let mut finite_suffix_incumbent = None;
    // The deferred singleton-plus owner accelerates only Span start recovery.
    // Exists keeps the established cut/negative/reverse-inner ordering and
    // must not scan or train this later, operation-specific sidecar.
    if let Some(suffix) = mandatory_suffix {
        if let Some(maximum_match_bytes) =
            suffix.finite_exists_maximum_match_bytes()
        {
            if window.end().checked_sub(window.start()).is_some_and(|bytes| {
                bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
            }) {
                return session
                    .search_exists_value(haystack, window, limits)
                    .map_err(SearchError::from);
            }
            if let Some(direct_route) = select_k0_finite_suffix_direct_route(
                session,
                &mut suffix_state_after_success,
                maximum_match_bytes,
                haystack.len(),
                window,
                limits,
                false,
            ) {
                let result = match direct_route {
                    K0FiniteSuffixDirectRoute::FreshClass { class_index } => {
                        match session
                            .search_window::<Exists>(haystack, window, limits)
                        {
                            Ok(report) => {
                                let single_pass_negative = !*report.output()
                                    && report.accounting().boundaries() == 0
                                    && session
                                        .negative_terminal_has_small_start_scanner();
                                observe_k0_finite_suffix_direct_incumbent(
                                    &mut suffix_state_after_success.classes
                                        [class_index],
                                    single_pass_negative,
                                );
                                Ok(report.into_output())
                            }
                            Err(error) => Err(SearchError::from(error)),
                        }
                    }
                    K0FiniteSuffixDirectRoute::ExactLossBackoff => session
                        .search_exists_value(haystack, window, limits)
                        .map_err(SearchError::from),
                };
                if result.is_ok() {
                    *mandatory_suffix_exists_state = suffix_state_after_success;
                }
                return result;
            }
        }
        let suffix_attempt = try_k0_mandatory_suffix_exists(
            session,
            suffix,
            suffix_state_after_success,
            haystack,
            window,
            limits,
            None,
        )?;
        suffix_state_after_success = suffix_attempt.state_after_success;
        match suffix_attempt.outcome {
            K0MandatorySuffixOutcome::Incumbent {
                class_index,
                may_switch_to_suffix,
            } => {
                finite_suffix_incumbent =
                    Some((class_index, may_switch_to_suffix));
            }
            K0MandatorySuffixOutcome::Found(found) => {
                *mandatory_suffix_exists_state = suffix_state_after_success;
                if suffix.universal_finite_match_byte_bounds().is_some()
                    && let Some(observation) = incumbent_observation.as_mut()
                {
                    **observation =
                        K0PackedFrontierIncumbentObservation::SpecializedComplete;
                }
                return Ok(found);
            }
            K0MandatorySuffixOutcome::Fallback => {
                let result = session
                    .search_exists_value(haystack, window, limits)
                    .map_err(SearchError::from);
                if result.is_ok() {
                    *mandatory_suffix_exists_state = suffix_state_after_success;
                }
                return result;
            }
            K0MandatorySuffixOutcome::Bypass
            | K0MandatorySuffixOutcome::GeometryBypass => {}
        }
    }
    let attempt = run_k0_negative_prefilter(
        mandatory_cut,
        negative_prefilter,
        *negative_prefilter_exists_state,
        haystack,
        window,
        limits,
    );
    let retry_finite_suffix = finite_suffix_incumbent.is_some_and(
        |(class_index, may_switch_to_suffix)| {
            observe_k0_finite_suffix_incumbent(
                &mut suffix_state_after_success,
                class_index,
                may_switch_to_suffix,
                attempt.outcome,
                attempt.candidate_floor,
                window,
            )
        },
    );
    let mut search_candidate_floor = attempt.candidate_floor;
    if retry_finite_suffix {
        let suffix = mandatory_suffix
            .as_ref()
            .copied()
            .expect("finite suffix retry requires its retained plan");
        let maximum_match_bytes = suffix
            .finite_exists_maximum_match_bytes()
            .expect("finite suffix retry retains its maximum width");
        let prefix_hedge_bytes = suffix
            .finite_prefix_hedge_bytes()
            .expect("finite suffix retry retains its prefix hedge");
        match run_k0_finite_prefix_exists_hedge(
            session,
            haystack,
            window,
            limits,
            search_candidate_floor,
            maximum_match_bytes,
            prefix_hedge_bytes,
        )? {
            K0FinitePrefixExistsHedge::Found => {
                let (class_index, _) = finite_suffix_incumbent
                    .expect("finite suffix hedge retains its class");
                observe_k0_finite_suffix_loss(
                    &mut suffix_state_after_success.classes[class_index],
                );
                *mandatory_suffix_exists_state = suffix_state_after_success;
                *negative_prefilter_exists_state = attempt.state_after_success;
                return Ok(true);
            }
            K0FinitePrefixExistsHedge::ResumeAt(resume_start) => {
                if resume_start >= window.end() {
                    let (class_index, _) = finite_suffix_incumbent
                        .expect("finite suffix hedge retains its class");
                    observe_k0_finite_suffix_loss(
                        &mut suffix_state_after_success.classes[class_index],
                    );
                    *mandatory_suffix_exists_state = suffix_state_after_success;
                    *negative_prefilter_exists_state = attempt.state_after_success;
                    return Ok(false);
                }
                search_candidate_floor = Some(resume_start);
            }
        }
        let suffix_attempt = try_k0_mandatory_suffix_exists(
            session,
            suffix,
            suffix_state_after_success,
            haystack,
            window,
            limits,
            search_candidate_floor,
        )?;
        suffix_state_after_success = suffix_attempt.state_after_success;
        match suffix_attempt.outcome {
            K0MandatorySuffixOutcome::Found(found) => {
                *mandatory_suffix_exists_state = suffix_state_after_success;
                *negative_prefilter_exists_state = attempt.state_after_success;
                return Ok(found);
            }
            K0MandatorySuffixOutcome::Fallback => {}
            K0MandatorySuffixOutcome::Incumbent { class_index, .. } => {
                observe_k0_finite_suffix_loss(
                    &mut suffix_state_after_success.classes[class_index],
                );
            }
            K0MandatorySuffixOutcome::Bypass
            | K0MandatorySuffixOutcome::GeometryBypass => {
                let (class_index, _) = finite_suffix_incumbent
                    .expect("finite suffix retry retains its class");
                observe_k0_finite_suffix_loss(
                    &mut suffix_state_after_success.classes[class_index],
                );
            }
        }
    }
    if attempt.outcome == K0NegativePrefilterOutcome::Absent {
        let certified = window
            .end()
            .checked_sub(window.start())
            .is_some_and(|input_bytes| {
                session.negative_terminal_has_reused_work_certificate(input_bytes)
            });
        if certified {
            *mandatory_suffix_exists_state = suffix_state_after_success;
            *negative_prefilter_exists_state = attempt.state_after_success;
            if let Some(observation) = incumbent_observation.as_mut() {
                **observation =
                    K0PackedFrontierIncumbentObservation::SpecializedComplete;
            }
            return Ok(false);
        }
    }
    // The reverse-inner proof owns no semantic continuation: a
    // fresh leftmost-start enumeration is created for this exact
    // plan, haystack and original window. Other K0 filters have
    // already retained first refusal of their cheap negatives.
    // A narrowed candidate floor would change the proof context,
    // so that case keeps the incumbent. The runtime absolute-end
    // guard is defensive closure over the construction exclusion.
    if absolute_end_proof.is_none()
        && limits == SearchLimits::unlimited()
        && search_candidate_floor.is_none()
        && let Some(reverse_inner) = reverse_inner.as_mut()
    {
        let window_bytes = window.end().saturating_sub(window.start());
        let mut next_state = reverse_inner.staged_exists_route_state();
        match next_state.select(window_bytes) {
            k0_general_reverse_inner::Route::Bypass => {
                let result = session
                    .search_exists_value(haystack, window, limits)
                    .map_err(SearchError::from);
                if result.is_ok() {
                    reverse_inner.publish_exists_route_state(next_state);
                    *mandatory_suffix_exists_state = suffix_state_after_success;
                    *negative_prefilter_exists_state = attempt.state_after_success;
                }
                return result;
            }
            k0_general_reverse_inner::Route::Learn { class_index } => {
                let report = session
                    .search_window::<Exists>(haystack, window, limits)
                    .map_err(SearchError::from)?;
                next_state.observe_incumbent(
                    class_index,
                    window_bytes,
                    report.accounting().work(),
                );
                reverse_inner.publish_exists_route_state(next_state);
                *mandatory_suffix_exists_state = suffix_state_after_success;
                *negative_prefilter_exists_state = attempt.state_after_success;
                return Ok(report.into_output());
            }
            k0_general_reverse_inner::Route::Candidate {
                class_index,
                incumbent_work,
            } => match k0_general_reverse_inner::try_exists(
                session,
                reverse_inner,
                haystack,
                window,
                incumbent_work,
            )? {
                k0_general_reverse_inner::Attempt::Complete { output, won } => {
                    next_state.observe_candidate_complete(class_index, won);
                    reverse_inner.publish_exists_route_state(next_state);
                    *mandatory_suffix_exists_state = suffix_state_after_success;
                    *negative_prefilter_exists_state = attempt.state_after_success;
                    if won
                        && let Some(observation) = incumbent_observation.as_mut()
                    {
                        **observation =
                            K0PackedFrontierIncumbentObservation::SpecializedComplete;
                    }
                    return Ok(output);
                }
                k0_general_reverse_inner::Attempt::Fallback => {
                    let result = session
                        .search_exists_value(haystack, window, limits)
                        .map_err(SearchError::from);
                    if result.is_ok() {
                        // A bounded candidate refusal is a loss,
                        // not an unobserved trial. Publish its
                        // backoff only after the authoritative
                        // incumbent succeeds so errors remain
                        // transactional and repeated steady calls
                        // do not repay the same failed candidate.
                        next_state.observe_candidate_complete(class_index, false);
                        reverse_inner.publish_exists_route_state(next_state);
                        *mandatory_suffix_exists_state = suffix_state_after_success;
                        *negative_prefilter_exists_state =
                            attempt.state_after_success;
                    }
                    return result;
                }
            },
        }
    }
    let search_window = search_candidate_floor
        .map_or(window, |start| SearchWindow::new(start, window.end()));
    let absolute_end_result = try_k0_absolute_end_exists(
        session,
        absolute_end_proof,
        haystack,
        search_window,
        limits,
    )?;
    let result = if let Some(output) = absolute_end_result {
        Ok(output)
    } else if measure_full_window_k0
        && search_window.start() == window.start()
        && search_window.end() == window.end()
    {
        match session.search_window::<Exists>(haystack, search_window, limits) {
            Ok(report) => {
                if let Some(observation) = incumbent_observation.as_mut() {
                    **observation =
                        K0PackedFrontierIncumbentObservation::RawK0 {
                            work: report.accounting().work(),
                        };
                }
                Ok(report.into_output())
            }
            Err(error) => Err(SearchError::from(error)),
        }
    } else {
        session
            .search_exists_value(haystack, search_window, limits)
            .map_err(SearchError::from)
    };
    if result.is_ok() {
        *mandatory_suffix_exists_state = suffix_state_after_success;
        *negative_prefilter_exists_state = attempt.state_after_success;
    }
    result
}

#[inline]
fn ordinary_literal_set_dfa_first_acceptance_at(
    executor: &LiteralSetUniformStandardOrdinaryExecutor<'_>,
    direct_next: &mut bool,
    haystack: &[u8],
    start: usize,
) -> Result<Option<usize>, SearchError> {
    let window = LiteralWindow::new(start, haystack.len());
    let Some(window_bytes) = haystack.len().checked_sub(start) else {
        *direct_next = false;
        #[cfg(test)]
        literal_set_dfa_ordinary_route_probe::record(false);
        return executor
            .ordinary_executor()
            .selected_end_window_value(haystack, window)
            .map_err(SearchError::from);
    };
    let direct = *direct_next;
    // Every attempted call consumes the prior observation. Only this call's
    // own near acceptance can promote its successor.
    *direct_next = false;
    #[cfg(test)]
    literal_set_dfa_ordinary_route_probe::record(direct);
    let ordinary = executor.ordinary_executor();
    let selected_end = if direct {
        let probe_bytes = executor
            .pattern_bytes()
            .saturating_mul(LITERAL_SET_DFA_DIRECT_PROBE_WIDTHS)
            .min(LITERAL_SET_DFA_DIRECT_MAX_PROBE_BYTES)
            .min(window_bytes);
        let probe_end = start.saturating_add(probe_bytes).min(haystack.len());
        match executor
            .first_acceptance_without_prefilter_window_value(
                haystack,
                LiteralWindow::new(start, probe_end),
            )
            .map_err(SearchError::from)?
        {
            Some(end) => Some(end),
            None => ordinary
                .selected_end_window_value(haystack, window)
                .map_err(SearchError::from)?,
        }
    } else {
        ordinary
            .selected_end_window_value(haystack, window)
            .map_err(SearchError::from)?
    };
    if let Some(distance) = selected_end.and_then(|end| end.checked_sub(start)) {
        let near_bytes = executor
            .pattern_bytes()
            .saturating_mul(LITERAL_SET_DFA_DIRECT_NEAR_WIDTHS);
        *direct_next = distance <= near_bytes;
    }
    Ok(selected_end)
}

#[inline]
fn ordinary_literal_set_dfa_find_at(
    executor: &LiteralSetUniformStandardOrdinaryExecutor<'_>,
    direct_next: &mut bool,
    haystack: &[u8],
    start: usize,
) -> Result<Option<Match>, SearchError> {
    let window = LiteralWindow::new(start, haystack.len());
    let ordinary = executor.ordinary_executor();
    let Some(window_bytes) = haystack.len().checked_sub(start) else {
        *direct_next = false;
        #[cfg(test)]
        literal_set_dfa_ordinary_route_probe::record(false);
        return ordinary
            .find_window_value(haystack, window)
            .map(|matched| matched.map(|(start, end)| Match { start, end }))
            .map_err(SearchError::from);
    };
    let direct = *direct_next;
    *direct_next = false;
    #[cfg(test)]
    literal_set_dfa_ordinary_route_probe::record(direct);
    let matched = if direct {
        let probe_bytes = executor
            .pattern_bytes()
            .saturating_mul(LITERAL_SET_DFA_DIRECT_PROBE_WIDTHS)
            .min(LITERAL_SET_DFA_DIRECT_MAX_PROBE_BYTES)
            .min(window_bytes);
        let probe_end = start.saturating_add(probe_bytes).min(haystack.len());
        match executor
            .first_acceptance_without_prefilter_window_value(
                haystack,
                LiteralWindow::new(start, probe_end),
            )
            .map_err(SearchError::from)?
        {
            Some(end) => {
                let pattern_bytes = executor.pattern_bytes();
                debug_assert!(
                    end.checked_sub(pattern_bytes)
                        .is_some_and(|matched_start| matched_start >= start),
                    "a selected fixed-width literal must begin within its search window",
                );
                Some(Match {
                    start: end - pattern_bytes,
                    end,
                })
            }
            None => ordinary
                .find_window_value(haystack, window)
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from)?,
        }
    } else {
        ordinary
            .find_window_value(haystack, window)
            .map(|matched| matched.map(|(start, end)| Match { start, end }))
            .map_err(SearchError::from)?
    };
    if let Some(distance) = matched
        .as_ref()
        .and_then(|matched| matched.end.checked_sub(start))
    {
        let near_bytes = executor
            .pattern_bytes()
            .saturating_mul(LITERAL_SET_DFA_DIRECT_NEAR_WIDTHS);
        *direct_next = distance <= near_bytes;
    }
    Ok(matched)
}

#[inline(never)]
fn count_ordinary_literal_set_dfa_with_selected_seed(
    executor: &LiteralSetOrdinaryExecutor<'_>,
    haystack: &[u8],
    start: usize,
) -> Result<u64, LiteralSetError> {
    if start == haystack.len() {
        return Ok(0);
    }
    let Some((_, first_end)) = executor.find_window_value(
        haystack,
        LiteralWindow::new(start, haystack.len()),
    )?
    else {
        return Ok(0);
    };
    executor
        .count_spans_window_value(
            haystack,
            LiteralWindow::new(first_end, haystack.len()),
        )?
        .checked_add(1)
        .ok_or(LiteralSetError::ArithmeticOverflow {
            computation: "positive-width literal-set match count",
        })
}

impl<'r> PortableOrdinarySession<'r> {
    /// Whether a match exists at or after `start`.
    ///
    /// A positive exact literal uses its retained finder without reconstructing
    /// a span. K0 uses its endpoint-only engine. An unanchored required-literal
    /// owner consumes a complete suffix witness without recovering the
    /// beginning of the greedy class run. Packed and DFA literal sets use their
    /// bound ordinary executors. Other canonical owners retain the boolean
    /// projection of [`Self::first_acceptance_at`].
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if `start` exceeds the haystack or ordinary
    /// execution encounters an allocation, arithmetic, or invariant failure.
    #[inline]
    pub fn is_match_at(&mut self, haystack: &[u8], start: usize) -> Result<bool, SearchError> {
        match &mut self.plan {
            PortableOrdinarySessionPlan::ExactLiteral { executor } => executor
                .exists_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::K0 { executor, .. } => executor
                .first_acceptance_at(haystack, start)
                .map(|endpoint| endpoint.is_some())
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::Canonical(session) => session
                .shortest_match_at_value(haystack, start)
                .map(|endpoint| endpoint.is_some()),
            PortableOrdinarySessionPlan::RequiredLiteral { projection, .. } => {
                #[cfg(test)]
                required_literal_ordinary_session_probe::record();
                projection.is_match_at(haystack, start)
            }
            PortableOrdinarySessionPlan::PackedLiteralSet { executor } => executor
                .exists_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetDfa {
                executor,
                ascii_exists,
            } => {
                let window = LiteralWindow::new(start, haystack.len());
                if let Some(projection) = ascii_exists.get_or_bind(*executor) {
                    projection
                        .exists_window_value(haystack, window)
                        .map_err(SearchError::from)
                } else {
                    executor
                        .exists_window_value(haystack, window)
                        .map_err(SearchError::from)
                }
            }
            PortableOrdinarySessionPlan::LiteralSetCompact { executor } => executor
                .exists_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                executor,
                direct_next,
            } => ordinary_literal_set_dfa_first_acceptance_at(
                executor,
                direct_next,
                haystack,
                start,
            )
            .map(|endpoint| endpoint.is_some()),
        }
    }

    /// Return the first accepting boundary at or after `start`.
    ///
    /// Positive exact literals and K0 execute endpoint-only engines. An
    /// unanchored required-literal owner selects the first suffix witness
    /// without recovering its greedy start. Packed literal sets return the
    /// selected endpoint. A nonuniform DFA literal set stops at its first
    /// accepting endpoint through its bound ordinary executor. Other canonical
    /// fallback plans use the existing value-only shortest-match projection
    /// with unlimited limits.
    /// Assertions inspect the complete original haystack and the returned
    /// boundary is relative to it.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if `start` exceeds the haystack or ordinary
    /// execution encounters an allocation, arithmetic, or invariant failure.
    #[inline]
    pub fn first_acceptance_at(
        &mut self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<usize>, SearchError> {
        match &mut self.plan {
            PortableOrdinarySessionPlan::ExactLiteral { executor } => executor
                .first_end_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::K0 { executor, .. } => executor
                .first_acceptance_at(haystack, start)
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::Canonical(session) => {
                session.shortest_match_at_value(haystack, start)
            }
            PortableOrdinarySessionPlan::RequiredLiteral { projection, .. } => {
                #[cfg(test)]
                required_literal_ordinary_session_probe::record_endpoint();
                projection.first_acceptance_at(haystack, start)
            }
            PortableOrdinarySessionPlan::PackedLiteralSet { executor } => executor
                .selected_end_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetDfa {
                executor,
                ascii_exists,
            } => {
                let window = LiteralWindow::new(start, haystack.len());
                if let Some(projection) = ascii_exists.get_or_bind(*executor) {
                    projection
                        .first_acceptance_window_value(haystack, window)
                        .map_err(SearchError::from)
                } else {
                    executor
                        .first_acceptance_window_value(haystack, window)
                        .map_err(SearchError::from)
                }
            }
            PortableOrdinarySessionPlan::LiteralSetCompact { executor } => executor
                .selected_end_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                executor,
                direct_next,
            } => ordinary_literal_set_dfa_first_acceptance_at(
                executor,
                direct_next,
                haystack,
                start,
            ),
        }
    }

    /// Return the first accepting boundary at or after `start`.
    ///
    /// This ripgrep-facing name is an exact alias for
    /// [`Self::first_acceptance_at`] and does not add another search engine.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::first_acceptance_at`].
    #[inline]
    pub fn shortest_match_at(
        &mut self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<usize>, SearchError> {
        self.first_acceptance_at(haystack, start)
    }

    /// Return the selected leftmost-first span at or after `start`.
    ///
    /// A positive exact literal selects the endpoint first and subtracts its
    /// sealed width only after a hit. K0 performs reverse start recovery only
    /// after a positive result requires it. On a promoted direct hit, a bound
    /// uniform-standard literal set likewise selects its endpoint first, then
    /// subtracts its sealed common width; its ordinary route and direct misses
    /// retain the canonical selected span. Other packed and DFA literal sets
    /// use their bound selected-span engines. Canonical fallback plans retain
    /// their existing selected-span implementation with unlimited limits.
    /// Assertions inspect the complete original haystack and offsets remain
    /// relative to it.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] if `start` exceeds the haystack or ordinary
    /// execution encounters an allocation, arithmetic, or invariant failure.
    #[inline]
    pub fn find_at(
        &mut self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<Match>, SearchError> {
        match &mut self.plan {
            PortableOrdinarySessionPlan::ExactLiteral { executor } => executor
                .find_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::K0 { executor, .. } => executor
                .selected_span_at(haystack, start)
                .map(|matched| {
                    matched.map(|span| Match {
                        start: span.start(),
                        end: span.end(),
                    })
                })
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::RequiredLiteral { regex, .. } => regex
                .find_window_value(
                    haystack,
                    SearchWindow::new(start, haystack.len()),
                    SearchLimits::unlimited(),
                ),
            PortableOrdinarySessionPlan::Canonical(session) => {
                session.find_at_value(haystack, start)
            }
            PortableOrdinarySessionPlan::PackedLiteralSet { executor } => executor
                .find_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetDfa { executor, .. } => executor
                .find_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetCompact { executor } => executor
                .find_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                executor,
                direct_next,
            } => ordinary_literal_set_dfa_find_at(
                executor,
                direct_next,
                haystack,
                start,
            ),
        }
    }

    /// Visit every non-overlapping selected span from the start of `haystack`.
    ///
    /// The callback returns `Ok(true)` to continue, `Ok(false)` to stop
    /// successfully, or `Err(error)` to return that callback error. Search
    /// failures are kept in the outer result so an embedding can distinguish
    /// them without wrapping its callback error.
    ///
    /// Empty matches make byte-wise progress and use the same suppression rule
    /// as the portable byte iterator. K0 retains its source cursor only for
    /// this call; dropping or returning from the visitor leaves the worker
    /// session source-free.
    ///
    /// # Errors
    ///
    /// Returns [`PortableFindIterError`] if selected-span iteration fails. K0
    /// wraps only its underlying [`SearchError`]; canonical fallback plans
    /// preserve the existing iterator error contract.
    #[inline]
    pub fn try_visit_spans<F, E>(
        &mut self,
        haystack: &[u8],
        visitor: F,
    ) -> Result<Result<(), E>, PortableFindIterError>
    where
        F: FnMut(Match) -> Result<bool, E>,
    {
        self.try_visit_spans_at(haystack, 0, visitor)
    }

    /// Visit every non-overlapping selected span at or after `start`.
    ///
    /// This is the ranged companion to [`Self::try_visit_spans`]. Assertions
    /// retain complete original-haystack context and offsets remain absolute.
    /// Positive exact literals and K0 pass selected items directly to the
    /// callback without an accounting iterator, result buffer, or search-call
    /// cap. Canonical fallback plans iterate the compact binding with
    /// unlimited value searches and the ordinary empty-match progress rule.
    ///
    /// # Errors
    ///
    /// Returns [`PortableFindIterError`] if `start` exceeds the haystack or
    /// selected-span iteration fails. Underlying search failures remain in its
    /// [`PortableFindIterError::Search`] variant.
    #[inline]
    pub fn try_visit_spans_at<F, E>(
        &mut self,
        haystack: &[u8],
        start: usize,
        visitor: F,
    ) -> Result<Result<(), E>, PortableFindIterError>
    where
        F: FnMut(Match) -> Result<bool, E>,
    {
        match &mut self.plan {
            PortableOrdinarySessionPlan::ExactLiteral { executor } => {
                let mut visitor = visitor;
                executor
                    .try_visit_spans_window_value(
                        haystack,
                        LiteralWindow::new(start, haystack.len()),
                        |(matched_start, end)| {
                            visitor(Match {
                                start: matched_start,
                                end,
                            })
                        },
                    )
                    .map_err(SearchError::from)
                    .map_err(PortableFindIterError::Search)
            }
            PortableOrdinarySessionPlan::K0 { executor, .. } => {
                let mut source = K0SpanSourceCursor::new(haystack);
                try_visit_ordinary_spans_at(
                    haystack.len(),
                    start,
                    |search_start| {
                        executor
                            .selected_span_at_source_cursor(&mut source, search_start)
                            .map(|matched| {
                                matched.map(|span| Match {
                                    start: span.start(),
                                    end: span.end(),
                                })
                            })
                            .map_err(SearchError::from)
                            .map_err(PortableFindIterError::Search)
                    },
                    visitor,
                )
            }
            PortableOrdinarySessionPlan::RequiredLiteral { regex, .. } => {
                PortableOrdinaryCanonical::Native(regex)
                    .try_visit_spans_at(haystack, start, visitor)
            }
            PortableOrdinarySessionPlan::Canonical(session) => {
                session.try_visit_spans_at(haystack, start, visitor)
            }
            PortableOrdinarySessionPlan::PackedLiteralSet { executor } => {
                let mut visitor = visitor;
                executor.try_visit_spans_window_value(
                    haystack,
                    LiteralWindow::new(start, haystack.len()),
                    |(start, end)| visitor(Match { start, end }),
                )
                .map_err(SearchError::from)
                .map_err(PortableFindIterError::Search)
            }
            PortableOrdinarySessionPlan::LiteralSetDfa { executor, .. } => {
                let mut visitor = visitor;
                executor
                    .try_visit_spans_window_value(
                        haystack,
                        LiteralWindow::new(start, haystack.len()),
                        |(start, end)| visitor(Match { start, end }),
                    )
                    .map_err(SearchError::from)
                    .map_err(PortableFindIterError::Search)
            }
            PortableOrdinarySessionPlan::LiteralSetCompact { executor } => {
                let mut visitor = visitor;
                executor
                    .try_visit_spans_window_value(
                        haystack,
                        LiteralWindow::new(start, haystack.len()),
                        |(start, end)| visitor(Match { start, end }),
                    )
                    .map_err(SearchError::from)
                    .map_err(PortableFindIterError::Search)
            }
            PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                executor,
                direct_next,
            } => {
                let initial_direct = core::mem::take(direct_next);
                let mut visitor = visitor;
                let (outcome, next_direct) = executor
                    .try_visit_spans_window_value_with_direct_recommendation(
                        haystack,
                        LiteralWindow::new(start, haystack.len()),
                        initial_direct,
                        |(matched_start, end)| {
                            visitor(Match {
                                start: matched_start,
                                end,
                            })
                        },
                    )
                    .map_err(SearchError::from)
                    .map_err(PortableFindIterError::Search)?;
                if next_direct {
                    *direct_next = true;
                }
                Ok(outcome)
            }
        }
    }

    /// Count selected positive-width matches at or after `start` using only
    /// their ordered endpoints.
    ///
    /// `Ok(Some(count))` is returned for a positive exact literal, a
    /// positive-width K0 plan, a legacy literal/class-run plan over a full or
    /// unguarded tail window, or a packed, ordinary non-uniform, or
    /// uniform-standard literal-set plan. Each construction seals nonempty
    /// selected spans.
    /// Unsupported plans return `Ok(None)` before validating `start` or
    /// searching the haystack. This lets an embedding fall back without
    /// duplicating partial work. Once execution begins, every error is
    /// authoritative.
    ///
    /// Each successful search resumes at the selected endpoint. K0 reports a
    /// failure to advance despite its positive-width proof as an invariant
    /// error rather than risking an infinite loop. Packed literal sets use
    /// their bound non-overlapping span iterator. An ordinary non-uniform
    /// literal set advances through its construction-selected DFA endpoints.
    /// When that DFA seals direct leftmost-first counting, one canonical
    /// selected match seeds the direct scanner at the selected endpoint.
    /// A uniform-standard literal set consumes any preceding near-acceptance
    /// observation on the first bounded tail probe and counts through its
    /// adaptive span visitor. After exhaustive success that accepts a
    /// current-call span, near final selected-end spacing and a near terminal
    /// gap may recommend one bounded probe for the next session operation.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] for an invalid `start`, an execution failure,
    /// arithmetic overflow, or a violated positive-width progress proof.
    #[doc(hidden)]
    pub fn count_positive_width_selected_ends_at(
        &mut self,
        haystack: &[u8],
        start: usize,
    ) -> Result<Option<u64>, SearchError> {
        match &mut self.plan {
            PortableOrdinarySessionPlan::ExactLiteral { executor } => executor
                .count_spans_window_value(
                    haystack,
                    LiteralWindow::new(start, haystack.len()),
                )
                .map(Some)
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::K0 {
                executor,
                positive: true,
            } => {
                let mut cursor = start;
                let mut count = 0_u64;
                loop {
                    let Some(selected_end) = executor
                        .selected_end_at(haystack, cursor)
                        .map_err(SearchError::from)?
                    else {
                        return Ok(Some(count));
                    };
                    if selected_end <= cursor {
                        return Err(SearchError::K0(K0SearchError::InternalInvariant {
                            detail: "positive-width selected-end iteration failed to advance",
                        }));
                    }
                    cursor = selected_end;
                    count = count.checked_add(1).ok_or(SearchError::K0(
                        K0SearchError::ArithmeticOverflow {
                            computation: "positive-width selected-end match count",
                        },
                    ))?;
                }
            }
            PortableOrdinarySessionPlan::PackedLiteralSet { executor } => executor
                .count_spans_window_value(
                    haystack,
                    LiteralWindow::new(start, haystack.len()),
                )
                .map(Some)
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetDfa { executor, .. } => {
                if executor.direct_count_scanner_supported() {
                    count_ordinary_literal_set_dfa_with_selected_seed(
                        executor, haystack, start,
                    )
                    .map(Some)
                    .map_err(SearchError::from)
                } else {
                    executor
                        .count_spans_window_value(
                            haystack,
                            LiteralWindow::new(start, haystack.len()),
                        )
                        .map(Some)
                        .map_err(SearchError::from)
                }
            }
            PortableOrdinarySessionPlan::LiteralSetCompact { executor } => executor
                .count_spans_window_value(haystack, LiteralWindow::new(start, haystack.len()))
                .map(Some)
                .map_err(SearchError::from),
            PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                executor,
                direct_next,
            } => {
                let initial_direct = core::mem::take(direct_next);
                let promotion_bytes = executor.pattern_bytes().saturating_mul(2);
                let mut penultimate_end = start;
                let mut previous_end = start;
                let mut count = 0_u64;
                let outcome = executor
                    .try_visit_spans_window_value_with_initial_direct(
                        haystack,
                        LiteralWindow::new(start, haystack.len()),
                        initial_direct,
                        |(_, end)| {
                            penultimate_end = previous_end;
                            previous_end = end;
                            count = count.checked_add(1).ok_or(
                                LiteralSetError::ArithmeticOverflow {
                                    computation: "positive-width literal-set match count",
                                },
                            )?;
                            Ok::<bool, LiteralSetError>(true)
                        },
                    )
                    .map_err(SearchError::from)?;
                outcome.map_err(SearchError::from)?;
                if previous_end != start
                    && previous_end.saturating_sub(penultimate_end) <= promotion_bytes
                    && haystack.len().saturating_sub(previous_end) <= promotion_bytes
                {
                    *direct_next = true;
                }
                Ok(Some(count))
            }
            PortableOrdinarySessionPlan::Canonical(
                PortableOrdinaryCanonical::LiteralClassRunLiteral { plan, .. },
            ) if start == 0
                || plan.boundary_semantics()
                    == LiteralClassRunLiteralBoundarySemantics::Unguarded =>
            {
                let tail = haystack.get(start..).ok_or_else(|| {
                    SearchError::from(LiteralClassRunLiteralSearchError::InvalidWindow {
                        start,
                        end: haystack.len(),
                        haystack_len: haystack.len(),
                    })
                })?;
                plan.count(tail, LiteralClassRunLiteralReduceLimits::unlimited())
                    .map(|result| Some(result.count))
                    .map_err(LiteralClassRunLiteralSearchError::from)
                    .map_err(SearchError::from)
            }
            _ => Ok(None),
        }
    }
}

fn try_visit_ordinary_spans_at<F, E, S>(
    haystack_len: usize,
    mut start: usize,
    mut search: S,
    mut visitor: F,
) -> Result<Result<(), E>, PortableFindIterError>
where
    F: FnMut(Match) -> Result<bool, E>,
    S: FnMut(usize) -> Result<Option<Match>, PortableFindIterError>,
{
    let mut last_match_end = None;
    let mut pending_empty_progress = false;
    loop {
        if pending_empty_progress {
            pending_empty_progress = false;
            if start == haystack_len {
                return Ok(Ok(()));
            }
            start += 1;
        }

        let Some(matched) = search(start)? else {
            return Ok(Ok(()));
        };
        if matched.is_empty() && last_match_end == Some(matched.end()) {
            if start == haystack_len {
                return Ok(Ok(()));
            }
            start += 1;
            continue;
        }

        start = matched.end();
        last_match_end = Some(matched.end());
        pending_empty_progress = matched.is_empty();
        match visitor(matched) {
            Ok(true) => {}
            Ok(false) => return Ok(Ok(())),
            Err(error) => return Ok(Err(error)),
        }
    }
}

impl<'r> PortableSearchSession<'r> {
    /// Stable runtime identity of the borrowed matcher.
    #[must_use]
    pub const fn runtime_implementation_id(&self) -> &'static str {
        match &self.plan {
            PortableSearchSessionPlan::ExactLiteral { regex, .. }
            | PortableSearchSessionPlan::FixedPredicateWord64 { regex, .. } => {
                regex.runtime_implementation_id()
            }
            PortableSearchSessionPlan::Native(regex) => {
                match regex.retained_find_iter_build_accounting() {
                    Some(accounting) => accounting.runtime_implementation_id,
                    None => regex.runtime_implementation_id(),
                }
            }
            PortableSearchSessionPlan::K0 { .. } => "k0",
        }
    }

    /// Aggregate one-time K0 workspace allocation and initialization facts.
    ///
    /// Native specialized plans return `None` because the session allocates no
    /// storage for them. Eligible general reverse-inner sessions include both
    /// the primary and residual-admitted prefix workspaces in this receipt.
    /// An immutable regex-owned start-filter proof is deliberately excluded;
    /// its separate exact setup receipt is returned by
    /// [`Self::prepare_k0_start_filter`].
    /// Demand growth performed by later searches is excluded and is reported
    /// by their [`SearchAccounting::cache_growth`] receipts instead.
    #[must_use]
    pub const fn workspace_setup_accounting(&self) -> Option<SearchSessionSetupAccounting> {
        match &self.plan {
            PortableSearchSessionPlan::ExactLiteral { .. }
            | PortableSearchSessionPlan::FixedPredicateWord64 { .. }
            | PortableSearchSessionPlan::Native(_) => None,
            PortableSearchSessionPlan::K0 {
                aggregate_setup, ..
            } => Some(*aggregate_setup),
        }
    }

    /// Settle the optional immutable K0 start-filter proof before a measured
    /// source-bearing operation.
    ///
    /// `limits` covers both the session's already-completed workspace
    /// construction and this graph-only preparation. Before allocation, the
    /// byte envelope reserves the complete maximum proof payload in addition
    /// to every retained session workspace. If either residual cap cannot
    /// admit that transaction, preparation permanently selects ordinary K0
    /// without inspecting source. Either K0 outcome means that the next search
    /// cannot derive or allocate this proof for the first time. Native
    /// sessions return `Ok(None)`.
    ///
    /// The returned owner bytes belong to the immutable regex, not to this
    /// session, and are therefore deliberately separate from
    /// [`Self::workspace_setup_accounting`]. Composite owners must charge any
    /// nonzero retained payload until the regex itself is released. The
    /// returned aggregate retained value has already been checked against
    /// `limits.max_scratch_bytes`.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] when either limit is below already-completed
    /// session setup, a proof retained by an earlier preparation does not fit
    /// the supplied aggregate scratch cap, or the authenticated source-free
    /// preparation encounters an invariant failure.
    #[doc(hidden)]
    pub fn prepare_k0_start_filter(
        &mut self,
        limits: SearchSessionLimits,
    ) -> Result<Option<PortableK0StartFilterSetupAccounting>, SearchError> {
        let PortableSearchSessionPlan::K0 {
            session,
            aggregate_setup,
            k0_plan,
            ..
        } = &mut self.plan
        else {
            return Ok(None);
        };
        let residual_work = limits
            .max_setup_work
            .checked_sub(aggregate_setup.work())
            .ok_or(K0SearchError::WorkLimitExceeded {
                limit: limits.max_setup_work,
                consumed: 0,
                requested: aggregate_setup.work(),
                position: 0,
            })?;
        if aggregate_setup.retained_bytes() > limits.max_scratch_bytes {
            return Err(K0SearchError::ResourceLimit {
                resource: fre_automata::ResourceKind::ScratchBytes,
                needed: aggregate_setup.retained_bytes(),
                limit: limits.max_scratch_bytes,
            }
            .into());
        }
        let proof_ceiling_fits = aggregate_setup
            .retained_bytes()
            .checked_add(K0StartFilterPreparationReceipt::MAX_RETAINED_OWNER_BYTES)
            .is_some_and(|needed| needed <= limits.max_scratch_bytes);
        let proof_work_limit = if proof_ceiling_fits { residual_work } else { 0 };
        let receipt = session.prepare_start_filter_with_setup_work_limit(proof_work_limit)?;
        let total_work = aggregate_setup
            .work()
            .checked_add(receipt.work_completed())
            .ok_or(K0SearchError::ArithmeticOverflow {
                computation: "aggregate K0 session and start-filter setup work",
            })?;
        if total_work > limits.max_setup_work {
            return Err(K0SearchError::InternalInvariant {
                detail: "K0 start-filter preparation exceeded its residual setup-work admission",
            }
            .into());
        }
        let retained_owner_bytes = k0_plan
            .automaton
            .compiler_private_start_filter_proof_retained_bytes();
        let aggregate_retained_bytes = aggregate_setup
            .retained_bytes()
            .checked_add(retained_owner_bytes)
            .ok_or(K0SearchError::ArithmeticOverflow {
                computation: "aggregate K0 session and start-filter retained bytes",
            })?;
        if aggregate_retained_bytes > limits.max_scratch_bytes {
            return Err(K0SearchError::ResourceLimit {
                resource: fre_automata::ResourceKind::ScratchBytes,
                needed: aggregate_retained_bytes,
                limit: limits.max_scratch_bytes,
            }
            .into());
        }
        Ok(Some(PortableK0StartFilterSetupAccounting {
            work_completed: receipt.work_completed(),
            total_setup_work: total_work,
            newly_retained_owner_bytes: receipt.retained_owner_bytes(),
            retained_owner_bytes,
            aggregate_retained_bytes,
            cap_declined: receipt.cap_declined(),
        }))
    }

    /// Prepare a source-independent token for repeated value-only existence
    /// searches under one fixed finite limit pair.
    ///
    /// Exact empty literals admit the largest full input, up to
    /// `maximum_input_bytes`, whose exact literal linear-term charge fits
    /// `limits`. Assertion-free warm-capable K0 sessions admit the largest
    /// input prefix whose conservative reused-work certificate fits `limits`.
    /// Construction-proved whole-line, byte-class delimiter, and class-guarded
    /// literal matchers instead retain their exact direct identities and
    /// source-free linear envelopes. The construction-time aggregate retained
    /// workspace must also fit the per-invocation scratch cap. Execution
    /// rechecks the adaptive primary's live retained floor, reserves any fixed
    /// sidecar, and charges cache growth under the same finite limits. Every
    /// other plan receives an incumbent token. Preparation reads no source,
    /// allocates nothing, and does not initialize lazy search state.
    #[must_use]
    pub fn prepare_is_match_value_token(
        &self,
        maximum_input_bytes: usize,
        limits: SearchLimits,
    ) -> PortableIsMatchValueToken {
        let route = match &self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } if plan.needle().is_empty() => {
                PortableIsMatchValueTokenRoute::EmptyLiteral {
                    maximum_input_bytes: maximum_input_bytes
                        .min(usize::try_from(limits.max_work).unwrap_or(usize::MAX)),
                }
            }
            PortableSearchSessionPlan::K0 {
                aggregate_setup,
                k0_plan,
                session,
                line_total_grep_plan,
                ..
            } if aggregate_setup.retained_bytes() <= limits.max_scratch_bytes => {
                if let Some(plan) = k0_plan.literal_prefix_class_exists
                    && let Some(maximum_input_bytes) =
                        literal_prefix_class_prepared_maximum_input_bytes(
                            &k0_plan.automaton,
                            maximum_input_bytes,
                            limits.max_work,
                            plan.prepared_work_per_input_byte(),
                        )
                {
                    return PortableIsMatchValueToken {
                        limits,
                        route: PortableIsMatchValueTokenRoute::LiteralPrefixClass {
                            automaton_identity: k0_plan.automaton.identity(),
                            plan_identity: plan.identity(),
                            maximum_input_bytes,
                        },
                    };
                }
                if let Some(plan) = k0_plan.class_delimiter_exists {
                    return PortableIsMatchValueToken {
                        limits,
                        route: PortableIsMatchValueTokenRoute::ByteClassDelimiter {
                            automaton_identity: k0_plan.automaton.identity(),
                            plan_identity: plan.identity(),
                            maximum_input_bytes:
                                class_delimiter_prepared_maximum_input_bytes(
                                    maximum_input_bytes,
                                    limits.max_work,
                                ),
                        },
                    };
                }
                if let Some(plan) = k0_plan.uri_exists {
                    let automaton_identity = k0_plan.automaton.identity();
                    let plan_identity = plan.identity();
                    let maximum_input_bytes = uri_like_prepared_maximum_input_bytes(
                        maximum_input_bytes,
                        limits.max_work,
                        plan.prepared_work_per_input_byte(),
                    );
                    let route = if plan.is_composite() {
                        PortableIsMatchValueTokenRoute::FusedUriLikeComposite {
                            automaton_identity,
                            plan_identity,
                            maximum_input_bytes,
                        }
                    } else {
                        PortableIsMatchValueTokenRoute::UriLike {
                            automaton_identity,
                            plan_identity,
                            maximum_input_bytes,
                        }
                    };
                    return PortableIsMatchValueToken {
                        limits,
                        route,
                    };
                }
                if let Some(plan) = k0_plan.bounded_delimited_exists {
                    return PortableIsMatchValueToken {
                        limits,
                        route: PortableIsMatchValueTokenRoute::BoundedDelimited {
                            automaton_identity: k0_plan.automaton.identity(),
                            plan_identity: plan.identity(),
                            maximum_input_bytes:
                                bounded_delimited_prepared_maximum_input_bytes(
                                    maximum_input_bytes,
                                    limits.max_work,
                                    plan.prepared_work_per_input_byte(),
                                ),
                        },
                    };
                }
                if let Some(plan) = k0_plan.anchored_scalar_corridor_exists {
                    return PortableIsMatchValueToken {
                        limits,
                        route: PortableIsMatchValueTokenRoute::AnchoredScalarCorridor {
                            automaton_identity: k0_plan.automaton.identity(),
                            plan_identity: plan.identity(),
                            maximum_input_bytes:
                                anchored_scalar_corridor_prepared_maximum_input_bytes(
                                    maximum_input_bytes,
                                    limits.max_work,
                                    plan.prepared_work_per_input_byte(),
                                ),
                        },
                    };
                }
                let maximum = k0_reused_exists_maximum_input_bytes(
                    &k0_plan.automaton,
                    maximum_input_bytes,
                    limits.max_work,
                );
                maximum.map_or(PortableIsMatchValueTokenRoute::Incumbent, |maximum| {
                    if let Some(plan) = line_total_grep_plan {
                        return PortableIsMatchValueTokenRoute::LineTotal {
                            automaton_identity: k0_plan.automaton.identity(),
                            plan_identity: plan.identity(),
                            maximum_input_bytes: maximum,
                        };
                    }
                    if k0_plan.automaton.stats().has_assertions()
                        || !session.report_free_warm_exists_available()
                    {
                        return PortableIsMatchValueTokenRoute::Incumbent;
                    }
                    PortableIsMatchValueTokenRoute::K0Warm {
                        automaton_identity: k0_plan.automaton.identity(),
                        maximum_input_bytes: maximum,
                    }
                })
            }
            PortableSearchSessionPlan::Native(regex) => match &regex.plan {
                PortablePlan::UnicodeWordRun(plan) => {
                    let identity = plan.aggregate_count_identity();
                    PortableIsMatchValueTokenRoute::UnicodeWordRun {
                        identity,
                        maximum_input_bytes: unicode_word_run_prepared_maximum_input_bytes(
                            identity,
                            maximum_input_bytes,
                            limits.max_work,
                        ),
                    }
                }
                _ => PortableIsMatchValueTokenRoute::Incumbent,
            },
            PortableSearchSessionPlan::ExactLiteral { .. }
            | PortableSearchSessionPlan::FixedPredicateWord64 { .. }
            | PortableSearchSessionPlan::K0 { .. } => PortableIsMatchValueTokenRoute::Incumbent,
        };
        PortableIsMatchValueToken { limits, route }
    }

    /// Prepare only the generic report-free K0 repeated-existence route.
    ///
    /// Unlike [`Self::prepare_is_match_value_token`], this deliberately
    /// ignores every construction-proved shape recognizer. It is useful when
    /// a caller permits the ordinary retained K0 executor but declines a
    /// narrower direct predicate. Preparation is source-independent, reads no
    /// haystack bytes, allocates nothing, and preserves the original finite
    /// limits for both the authenticated warm executor and the ordinary
    /// fallback path. Execution rechecks live retained scratch and meters any
    /// adaptive first-hole growth under those limits.
    #[must_use]
    pub fn prepare_k0_warm_is_match_value_token(
        &self,
        maximum_input_bytes: usize,
        limits: SearchLimits,
    ) -> PortableIsMatchValueToken {
        let route = match &self.plan {
            PortableSearchSessionPlan::K0 {
                aggregate_setup,
                k0_plan,
                session,
                ..
            } if aggregate_setup.retained_bytes() <= limits.max_scratch_bytes => {
                k0_reused_exists_maximum_input_bytes(
                    &k0_plan.automaton,
                    maximum_input_bytes,
                    limits.max_work,
                )
                .map_or(PortableIsMatchValueTokenRoute::Incumbent, |maximum| {
                    if k0_plan.automaton.stats().has_assertions()
                        || !session.report_free_warm_exists_available()
                    {
                        return PortableIsMatchValueTokenRoute::Incumbent;
                    }
                    PortableIsMatchValueTokenRoute::K0Warm {
                        automaton_identity: k0_plan.automaton.identity(),
                        maximum_input_bytes: maximum,
                    }
                })
            }
            PortableSearchSessionPlan::ExactLiteral { .. }
            | PortableSearchSessionPlan::FixedPredicateWord64 { .. }
            | PortableSearchSessionPlan::Native(_)
            | PortableSearchSessionPlan::K0 { .. } => PortableIsMatchValueTokenRoute::Incumbent,
        };
        PortableIsMatchValueToken { limits, route }
    }

    /// Bind an exact whole-line token to this session once for repeated
    /// value-only calls.
    ///
    /// The returned matcher carries the token's finite input envelope. A
    /// token for another automaton owner, a changed plan, or any non-whole-line
    /// route returns `None` without reading source or allocating. Separate
    /// sessions over the same exact immutable automaton remain compatible.
    #[must_use]
    pub fn bind_line_total_is_match_value_token(
        &self,
        token: PortableIsMatchValueToken,
    ) -> Option<PortableBoundLineTotalMatcher> {
        let PortableIsMatchValueTokenRoute::LineTotal {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
        else {
            return None;
        };
        let PortableSearchSessionPlan::K0 {
            k0_plan,
            line_total_grep_plan: Some(plan),
            ..
        } = &self.plan
        else {
            return None;
        };
        (k0_plan.automaton.identity() == automaton_identity
            && plan.identity() == plan_identity)
            .then_some(PortableBoundLineTotalMatcher {
                maximum_input_bytes,
            })
    }

    /// Bind an exact byte-class delimiter token to this session once for
    /// repeated value-only calls.
    ///
    /// The returned matcher carries the construction-proved plan and the
    /// token's finite input envelope. A token from another session, a changed
    /// plan, or any non-byte-class route returns `None` without reading source
    /// or allocating.
    #[must_use]
    pub fn bind_byte_class_delimiter_is_match_value_token(
        &self,
        token: PortableIsMatchValueToken,
    ) -> Option<PortableBoundByteClassDelimiterMatcher> {
        let PortableIsMatchValueTokenRoute::ByteClassDelimiter {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
        else {
            return None;
        };
        let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan else {
            return None;
        };
        let plan = k0_plan.class_delimiter_exists?;
        (k0_plan.automaton.identity() == automaton_identity
            && plan.identity() == plan_identity)
            .then_some(PortableBoundByteClassDelimiterMatcher {
                plan,
                maximum_input_bytes,
            })
    }

    /// Bind a generic warm-K0 token to this exact retained session.
    ///
    /// The returned handle omits repeated token-route and warm-capability
    /// checks while retaining one automaton-owner comparison per call. It
    /// retains the token's finite per-call limits and source-independent
    /// maximum input length, and it retains no source bytes, positions,
    /// result, or execution proof.
    #[must_use]
    pub fn bind_k0_warm_is_match_value_token(
        &self,
        token: PortableIsMatchValueToken,
    ) -> Option<PortableBoundK0WarmIsMatchValueToken> {
        let PortableIsMatchValueTokenRoute::K0Warm {
            automaton_identity,
            maximum_input_bytes,
        } = token.route
        else {
            return None;
        };
        let PortableSearchSessionPlan::K0 {
            k0_plan, session, ..
        } = &self.plan
        else {
            return None;
        };
        (k0_plan.automaton.identity() == automaton_identity
            && !k0_plan.automaton.stats().has_assertions()
            && session.report_free_warm_exists_available())
        .then_some(PortableBoundK0WarmIsMatchValueToken {
            limits: token.limits,
            automaton_identity,
            maximum_input_bytes,
        })
    }

    /// Whether a selected match exists, reusing K0 state when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::is_match_accounted`].
    pub fn is_match(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        self.is_match_window(haystack, SearchWindow::full(haystack), limits)
    }

    /// Whether a selected match exists without constructing facade diagnostic
    /// accounting on the success path, reusing K0 state when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::is_match_value`].
    pub fn is_match_value(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        self.is_match_window_value(haystack, SearchWindow::full(haystack), limits)
    }

    /// Whether a match exists under one prepared repeated-call envelope.
    ///
    /// An exact token may complete through an exact empty-literal result, a
    /// construction-proved LF-free line result, an exact byte-class delimiter,
    /// class-guarded literal, absolute-start scalar-corridor predicate, or the
    /// already-warm report-free K0 executor. A cold cache, token/session
    /// mismatch, input above the certified maximum, or any other admission
    /// decline replays
    /// [`Self::is_match_value`] with the token's original finite limits. Thus
    /// preparation cannot widen acceptance or turn a previously accepted call
    /// into a conservative refusal.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same finite resource contract as
    /// [`Self::is_match_value`].
    #[inline]
    pub fn is_match_value_prepared(
        &mut self,
        haystack: &[u8],
        token: PortableIsMatchValueToken,
    ) -> Result<bool, SearchError> {
        if let PortableIsMatchValueTokenRoute::EmptyLiteral {
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::ExactLiteral { plan, .. } = &self.plan
            && plan.needle().is_empty()
        {
            return Ok(true);
        }
        let k0_owner_identity = match token.route {
            PortableIsMatchValueTokenRoute::LineTotal {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::K0Warm {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::LiteralPrefixClass {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::ByteClassDelimiter {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::BoundedDelimited {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::UriLike {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::FusedUriLikeComposite {
                automaton_identity, ..
            }
            | PortableIsMatchValueTokenRoute::AnchoredScalarCorridor {
                automaton_identity, ..
            } => Some(automaton_identity),
            PortableIsMatchValueTokenRoute::Incumbent
            | PortableIsMatchValueTokenRoute::EmptyLiteral { .. }
            | PortableIsMatchValueTokenRoute::UnicodeWordRun { .. } => None,
        };
        if let Some(automaton_identity) = k0_owner_identity
            && let PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                ..
            } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
        {
            K0AggregateInvocation::admit(session, *aggregate_setup, token.limits)?;
        }
        if let PortableIsMatchValueTokenRoute::LineTotal {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && memchr(b'\n', haystack).is_none()
            && let PortableSearchSessionPlan::K0 {
                k0_plan,
                line_total_grep_plan: Some(plan),
                ..
            } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && plan.identity() == plan_identity
        {
            return Ok(true);
        }
        if let PortableIsMatchValueTokenRoute::K0Warm {
            automaton_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                ..
            } = &mut self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && !k0_plan.automaton.stats().has_assertions()
            && let Some(matched) = try_k0_warm_exists_value_with_aggregate_limits(
                session,
                *aggregate_setup,
                haystack,
                token.limits,
            )?
        {
            return Ok(matched);
        }
        if let PortableIsMatchValueTokenRoute::LiteralPrefixClass {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && let Some(plan) = k0_plan.literal_prefix_class_exists
            && plan.identity() == plan_identity
        {
            return Ok(plan.is_match_full(haystack));
        }
        if let PortableIsMatchValueTokenRoute::ByteClassDelimiter {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && let Some(plan) = k0_plan.class_delimiter_exists
            && plan.identity() == plan_identity
        {
            return Ok(plan.is_match_full(haystack));
        }
        if let PortableIsMatchValueTokenRoute::UriLike {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && let Some(plan) = k0_plan.uri_exists
            && plan.identity() == plan_identity
        {
            return Ok(plan.is_match_full(haystack));
        }
        if let PortableIsMatchValueTokenRoute::FusedUriLikeComposite {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && let Some(plan) = k0_plan.uri_exists
            && plan.identity() == plan_identity
            && plan.is_composite()
        {
            return Ok(plan.is_match_fused_composite_full(haystack));
        }
        if let PortableIsMatchValueTokenRoute::BoundedDelimited {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && let Some(plan) = k0_plan.bounded_delimited_exists
            && plan.identity() == plan_identity
        {
            return Ok(plan.is_match_full(haystack));
        }
        if let PortableIsMatchValueTokenRoute::AnchoredScalarCorridor {
            automaton_identity,
            plan_identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::K0 { k0_plan, .. } = &self.plan
            && k0_plan.automaton.identity() == automaton_identity
            && let Some(plan) = k0_plan.anchored_scalar_corridor_exists
            && plan.identity() == plan_identity
        {
            return Ok(plan.is_match_full(haystack));
        }
        if let PortableIsMatchValueTokenRoute::UnicodeWordRun {
            identity,
            maximum_input_bytes,
        } = token.route
            && haystack.len() <= maximum_input_bytes
            && let PortableSearchSessionPlan::Native(regex) = &self.plan
        {
            match &regex.plan {
                PortablePlan::UnicodeWordRun(plan)
                    if plan.aggregate_count_identity() == identity =>
                {
                    return Ok(plan.is_match_full_prepared(haystack));
                }
                _ => {}
            }
        }
        self.is_match_value(haystack, token.limits)
    }

    /// Whether a match exists through an already authenticated generic K0
    /// repeated-call handle.
    ///
    /// Every admitted call executes the same complete report-free warm K0
    /// search as [`Self::is_match_value_prepared`] under the handle's original
    /// finite limits, including the live retained-scratch floor and any
    /// adaptive first-hole growth. A source longer than the handle's immutable
    /// envelope replays [`Self::is_match_value`] under those limits.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same finite resource contract as the
    /// token from which `bound` was derived.
    #[inline]
    pub fn is_match_value_bound_k0_warm(
        &mut self,
        haystack: &[u8],
        bound: PortableBoundK0WarmIsMatchValueToken,
    ) -> Result<bool, SearchError> {
        if haystack.len() <= bound.maximum_input_bytes
            && let PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                ..
            } = &mut self.plan
            && k0_plan.automaton.identity() == bound.automaton_identity
            && let Some(matched) = try_k0_warm_exists_value_with_aggregate_limits(
                session,
                *aggregate_setup,
                haystack,
                bound.limits,
            )?
        {
            return Ok(matched);
        }
        self.is_match_value(haystack, bound.limits)
    }

    /// Whether a selected match exists at or after `start`, reusing K0 state.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::is_match_at`].
    pub fn is_match_at(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        self.is_match_window(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Whether a selected match exists at or after `start` without
    /// constructing facade diagnostic accounting, reusing K0 state when
    /// applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::is_match_value_at`].
    pub fn is_match_value_at(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        self.is_match_window_value(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Whether a selected match exists wholly inside a range, reusing K0
    /// state and retaining original-haystack assertion context.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::is_match_window`].
    pub fn is_match_window(
        &mut self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(bool, SearchAccounting), SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )?;
                Ok((
                    matched.is_some(),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => {
                let (matched, accounting) = plan.is_match_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((
                    matched,
                    SearchAccounting::FixedPredicateWord64(accounting),
                ))
            }
            PortableSearchSessionPlan::Native(regex) => {
                regex.is_match_window(haystack, window, limits)
            }
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                ..
            } => {
                validate_k0_facade_window(haystack.len(), window)?;
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let report = session
                    .search_window::<Exists>(haystack, window, invocation.primary_limits())
                    .map_err(|error| invocation.map_k0_error(error))?;
                let accounting = invocation.accounting(report.accounting())?;
                Ok((report.into_output(), SearchAccounting::K0(accounting)))
            }
        }
    }

    /// Whether a selected match exists wholly inside a range without
    /// constructing facade diagnostic accounting, reusing K0 state when
    /// applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::is_match_window_value`].
    pub fn is_match_window_value(
        &mut self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<bool, SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => plan
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )
                .map(|(matched, _)| matched.is_some())
                .map_err(SearchError::from),
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => plan
                .is_match_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map_err(SearchError::from),
            PortableSearchSessionPlan::Native(regex) => {
                regex.is_match_window_value(haystack, window, limits)
            }
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                reverse_inner,
                mandatory_suffix,
                mandatory_cut,
                negative_prefilter,
                exclusive_route_state,
                mandatory_suffix_exists_state,
                negative_prefilter_exists_state,
                ..
            } => {
                validate_k0_facade_window(haystack.len(), window)?;
                let absolute_end_proof = k0_plan.absolute_end_proof;
                if k0_finite_minimum_window_is_proven_empty(
                    *mandatory_suffix,
                    haystack.len(),
                    window,
                ) || k0_absolute_end_window_is_proven_empty(
                    absolute_end_proof,
                    haystack.len(),
                    window,
                ) {
                    return Ok(false);
                }
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let limits = invocation.primary_limits();
                let result = (|| {
                    let correlated_terminal = k0_plan.correlated_terminal();
                if let Some(suffix) = (*mandatory_suffix)
                    .filter(|suffix| suffix.universal_finite_match_byte_bounds().is_some())
                {
                    // This immutable language proof owns the call before any
                    // correlated/finite route adaptation, independent
                    // negative prefilter, or reverse-K0 capability check.
                    // Exists is exactly one forward literal search.
                    let mut suffix_state_after_success = *mandatory_suffix_exists_state;
                    let suffix_attempt = try_k0_mandatory_suffix_exists(
                        session,
                        suffix,
                        suffix_state_after_success,
                        haystack,
                        window,
                        limits,
                        None,
                    )?;
                    suffix_state_after_success = suffix_attempt.state_after_success;
                    if suffix_attempt.outcome != K0MandatorySuffixOutcome::GeometryBypass {
                        let result = match suffix_attempt.outcome {
                            K0MandatorySuffixOutcome::Found(found) => Ok(found),
                            K0MandatorySuffixOutcome::Fallback
                            | K0MandatorySuffixOutcome::Bypass
                            | K0MandatorySuffixOutcome::GeometryBypass
                            | K0MandatorySuffixOutcome::Incumbent { .. } => session
                                .search_exists_value(haystack, window, limits)
                                .map_err(SearchError::from),
                        };
                        if result.is_ok() {
                            *mandatory_suffix_exists_state = suffix_state_after_success;
                        }
                        return result;
                    }
                }
                if let Some(receipt) = K0PackedFrontierExistsReceipt::admit(
                    k0_plan,
                    session,
                    haystack,
                    window,
                    limits,
                )? {
                    // Admission transfers complete ownership to exactly one
                    // packed or incumbent executor. The incumbent callback is
                    // the same tail used below when packed admission declines;
                    // staged policy state is published only after it succeeds.
                    debug_assert!(correlated_terminal.is_none());
                    let packed_frontier_exists_state = exclusive_route_state
                        .packed_mut()
                        .ok_or(SearchError::K0(K0SearchError::InternalInvariant {
                            detail: "packed K0 plan lost its exclusive Exists state",
                        }))?;
                    return execute_k0_packed_frontier_exists_route(
                        receipt,
                        packed_frontier_exists_state,
                        |session, haystack, window, limits, measured_work| {
                            execute_k0_exists_incumbent(
                                session,
                                reverse_inner,
                                *mandatory_suffix,
                                *mandatory_cut,
                                *negative_prefilter,
                                mandatory_suffix_exists_state,
                                negative_prefilter_exists_state,
                                absolute_end_proof,
                                haystack,
                                window,
                                limits,
                                measured_work,
                            )
                        },
                    );
                }
                if let Some(plan) = correlated_terminal {
                    let correlated_terminal_exists_state = &mut exclusive_route_state
                        .correlated_mut()
                        .ok_or(SearchError::K0(K0SearchError::InternalInvariant {
                            detail: "correlated K0 plan lost its exclusive Exists state",
                        }))?
                        .exists;
                    if k0_correlated_exact_delimited_allows(
                        plan,
                        haystack.len(),
                        window,
                        limits,
                    ) {
                        match plan.probe_exact_delimited(
                            haystack,
                            window.start(),
                            window.end(),
                        ) {
                            correlated_bounded_alternation::ExactDelimitedProbe::Match {
                                ..
                            } => return Ok(true),
                            correlated_bounded_alternation::ExactDelimitedProbe::Exhausted => {
                                return Ok(false);
                            }
                            correlated_bounded_alternation::ExactDelimitedProbe::Fallback {
                                first_unproved_start,
                            } => {
                                return session
                                    .search_exists_value(
                                        haystack,
                                        SearchWindow::new(
                                            first_unproved_start.min(window.end()),
                                            window.end(),
                                        ),
                                        limits,
                                    )
                                    .map_err(SearchError::from);
                            }
                        }
                    }
                    if k0_correlated_geometry_allows(
                        session,
                        plan,
                        haystack.len(),
                        window,
                        limits,
                    ) {
                        let window_bytes = window.end().saturating_sub(window.start());
                        match correlated_terminal_exists_state.select(window_bytes) {
                            correlated_bounded_alternation::Route::Bypass => {}
                            correlated_bounded_alternation::Route::Learn { class_index } => {
                                let report = session
                                    .search_window::<Exists>(haystack, window, limits)
                                    .map_err(SearchError::from)?;
                                correlated_terminal_exists_state.observe_incumbent(
                                    class_index,
                                    window_bytes,
                                    report.accounting().work(),
                                    report.accounting().boundaries(),
                                    plan.maximum_match_bytes(),
                                    plan.branch_count(),
                                );
                                return Ok(report.into_output());
                            }
                            correlated_bounded_alternation::Route::Terminal {
                                class_index,
                                incumbent_transition_work,
                            } => match try_k0_correlated_terminal_exists(
                                session,
                                plan,
                                haystack,
                                window,
                                limits,
                                incumbent_transition_work,
                            )? {
                                K0CorrelatedTerminalAttempt::Bypass => {}
                                K0CorrelatedTerminalAttempt::Complete { output, won } => {
                                    if won {
                                        correlated_terminal_exists_state
                                            .observe_terminal_success(class_index);
                                    } else {
                                        correlated_terminal_exists_state
                                            .observe_terminal_loss(class_index);
                                    }
                                    return Ok(output);
                                }
                            },
                        }
                    }
                }
                    execute_k0_exists_incumbent(
                        session,
                        reverse_inner,
                        *mandatory_suffix,
                        *mandatory_cut,
                        *negative_prefilter,
                        mandatory_suffix_exists_state,
                        negative_prefilter_exists_state,
                        absolute_end_proof,
                        haystack,
                        window,
                        limits,
                        None,
                    )
                })();
                result.map_err(|error| invocation.map_error(error))
            }
        }
    }

    /// Return the first detected match end, reusing K0 state when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::shortest_match`].
    pub fn shortest_match(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        self.shortest_match_window(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return the first detected match end at or after `start`, reusing K0
    /// state.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::shortest_match_at`].
    pub fn shortest_match_at(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        self.shortest_match_window(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Return only the first detected match end, reusing operation-local K0
    /// state when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as [`Self::shortest_match`].
    pub fn shortest_match_value(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        self.shortest_match_window_value(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return only the first detected match end at or after `start`.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as [`Self::shortest_match_at`].
    pub fn shortest_match_at_value(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        self.shortest_match_window_value(
            haystack,
            SearchWindow::new(start, haystack.len()),
            limits,
        )
    }

    /// Return only the first detected match end wholly inside `window`.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as the accountingful
    /// shortest-match operation.
    pub fn shortest_match_window_value(
        &mut self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => plan
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(_, end)| end))
                .map_err(SearchError::from),
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => plan
                .earliest_end_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map(|(end, _)| end)
                .map_err(SearchError::from),
            PortableSearchSessionPlan::Native(regex) => {
                regex.shortest_match_window_value(haystack, window, limits)
            }
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                mandatory_suffix,
                exclusive_route_state,
                ..
            } => {
                validate_k0_facade_window(haystack.len(), window)?;
                let absolute_end_proof = k0_plan.absolute_end_proof;
                if k0_finite_minimum_window_is_proven_empty(
                    *mandatory_suffix,
                    haystack.len(),
                    window,
                ) || k0_absolute_end_window_is_proven_empty(
                    absolute_end_proof,
                    haystack.len(),
                    window,
                ) {
                    return Ok(None);
                }
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let limits = invocation.primary_limits();
                let result = (|| {
                    let correlated_terminal = k0_plan.correlated_terminal();
                if let Some(plan) = correlated_terminal {
                    if k0_correlated_exact_delimited_allows(
                        plan,
                        haystack.len(),
                        window,
                        limits,
                    ) {
                        match plan.probe_exact_delimited(
                            haystack,
                            window.start(),
                            window.end(),
                        ) {
                            correlated_bounded_alternation::ExactDelimitedProbe::Match {
                                end,
                                ..
                            } => return Ok(Some(end)),
                            correlated_bounded_alternation::ExactDelimitedProbe::Exhausted => {
                                return Ok(None);
                            }
                            correlated_bounded_alternation::ExactDelimitedProbe::Fallback {
                                first_unproved_start,
                            } => {
                                return session
                                    .search_earliest_end_value(
                                        haystack,
                                        SearchWindow::new(
                                            first_unproved_start.min(window.end()),
                                            window.end(),
                                        ),
                                        limits,
                                    )
                                    .map_err(SearchError::from);
                            }
                        }
                    }
                    let correlated_terminal_earliest_end_state = &mut exclusive_route_state
                        .correlated_mut()
                        .ok_or(SearchError::K0(K0SearchError::InternalInvariant {
                            detail: "correlated K0 plan lost its exclusive earliest-end state",
                        }))?
                        .earliest_end;
                    if k0_correlated_geometry_allows(
                        session,
                        plan,
                        haystack.len(),
                        window,
                        limits,
                    ) {
                        let window_bytes = window.end().saturating_sub(window.start());
                        let mut next_state = *correlated_terminal_earliest_end_state;
                        match next_state.select(window_bytes) {
                            correlated_bounded_alternation::Route::Bypass => {
                                let output = session
                                    .search_earliest_end_value(haystack, window, limits)
                                    .map_err(SearchError::from)?;
                                *correlated_terminal_earliest_end_state = next_state;
                                return Ok(output);
                            }
                            correlated_bounded_alternation::Route::Learn { class_index } => {
                                let report = session
                                    .search_window::<EarliestEnd>(haystack, window, limits)
                                    .map_err(SearchError::from)?;
                                next_state.observe_incumbent(
                                    class_index,
                                    window_bytes,
                                    report.accounting().work(),
                                    report.accounting().boundaries(),
                                    plan.maximum_match_bytes(),
                                    plan.branch_count(),
                                );
                                *correlated_terminal_earliest_end_state = next_state;
                                return Ok(report.into_output());
                            }
                            correlated_bounded_alternation::Route::Terminal {
                                class_index,
                                incumbent_transition_work,
                            } => match try_k0_correlated_terminal_earliest_end(
                                session,
                                plan,
                                haystack,
                                window,
                                limits,
                                incumbent_transition_work,
                            )? {
                                K0CorrelatedTerminalAttempt::Bypass => {
                                    let output = session
                                        .search_earliest_end_value(haystack, window, limits)
                                        .map_err(SearchError::from)?;
                                    *correlated_terminal_earliest_end_state = next_state;
                                    return Ok(output);
                                }
                                K0CorrelatedTerminalAttempt::Complete { output, won } => {
                                    if won {
                                        next_state.observe_terminal_success(class_index);
                                    } else {
                                        next_state.observe_terminal_loss(class_index);
                                    }
                                    *correlated_terminal_earliest_end_state = next_state;
                                    return Ok(output);
                                }
                            },
                        }
                    }
                }
                if let Some(matched) = try_k0_absolute_end_exists(
                    session,
                    absolute_end_proof,
                    haystack,
                    window,
                    limits,
                )? {
                    return Ok(matched.then_some(window.end()));
                }
                    session
                        .search_earliest_end_value(haystack, window, limits)
                        .map_err(SearchError::from)
                })();
                result.map_err(|error| invocation.map_error(error))
            }
        }
    }

    fn shortest_match_window(
        &mut self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => {
                let (end, accounting) = plan.earliest_end_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((end, SearchAccounting::FixedPredicateWord64(accounting)))
            }
            PortableSearchSessionPlan::Native(regex) => {
                regex.shortest_match_window(haystack, window, limits)
            }
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                ..
            } => {
                validate_k0_facade_window(haystack.len(), window)?;
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let report = session
                    .search_window::<EarliestEnd>(haystack, window, invocation.primary_limits())
                    .map_err(|error| invocation.map_k0_error(error))?;
                let accounting = invocation.accounting(report.accounting())?;
                Ok((report.into_output(), SearchAccounting::K0(accounting)))
            }
        }
    }

    /// Return the selected match end, reusing K0 state when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::selected_end`].
    pub fn selected_end(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<usize>, SearchAccounting), SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => {
                let (matched, accounting) = plan.find(haystack, literal_limits(limits))?;
                Ok((
                    matched.map(|(_, end)| end),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => {
                let (end, accounting) =
                    plan.selected_end(haystack, fixed_predicate_word64_search_limits(limits))?;
                Ok((end, SearchAccounting::FixedPredicateWord64(accounting)))
            }
            PortableSearchSessionPlan::Native(regex) => regex.selected_end(haystack, limits),
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                ..
            } => {
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let report = session
                    .search::<SelectedEnd>(haystack, invocation.primary_limits())
                    .map_err(|error| invocation.map_k0_error(error))?;
                let accounting = invocation.accounting(report.accounting())?;
                Ok((report.into_output(), SearchAccounting::K0(accounting)))
            }
        }
    }

    /// Return only the selected match end, reusing the selected-span K0 route
    /// and its operation-local state when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same contract as [`Self::selected_end`].
    pub fn selected_end_value(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<usize>, SearchError> {
        self.find_value(haystack, limits)
            .map(|matched| matched.map(Match::end))
    }

    /// Return the profile-selected leftmost-first match.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::find_accounted`].
    pub fn find(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<(Option<Match>, SearchAccounting), SearchError> {
        self.find_window(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return only the profile-selected leftmost-first match, reusing K0 state
    /// when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::find_value`].
    pub fn find_value(
        &mut self,
        haystack: &[u8],
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        self.find_window_value(haystack, SearchWindow::full(haystack), limits)
    }

    /// Return the selected match while retaining the complete original
    /// haystack and reusing K0 state.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`Self::find`].
    pub fn find_borrowed<'h>(
        &mut self,
        haystack: &'h [u8],
        limits: SearchLimits,
    ) -> Result<(Option<ByteMatch<'h>>, SearchAccounting), SearchError> {
        let (matched, accounting) = self.find(haystack, limits)?;
        Ok((matched.map(|span| ByteMatch { haystack, span }), accounting))
    }

    /// Return only the selected match while retaining the complete original
    /// haystack and reusing K0 state.
    ///
    /// This is the value-only companion to [`Self::find_borrowed`]. It uses
    /// the exact selected-span route of [`Self::find_value`] without
    /// constructing facade diagnostic accounting.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`Self::find_value`].
    pub fn find_borrowed_value<'h>(
        &mut self,
        haystack: &'h [u8],
        limits: SearchLimits,
    ) -> Result<Option<ByteMatch<'h>>, SearchError> {
        self.find_value(haystack, limits)
            .map(|matched| matched.map(|span| ByteMatch { haystack, span }))
    }

    /// Return the selected match at or after `start`, reusing K0 state.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::find_at`].
    pub fn find_at(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, SearchAccounting), SearchError> {
        self.find_window(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Return only the selected match at or after `start`, reusing K0 state
    /// when applicable.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::find_at_value`].
    pub fn find_at_value(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        self.find_window_value(haystack, SearchWindow::new(start, haystack.len()), limits)
    }

    /// Return the selected match at or after `start` while retaining the
    /// complete original haystack and reusing K0 state.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`Self::find_at`].
    pub fn find_at_borrowed<'h>(
        &mut self,
        haystack: &'h [u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<ByteMatch<'h>>, SearchAccounting), SearchError> {
        let (matched, accounting) = self.find_at(haystack, start, limits)?;
        Ok((matched.map(|span| ByteMatch { haystack, span }), accounting))
    }

    /// Return only the selected match at or after `start` while retaining the
    /// complete original haystack and reusing K0 state.
    ///
    /// This is the ranged value-only companion to
    /// [`Self::find_at_borrowed`]. It preserves the exact range validation,
    /// original-haystack assertion context and selected-span route of
    /// [`Self::find_at_value`] without constructing facade diagnostic
    /// accounting.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`Self::find_at_value`].
    pub fn find_at_borrowed_value<'h>(
        &mut self,
        haystack: &'h [u8],
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<ByteMatch<'h>>, SearchError> {
        self.find_at_value(haystack, start, limits)
            .map(|matched| matched.map(|span| ByteMatch { haystack, span }))
    }

    /// Search a range while assertions retain original-haystack context.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same per-invocation limits as
    /// [`PortableRegex::find_window`].
    pub fn find_window(
        &mut self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, SearchAccounting), SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::ExactLiteral(accounting),
                ))
            }
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => {
                let (matched, accounting) = plan.find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    SearchAccounting::FixedPredicateWord64(accounting),
                ))
            }
            PortableSearchSessionPlan::Native(regex) => regex.find_window(haystack, window, limits),
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                ..
            } => {
                validate_k0_facade_window(haystack.len(), window)?;
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let report = if window.end() == haystack.len() {
                    session
                        .search_span_at_cursor(
                            haystack,
                            window.start(),
                            invocation.primary_limits(),
                        )
                        .map_err(|error| invocation.map_k0_error(error))?
                } else {
                    session
                        .search_window::<Span>(haystack, window, invocation.primary_limits())
                        .map_err(|error| invocation.map_k0_error(error))?
                };
                let accounting = invocation.accounting(report.accounting())?;
                let matched = report.into_output().map(|span| Match {
                    start: span.start(),
                    end: span.end(),
                });
                Ok((matched, SearchAccounting::K0(accounting)))
            }
        }
    }

    /// Return only the selected match wholly inside a search range, reusing K0
    /// state and retaining original-haystack assertion context.
    ///
    /// # Errors
    ///
    /// Returns [`SearchError`] under the same range and resource contract as
    /// [`PortableRegex::find_window_value`].
    pub fn find_window_value(
        &mut self,
        haystack: &[u8],
        window: SearchWindow,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => plan
                .find_window(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    literal_limits(limits),
                )
                .map(|(matched, _)| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => plan
                .find_window_value(
                    haystack,
                    LiteralWindow::new(window.start(), window.end()),
                    fixed_predicate_word64_search_limits(limits),
                )
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            PortableSearchSessionPlan::Native(regex) => {
                regex.find_window_value(haystack, window, limits)
            }
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                mandatory_suffix,
                mandatory_cut,
                negative_prefilter,
                exclusive_route_state,
                mandatory_suffix_span_state,
                negative_prefilter_span_state,
                ..
            } => {
                validate_k0_facade_window(haystack.len(), window)?;
                let absolute_end_proof = k0_plan.absolute_end_proof;
                if k0_finite_minimum_window_is_proven_empty(
                    *mandatory_suffix,
                    haystack.len(),
                    window,
                ) || k0_absolute_end_window_is_proven_empty(
                    absolute_end_proof,
                    haystack.len(),
                    window,
                ) {
                    return Ok(None);
                }
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let limits = invocation.primary_limits();
                let result = (|| {
                    let correlated_terminal = k0_plan.correlated_terminal();
                if let Some(suffix) = (*mandatory_suffix)
                    .filter(|suffix| suffix.universal_finite_match_byte_bounds().is_some())
                {
                    // The universal corridor owns the call before any
                    // correlated/finite route adaptation. A late first suffix
                    // proves the span directly; only the near-floor case
                    // enters selected-end replay. After a complete negative
                    // suffix proof, one independent mandatory-predicate pass
                    // calibrates whether the lower-dispatch prefilter should
                    // own stable negative traffic.
                    let mut suffix_state_after_success = *mandatory_suffix_span_state;
                    let mut suffix_attempt = try_k0_mandatory_suffix_span_start(
                        session,
                        suffix,
                        suffix_state_after_success,
                        haystack,
                        window,
                        limits,
                        None,
                    )?;
                    suffix_state_after_success = suffix_attempt.state_after_success;
                    if let K0MandatorySuffixSpanOutcome::UniversalIncumbent {
                        class_index,
                        calibration,
                    } = suffix_attempt.outcome
                    {
                        let incumbent_route = if calibration {
                            K0UniversalFiniteSuffixIncumbentRoute::Calibration { class_index }
                        } else {
                            K0UniversalFiniteSuffixIncumbentRoute::Retained { class_index }
                        };
                        let mut matched = Match { start: 0, end: 0 };
                        match try_k0_universal_finite_suffix_incumbent(
                            session,
                            suffix,
                            *mandatory_cut,
                            *negative_prefilter,
                            mandatory_suffix_span_state,
                            suffix_state_after_success,
                            negative_prefilter_span_state,
                            incumbent_route,
                            haystack,
                            window,
                            limits,
                            &mut matched,
                        )? {
                            K0UniversalFiniteSuffixIncumbentOutcome::GeometryBypass => {
                                // The old caller-side selector declined into
                                // this same authoritative whole-window route.
                                suffix_attempt.outcome = K0MandatorySuffixSpanOutcome::Fallback;
                            }
                            K0UniversalFiniteSuffixIncumbentOutcome::ProvedAbsent => {
                                return Ok(None);
                            }
                            K0UniversalFiniteSuffixIncumbentOutcome::ProvedMatch => {
                                return Ok(Some(matched));
                            }
                        }
                    }
                    if suffix_attempt.outcome
                        != K0MandatorySuffixSpanOutcome::GeometryBypass
                    {
                        let result = match suffix_attempt.outcome {
                            K0MandatorySuffixSpanOutcome::ProvedAbsent => {
                                if k0_negative_prefilter_admitted(
                                    *mandatory_cut,
                                    *negative_prefilter,
                                    haystack.len(),
                                    window,
                                    limits,
                                ) && window.end().checked_sub(window.start()).is_some_and(
                                    |window_bytes| {
                                        session.negative_terminal_has_reused_work_certificate(
                                            window_bytes,
                                        )
                                    },
                                ) {
                                    schedule_k0_universal_finite_suffix_incumbent_calibration(
                                        &mut suffix_state_after_success,
                                        window,
                                    );
                                }
                                Ok(None)
                            }
                            K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => {
                                Ok(Some(Match { start, end }))
                            }
                            K0MandatorySuffixSpanOutcome::ProvedStart {
                                start,
                                maximum_match_bytes,
                            } => match replay_k0_finite_proved_start_with_exact_receipt(
                                session,
                                haystack,
                                window,
                                limits,
                                start,
                                maximum_match_bytes,
                            ) {
                                Ok((output, exact_receipt)) => {
                                    if !exact_receipt {
                                        observe_k0_finite_suffix_span_replay_fallback(
                                            &mut suffix_state_after_success,
                                            window,
                                        );
                                    }
                                    Ok(output)
                                }
                                Err(error) => Err(error),
                            },
                            K0MandatorySuffixSpanOutcome::Fallback => session
                                .search_span_value(haystack, window, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from),
                            K0MandatorySuffixSpanOutcome::Bypass
                            | K0MandatorySuffixSpanOutcome::GeometryBypass
                            | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. }
                            | K0MandatorySuffixSpanOutcome::Absent
                            | K0MandatorySuffixSpanOutcome::Narrowed(_)
                            | K0MandatorySuffixSpanOutcome::Incumbent { .. } => session
                                .search_span_value(haystack, window, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from),
                        };
                        if result.is_ok() {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                        }
                        return result;
                    }
                }
                if let Some(plan) = correlated_terminal {
                    let correlated_terminal_span_state = &mut exclusive_route_state
                        .correlated_mut()
                        .ok_or(SearchError::K0(K0SearchError::InternalInvariant {
                            detail: "correlated K0 plan lost its exclusive span state",
                        }))?
                        .span;
                    if k0_correlated_exact_delimited_allows(
                        plan,
                        haystack.len(),
                        window,
                        limits,
                    ) {
                        match plan.probe_exact_delimited(
                            haystack,
                            window.start(),
                            window.end(),
                        ) {
                            correlated_bounded_alternation::ExactDelimitedProbe::Match {
                                start,
                                end,
                            } => return Ok(Some(Match { start, end })),
                            correlated_bounded_alternation::ExactDelimitedProbe::Exhausted => {
                                return Ok(None);
                            }
                            correlated_bounded_alternation::ExactDelimitedProbe::Fallback {
                                first_unproved_start,
                            } => {
                                let fallback = SearchWindow::new(
                                    first_unproved_start.min(window.end()),
                                    window.end(),
                                );
                                let report = if fallback.end() == haystack.len() {
                                    session.search_span_at_cursor(
                                        haystack,
                                        fallback.start(),
                                        limits,
                                    )
                                } else {
                                    session.search_window::<Span>(haystack, fallback, limits)
                                }
                                .map_err(SearchError::from)?;
                                return Ok(report.into_output().map(|span| Match {
                                    start: span.start(),
                                    end: span.end(),
                                }));
                            }
                        }
                    }
                    if k0_correlated_geometry_allows(
                        session,
                        plan,
                        haystack.len(),
                        window,
                        limits,
                    ) {
                        let window_bytes = window.end().saturating_sub(window.start());
                        match correlated_terminal_span_state.select(window_bytes) {
                            correlated_bounded_alternation::Route::Bypass => {}
                            correlated_bounded_alternation::Route::Learn { class_index } => {
                                let report = if window.end() == haystack.len() {
                                    session.search_span_at_cursor(
                                        haystack,
                                        window.start(),
                                        limits,
                                    )
                                } else {
                                    session.search_window::<Span>(haystack, window, limits)
                                }
                                .map_err(SearchError::from)?;
                                correlated_terminal_span_state.observe_incumbent(
                                    class_index,
                                    window_bytes,
                                    report.accounting().work(),
                                    report.accounting().boundaries(),
                                    plan.maximum_match_bytes(),
                                    plan.branch_count(),
                                );
                                return Ok(report.into_output().map(|span| Match {
                                    start: span.start(),
                                    end: span.end(),
                                }));
                            }
                            correlated_bounded_alternation::Route::Terminal {
                                class_index,
                                incumbent_transition_work,
                            } => match try_k0_correlated_terminal_span(
                                session,
                                plan,
                                haystack,
                                window,
                                limits,
                                incumbent_transition_work,
                            )? {
                                K0CorrelatedTerminalAttempt::Bypass => {}
                                K0CorrelatedTerminalAttempt::Complete { output, won } => {
                                    if won {
                                        correlated_terminal_span_state
                                            .observe_terminal_success(class_index);
                                    } else {
                                        correlated_terminal_span_state
                                            .observe_terminal_loss(class_index);
                                    }
                                    return Ok(output);
                                }
                            },
                        }
                    }
                }
                let mut suffix_state_after_success = *mandatory_suffix_span_state;
                let mut finite_suffix_incumbent = None;
                // A long finite suffix whose consumption-run proof declined is
                // a Span-only recovery sidecar. Keep the incumbent negative
                // prefilter first for that class: an absent mandatory literal
                // is already a complete answer, so touching the reverse-route
                // state before that proof only adds dispatch to the cheapest
                // negative path. Positive and inconclusive calls defer the
                // same bounded reverse recovery until after the incumbent has
                // published its candidate floor.
                let deferred_finite_span_only = (*mandatory_suffix).filter(|suffix| {
                    suffix.finite_span_only_maximum_match_bytes().is_some()
                });
                let incumbent_suffix = if deferred_finite_span_only.is_some() {
                    None
                } else {
                    *mandatory_suffix
                };
                if let Some(suffix) = incumbent_suffix {
                    if let Some(maximum_match_bytes) = suffix.finite_maximum_match_bytes() {
                        if window.end().checked_sub(window.start()).is_some_and(|bytes| {
                            bytes < K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
                        }) {
                            return session
                                .search_span_value(haystack, window, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from);
                        }
                        if let Some(direct_route) = select_k0_finite_suffix_direct_route(
                            session,
                            &mut suffix_state_after_success,
                            maximum_match_bytes,
                            haystack.len(),
                            window,
                            limits,
                            true,
                        ) {
                            let result = match direct_route {
                                K0FiniteSuffixDirectRoute::FreshClass { class_index } => {
                                    let report = if window.end() == haystack.len() {
                                        session.search_span_at_cursor(
                                            haystack,
                                            window.start(),
                                            limits,
                                        )
                                    } else {
                                        session.search_window::<Span>(haystack, window, limits)
                                    };
                                    match report {
                                        Ok(report) => {
                                            let single_pass_negative = report.output().is_none()
                                                && report.accounting().boundaries() == 0
                                                && session
                                                    .negative_terminal_has_small_start_scanner();
                                            observe_k0_finite_suffix_direct_incumbent(
                                                &mut suffix_state_after_success.classes
                                                    [class_index],
                                                single_pass_negative,
                                            );
                                            Ok(report.into_output().map(|span| Match {
                                                start: span.start(),
                                                end: span.end(),
                                            }))
                                        }
                                        Err(error) => Err(SearchError::from(error)),
                                    }
                                }
                                K0FiniteSuffixDirectRoute::ExactLossBackoff => session
                                    .search_span_value(haystack, window, limits)
                                    .map(|found| {
                                        found.map(|span| Match {
                                            start: span.start(),
                                            end: span.end(),
                                        })
                                    })
                                    .map_err(SearchError::from),
                            };
                            if result.is_ok() {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                            }
                            return result;
                        }
                    }
                    let suffix_attempt = try_k0_mandatory_suffix_span_start(
                        session,
                        suffix,
                        suffix_state_after_success,
                        haystack,
                        window,
                        limits,
                        None,
                    )?;
                    suffix_state_after_success = suffix_attempt.state_after_success;
                    let run_k0_directly = match suffix_attempt.outcome {
                        K0MandatorySuffixSpanOutcome::Incumbent {
                            class_index,
                            may_switch_to_suffix,
                        } => {
                            finite_suffix_incumbent =
                                Some((class_index, may_switch_to_suffix));
                            false
                        }
                        K0MandatorySuffixSpanOutcome::ProvedAbsent => {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            return Ok(None);
                        }
                        K0MandatorySuffixSpanOutcome::Absent => {
                            let certified = window
                                .end()
                                .checked_sub(window.start())
                                .is_some_and(|input_bytes| {
                                    session
                                        .negative_terminal_has_reused_work_certificate(input_bytes)
                                });
                            if certified {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                                return Ok(None);
                            }
                            true
                        }
                        K0MandatorySuffixSpanOutcome::Narrowed(start) => {
                            let narrowed = SearchWindow::new(start, window.end());
                            let result = session
                                .search_span_value(haystack, narrowed, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from);
                            if result.is_ok() {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                            }
                            return result;
                        }
                        K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            return Ok(Some(Match { start, end }));
                        }
                        K0MandatorySuffixSpanOutcome::ProvedStart {
                            start,
                            maximum_match_bytes,
                        } => {
                            match replay_k0_finite_proved_start_with_exact_receipt(
                                session,
                                haystack,
                                window,
                                limits,
                                start,
                                maximum_match_bytes,
                            ) {
                                Ok((output, exact_receipt)) => {
                                    if !exact_receipt {
                                        observe_k0_finite_suffix_span_replay_fallback(
                                            &mut suffix_state_after_success,
                                            window,
                                        );
                                    }
                                    *mandatory_suffix_span_state = suffix_state_after_success;
                                    return Ok(output);
                                }
                                Err(error) => return Err(error),
                            }
                        }
                        K0MandatorySuffixSpanOutcome::Fallback
                        | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. } => true,
                        K0MandatorySuffixSpanOutcome::Bypass
                        | K0MandatorySuffixSpanOutcome::GeometryBypass => false,
                    };
                    if run_k0_directly {
                        // A completed or failed suffix attempt may already
                        // have scanned the source. Do not phase-lock a second
                        // sidecar predicate behind it.
                        let result = session
                            .search_span_value(haystack, window, limits)
                            .map(|found| {
                                found.map(|span| Match {
                                    start: span.start(),
                                    end: span.end(),
                                })
                            })
                            .map_err(SearchError::from);
                        if result.is_ok() {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                        }
                        return result;
                    }
                }
                if let Some(suffix) = deferred_finite_span_only {
                    if k0_finite_suffix_exact_loss_backoff_pending(
                        &suffix_state_after_success,
                        window,
                    ) {
                        let maximum_match_bytes = suffix
                            .finite_span_only_maximum_match_bytes()
                            .expect("deferred finite Span suffix retains its maximum width");
                        if matches!(
                            select_k0_finite_suffix_direct_route(
                                session,
                                &mut suffix_state_after_success,
                                maximum_match_bytes,
                                haystack.len(),
                                window,
                                limits,
                                true,
                            ),
                            Some(K0FiniteSuffixDirectRoute::ExactLossBackoff)
                        ) {
                            let result = session
                                .search_span_value(haystack, window, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from);
                            if result.is_ok() {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                            }
                            return result;
                        }
                    }
                }
                let attempt = run_k0_negative_prefilter(
                    *mandatory_cut,
                    *negative_prefilter,
                    *negative_prefilter_span_state,
                    haystack,
                    window,
                    limits,
                );
                if let Some(suffix) = deferred_finite_span_only {
                    if attempt.outcome == K0NegativePrefilterOutcome::Absent {
                        let certified = window
                            .end()
                            .checked_sub(window.start())
                            .is_some_and(|input_bytes| {
                                session
                                    .negative_terminal_has_reused_work_certificate(input_bytes)
                            });
                        if certified {
                            // The incumbent predicate already proved the
                            // mandatory language absent. Publish only its own
                            // staged state: the deferred reverse route was not
                            // consulted and must retain no synthetic history.
                            *negative_prefilter_span_state = attempt.state_after_success;
                            return Ok(None);
                        }
                    }

                    let maximum_match_bytes = suffix
                        .finite_span_only_maximum_match_bytes()
                        .expect("deferred finite Span suffix retains its maximum width");
                    if let Some(direct_route) = select_k0_finite_suffix_direct_route(
                        session,
                        &mut suffix_state_after_success,
                        maximum_match_bytes,
                        haystack.len(),
                        window,
                        limits,
                        true,
                    ) {
                        let result = match direct_route {
                            K0FiniteSuffixDirectRoute::FreshClass { class_index } => {
                                let report = if window.end() == haystack.len() {
                                    session.search_span_at_cursor(
                                        haystack,
                                        window.start(),
                                        limits,
                                    )
                                } else {
                                    session.search_window::<Span>(haystack, window, limits)
                                };
                                match report {
                                    Ok(report) => {
                                        let single_pass_negative = report.output().is_none()
                                            && report.accounting().boundaries() == 0
                                            && session
                                                .negative_terminal_has_small_start_scanner();
                                        observe_k0_finite_suffix_direct_incumbent(
                                            &mut suffix_state_after_success.classes[class_index],
                                            single_pass_negative,
                                        );
                                        Ok(report.into_output().map(|span| Match {
                                            start: span.start(),
                                            end: span.end(),
                                        }))
                                    }
                                    Err(error) => Err(SearchError::from(error)),
                                }
                            }
                            K0FiniteSuffixDirectRoute::ExactLossBackoff => session
                                .search_span_value(haystack, window, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from),
                        };
                        if result.is_ok() {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            *negative_prefilter_span_state = attempt.state_after_success;
                        }
                        return result;
                    }

                    let suffix_attempt = try_k0_mandatory_suffix_span_start(
                        session,
                        suffix,
                        suffix_state_after_success,
                        haystack,
                        window,
                        limits,
                        attempt.candidate_floor,
                    )?;
                    suffix_state_after_success = suffix_attempt.state_after_success;
                    match suffix_attempt.outcome {
                        K0MandatorySuffixSpanOutcome::Incumbent {
                            class_index,
                            may_switch_to_suffix,
                        } => {
                            finite_suffix_incumbent =
                                Some((class_index, may_switch_to_suffix));
                        }
                        K0MandatorySuffixSpanOutcome::ProvedAbsent => {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            *negative_prefilter_span_state = attempt.state_after_success;
                            return Ok(None);
                        }
                        K0MandatorySuffixSpanOutcome::Absent => {
                            let certified = window
                                .end()
                                .checked_sub(window.start())
                                .is_some_and(|input_bytes| {
                                    session.negative_terminal_has_reused_work_certificate(
                                        input_bytes,
                                    )
                                });
                            if certified {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                                *negative_prefilter_span_state = attempt.state_after_success;
                                return Ok(None);
                            }
                        }
                        K0MandatorySuffixSpanOutcome::Narrowed(start) => {
                            let narrowed = SearchWindow::new(start, window.end());
                            let result = session
                                .search_span_value(haystack, narrowed, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from);
                            if result.is_ok() {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                                *negative_prefilter_span_state = attempt.state_after_success;
                            }
                            return result;
                        }
                        K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            *negative_prefilter_span_state = attempt.state_after_success;
                            return Ok(Some(Match { start, end }));
                        }
                        K0MandatorySuffixSpanOutcome::ProvedStart {
                            start,
                            maximum_match_bytes,
                        } => {
                            match replay_k0_finite_proved_start_with_exact_receipt(
                                session,
                                haystack,
                                window,
                                limits,
                                start,
                                maximum_match_bytes,
                            ) {
                                Ok((output, exact_receipt)) => {
                                    if !exact_receipt {
                                        observe_k0_finite_suffix_span_replay_fallback(
                                            &mut suffix_state_after_success,
                                            window,
                                        );
                                    }
                                    *mandatory_suffix_span_state = suffix_state_after_success;
                                    *negative_prefilter_span_state = attempt.state_after_success;
                                    return Ok(output);
                                }
                                Err(error) => return Err(error),
                            }
                        }
                        K0MandatorySuffixSpanOutcome::Fallback
                        | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. }
                        | K0MandatorySuffixSpanOutcome::Bypass
                        | K0MandatorySuffixSpanOutcome::GeometryBypass => {}
                    }
                }
                let retry_finite_suffix = finite_suffix_incumbent.is_some_and(
                    |(class_index, may_switch_to_suffix)| {
                        observe_k0_finite_suffix_span_incumbent(
                            &mut suffix_state_after_success,
                            class_index,
                            may_switch_to_suffix,
                            attempt.outcome,
                        )
                    },
                );
                let search_candidate_floor = attempt.candidate_floor;
                if retry_finite_suffix {
                    let suffix = mandatory_suffix
                        .as_ref()
                        .copied()
                        .expect("finite suffix retry requires its retained plan");
                    // The incumbent cut already authenticated this floor for
                    // every possible match start. The finite reverse route
                    // consumes that same residual window and either proves
                    // its earliest start or declines transactionally. A
                    // forward prefix hedge would repeat part of the proof and
                    // can turn floor equality into a redundant whole-window
                    // replay, so Span goes directly to the exact route.
                    let suffix_attempt = try_k0_mandatory_suffix_span_start(
                        session,
                        suffix,
                        suffix_state_after_success,
                        haystack,
                        window,
                        limits,
                        search_candidate_floor,
                    )?;
                    suffix_state_after_success = suffix_attempt.state_after_success;
                    match suffix_attempt.outcome {
                        K0MandatorySuffixSpanOutcome::ProvedAbsent => {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            *negative_prefilter_span_state = attempt.state_after_success;
                            return Ok(None);
                        }
                        K0MandatorySuffixSpanOutcome::Absent => {
                            let certified = window
                                .end()
                                .checked_sub(window.start())
                                .is_some_and(|input_bytes| {
                                    session.negative_terminal_has_reused_work_certificate(
                                        input_bytes,
                                    )
                                });
                            if certified {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                                *negative_prefilter_span_state = attempt.state_after_success;
                                return Ok(None);
                            }
                        }
                        K0MandatorySuffixSpanOutcome::Narrowed(start) => {
                            let narrowed = SearchWindow::new(start, window.end());
                            let result = session
                                .search_span_value(haystack, narrowed, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from);
                            if result.is_ok() {
                                *mandatory_suffix_span_state = suffix_state_after_success;
                                *negative_prefilter_span_state = attempt.state_after_success;
                            }
                            return result;
                        }
                        K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => {
                            *mandatory_suffix_span_state = suffix_state_after_success;
                            *negative_prefilter_span_state = attempt.state_after_success;
                            return Ok(Some(Match { start, end }));
                        }
                        K0MandatorySuffixSpanOutcome::ProvedStart {
                            start,
                            maximum_match_bytes,
                        } => {
                            match replay_k0_finite_proved_start_with_exact_receipt(
                                session,
                                haystack,
                                window,
                                limits,
                                start,
                                maximum_match_bytes,
                            ) {
                                Ok((output, exact_receipt)) => {
                                    if !exact_receipt {
                                        observe_k0_finite_suffix_span_replay_fallback(
                                            &mut suffix_state_after_success,
                                            window,
                                        );
                                    }
                                    *mandatory_suffix_span_state = suffix_state_after_success;
                                    *negative_prefilter_span_state = attempt.state_after_success;
                                    return Ok(output);
                                }
                                Err(error) => return Err(error),
                            }
                        }
                        K0MandatorySuffixSpanOutcome::Fallback
                        | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. } => {}
                        K0MandatorySuffixSpanOutcome::Incumbent { class_index, .. } => {
                            observe_k0_finite_suffix_loss(
                                &mut suffix_state_after_success.classes[class_index],
                            );
                        }
                        K0MandatorySuffixSpanOutcome::Bypass
                        | K0MandatorySuffixSpanOutcome::GeometryBypass => {
                            let (class_index, _) = finite_suffix_incumbent
                                .expect("finite suffix retry retains its class");
                            observe_k0_finite_suffix_loss(
                                &mut suffix_state_after_success.classes[class_index],
                            );
                        }
                    }
                }
                if attempt.outcome == K0NegativePrefilterOutcome::Absent {
                    let certified = window
                        .end()
                        .checked_sub(window.start())
                        .is_some_and(|input_bytes| {
                            session.negative_terminal_has_reused_work_certificate(input_bytes)
                        });
                    if certified {
                        *mandatory_suffix_span_state = suffix_state_after_success;
                        *negative_prefilter_span_state = attempt.state_after_success;
                        return Ok(None);
                    }
                }
                let reverse_incumbent_inspected_source = attempt.outcome
                    != K0NegativePrefilterOutcome::Bypass;
                // A positive retained cut is the ordinary start predicate's
                // authenticated first refusal. Without that witness, trial a
                // second whole-window sidecar only after ordinary K0 has
                // completed its immutable proof. Root-run and direct
                // empty and frequency-preferred compact owners keep first
                // refusal. Wider or less-selective scanners may compete under
                // the bounded reverse-suffix adaptive policy. `None` is
                // deliberately cold: one raw K0 call gets to publish the
                // incumbent before the optional route can compete later.
                let short_reverse_suffix = (*mandatory_suffix)
                    .filter(|suffix| suffix.has_short_standalone_reverse_suffix_span());
                let reverse_incumbent_can_chain = attempt.cut_first_member.is_some()
                    || (!reverse_incumbent_inspected_source
                        && short_reverse_suffix.is_some_and(|suffix| {
                            session.reverse_suffix_has_preferred_start_owner(suffix.needle()[0])
                                == Some(false)
                        }));
                let window_bytes = window.end().saturating_sub(window.start());
                if reverse_incumbent_can_chain
                    && absolute_end_proof.is_none()
                    && limits == SearchLimits::unlimited()
                    && window.start() <= window.end()
                    && window.end() <= haystack.len()
                    && window_bytes >= K0_NEGATIVE_PREFILTER_MIN_WINDOW_BYTES
                    && session.positive_end_verifier_available()
                    && let Some(suffix) = short_reverse_suffix
                    && suffix.reverse_suffix_span_is_eligible(window_bytes)
                {
                    let incumbent_search_start = search_candidate_floor.unwrap_or(window.start());
                    let suffix_search_start = match (*mandatory_cut, attempt.cut_first_member) {
                        (Some(cut), Some(first_member)) => cut
                            .mandatory_suffix_candidate_floor(
                                window.start(),
                                first_member,
                                suffix.needle(),
                            )
                            .ok_or(SearchError::K0(K0SearchError::ArithmeticOverflow {
                                computation: "post-cut explicit reverse-suffix search start",
                            }))?,
                        _ => incumbent_search_start,
                    };
                    match try_execute_k0_reverse_suffix_span_after_incumbent(
                        session,
                        suffix,
                        haystack,
                        window,
                        incumbent_search_start,
                        suffix_search_start,
                        limits,
                    )? {
                        K0ReverseSuffixSpanAttempt::Complete(output) => {
                            *negative_prefilter_span_state = attempt.state_after_success;
                            return Ok(output);
                        }
                        K0ReverseSuffixSpanAttempt::Unattempted => {}
                        K0ReverseSuffixSpanAttempt::Bypass
                        | K0ReverseSuffixSpanAttempt::Declined => {
                            // An admitted reverse attempt may already have
                            // scanned source or verified endpoints. Avoid a
                            // second predicate sidecar; the incumbent-
                            // authenticated residual window remains
                            // authoritative for
                            // ordinary K0.
                            let fallback_window = SearchWindow::new(
                                incumbent_search_start,
                                window.end(),
                            );
                            let result = session
                                .search_span_value(haystack, fallback_window, limits)
                                .map(|found| {
                                    found.map(|span| Match {
                                        start: span.start(),
                                        end: span.end(),
                                    })
                                })
                                .map_err(SearchError::from);
                            if result.is_ok() {
                                *negative_prefilter_span_state = attempt.state_after_success;
                            }
                            return result;
                        }
                    }
                }
                let search_window = search_candidate_floor
                    .map_or(window, |start| SearchWindow::new(start, window.end()));
                let absolute_end_attempt = try_k0_absolute_end_span(
                    session,
                    absolute_end_proof,
                    haystack,
                    search_window,
                    limits,
                )?;
                let result = match absolute_end_attempt {
                    K0AbsoluteEndSpanAttempt::Complete(output) => Ok(output),
                    K0AbsoluteEndSpanAttempt::Declined => session
                        .search_span_value(haystack, search_window, limits)
                        .map(|found| {
                            found.map(|span| Match {
                                start: span.start(),
                                end: span.end(),
                            })
                        })
                        .map_err(SearchError::from),
                };
                if result.is_ok() {
                    *mandatory_suffix_span_state = suffix_state_after_success;
                    *negative_prefilter_span_state = attempt.state_after_success;
                }
                    result
                })();
                result.map_err(|error| invocation.map_error(error))
            }
        }
    }

    /// Iterate over every non-overlapping byte match while reusing this
    /// session's existing workspace.
    ///
    /// Session construction and its one-time accounting happened before this
    /// call. Constructing this iterator allocates nothing, and its
    /// [`PortableFindIterAccounting`] starts at zero for this haystack. A
    /// session created by [`PortableRegex::search_session`] may still grow K0
    /// cache storage during iteration; one created by
    /// [`PortableRegex::fixed_search_session`] does not grow retained cache
    /// capacity.
    /// Dropping the iterator early, or dropping it after a yielded error,
    /// releases the mutable borrow so the session can be used again.
    ///
    /// [`PortableRegex::find_iter`] remains the cold/fresh convenience API:
    /// it constructs and owns a new session for each iterator. This method is
    /// the explicit steady-state API for callers that choose to retain one
    /// session across haystacks.
    #[must_use]
    pub fn find_iter<'s, 'h>(
        &'s mut self,
        haystack: &'h [u8],
        limits: PortableFindIterRunLimits,
    ) -> PortableSessionMatches<'s, 'r, 'h> {
        self.find_iter_with_progress(haystack, limits, EmptyMatchProgress::Byte)
    }

    /// Iterate over every non-overlapping byte match through this session's
    /// value-only selected-span route.
    ///
    /// Empty-match progress and the whole-iterator search-call cap are
    /// identical to [`Self::find_iter`]. The iterator intentionally omits a
    /// unified per-iterator search-accounting aggregate so value-only
    /// accelerators can be used without manufacturing facade receipts. If this
    /// is an adaptive K0 session, contextual searches may grow retained cache
    /// capacity under `limits.search`; that growth is deliberately unavailable
    /// as a unified receipt here. A session created by
    /// [`PortableRegex::fixed_search_session`] does not grow retained capacity.
    #[must_use]
    pub fn find_iter_value<'s, 'h>(
        &'s mut self,
        haystack: &'h [u8],
        limits: PortableFindIterRunLimits,
    ) -> PortableSessionValueMatches<'s, 'r, 'h> {
        self.find_iter_value_at(haystack, 0, limits)
    }

    /// Iterate over every non-overlapping byte match at or after `start`
    /// through this session's value-only selected-span route.
    ///
    /// Assertions retain complete original-haystack context and offsets remain
    /// absolute. An invalid `start` is yielded as an iterator error after the
    /// iterator-level search-call cap admits that search.
    #[must_use]
    pub fn find_iter_value_at<'s, 'h>(
        &'s mut self,
        haystack: &'h [u8],
        start: usize,
        limits: PortableFindIterRunLimits,
    ) -> PortableSessionValueMatches<'s, 'r, 'h> {
        let native_cursor = self.value_native_search_cursor(haystack);
        PortableSessionValueMatches {
            session: self,
            state: PortableValueMatchIterState::new_at(haystack, start, limits, native_cursor),
        }
    }

    /// Visit every complete fixed-predicate match through the retained plan.
    ///
    /// This operation is separate from the general portable visitor so a
    /// facade can select it without enlarging the fallback operation state.
    /// Other retained plan families return `Ok(None)` without invoking the
    /// callback. Resource refusal precedes the first callback.
    #[doc(hidden)]
    pub fn try_visit_fixed_predicate_spans<F>(
        &mut self,
        haystack: &[u8],
        limits: FixedPredicateWord64ReduceLimits,
        mut visitor: F,
    ) -> Result<Option<FixedPredicateWord64SpanVisitResult>, FixedPredicateWord64ReduceError>
    where
        F: FnMut(Match),
    {
        let PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } = &self.plan else {
            return Ok(None);
        };
        plan.visit_spans(haystack, limits, |span| {
            visitor(Match {
                start: span.start,
                end: span.end,
            });
        })
        .map(Some)
    }

    /// Visit every complete non-overlapping match when this session's
    /// construction-selected plan has a direct bounded traversal.
    ///
    /// `Ok(None)` means the selected plan is ineligible; the callback is not
    /// invoked and callers may fall back to [`Self::find_iter_value`] on the
    /// same retained session. A supported plan preflights all operation limits
    /// before source access or the first callback.
    ///
    /// # Errors
    ///
    /// Returns a typed operation-specific refusal for a supported plan. A
    /// refusal occurs before the first callback.
    pub fn try_visit_spans<F>(
        &mut self,
        haystack: &[u8],
        limits: PortableSpanVisitLimits,
        mut visitor: F,
    ) -> Result<Option<PortableSpanVisitResult>, PortableSpanVisitError>
    where
        F: FnMut(Match),
    {
        match &self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => {
                let result = plan.visit_spans(haystack, limits.exact_literal, |span| {
                    visitor(Match {
                        start: span.start,
                        end: span.end,
                    });
                })?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::ExactLiteral(result.accounting),
                }))
            }
            PortableSearchSessionPlan::Native(regex)
            | PortableSearchSessionPlan::FixedPredicateWord64 { regex, .. } => {
                regex.try_visit_spans(haystack, limits, visitor)
            }
            PortableSearchSessionPlan::K0 {
                k0_plan,
                lazy_delimited_repeat,
                greedy_class_literal_tail,
                ..
            } => {
                if let Some(casefold) = k0_plan.k0_casefold_prefix_class_span {
                    let result = k0_casefold_prefix_class_span::visit(
                        casefold,
                        haystack,
                        limits.k0_casefold_prefix_class,
                        |start, end| visitor(Match { start, end }),
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::K0CasefoldPrefixClass(
                            result.accounting,
                        ),
                    }));
                }
                if let Some(lazy) = lazy_delimited_repeat {
                    let result = lazy.visit_spans(
                        haystack,
                        limits.lazy_delimited_repeat,
                        |span| {
                            visitor(Match {
                                start: span.start,
                                end: span.end,
                            });
                        },
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::LazyDelimitedRepeat(
                            result.accounting,
                        ),
                    }));
                }
                if let Some(corridor) = k0_plan.greedy_delimited_corridor.as_deref() {
                    let result = corridor.visit_spans(
                        haystack,
                        limits.greedy_delimited_corridor,
                        |span| {
                            visitor(Match {
                                start: span.start,
                                end: span.end,
                            });
                        },
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::GreedyDelimitedCorridor(
                            result.accounting,
                        ),
                    }));
                }
                if let Some(phrase) = k0_plan.unicode_token_phrase {
                    let result = phrase.visit_spans(
                        haystack,
                        limits.unicode_token_phrase,
                        |span| {
                            visitor(Match {
                                start: span.start,
                                end: span.end,
                            });
                        },
                    )?;
                    return Ok(Some(PortableSpanVisitResult {
                        matches: result.matches,
                        span_sum: result.span_sum,
                        accounting: PortableSpanVisitAccounting::UnicodeTokenPhrase(
                            result.accounting,
                        ),
                    }));
                }
                let Some(greedy) = greedy_class_literal_tail else {
                    return Ok(None);
                };
                let result = greedy.visit_spans(
                    haystack,
                    limits.greedy_class_literal_tail,
                    |span| {
                        visitor(Match {
                            start: span.start,
                            end: span.end,
                        });
                    },
                )?;
                Ok(Some(PortableSpanVisitResult {
                    matches: result.matches,
                    span_sum: result.span_sum,
                    accounting: PortableSpanVisitAccounting::GreedyClassLiteralTail(
                        result.accounting,
                    ),
                }))
            }
        }
    }

    pub(crate) fn find_iter_utf8<'s, 'h>(
        &'s mut self,
        haystack: &'h str,
        limits: PortableFindIterRunLimits,
    ) -> PortableSessionMatches<'s, 'r, 'h> {
        self.find_iter_with_progress(haystack.as_bytes(), limits, EmptyMatchProgress::Utf8Scalar)
    }

    fn find_iter_with_progress<'s, 'h>(
        &'s mut self,
        haystack: &'h [u8],
        limits: PortableFindIterRunLimits,
        empty_match_progress: EmptyMatchProgress,
    ) -> PortableSessionMatches<'s, 'r, 'h> {
        let native_cursor = self.native_search_cursor(haystack);
        PortableSessionMatches {
            session: self,
            state: PortableMatchIterState::new(
                haystack,
                limits,
                empty_match_progress,
                native_cursor,
            ),
        }
    }

    fn native_search_cursor<'h>(
        &self,
        haystack: &'h [u8],
    ) -> Option<PortableNativeSearchCursor<'r, 'h>> {
        match &self.plan {
            PortableSearchSessionPlan::ExactLiteral { .. } => None,
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => Some(
                PortableNativeSearchCursor::FixedPredicate(plan.search_cursor(haystack)),
            ),
            PortableSearchSessionPlan::Native(regex) => regex.native_search_cursor(haystack),
            PortableSearchSessionPlan::K0 { .. } => None,
        }
    }

    fn value_native_search_cursor<'h>(
        &mut self,
        haystack: &'h [u8],
    ) -> Option<PortableNativeSearchCursor<'r, 'h>> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { .. } => None,
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => Some(
                PortableNativeSearchCursor::FixedPredicate(plan.search_cursor(haystack)),
            ),
            PortableSearchSessionPlan::Native(regex) => regex.native_search_cursor(haystack),
            PortableSearchSessionPlan::K0 {
                session,
                k0_plan,
                reverse_inner,
                mandatory_suffix,
                mandatory_cut,
                negative_prefilter,
                exclusive_route_state,
                ..
            } => {
                match exclusive_route_state.value_iter_route() {
                    K0ValueIterRoute::General => None,
                    K0ValueIterRoute::SourceBound => {
                        Some(PortableNativeSearchCursor::K0SourceBound)
                    }
                    K0ValueIterRoute::Unknown => {
                        let sidecars_absent = reverse_inner.is_none()
                            && mandatory_suffix.is_none()
                            && mandatory_cut.is_none()
                            && negative_prefilter.is_none()
                            && k0_plan.correlated_terminal().is_none()
                            && k0_plan.absolute_end_proof.is_none();
                        let classified = classify_and_cache_k0_value_iter_route(
                            session,
                            sidecars_absent,
                            exclusive_route_state,
                        );
                        (classified == K0ValueIterRoute::SourceBound)
                        .then_some(PortableNativeSearchCursor::K0SourceBound)
                    }
                }
            }
        }
    }

    fn find_iter_universal_finite_suffix_at(
        &mut self,
        haystack: &[u8],
        start: usize,
        limits: SearchLimits,
    ) -> Option<Result<Option<Match>, SearchError>> {
        let window = SearchWindow::new(start, haystack.len());
        let PortableSearchSessionPlan::K0 {
            session,
            aggregate_setup,
            k0_plan,
            mandatory_suffix,
            mandatory_suffix_span_state,
            ..
        } = &mut self.plan
        else {
            return None;
        };
        let Some(suffix) = *mandatory_suffix else {
            return None;
        };
        if suffix.universal_finite_match_byte_bounds().is_none() {
            return None;
        }
        if let Err(error) = validate_k0_facade_window(haystack.len(), window) {
            return Some(Err(error));
        }
        if k0_finite_minimum_window_is_proven_empty(Some(suffix), haystack.len(), window)
            || k0_absolute_end_window_is_proven_empty(
                k0_plan.absolute_end_proof,
                haystack.len(),
                window,
            )
        {
            return Some(Ok(None));
        }
        let invocation = match K0AggregateInvocation::admit(session, *aggregate_setup, limits) {
            Ok(invocation) => invocation,
            Err(error) => return Some(Err(error)),
        };
        let limits = invocation.primary_limits();

        // A positive-width iterator continuation owns a monotone residual
        // window. The graph-proved universal corridor is exact there even
        // when the standalone 1-KiB/4x performance heuristic declines. Keep
        // this separate entry point so standalone search retains its original
        // linked hot path and the compiler specializes the proof mode.
        let mut suffix_state_after_success = *mandatory_suffix_span_state;
        let suffix_attempt = match try_k0_mandatory_suffix_span_start_for_iteration(
            session,
            suffix,
            suffix_state_after_success,
            haystack,
            window,
            limits,
            None,
        ) {
            Ok(attempt) => attempt,
            Err(error) => return Some(Err(error)),
        };
        suffix_state_after_success = suffix_attempt.state_after_success;
        let result = match suffix_attempt.outcome {
            K0MandatorySuffixSpanOutcome::ProvedAbsent => Ok(None),
            K0MandatorySuffixSpanOutcome::ProvedSpan { start, end } => {
                Ok(Some(Match { start, end }))
            }
            K0MandatorySuffixSpanOutcome::ProvedStart {
                start,
                maximum_match_bytes,
            } => match replay_k0_finite_proved_start_with_exact_receipt(
                session,
                haystack,
                window,
                limits,
                start,
                maximum_match_bytes,
            ) {
                Ok((output, exact_receipt)) => {
                    if !exact_receipt {
                        observe_k0_finite_suffix_span_replay_fallback(
                            &mut suffix_state_after_success,
                            window,
                        );
                    }
                    Ok(output)
                }
                Err(error) => Err(error),
            },
            K0MandatorySuffixSpanOutcome::Fallback
            | K0MandatorySuffixSpanOutcome::Bypass
            | K0MandatorySuffixSpanOutcome::GeometryBypass
            | K0MandatorySuffixSpanOutcome::UniversalIncumbent { .. }
            | K0MandatorySuffixSpanOutcome::Absent
            | K0MandatorySuffixSpanOutcome::Narrowed(_)
            | K0MandatorySuffixSpanOutcome::Incumbent { .. } => session
                .search_span_value(haystack, window, limits)
                .map(|found| {
                    found.map(|span| Match {
                        start: span.start(),
                        end: span.end(),
                    })
                })
                .map_err(SearchError::from),
        };
        if result.is_ok() {
            *mandatory_suffix_span_state = suffix_state_after_success;
        }
        Some(result.map_err(|error| invocation.map_error(error)))
    }

    fn find_iter_value_source_bound_at(
        &mut self,
        source: &mut K0SpanSourceCursor<'_>,
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        let PortableSearchSessionPlan::K0 {
            session,
            aggregate_setup,
            ..
        } = &mut self.plan
        else {
            unreachable!("source-bound K0 iterator route was checked before construction");
        };
        validate_k0_facade_window(
            source.haystack().len(),
            SearchWindow::new(start, source.haystack().len()),
        )?;
        let invocation = K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
        let found = session
            .search_span_value_at_source_cursor(source, start, invocation.primary_limits())
            .map_err(|error| invocation.map_k0_error(error))?;
        Ok(found.map(|span| Match {
            start: span.start(),
            end: span.end(),
        }))
    }

    fn find_iter_value_source_at(
        &mut self,
        source: &mut K0SpanSourceCursor<'_>,
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        let retained_root_run = match &self.plan {
            PortableSearchSessionPlan::K0 {
                session,
                k0_plan,
                mandatory_suffix: None,
                mandatory_cut: None,
                negative_prefilter: None,
                ..
            } if k0_plan.correlated_terminal().is_none()
                && k0_plan.absolute_end_proof.is_none() => {
                session.retained_root_run_cursor_available()
            }
            PortableSearchSessionPlan::ExactLiteral { .. }
            | PortableSearchSessionPlan::FixedPredicateWord64 { .. }
            | PortableSearchSessionPlan::Native(_)
            | PortableSearchSessionPlan::K0 { .. } => false,
        };
        if retained_root_run {
            let PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                ..
            } = &mut self.plan
            else {
                unreachable!("retained K0 root-run cursor was checked above");
            };
            validate_k0_facade_window(
                source.haystack().len(),
                SearchWindow::new(start, source.haystack().len()),
            )?;
            let invocation = K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
            let report = session
                .search_span_at_source_cursor(source, start, invocation.primary_limits())
                .map_err(|error| invocation.map_k0_error(error))?;
            return Ok(report.into_output().map(|span| Match {
                start: span.start(),
                end: span.end(),
            }));
        }
        let universal_suffix_continuation = start != 0
            && matches!(
                &self.plan,
                PortableSearchSessionPlan::K0 {
                    mandatory_suffix: Some(suffix),
                    ..
                } if suffix.universal_finite_match_byte_bounds().is_some()
            );
        if universal_suffix_continuation {
            return self
                .find_iter_universal_finite_suffix_at(source.haystack(), start, limits)
                .expect("universal finite suffix eligibility was checked above");
        }
        self.find_at_value(source.haystack(), start, limits)
    }

    fn find_iter_at(
        &mut self,
        source: &mut K0SpanSourceCursor<'_>,
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, PortableFindIterStepAccounting), SearchError> {
        match &mut self.plan {
            PortableSearchSessionPlan::ExactLiteral { plan, .. } => {
                let (matched, accounting) = plan.find_window(
                    source.haystack(),
                    LiteralWindow::new(start, source.haystack().len()),
                    literal_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    PortableFindIterStepAccounting::work(
                        u64::try_from(accounting.linear_terms).unwrap_or(u64::MAX),
                    ),
                ))
            }
            PortableSearchSessionPlan::FixedPredicateWord64 { plan, .. } => {
                let (matched, accounting) = plan.find_window(
                    source.haystack(),
                    LiteralWindow::new(start, source.haystack().len()),
                    fixed_predicate_word64_search_limits(limits),
                )?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    PortableFindIterStepAccounting::work(accounting.actual.work),
                ))
            }
            PortableSearchSessionPlan::Native(regex) => regex
                .find_iter_at(source.haystack(), start, limits)
                .map(|(matched, work)| (matched, PortableFindIterStepAccounting::work(work))),
            PortableSearchSessionPlan::K0 {
                session,
                aggregate_setup,
                k0_plan,
                reverse_inner,
                mandatory_suffix,
                mandatory_cut,
                negative_prefilter,
                ..
            } => {
                validate_k0_facade_window(
                    source.haystack().len(),
                    SearchWindow::new(start, source.haystack().len()),
                )?;
                let invocation =
                    K0AggregateInvocation::admit(session, *aggregate_setup, limits)?;
                let limits = invocation.primary_limits();
                let result = (|| {
                    if k0_plan.correlated_terminal().is_some() {
                        let sidecars_absent = reverse_inner.is_none()
                            && mandatory_suffix.is_none()
                            && mandatory_cut.is_none()
                            && negative_prefilter.is_none()
                            && k0_plan.absolute_end_proof.is_none();
                        if let Some(prepared) = prepare_k0_correlated_iter_at(
                            session,
                            k0_plan,
                            sidecars_absent,
                            source,
                            start,
                            limits,
                        ) {
                            return prepared.map(|prepared| prepared.commit(source));
                        }
                    }
                    let report = session
                        .search_span_at_source_cursor(source, start, limits)
                        .map_err(SearchError::from)?;
                    let accounting = PortableFindIterStepAccounting::k0(
                        invocation.accounting(report.accounting())?,
                    );
                    let matched = report.into_output().map(|span| Match {
                        start: span.start(),
                        end: span.end(),
                    });
                    Ok((matched, accounting))
                })();
                result.map_err(|error| invocation.map_error(error))
            }
        }
    }
}

/// Fallible iterator over every non-overlapping byte match.
///
/// Repeated empty matches at the previous match end are suppressed before the
/// next byte position is searched. This preserves the pinned Rust bytes
/// iterator's adjacent-empty behavior without reinterpreting anchors against
/// sliced suffixes.
#[derive(Debug)]
pub struct PortableMatches<'r, 'h> {
    session: PortableSearchSession<'r>,
    state: PortableMatchIterState<'r, 'h>,
}

/// Fallible byte-match iterator borrowing an existing search session.
///
/// The mutable borrow is held for the iterator's lifetime, preventing
/// overlapping use of the same workspace. Dropping this iterator releases the
/// session for another haystack. Unlike [`PortableMatches`], this type performs
/// no session construction and owns no workspace.
#[derive(Debug)]
pub struct PortableSessionMatches<'s, 'r, 'h> {
    session: &'s mut PortableSearchSession<'r>,
    state: PortableMatchIterState<'r, 'h>,
}

/// Fallible value-only iterator owning a fresh search session.
///
/// Unlike [`PortableMatches`], this type exposes no per-search or
/// whole-iterator work accounting and can therefore dispatch each contextual
/// search through value-only accelerators. Exact one-time session setup facts
/// remain available.
#[derive(Debug)]
pub struct PortableValueMatches<'r, 'h> {
    session: PortableSearchSession<'r>,
    state: PortableValueMatchIterState<'r, 'h>,
}

/// Fallible value-only iterator borrowing an existing search session.
///
/// Dropping the iterator releases the mutable session borrow. The iterator
/// preserves the same byte progress, error fusion, and search-call cap as
/// [`PortableSessionMatches`], but exposes no per-search or whole-iterator work
/// accounting. Exact one-time session setup facts remain available.
#[derive(Debug)]
pub struct PortableSessionValueMatches<'s, 'r, 'h> {
    session: &'s mut PortableSearchSession<'r>,
    state: PortableValueMatchIterState<'r, 'h>,
}

#[derive(Clone, Copy, Debug)]
enum PortableNativeSearchCursor<'r, 'h> {
    #[cfg(not(feature = "static-dispatch"))]
    PackedLiteralSet(PackedLiteralSetSearchCursor<'r, 'h>),
    FixedPredicate(FixedPredicateWord64SearchCursor<'r, 'h>),
    PrefixClass(PrefixClassAlternationSearchCursor<'r, 'h>),
    DispatchedPrefixClass(DispatchedPrefixClassAlternationSearchCursor<'r, 'h>),
    UnicodeScalarRun(UnicodeScalarSearchCursor<'r, 'h>),
    LineDomainByteAtoms(line_domain_byte_atoms::SearchCursor<'r, 'h>),
    K0SourceBound,
}

impl PortableNativeSearchCursor<'_, '_> {
    fn find_at(
        &mut self,
        start: usize,
        limits: SearchLimits,
    ) -> Result<(Option<Match>, u64), SearchError> {
        match self {
            #[cfg(not(feature = "static-dispatch"))]
            Self::PackedLiteralSet(cursor) => {
                let (matched, accounting) = cursor
                    .find_at(start, packed_literal_set_limits(limits))
                    .map_err(SearchError::from)?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.work_upper_bound).unwrap_or(u64::MAX),
                ))
            }
            Self::FixedPredicate(cursor) => {
                let (matched, accounting) = cursor
                    .find_at(start, fixed_predicate_word64_search_limits(limits))
                    .map_err(SearchError::from)?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    accounting.actual.work,
                ))
            }
            Self::PrefixClass(cursor) => {
                let (matched, _accounting, prepaid_work) = cursor
                    .find_at(start, prefix_class_alternation_search_limits(limits))
                    .map_err(SearchError::from)?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(prepaid_work).unwrap_or(u64::MAX),
                ))
            }
            Self::DispatchedPrefixClass(cursor) => {
                let (matched, _accounting, prepaid_work) = cursor
                    .find_at(start, prefix_class_alternation_search_limits(limits))
                    .map_err(SearchError::from)?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(prepaid_work).unwrap_or(u64::MAX),
                ))
            }
            Self::UnicodeScalarRun(cursor) => {
                let (matched, accounting) = cursor
                    .find_at(start, unicode_scalar_search_limits(limits))
                    .map_err(SearchError::from)?;
                Ok((
                    matched.map(|(start, end)| Match { start, end }),
                    u64::try_from(accounting.actual.work).unwrap_or(u64::MAX),
                ))
            }
            Self::LineDomainByteAtoms(cursor) => {
                let (matched, accounting) = cursor.find_at(start, limits)?;
                Ok((matched, accounting.actual.work))
            }
            Self::K0SourceBound => {
                unreachable!("source-bound K0 iteration is dispatched with its mutable session")
            }
        }
    }

    fn find_at_value(
        &mut self,
        start: usize,
        limits: SearchLimits,
    ) -> Result<Option<Match>, SearchError> {
        match self {
            #[cfg(not(feature = "static-dispatch"))]
            Self::PackedLiteralSet(cursor) => cursor
                .find_at_value(start, packed_literal_set_limits(limits))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            Self::UnicodeScalarRun(cursor) => cursor
                .find_at_value(start, unicode_scalar_search_limits(limits))
                .map(|matched| matched.map(|(start, end)| Match { start, end }))
                .map_err(SearchError::from),
            Self::LineDomainByteAtoms(cursor) => cursor
                .find_at_value(start, limits)
                .map_err(SearchError::from),
            Self::K0SourceBound => {
                unreachable!("source-bound K0 iteration is dispatched with its mutable session")
            }
            _ => self.find_at(start, limits).map(|(matched, _work)| matched),
        }
    }
}

// One term for the forward terminal stream, one for the disjoint reverse
// class runs, at most two sixteen-byte literal comparisons per terminal, and
// the remaining branch lookup/progress arithmetic all fit below this linear
// envelope. Exact-delimited admission makes terminal-separated regions
// disjoint across both one search and monotone iterator continuations.
const K0_CORRELATED_ITER_LINEAR_TERMS_PER_BYTE: u64 = 64;
const K0_CORRELATED_ITER_LINEAR_BASE_TERMS: u64 = 1;

fn k0_correlated_iter_linear_work(window_bytes: usize) -> Option<u64> {
    u64::try_from(window_bytes)
        .ok()?
        .checked_mul(K0_CORRELATED_ITER_LINEAR_TERMS_PER_BYTE)?
        .checked_add(K0_CORRELATED_ITER_LINEAR_BASE_TERMS)
}

#[derive(Clone, Copy, Debug)]
struct K0CorrelatedIterPrepared {
    matched: Option<Match>,
    accounting: PortableFindIterStepAccounting,
    #[cfg(test)]
    fallback_work: u64,
    automaton_identity: u64,
    window_end: usize,
    next_start: usize,
}

impl K0CorrelatedIterPrepared {
    fn commit(
        self,
        source: &mut K0SpanSourceCursor<'_>,
    ) -> (Option<Match>, PortableFindIterStepAccounting) {
        source.publish_facade_continuation(
            self.automaton_identity,
            self.window_end,
            self.next_start,
        );
        (self.matched, self.accounting)
    }
}

#[inline(never)]
fn prepare_k0_correlated_iter_at(
    session: &mut K0SearchSession<'_>,
    k0_plan: &PortableK0Plan,
    sidecars_absent: bool,
    source: &mut K0SpanSourceCursor<'_>,
    start: usize,
    limits: SearchLimits,
) -> Option<Result<K0CorrelatedIterPrepared, SearchError>> {
    let plan = k0_plan.correlated_terminal()?;
    if !sidecars_absent || session.retained_root_run_cursor_available() {
        return None;
    }
    let haystack = source.haystack();
    let window = SearchWindow::new(start, haystack.len());
    if !k0_correlated_exact_delimited_allows(plan, haystack.len(), window, limits) {
        return None;
    }
    // Complete the source-independent prospective before touching bytes. An
    // unrepresentable optional envelope declines to authoritative ordinary K0.
    let prospective = k0_correlated_iter_linear_work(
        window.end().checked_sub(window.start())?,
    )?;
    let automaton_identity = k0_plan.automaton.identity();
    let retained = match source.retained_facade_continuation(automaton_identity) {
        Ok(retained) => retained,
        Err(error) => return Some(Err(SearchError::from(error))),
    };
    let prepaid_work = if retained == Some((window.end(), window.start())) {
        0
    } else {
        prospective
    };
    let searched = match plan.probe_exact_delimited(
        haystack,
        window.start(),
        window.end(),
    ) {
        correlated_bounded_alternation::ExactDelimitedProbe::Match { start, end } => {
            Ok((
                Some(Match { start, end }),
                PortableFindIterStepAccounting::work(prepaid_work),
                0,
            ))
        }
        correlated_bounded_alternation::ExactDelimitedProbe::Exhausted => {
            Ok((None, PortableFindIterStepAccounting::work(prepaid_work), 0))
        }
        correlated_bounded_alternation::ExactDelimitedProbe::Fallback {
            first_unproved_start,
        } => {
            let fallback_start = first_unproved_start.min(window.end());
            session
                .search_span_at_source_cursor(source, fallback_start, limits)
                .map_err(SearchError::from)
                .and_then(|report| {
                    let fallback_accounting =
                        PortableFindIterStepAccounting::k0(report.accounting());
                    let fallback_work = fallback_accounting.work_or_linear_terms;
                    let matched = report.into_output().map(|span| Match {
                        start: span.start(),
                        end: span.end(),
                    });
                    let accounting = fallback_accounting.checked_add_work(prepaid_work).ok_or(
                        SearchError::K0(K0SearchError::ArithmeticOverflow {
                            computation: "correlated iterator prepaid plus fallback work",
                        }),
                    )?;
                    Ok((matched, accounting, fallback_work))
                })
        }
    };
    Some(searched.map(|(matched, accounting, _fallback_work)| {
        K0CorrelatedIterPrepared {
            matched,
            accounting,
            #[cfg(test)]
            fallback_work: _fallback_work,
            automaton_identity,
            window_end: window.end(),
            next_start: matched.map_or(window.end(), Match::end),
        }
    }))
}

#[derive(Debug)]
enum PortableMatchIterState<'r, 'h> {
    General(PortableMatchIterCore<'h>),
    Native {
        core: PortableMatchIterCore<'h>,
        cursor: PortableNativeSearchCursor<'r, 'h>,
    },
}

#[derive(Debug)]
struct PortableMatchIterCore<'h> {
    k0_source: K0SpanSourceCursor<'h>,
    limits: PortableFindIterRunLimits,
    empty_match_progress: EmptyMatchProgress,
    start: usize,
    last_match_end: Option<usize>,
    pending_empty_progress: bool,
    accounting: PortableFindIterAccounting,
    finished: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum EmptyMatchProgress {
    Byte,
    Utf8Scalar,
}

#[derive(Debug)]
enum PortableValueMatchIterState<'r, 'h> {
    General(PortableValueMatchIterCore<'h>),
    Native {
        core: PortableValueMatchIterCore<'h>,
        cursor: PortableNativeSearchCursor<'r, 'h>,
    },
}

#[derive(Debug)]
struct PortableValueMatchIterCore<'h> {
    k0_source: K0SpanSourceCursor<'h>,
    limits: PortableFindIterRunLimits,
    start: usize,
    last_match_end: Option<usize>,
    pending_empty_progress: bool,
    search_calls: usize,
    finished: bool,
}

impl<'h> PortableValueMatchIterCore<'h> {
    const fn new_at(
        haystack: &'h [u8],
        start: usize,
        limits: PortableFindIterRunLimits,
    ) -> Self {
        Self {
            k0_source: K0SpanSourceCursor::new(haystack),
            limits,
            start,
            last_match_end: None,
            pending_empty_progress: false,
            search_calls: 0,
            finished: false,
        }
    }

    fn fail(&mut self, error: PortableFindIterError) -> Result<Match, PortableFindIterError> {
        self.finished = true;
        Err(error)
    }

    fn begin_search(&mut self) -> Result<(), PortableFindIterError> {
        let needed = self.search_calls.checked_add(1).ok_or(
            PortableFindIterError::AccountingOverflow {
                counter: "search-call",
            },
        )?;
        if needed > self.limits.max_search_calls {
            return Err(PortableFindIterError::SearchCallLimit {
                needed,
                limit: self.limits.max_search_calls,
            });
        }
        self.search_calls = needed;
        Ok(())
    }

    fn advance_past_repeated_empty(&mut self) -> bool {
        if self.start == self.k0_source.haystack().len() {
            self.finished = true;
            return true;
        }
        self.start = self.start.saturating_add(1);
        false
    }

    fn advance_pending_empty(&mut self) -> bool {
        if !self.pending_empty_progress {
            return false;
        }
        self.pending_empty_progress = false;
        self.advance_past_repeated_empty()
    }

    fn next_match_with(
        &mut self,
        mut search: impl FnMut(
            &mut K0SpanSourceCursor<'h>,
            usize,
            SearchLimits,
        ) -> Result<Option<Match>, SearchError>,
    ) -> Option<Result<Match, PortableFindIterError>> {
        // Keep this byte progression sequence-equivalent to
        // `PortableMatchIterCore`; the value path differs only in accounting
        // and the contextual search it invokes.
        while !self.finished {
            if self.advance_pending_empty() {
                return None;
            }
            if let Err(error) = self.begin_search() {
                return Some(self.fail(error));
            }
            let matched = match search(&mut self.k0_source, self.start, self.limits.search) {
                Ok(result) => result,
                Err(error) => {
                    return Some(self.fail(PortableFindIterError::Search(error)));
                }
            };
            let Some(matched) = matched else {
                self.finished = true;
                return None;
            };

            if matched.is_empty() && self.last_match_end == Some(matched.end()) {
                if self.advance_past_repeated_empty() {
                    return None;
                }
                continue;
            }

            self.start = matched.end();
            self.last_match_end = Some(matched.end());
            self.pending_empty_progress = matched.is_empty();
            return Some(Ok(matched));
        }
        None
    }
}

impl<'r, 'h> PortableValueMatchIterState<'r, 'h> {
    const fn new_at(
        haystack: &'h [u8],
        start: usize,
        limits: PortableFindIterRunLimits,
        native_cursor: Option<PortableNativeSearchCursor<'r, 'h>>,
    ) -> Self {
        let core = PortableValueMatchIterCore::new_at(haystack, start, limits);
        match native_cursor {
            Some(cursor) => Self::Native { core, cursor },
            None => Self::General(core),
        }
    }

    #[cfg(test)]
    const fn is_fixed_predicate(&self) -> bool {
        matches!(
            self,
            Self::Native {
                cursor: PortableNativeSearchCursor::FixedPredicate(_),
                ..
            }
        )
    }

    fn next_match(
        &mut self,
        session: &mut PortableSearchSession<'r>,
    ) -> Option<Result<Match, PortableFindIterError>> {
        match self {
            Self::General(core) => core.next_match_with(|source, start, limits| {
                session.find_iter_value_source_at(source, start, limits)
            }),
            Self::Native { core, cursor } => {
                if matches!(cursor, PortableNativeSearchCursor::K0SourceBound) {
                    next_source_bound_k0_value_match(core, session)
                } else {
                    core.next_match_with(|_source, start, limits| {
                        cursor.find_at_value(start, limits)
                    })
                }
            }
        }
    }
}

#[inline(never)]
fn next_source_bound_k0_value_match<'r, 'h>(
    core: &mut PortableValueMatchIterCore<'h>,
    session: &mut PortableSearchSession<'r>,
) -> Option<Result<Match, PortableFindIterError>> {
    core.next_match_with(|source, start, limits| {
        session.find_iter_value_source_bound_at(source, start, limits)
    })
}

impl<'h> PortableMatchIterCore<'h> {
    const fn new(
        haystack: &'h [u8],
        limits: PortableFindIterRunLimits,
        empty_match_progress: EmptyMatchProgress,
    ) -> Self {
        Self {
            k0_source: K0SpanSourceCursor::new(haystack),
            limits,
            empty_match_progress,
            start: 0,
            last_match_end: None,
            pending_empty_progress: false,
            accounting: PortableFindIterAccounting {
                search_calls: 0,
                matches: 0,
                suppressed_empty: 0,
                work_or_linear_terms: 0,
                cache_growth_events: 0,
                cache_growth_allocated_bytes: 0,
                cache_growth_initialized_bytes: 0,
                cache_growth_retained_delta: 0,
                cache_growth_peak_scratch_bytes: 0,
                utf8_progress_byte_probes: 0,
                utf8_progress_work: 0,
            },
            finished: false,
        }
    }

    const fn haystack(&self) -> &'h [u8] {
        self.k0_source.haystack()
    }

    fn fail(&mut self, error: PortableFindIterError) -> Result<Match, PortableFindIterError> {
        self.finished = true;
        Err(error)
    }

    fn begin_search(&mut self) -> Result<(), PortableFindIterError> {
        let needed = self.accounting.search_calls.checked_add(1).ok_or(
            PortableFindIterError::AccountingOverflow {
                counter: "search-call",
            },
        )?;
        if needed > self.limits.max_search_calls {
            return Err(PortableFindIterError::SearchCallLimit {
                needed,
                limit: self.limits.max_search_calls,
            });
        }
        self.accounting.search_calls = needed;
        Ok(())
    }

    fn record_search_accounting(
        &mut self,
        search: PortableFindIterStepAccounting,
    ) -> Result<(), PortableFindIterError> {
        let Some(work_or_linear_terms) = self
            .accounting
            .work_or_linear_terms
            .checked_add(search.work_or_linear_terms)
        else {
            return Err(PortableFindIterError::AccountingOverflow { counter: "work" });
        };
        let Some(cache_growth_events) = self
            .accounting
            .cache_growth_events
            .checked_add(search.cache_growth_events)
        else {
            return Err(PortableFindIterError::AccountingOverflow {
                counter: "cache-growth-event",
            });
        };
        let Some(cache_growth_allocated_bytes) = self
            .accounting
            .cache_growth_allocated_bytes
            .checked_add(search.cache_growth_allocated_bytes)
        else {
            return Err(PortableFindIterError::AccountingOverflow {
                counter: "cache-growth-allocated-byte",
            });
        };
        let Some(cache_growth_initialized_bytes) = self
            .accounting
            .cache_growth_initialized_bytes
            .checked_add(search.cache_growth_initialized_bytes)
        else {
            return Err(PortableFindIterError::AccountingOverflow {
                counter: "cache-growth-initialized-byte",
            });
        };
        let Some(cache_growth_retained_delta) = self
            .accounting
            .cache_growth_retained_delta
            .checked_add(search.cache_growth_retained_delta)
        else {
            return Err(PortableFindIterError::AccountingOverflow {
                counter: "cache-growth-retained-byte",
            });
        };
        self.accounting.work_or_linear_terms = work_or_linear_terms;
        self.accounting.cache_growth_events = cache_growth_events;
        self.accounting.cache_growth_allocated_bytes = cache_growth_allocated_bytes;
        self.accounting.cache_growth_initialized_bytes = cache_growth_initialized_bytes;
        self.accounting.cache_growth_retained_delta = cache_growth_retained_delta;
        self.accounting.cache_growth_peak_scratch_bytes = self
            .accounting
            .cache_growth_peak_scratch_bytes
            .max(search.cache_growth_peak_scratch_bytes);
        Ok(())
    }

    fn record_utf8_progress(
        &mut self,
        byte_probes: u64,
        work: u64,
    ) -> Result<(), PortableFindIterError> {
        let next_byte_probes = self
            .accounting
            .utf8_progress_byte_probes
            .checked_add(byte_probes)
            .ok_or(PortableFindIterError::AccountingOverflow {
                counter: "utf8-progress-byte-probe",
            })?;
        let next_work = self
            .accounting
            .work_or_linear_terms
            .checked_add(work)
            .ok_or(PortableFindIterError::AccountingOverflow {
                counter: "utf8-progress-work",
            })?;
        let next_progress_work = self.accounting.utf8_progress_work.checked_add(work).ok_or(
            PortableFindIterError::AccountingOverflow {
                counter: "utf8-progress-work",
            },
        )?;
        self.accounting.utf8_progress_byte_probes = next_byte_probes;
        self.accounting.work_or_linear_terms = next_work;
        self.accounting.utf8_progress_work = next_progress_work;
        Ok(())
    }

    fn advance_past_repeated_empty(&mut self) -> Result<bool, PortableFindIterError> {
        self.accounting.suppressed_empty = self.accounting.suppressed_empty.checked_add(1).ok_or(
            PortableFindIterError::AccountingOverflow {
                counter: "suppressed-empty",
            },
        )?;
        if self.start == self.haystack().len() {
            self.finished = true;
            return Ok(true);
        }
        self.start = match self.empty_match_progress {
            EmptyMatchProgress::Byte => self.start.saturating_add(1),
            EmptyMatchProgress::Utf8Scalar => {
                // This mode is constructed only from `&str`. Starting at a
                // scalar boundary, skip its UTF-8 continuation bytes to reach
                // the next scalar boundary. Charge the initial increment,
                // every byte classification, and every continuation-byte
                // increment.
                let mut next = self.start.saturating_add(1);
                let mut byte_probes = 0_u64;
                let mut progress_work = 1_u64;
                while next < self.haystack().len() {
                    byte_probes = byte_probes.checked_add(1).ok_or(
                        PortableFindIterError::AccountingOverflow {
                            counter: "utf8-progress-byte-probe",
                        },
                    )?;
                    progress_work = progress_work.checked_add(1).ok_or(
                        PortableFindIterError::AccountingOverflow {
                            counter: "utf8-progress-work",
                        },
                    )?;
                    if (self.haystack()[next] & 0b1100_0000) != 0b1000_0000 {
                        break;
                    }
                    progress_work = progress_work.checked_add(1).ok_or(
                        PortableFindIterError::AccountingOverflow {
                            counter: "utf8-progress-work",
                        },
                    )?;
                    next = next.saturating_add(1);
                }
                self.record_utf8_progress(byte_probes, progress_work)?;
                next
            }
        };
        Ok(false)
    }

    fn advance_pending_empty(&mut self) -> Result<bool, PortableFindIterError> {
        if !self.pending_empty_progress {
            return Ok(false);
        }
        self.pending_empty_progress = false;
        // The immutable matcher, original haystack, assertion context, and
        // cursor are unchanged since the emitted empty match. Repeating the
        // same search can only select that same empty span, so suppress it
        // without another invocation and perform the standard progress step.
        self.advance_past_repeated_empty()
    }

    fn next_match_with(
        &mut self,
        mut search: impl FnMut(
            &mut K0SpanSourceCursor<'h>,
            usize,
            SearchLimits,
        )
            -> Result<(Option<Match>, PortableFindIterStepAccounting), SearchError>,
    ) -> Option<Result<Match, PortableFindIterError>> {
        while !self.finished {
            match self.advance_pending_empty() {
                Ok(false) => {}
                Ok(true) => return None,
                Err(error) => return Some(self.fail(error)),
            }
            if let Err(error) = self.begin_search() {
                return Some(self.fail(error));
            }
            let searched = search(&mut self.k0_source, self.start, self.limits.search);
            let (matched, search_accounting) = match searched {
                Ok(result) => result,
                Err(error) => return Some(self.fail(PortableFindIterError::Search(error))),
            };
            if let Err(error) = self.record_search_accounting(search_accounting) {
                return Some(self.fail(error));
            }
            let Some(matched) = matched else {
                self.finished = true;
                return None;
            };

            if matched.is_empty() && self.last_match_end == Some(matched.end()) {
                match self.advance_past_repeated_empty() {
                    Ok(false) => continue,
                    Ok(true) => return None,
                    Err(error) => return Some(self.fail(error)),
                }
            }

            self.start = matched.end();
            self.last_match_end = Some(matched.end());
            self.pending_empty_progress = matched.is_empty();
            let Some(emitted_count) = self.accounting.matches.checked_add(1) else {
                return Some(
                    self.fail(PortableFindIterError::AccountingOverflow { counter: "match" }),
                );
            };
            self.accounting.matches = emitted_count;
            return Some(Ok(matched));
        }
        None
    }
}

impl<'r, 'h> PortableMatchIterState<'r, 'h> {
    const fn new(
        haystack: &'h [u8],
        limits: PortableFindIterRunLimits,
        empty_match_progress: EmptyMatchProgress,
        native_cursor: Option<PortableNativeSearchCursor<'r, 'h>>,
    ) -> Self {
        let core = PortableMatchIterCore::new(haystack, limits, empty_match_progress);
        match native_cursor {
            Some(cursor) => Self::Native { core, cursor },
            None => Self::General(core),
        }
    }

    const fn core(&self) -> &PortableMatchIterCore<'h> {
        match self {
            Self::General(core) | Self::Native { core, .. } => core,
        }
    }

    #[cfg(test)]
    fn core_mut(&mut self) -> &mut PortableMatchIterCore<'h> {
        match self {
            Self::General(core) | Self::Native { core, .. } => core,
        }
    }

    const fn haystack(&self) -> &'h [u8] {
        self.core().haystack()
    }

    const fn accounting(&self) -> PortableFindIterAccounting {
        self.core().accounting
    }

    #[cfg(test)]
    const fn is_fixed_predicate(&self) -> bool {
        matches!(
            self,
            Self::Native {
                cursor: PortableNativeSearchCursor::FixedPredicate(_),
                ..
            }
        )
    }

    fn next_match(
        &mut self,
        session: &mut PortableSearchSession<'r>,
    ) -> Option<Result<Match, PortableFindIterError>> {
        match self {
            Self::General(core) => core.next_match_with(|source, start, limits| {
                session.find_iter_at(source, start, limits)
            }),
            Self::Native { core, cursor } => core.next_match_with(|_source, start, limits| {
                cursor
                    .find_at(start, limits)
                    .map(|(matched, work)| (matched, PortableFindIterStepAccounting::work(work)))
            }),
        }
    }
}

impl PortableValueMatches<'_, '_> {
    /// One-time K0 workspace setup facts, or `None` for native plans.
    #[must_use]
    pub const fn workspace_setup_accounting(&self) -> Option<SearchSessionSetupAccounting> {
        self.session.workspace_setup_accounting()
    }
}

impl Iterator for PortableValueMatches<'_, '_> {
    type Item = Result<Match, PortableFindIterError>;

    fn next(&mut self) -> Option<Self::Item> {
        self.state.next_match(&mut self.session)
    }
}

impl core::iter::FusedIterator for PortableValueMatches<'_, '_> {}

impl PortableSessionValueMatches<'_, '_, '_> {
    /// The reused session's one-time K0 setup facts.
    #[must_use]
    pub const fn workspace_setup_accounting(&self) -> Option<SearchSessionSetupAccounting> {
        self.session.workspace_setup_accounting()
    }
}

impl Iterator for PortableSessionValueMatches<'_, '_, '_> {
    type Item = Result<Match, PortableFindIterError>;

    fn next(&mut self) -> Option<Self::Item> {
        self.state.next_match(self.session)
    }
}

impl core::iter::FusedIterator for PortableSessionValueMatches<'_, '_, '_> {}

impl PortableMatches<'_, '_> {
    /// Exact counters accumulated through the most recent iterator action.
    #[must_use]
    pub const fn accounting(&self) -> PortableFindIterAccounting {
        self.state.accounting()
    }

    /// One-time K0 workspace setup facts, or `None` for native plans.
    #[must_use]
    pub const fn workspace_setup_accounting(&self) -> Option<SearchSessionSetupAccounting> {
        self.session.workspace_setup_accounting()
    }
}

impl Iterator for PortableMatches<'_, '_> {
    type Item = Result<Match, PortableFindIterError>;

    fn next(&mut self) -> Option<Self::Item> {
        self.state.next_match(&mut self.session)
    }
}

impl core::iter::FusedIterator for PortableMatches<'_, '_> {}

impl PortableSessionMatches<'_, '_, '_> {
    /// Exact counters accumulated by this iterator.
    ///
    /// Every new iterator starts from zero even when the same session has
    /// already searched other haystacks.
    #[must_use]
    pub const fn accounting(&self) -> PortableFindIterAccounting {
        self.state.accounting()
    }

    /// The reused session's one-time K0 setup facts.
    ///
    /// These facts predate this iterator and are not included in
    /// [`Self::accounting`]. Native plans return `None`.
    #[must_use]
    pub const fn workspace_setup_accounting(&self) -> Option<SearchSessionSetupAccounting> {
        self.session.workspace_setup_accounting()
    }
}

impl Iterator for PortableSessionMatches<'_, '_, '_> {
    type Item = Result<Match, PortableFindIterError>;

    fn next(&mut self) -> Option<Self::Item> {
        self.state.next_match(self.session)
    }
}

impl core::iter::FusedIterator for PortableSessionMatches<'_, '_, '_> {}

/// Fallible iterator over borrowed, non-overlapping byte matches.
///
/// This is the match-value projection of [`PortableMatches`]. It retains the
/// complete original haystack for [`ByteMatch::as_bytes`] while delegating all
/// search and progress state to the offset iterator.
#[derive(Debug)]
pub struct PortableByteMatches<'r, 'h> {
    inner: PortableMatches<'r, 'h>,
}

impl PortableByteMatches<'_, '_> {
    /// Exact counters accumulated through the most recent iterator action.
    #[must_use]
    pub const fn accounting(&self) -> PortableFindIterAccounting {
        self.inner.accounting()
    }

    /// One-time K0 workspace setup facts, or `None` for native plans.
    #[must_use]
    pub const fn workspace_setup_accounting(&self) -> Option<SearchSessionSetupAccounting> {
        self.inner.workspace_setup_accounting()
    }
}

impl<'h> Iterator for PortableByteMatches<'_, 'h> {
    type Item = Result<ByteMatch<'h>, PortableFindIterError>;

    fn next(&mut self) -> Option<Self::Item> {
        let haystack = self.inner.state.haystack();
        self.inner
            .next()
            .map(|result| result.map(|span| ByteMatch { haystack, span }))
    }
}

impl core::iter::FusedIterator for PortableByteMatches<'_, '_> {}

pub(crate) fn reserve_planner<T>(
    values: &mut Vec<T>,
    additional: usize,
    work: &mut u64,
    limit: u64,
    structure: &'static str,
) -> Result<(), BuildError> {
    let needed = values
        .len()
        .checked_add(additional)
        .ok_or(BuildError::PlannerWorkLimit {
            needed: u64::MAX,
            limit,
        })?;
    if needed > values.capacity() {
        charge_planner(work, u64::try_from(values.len()).unwrap_or(u64::MAX), limit)?;
    }
    charge_planner(work, u64::try_from(additional).unwrap_or(u64::MAX), limit)?;
    values
        .try_reserve(additional)
        .map_err(|_| BuildError::AllocationFailed {
            structure,
            additional,
        })
}

pub(crate) fn charge_planner(work: &mut u64, amount: u64, limit: u64) -> Result<(), BuildError> {
    let needed = work
        .checked_add(amount)
        .ok_or(BuildError::PlannerWorkLimit {
            needed: u64::MAX,
            limit,
        })?;
    if needed > limit {
        return Err(BuildError::PlannerWorkLimit { needed, limit });
    }
    *work = needed;
    Ok(())
}

