    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one route-isolation matrix covers every public explicit-state family"
    )]
    fn k0_literal_class_corridor_ordinary_facades_are_exact_and_isolated() {
        let pattern = r"(?-u:BEGIN.*END)";
        let regex = PortableBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        let PortablePlan::K0(k0) = &regex.plan else {
            unreachable!("literal/class corridor selected another plan");
        };
        assert!(matches!(
            &k0.exclusive,
            super::K0ExclusivePlan::Line(plan)
                if plan.literal_class_corridor().is_some()
        ));
        assert_eq!(regex.captures_len(), 1);

        let length = super::k0_literal_class_corridor::MIN_INPUT_BYTES + 64;
        let mut haystack = vec![b'x'; length];
        let corridor = b"BEGINaENDbEND";
        let match_start = haystack.len() - corridor.len();
        haystack[match_start..].copy_from_slice(corridor);
        let expected = Some(Match {
            start: match_start,
            end: haystack.len(),
        });
        let full = SearchWindow::full(&haystack);
        let unlimited = SearchLimits::unlimited();

        super::k0_literal_class_corridor_ordinary_facade_probe::reset();
        assert!(regex.is_match_value(&haystack, unlimited).unwrap());
        assert!(regex.is_match_at(&haystack, 0, unlimited).unwrap().0);
        assert!(regex
            .is_match_value_at(&haystack, 0, unlimited)
            .unwrap());
        assert!(regex.is_match_window(&haystack, full, unlimited).unwrap().0);
        assert!(regex
            .is_match_window_value(&haystack, full, unlimited)
            .unwrap());
        assert_eq!(regex.find_value(&haystack, unlimited).unwrap(), expected);
        assert_eq!(regex.find_accounted(&haystack, unlimited).unwrap().0, expected);
        assert_eq!(regex.find_at(&haystack, 0, unlimited).unwrap().0, expected);
        assert_eq!(
            regex.find_at_value(&haystack, 0, unlimited).unwrap(),
            expected
        );
        assert_eq!(regex.find_window(&haystack, full, unlimited).unwrap().0, expected);
        assert_eq!(
            regex.find_window_value(&haystack, full, unlimited).unwrap(),
            expected
        );
        assert_eq!(regex.selected_end_value(&haystack, unlimited).unwrap(), Some(length));

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(session.is_match_value(&haystack, unlimited).unwrap());
        assert_eq!(session.find_value(&haystack, unlimited).unwrap(), expected);
        let mut ordinary = regex.ordinary_session().unwrap();
        assert!(ordinary.is_match_at(&haystack, 0).unwrap());
        assert_eq!(ordinary.find_at(&haystack, 0).unwrap(), expected);
        assert_eq!(
            regex
                .find_iter(&haystack, PortableFindIterLimits::unlimited())
                .unwrap()
                .next()
                .transpose()
                .unwrap(),
            expected,
        );
        assert_eq!(
            regex
                .find_iter_value(&haystack, PortableFindIterLimits::unlimited())
                .unwrap()
                .next()
                .transpose()
                .unwrap(),
            expected,
        );

        let mut locations = regex.capture_locations();
        assert_eq!(
            regex
                .captures_read_value(&mut locations, &haystack, unlimited)
                .unwrap()
                .map(|matched| Match {
                    start: matched.start(),
                    end: matched.end(),
                }),
            expected,
        );
        assert_eq!(locations.get(0), Some((match_start, length)));
        assert_eq!(
            regex
                .captures_read(&mut locations, &haystack, unlimited)
                .unwrap()
                .0
                .map(|matched| Match {
                    start: matched.start(),
                    end: matched.end(),
                }),
            expected,
        );
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (0, 0),
            "bounded, accounted, session, iterator, and capture APIs stay canonical",
        );

        let short = vec![b'x'; super::k0_literal_class_corridor::MIN_INPUT_BYTES - 1];
        assert!(!regex.is_match(&short));
        assert_eq!(regex.find(&short), None);
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (0, 0),
            "a below-threshold ordinary call stays canonical",
        );

        assert!(regex.is_match(&haystack));
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (1, 0),
        );
        assert_eq!(regex.find(&haystack), expected);
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (1, 1),
        );

        let address = haystack.as_ptr();
        haystack[match_start] = b'Q';
        assert_eq!(haystack.as_ptr(), address);
        assert!(!regex.is_match(&haystack));
        assert_eq!(regex.find(&haystack), None);
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (2, 2),
            "same-address mutation cannot reuse source-dependent results",
        );
    }

    #[test]
    fn k0_literal_class_corridor_capture_refusal_is_contained() {
        let regex = PortableBuilder::new(r"(?-u:(BEGIN).*(END))")
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        let PortablePlan::K0(k0) = &regex.plan else {
            unreachable!("captured literal/class corridor selected another plan");
        };
        assert!(matches!(
            &k0.exclusive,
            super::K0ExclusivePlan::Line(plan)
                if plan.literal_class_corridor().is_some()
        ));
        assert_eq!(regex.captures_len(), 3);

        let length = super::k0_literal_class_corridor::MIN_INPUT_BYTES + 17;
        let mut haystack = vec![b'x'; length];
        let corridor = b"BEGINaENDbEND";
        let match_start = haystack.len() - corridor.len();
        haystack[match_start..].copy_from_slice(corridor);
        let expected = Some(Match {
            start: match_start,
            end: length,
        });
        let unlimited = SearchLimits::unlimited();
        let mut locations = regex.capture_locations();

        super::k0_literal_class_corridor_ordinary_facade_probe::reset();
        assert!(matches!(
            regex.captures_read_value(&mut locations, &haystack, unlimited),
            Err(super::PortableCapturesReadError::ExplicitCapturesUnsupported { captures: 2 })
        ));
        assert!(matches!(
            regex.captures_read(&mut locations, &haystack, unlimited),
            Err(super::PortableCapturesReadError::ExplicitCapturesUnsupported { captures: 2 })
        ));
        for index in 0..regex.captures_len() {
            assert_eq!(locations.get(index), None);
        }
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (0, 0),
            "explicit capture refusal stays on canonical K0",
        );

        assert!(regex.is_match(&haystack));
        assert_eq!(regex.find(&haystack), expected);
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (1, 1),
            "whole-match ordinary values may use the capture-transparent proof",
        );
    }

    #[test]
    fn k0_literal_class_corridor_resource_refusal_keeps_canonical_k0() {
        let pattern = r"(?-u:BEGIN.*END)";
        let baseline = PortableBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        let baseline_report = baseline.build_report();
        let PortablePlan::K0(baseline_k0) = &baseline.plan else {
            unreachable!("corridor baseline selected another plan");
        };
        assert!(baseline_k0.exclusive.literal_class_corridor().is_some());
        assert!(baseline_report.charged_persistent_bytes > 0);
        assert!(baseline_report.planner_work > 0);

        let exact = PortableBuilder::new(pattern)
            .unicode(false)
            .limits(BuildLimits {
                max_planner_work: baseline_report.planner_work,
                max_persistent_bytes: baseline_report.charged_persistent_bytes,
                ..BuildLimits::default()
            })
            .build()
            .expect("the exact corridor resource envelope replays");
        let PortablePlan::K0(exact_k0) = &exact.plan else {
            unreachable!("exact-envelope corridor selected another plan");
        };
        assert!(exact_k0.exclusive.literal_class_corridor().is_some());
        assert_eq!(exact.build_report().planner_work, baseline_report.planner_work);
        assert_eq!(
            exact.build_report().charged_persistent_bytes,
            baseline_report.charged_persistent_bytes,
        );

        let persistent_limit = baseline_report.charged_persistent_bytes - 1;
        let persistent_refusal = PortableBuilder::new(pattern)
            .unicode(false)
            .limits(BuildLimits {
                max_persistent_bytes: persistent_limit,
                ..BuildLimits::default()
            })
            .build()
            .expect("optional corridor storage refusal keeps canonical K0");
        let PortablePlan::K0(persistent_k0) = &persistent_refusal.plan else {
            unreachable!("persistent refusal changed the incumbent family");
        };
        assert!(persistent_k0.exclusive.literal_class_corridor().is_none());
        assert!(persistent_refusal.build_report().charged_persistent_bytes <= persistent_limit);
        assert_eq!(
            baseline_report.plan_storage_bytes
                - persistent_refusal.build_report().plan_storage_bytes,
            super::K0LinePlan::storage_bytes(),
        );

        let planner_limit = baseline_report.planner_work - 1;
        let planner_refusal = PortableBuilder::new(pattern)
            .unicode(false)
            .limits(BuildLimits {
                max_planner_work: planner_limit,
                ..BuildLimits::default()
            })
            .build()
            .expect("optional corridor planner refusal keeps canonical K0");
        let PortablePlan::K0(planner_k0) = &planner_refusal.plan else {
            unreachable!("planner refusal changed the incumbent family");
        };
        assert!(planner_k0.exclusive.literal_class_corridor().is_none());
        assert!(planner_refusal.build_report().planner_work <= planner_limit);

        let _failure = super::k0_literal_class_corridor_owner_allocation_probe::fail_next();
        let allocation_refusal = PortableBuilder::new(pattern)
            .unicode(false)
            .build()
            .expect("optional corridor allocation failure keeps canonical K0");
        let PortablePlan::K0(allocation_k0) = &allocation_refusal.plan else {
            unreachable!("allocation refusal changed the incumbent family");
        };
        assert!(allocation_k0.exclusive.literal_class_corridor().is_none());
        assert_eq!(
            baseline_report.plan_storage_bytes
                - allocation_refusal.build_report().plan_storage_bytes,
            super::K0LinePlan::storage_bytes(),
        );

        let mut haystack = vec![b'x'; super::k0_literal_class_corridor::MIN_INPUT_BYTES];
        let suffix = b"BEGINEND";
        let start = haystack.len() - suffix.len();
        haystack[start..].copy_from_slice(suffix);
        let expected = Some(Match {
            start,
            end: haystack.len(),
        });
        super::k0_literal_class_corridor_ordinary_facade_probe::reset();
        for regex in [&persistent_refusal, &planner_refusal, &allocation_refusal] {
            assert!(regex.is_match(&haystack));
            assert_eq!(regex.find(&haystack), expected);
        }
        assert_eq!(
            super::k0_literal_class_corridor_ordinary_facade_probe::snapshot(),
            (0, 0),
            "every resource refusal uses canonical K0 ordinary execution",
        );
    }

    #[test]
    fn class_plus_literal_class_plus_ordinary_facades_are_exact_and_stateless() {
        let regex = PortableBuilder::new(r"(?-u:[a-z]+MID[0-9]+)")
            .unicode(false)
            .build()
            .expect("class-plus corridor builds automatically");
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        let PortablePlan::K0(k0) = &regex.plan else {
            panic!("class-plus corridor did not retain K0");
        };
        let plan = k0
            .uri_exists
            .expect("class-plus corridor retains its structural proof");
        assert_eq!(
            plan.identity().plan_id,
            super::k0_uri_exists::CLASS_PLUS_PLAN_ID
        );

        let mut storage = vec![b'!'; 128];
        let address = storage.as_ptr();
        storage[108..126].copy_from_slice(b"alphabeticMID12345");
        let late = Some(Match {
            start: 108,
            end: 126,
        });
        assert!(regex.is_match(&storage));
        assert_eq!(regex.find(&storage), late);

        storage.fill(b'!');
        assert_eq!(storage.as_ptr(), address);
        assert!(!regex.is_match(&storage));
        assert_eq!(regex.find(&storage), None);

        storage[1..14].copy_from_slice(b"lettersMID123");
        let early = Some(Match { start: 1, end: 14 });
        assert_eq!(storage.as_ptr(), address);
        assert!(regex.is_match(&storage));
        assert_eq!(regex.find(&storage), early);

        let mut dense = Vec::new();
        for _ in 0..8 {
            dense.extend_from_slice(b"!MID!");
        }
        let dense_start = dense.len();
        dense.extend_from_slice(b"lettersMID123");
        let dense_expected = Some(Match {
            start: dense_start,
            end: dense.len(),
        });
        assert!(regex.is_match(&dense));
        assert_eq!(regex.find(&dense), dense_expected);

        let limits = SearchLimits::unlimited();
        assert!(regex.is_match_value(&dense, limits).unwrap());
        assert_eq!(regex.find_value(&dense, limits).unwrap(), dense_expected);
        assert_eq!(
            regex.is_match_accounted(&dense, limits).unwrap().0,
            true
        );
        assert_eq!(
            regex.find_accounted(&dense, limits).unwrap().0,
            dense_expected
        );

        let mut checked = regex
            .search_session(SearchSessionLimits::unlimited())
            .expect("checked class-plus session constructs");
        assert!(checked.is_match_value(&dense, limits).unwrap());
        assert_eq!(checked.find_value(&dense, limits).unwrap(), dense_expected);

        let mut ordinary = regex
            .ordinary_session()
            .expect("ordinary class-plus session constructs");
        assert!(ordinary.is_match_at(&dense, 0).unwrap());
        assert_eq!(ordinary.find_at(&dense, 0).unwrap(), dense_expected);

        let two = b"aMID1!bbMID22";
        assert_eq!(regex.find(two), Some(Match { start: 0, end: 5 }));
        let second = SearchWindow::new(6, two.len());
        assert_eq!(
            regex.find_window_value(two, second, limits).unwrap(),
            Some(Match { start: 6, end: 13 })
        );
        assert!(regex.is_match_window_value(two, second, limits).unwrap());
    }

    #[test]
    fn prefix_class_ordinary_facades_are_full_window_only() {
        let regex = PortableBuilder::new(r"(?:ab[0-9]+|cd[A-Z]+)")
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::PrefixClassAlternation);
        let haystack = b"!cdAZ!ab123!";
        let full = SearchWindow::full(haystack);
        let expected = Some(Match { start: 1, end: 5 });

        super::prefix_class_alternation_ordinary_facade_probe::reset();
        assert!(regex.is_match(haystack));
        assert_eq!(regex.find(haystack), expected);
        assert_eq!(
            super::prefix_class_alternation_ordinary_facade_probe::snapshot(),
            (1, 1),
        );

        assert!(
            regex
                .is_match_window_value(haystack, full, SearchLimits::unlimited())
                .unwrap()
        );
        assert_eq!(
            regex
                .find_window_value(haystack, full, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert!(
            regex
                .is_match_with_limits(haystack, SearchLimits::unlimited())
                .unwrap()
        );
        assert_eq!(
            regex
                .find_with_limits(haystack, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert!(
            regex
                .is_match_accounted(haystack, SearchLimits::unlimited())
                .unwrap()
                .0
        );
        assert_eq!(
            regex
                .find_accounted(haystack, SearchLimits::unlimited())
                .unwrap()
                .0,
            expected,
        );

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(
            session
                .is_match_value(haystack, SearchLimits::unlimited())
                .unwrap()
        );
        assert_eq!(
            session
                .find_value(haystack, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert_eq!(
            regex
                .find_iter_value(haystack, PortableFindIterLimits::unlimited())
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap(),
            vec![
                Match { start: 1, end: 5 },
                Match { start: 6, end: 11 },
            ],
        );
        let mut locations = regex.capture_locations();
        assert_eq!(
            regex
                .captures_read_value(
                    &mut locations,
                    haystack,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .map(|matched| (matched.start(), matched.end())),
            Some((1, 5)),
        );
        assert_eq!(
            super::prefix_class_alternation_ordinary_facade_probe::snapshot(),
            (1, 1),
        );
    }

    #[test]
    fn composed_ordinary_routes_remain_plan_local() {
        let bounded = PortableBuilder::new(r"\b\p{Greek}+\b")
            .unicode(true)
            .build()
            .unwrap();
        let word = PortableBuilder::new(r"\b\w{2,}\b")
            .unicode(true)
            .build()
            .unwrap();
        assert!(matches!(
            &bounded.plan,
            PortablePlan::BoundedWordClass(_)
        ));
        assert!(matches!(&word.plan, PortablePlan::UnicodeWordRun(_)));

        super::bounded_word_class::ordinary_is_match_probe::reset();
        super::unicode_word_run::reset_full_prepared_call_count();
        assert!(bounded.is_match("!\u{03b1}\u{03b2}!".as_bytes()));
        assert_eq!(
            super::bounded_word_class::ordinary_is_match_probe::snapshot().calls,
            1
        );
        assert_eq!(super::unicode_word_run::full_prepared_call_count(), 0);

        super::bounded_word_class::ordinary_find_probe::reset();
        super::unicode_scalar_run_ordinary_facade_probe::reset();
        assert_eq!(
            bounded
                .find("!\u{03b1}\u{03b2}!".as_bytes())
                .map(|matched| (matched.start(), matched.end())),
            Some((1, 5)),
        );
        assert_eq!(super::bounded_word_class::ordinary_find_probe::calls(), 1);
        assert_eq!(
            super::unicode_scalar_run_ordinary_facade_probe::calls(),
            0,
            "the BWC ordinary find arm remains first and plan-local",
        );

        super::bounded_word_class::ordinary_is_match_probe::reset();
        super::unicode_word_run::reset_full_prepared_call_count();
        assert!(word.is_match("!\u{03b1}\u{03b2}!".as_bytes()));
        assert_eq!(
            super::bounded_word_class::ordinary_is_match_probe::snapshot().calls,
            0
        );
        assert_eq!(super::unicode_word_run::full_prepared_call_count(), 1);
    }

    #[test]
    fn reverse_inner_ordinary_facades_are_single_literal_and_api_local() {
        let regex = PortableBuilder::new(r"[abλ]+aa[abλ]+")
            .unicode(true)
            .build()
            .unwrap();
        let haystack = b"!aaaab!";
        let expected = Some((1, 6));
        assert_eq!(regex.build_report().plan, PlanKind::ReverseInner);
        assert_eq!(
            regex.runtime_implementation_id(),
            super::REVERSE_INNER_PLAN_ID,
        );

        super::reverse_inner_ordinary_facade_probe::reset();
        assert_eq!(
            regex
                .find(haystack)
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(regex.is_match(haystack));
        let ordinary = super::reverse_inner_ordinary_facade_probe::snapshot();
        assert_eq!(ordinary, (1, 1));

        assert_eq!(
            regex
                .find_value(haystack, SearchLimits::unlimited())
                .unwrap()
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(
            regex
                .is_match_value(haystack, SearchLimits::unlimited())
                .unwrap()
        );
        assert_eq!(
            regex
                .find_accounted(haystack, SearchLimits::unlimited())
                .unwrap()
                .0
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(
            regex
                .is_match_accounted(haystack, SearchLimits::unlimited())
                .unwrap()
                .0
        );
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            session
                .find_value(haystack, SearchLimits::unlimited())
                .unwrap()
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(
            session
                .is_match_value(haystack, SearchLimits::unlimited())
                .unwrap()
        );
        let first = regex
            .find_iter_value(haystack, PortableFindIterLimits::unlimited())
            .unwrap()
            .next()
            .expect("one reverse-inner match")
            .unwrap();
        assert_eq!((first.start(), first.end()), expected.unwrap());
        let mut locations = regex.capture_locations();
        assert_eq!(
            regex
                .captures_read_value(&mut locations, haystack, SearchLimits::unlimited())
                .unwrap()
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert_eq!(locations.get(0), expected);
        assert_eq!(
            super::reverse_inner_ordinary_facade_probe::snapshot(),
            ordinary,
            "finite, accounted, session, iterator, and capture APIs stay canonical",
        );

        let union = PortableBuilder::new(r"(?:[abλ]+aa[abλ]+|[abλ]+b[abλ]+)")
            .unicode(true)
            .build()
            .unwrap();
        assert_eq!(union.build_report().plan, PlanKind::ReverseInner);
        assert_eq!(
            union.runtime_implementation_id(),
            super::REVERSE_INNER_UNION_PLAN_ID,
        );
        super::reverse_inner_ordinary_facade_probe::reset();
        assert_eq!(
            union
                .find(haystack)
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(union.is_match(haystack));
        assert_eq!(
            super::reverse_inner_ordinary_facade_probe::snapshot(),
            (0, 0),
            "literal unions must retain their construction-selected route",
        );

        let grouped_union = PortableBuilder::new(r"[a-zλ]+(?:aab|abb)[a-zλ]+")
            .unicode(true)
            .build()
            .unwrap();
        assert_eq!(grouped_union.build_report().plan, PlanKind::ReverseInner);
        assert_eq!(
            grouped_union.runtime_implementation_id(),
            super::REVERSE_INNER_GROUPED_UNION_PLAN_ID,
        );
        let grouped_haystack = b"!zaabz!";
        super::reverse_inner_ordinary_facade_probe::reset();
        assert_eq!(
            grouped_union
                .find(grouped_haystack)
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(grouped_union.is_match(grouped_haystack));
        assert_eq!(
            super::reverse_inner_ordinary_facade_probe::snapshot(),
            (0, 0),
            "grouped literal unions must retain their construction-selected route",
        );
    }

    #[test]
    fn reverse_inner_nested_named_capture_refusal_isolated_from_ordinary_values() {
        let regex = PortableBuilder::new(r"(?P<outer>[abλ]+(?P<inner>aa)[abλ]+)")
            .unicode(true)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::ReverseInner);
        assert_eq!(
            regex.runtime_implementation_id(),
            super::REVERSE_INNER_PLAN_ID,
        );
        assert_eq!(regex.captures_len(), 3);
        assert_eq!(
            regex.capture_names().collect::<Vec<_>>(),
            vec![None, Some("outer"), Some("inner")],
        );

        let haystack = b"!aaaab!";
        let expected = Some((1, 6));
        super::reverse_inner_ordinary_facade_probe::reset();
        assert_eq!(
            regex
                .find(haystack)
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert!(regex.is_match(haystack));
        let ordinary = super::reverse_inner_ordinary_facade_probe::snapshot();
        assert_eq!(ordinary, (1, 1));

        let mut locations = regex.capture_locations();
        assert!(matches!(
            regex.captures_read_value(
                &mut locations,
                haystack,
                SearchLimits::unlimited(),
            ),
            Err(super::PortableCapturesReadError::ExplicitCapturesUnsupported { captures: 2 }),
        ));
        assert!(matches!(
            regex.captures_read(&mut locations, haystack, SearchLimits::unlimited()),
            Err(super::PortableCapturesReadError::ExplicitCapturesUnsupported { captures: 2 }),
        ));
        for index in 0..regex.captures_len() {
            assert_eq!(locations.get(index), None);
        }
        assert_eq!(
            super::reverse_inner_ordinary_facade_probe::snapshot(),
            ordinary,
            "explicit capture refusal cannot enter either ordinary facade",
        );
    }

