    #[test]
    fn ripgrep_standard_literal_text_byte_classifier_is_exact() {
        assert_eq!(super::classify_ripgrep_standard_literal_text(""), None);

        let classify = |text: &str, forbidden_byte| {
            let mut census = super::RipgrepStandardLiteralByteCensus::empty();
            let classified = super::classify_ripgrep_standard_literal_text_with_census(
                text,
                forbidden_byte,
                &mut census,
            );
            (classified, census)
        };

        for byte in 0_u8..=0x7f {
            let character = char::from(byte);
            let text = character.to_string();
            let rejected = byte == b'\n' || regex_syntax::is_meta_character(character);
            assert_eq!(
                super::classify_ripgrep_standard_literal_text(&text),
                (!rejected).then_some(false),
                "typed classifier disagrees for ASCII byte {byte:#04x}"
            );
            let (classified, census) = classify(&text, None);
            assert_eq!(classified, (!rejected).then_some(false));
            assert_eq!(
                census.contains(byte),
                !rejected,
                "typed census disagrees for ASCII byte {byte:#04x}"
            );
        }

        for scalar in [
            "\u{80}",
            "\u{7ff}",
            "\u{800}",
            "\u{ffff}",
            "\u{10000}",
            "\u{10ffff}",
            "\u{2028}",
        ] {
            assert_eq!(
                super::classify_ripgrep_standard_literal_text(scalar),
                Some(false),
                "one Unicode scalar must not be grouped: {scalar:?}"
            );
            let (classified, census) = classify(scalar, None);
            assert_eq!(classified, Some(false));
            for &byte in scalar.as_bytes() {
                assert!(census.contains(byte), "missing UTF-8 byte {byte:#04x}");
            }
        }
        for grouped in ["éa", "aé", "é界", "e\u{301}", "🦀界"] {
            assert_eq!(
                super::classify_ripgrep_standard_literal_text(grouped),
                Some(true),
                "multiple Unicode scalars must be grouped: {grouped:?}"
            );
        }
        assert_eq!(
            super::classify_ripgrep_standard_literal_text("é\n界"),
            None
        );
        assert_eq!(
            super::classify_ripgrep_standard_literal_text("é[界"),
            None
        );
        assert_eq!(classify("a\0b", Some(b'\0')).0, None);
        let (classified, census) = classify("a\0b", None);
        assert_eq!(classified, Some(true));
        for &byte in b"a\0b" {
            assert!(census.contains(byte));
        }
    }

    #[test]
    fn ripgrep_standard_literal_text_closes_exact_resource_boundaries_before_scanning() {
        #[derive(Clone, Copy)]
        struct TextMustNotBeRequested;

        impl super::RipgrepStandardLiteral<'static> for TextMustNotBeRequested {
            fn bytes(self) -> &'static [u8] {
                b"a"
            }

            fn text(self) -> Option<&'static str> {
                panic!("resource refusal must precede the typed value scan")
            }
        }

        assert!(
            super::ripgrep_standard_literal_context_from::<_, _, true>(
                1,
                |index| (index == 0).then_some(TextMustNotBeRequested),
                BuildLimits::default(),
                0,
            )
            .is_none()
        );

        let patterns = (0..129)
            .map(|index| format!("界value{index:04}"))
            .collect::<Vec<_>>();
        let pattern_refs = patterns.iter().map(String::as_str).collect::<Vec<_>>();
        let context = |limits, canonical_source_limit| {
            super::ripgrep_standard_literal_context_from::<_, _, true>(
                pattern_refs.len(),
                |index| pattern_refs.get(index).copied(),
                limits,
                canonical_source_limit,
            )
        };

        let baseline = context(BuildLimits::default(), usize::MAX)
            .expect("default typed literal resources admit the fixture");
        let expected_source = Hir::alternation(
            patterns
                .iter()
                .map(|pattern| Hir::literal(pattern.as_bytes()))
                .collect(),
        )
        .to_string();
        assert_eq!(&*baseline.source, expected_source);
        let source_bytes = baseline.source.len();
        let syntax = baseline.syntax.clone();

        assert!(context(BuildLimits::default(), source_bytes).is_some());
        assert!(
            context(BuildLimits::default(), source_bytes.saturating_sub(1)).is_none()
        );

        macro_rules! assert_safety_boundary {
            ($field:ident, $observed:expr) => {{
                let observed = $observed;
                assert!(observed > 0, "focused resource boundary must be positive");
                let mut exact = BuildLimits::default();
                exact.syntax_safety.$field = observed;
                assert!(
                    context(exact, usize::MAX).is_some(),
                    "exact {} boundary must admit",
                    stringify!($field)
                );
                let mut one_below = exact;
                one_below.syntax_safety.$field = observed - 1;
                assert!(
                    context(one_below, usize::MAX).is_none(),
                    "one-below {} boundary must refuse",
                    stringify!($field)
                );
            }};
        }

        assert_safety_boundary!(max_pattern_bytes, u64::try_from(source_bytes).unwrap());
        assert_safety_boundary!(max_nesting, syntax.max_depth);
        assert_safety_boundary!(max_hir_nodes, syntax.hir_nodes);
        assert_safety_boundary!(max_parse_work, syntax.parse_work);
        assert_safety_boundary!(
            max_traversal_stack,
            u64::try_from(pattern_refs.len()).unwrap()
        );
    }

    #[test]
    fn ripgrep_standard_literal_text_refuses_every_nonterminal_boundary() {
        fn refs(patterns: &[String]) -> Vec<&str> {
            patterns.iter().map(String::as_str).collect()
        }

        let standard = (0..129)
            .map(|index| format!("value{index:04}"))
            .collect::<Vec<_>>();
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .build_ripgrep_standard_literals(&refs(&standard[..128]), usize::MAX)
                .expect("small-set refusal completes")
                .is_none()
        );
        let oversized = (0..257)
            .map(|index| format!("value{index:04}"))
            .collect::<Vec<_>>();
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .build_ripgrep_standard_literals(&refs(&oversized), usize::MAX)
                .expect("oversized-set refusal completes")
                .is_none()
        );
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .build_ripgrep_standard_literals(&vec!["x"; 129], usize::MAX)
                .expect("smart-class refusal completes")
                .is_none()
        );

        for replacement in ["", "meta.value", "line\nvalue"] {
            let mut refused = standard.clone();
            refused[17] = replacement.to_owned();
            assert!(
                PortableBuilder::new("")
                    .multi_line(true)
                    .build_ripgrep_standard_literals(&refs(&refused), usize::MAX)
                    .expect("literal-value refusal completes")
                .is_none()
            );
        }
        for byte in 0_u8..=0x7f {
            let character = char::from(byte);
            if !regex_syntax::is_meta_character(character) {
                continue;
            }
            let mut refused = standard.clone();
            refused[17] = format!("before{character}after");
            assert!(
                PortableBuilder::new("")
                    .multi_line(true)
                    .build_ripgrep_standard_literals(&refs(&refused), usize::MAX)
                    .expect("metacharacter refusal completes")
                    .is_none(),
                "typed handoff admitted metacharacter {character:?}"
            );
        }
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .unicode(false)
                .build_ripgrep_standard_literals(&refs(&standard), usize::MAX)
                .expect("profile refusal completes")
                .is_none()
        );
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .build_ripgrep_standard_literals(&refs(&standard), 1)
                .expect("source-limit refusal completes")
                .is_none()
        );
        let mut finite_limits = BuildLimits::default();
        finite_limits.literal_set.max_patterns = 128;
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .limits(finite_limits)
                .build_ripgrep_standard_literals(&refs(&standard), usize::MAX)
                .expect("finite-limit refusal completes")
                .is_none()
        );
        let mut planner_limits = BuildLimits::default();
        planner_limits.max_planner_work = 0;
        assert!(
            PortableBuilder::new("")
                .multi_line(true)
                .limits(planner_limits)
                .build_ripgrep_standard_literals(&refs(&standard), usize::MAX)
                .expect("planner-limit refusal completes")
                .is_none()
        );
    }

    #[test]
    fn ripgrep_standard_literal_hir_handoff_reproduces_pinned_printer_source() {
        let alternatives = Hir::alternation(vec![
            Hir::literal(b"ab".to_vec()),
            Hir::literal("é".as_bytes()),
            Hir::literal(b"x|".to_vec()),
        ]);
        let cases = [
            (Hir::literal(b"a".to_vec()), "a"),
            (Hir::literal(b"ab".to_vec()), "(?:ab)"),
            (Hir::literal("é".as_bytes()), "é"),
            (Hir::literal(b"|".to_vec()), r"\|"),
            (Hir::literal(b"a|".to_vec()), r"(?:a\|)"),
            (Hir::literal(b"\0".to_vec()), "\0"),
            (alternatives, r"(?:(?:ab)|é|(?:x\|))"),
        ];

        for (hir, expected_source) in cases {
            assert_eq!(hir.to_string(), expected_source);
            let source_limit = expected_source.len();
            let admitted = PortableBuilder::new("")
                .multi_line(true)
                .build_ripgrep_standard_literal_hir(&hir, source_limit)
                .expect("exact source boundary completes")
                .expect("exact source boundary admits the HIR");
            assert_eq!(admitted.as_str(), expected_source);
            assert_eq!(admitted.build_report().source_storage_bytes, source_limit);
            assert_eq!(
                admitted.build_report().syntax.parse_work,
                u64::try_from(source_limit).expect("focused source length fits u64")
                    + admitted.build_report().syntax.hir_nodes
                    + admitted.build_report().syntax.literal_bytes
            );
            assert!(
                PortableBuilder::new("")
                    .multi_line(true)
                    .build_ripgrep_standard_literal_hir(&hir, source_limit.saturating_sub(1),)
                    .expect("below-source boundary completes")
                    .is_none()
            );
        }
    }

