    #[test]
    fn ordinary_session_binds_positive_exact_literal_value_engines() {
        let regex = PortableBuilder::new("needle")
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::ExactLiteral);
        let mut ordinary = regex.ordinary_session().unwrap();
        let PortablePlan::ExactLiteral(literal) = &regex.plan else {
            unreachable!("exact-literal fixture changed plan")
        };
        assert!(matches!(
            &ordinary.plan,
            super::PortableOrdinarySessionPlan::ExactLiteral { executor }
                if executor.is_bound_to(literal)
        ));

        let haystack = b"xxneedle--needle";
        for start in 0..=haystack.len() {
            assert_eq!(
                ordinary.first_acceptance_at(haystack, start),
                regex.shortest_match_at_value(haystack, start, SearchLimits::unlimited())
            );
            assert_eq!(
                ordinary.find_at(haystack, start),
                regex.find_at_value(haystack, start, SearchLimits::unlimited())
            );
            assert_eq!(
                ordinary.is_match_at(haystack, start),
                regex.is_match_value_at(haystack, start, SearchLimits::unlimited())
            );
        }

        let mut visited = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(haystack, |matched| {
                    visited.push((matched.start(), matched.end()));
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(())
        );
        assert_eq!(visited, [(2, 8), (10, 16)]);

        let mut callback_called = false;
        assert!(ordinary
            .try_visit_spans_at(haystack, haystack.len() + 1, |_| {
                callback_called = true;
                Ok::<bool, ()>(true)
            })
            .is_err());
        assert!(!callback_called);

        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(haystack, 0),
            Ok(Some(2)),
        );

        let empty = PortableRegex::new("").unwrap();
        let empty = empty.ordinary_session().unwrap();
        assert!(matches!(
            &empty.plan,
            super::PortableOrdinarySessionPlan::Canonical(_)
        ));
    }

    #[test]
    fn ordinary_exact_literal_session_exhaustively_matches_checked_values() {
        for pattern in words(3).into_iter().filter(|pattern| !pattern.is_empty()) {
            let pattern = core::str::from_utf8(&pattern).unwrap();
            let regex = PortableBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            assert_eq!(regex.build_report().plan, PlanKind::ExactLiteral);
            let mut ordinary = regex.ordinary_session().unwrap();
            for haystack in words(5) {
                for start in 0..=haystack.len() {
                    let expected = regex
                        .find_at_value(&haystack, start, SearchLimits::unlimited())
                        .unwrap();
                    assert_eq!(
                        ordinary.is_match_at(&haystack, start),
                        Ok(expected.is_some()),
                    );
                    assert_eq!(
                        ordinary.first_acceptance_at(&haystack, start),
                        Ok(expected.map(Match::end)),
                    );
                    assert_eq!(ordinary.find_at(&haystack, start), Ok(expected));

                    let mut expected_spans = Vec::new();
                    let mut cursor = start;
                    while let Some(matched) = regex
                        .find_at_value(&haystack, cursor, SearchLimits::unlimited())
                        .unwrap()
                    {
                        expected_spans.push((matched.start(), matched.end()));
                        cursor = matched.end();
                    }
                    let mut spans = Vec::new();
                    assert_eq!(
                        ordinary
                            .try_visit_spans_at(&haystack, start, |matched| {
                                spans.push((matched.start(), matched.end()));
                                Ok::<bool, ()>(true)
                            })
                            .unwrap(),
                        Ok(()),
                    );
                    assert_eq!(spans, expected_spans);
                    assert_eq!(
                        ordinary
                            .count_positive_width_selected_ends_at(&haystack, start),
                        Ok(Some(u64::try_from(expected_spans.len()).unwrap())),
                    );
                }
            }
        }
    }

    const ASCII_FOLDED_LITERAL_SET_PATTERN: &str =
        "(?i-u:alpha|bravo|charlie|delta)";

    fn ascii_folded_literal_set_fixture() -> PortableRegex {
        let regex = PortableBuilder::new(ASCII_FOLDED_LITERAL_SET_PATTERN)
            .unicode(false)
            .build()
            .expect("ASCII-folded literal alternation builds");
        assert_eq!(regex.build_report().plan, PlanKind::LiteralSetDfa);
        let PortablePlan::LiteralSetDfa(plan) = &regex.plan else {
            panic!("ASCII-folded fixture did not retain a literal-set DFA")
        };
        assert_eq!(
            plan.ordinary_ascii_folded()
                .expect("ASCII-folded ordinary sidecar is admitted")
                .branch_count(),
            4,
        );
        regex
    }

    fn ascii_casings(word: &[u8]) -> Vec<Vec<u8>> {
        (0..(1_usize << word.len()))
            .map(|mask| {
                word.iter()
                    .enumerate()
                    .map(|(index, &byte)| {
                        if mask & (1_usize << index) == 0 {
                            byte.to_ascii_lowercase()
                        } else {
                            byte.to_ascii_uppercase()
                        }
                    })
                    .collect()
            })
            .collect()
    }

    #[test]
    fn ascii_folded_literal_set_ordinary_sidecar_matches_upstream_and_rereads_source() {
        let regex = ascii_folded_literal_set_fixture();
        let upstream = regex::bytes::RegexBuilder::new(ASCII_FOLDED_LITERAL_SET_PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let small = b"!!ChArLiE";
        super::ascii_folded_literal_set_ordinary_facade_probe::reset();
        assert!(regex.is_match(small));
        assert_eq!(regex.find(small), Some(Match { start: 2, end: 9 }));
        assert_eq!(
            super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
            (0, 0),
            "inputs below the measured crossover stay on the canonical DFA",
        );
        let crossover = super::ascii_folded_literal_alternation::MIN_FULL_INPUT_BYTES;
        let mut below_crossover = vec![b'!'; crossover - 1];
        below_crossover[crossover - 8..].copy_from_slice(b"ChArLiE");
        super::ascii_folded_literal_set_ordinary_facade_probe::reset();
        assert!(regex.is_match(&below_crossover));
        assert_eq!(
            regex.find(&below_crossover),
            Some(Match {
                start: crossover - 8,
                end: crossover - 1,
            }),
        );
        assert_eq!(
            super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
            (0, 0),
        );
        let mut at_crossover = vec![b'!'; crossover];
        at_crossover[crossover - 7..].copy_from_slice(b"ChArLiE");
        super::ascii_folded_literal_set_ordinary_facade_probe::reset();
        assert!(regex.is_match(&at_crossover));
        assert_eq!(
            regex.find(&at_crossover),
            Some(Match {
                start: crossover - 7,
                end: crossover,
            }),
        );
        assert_eq!(
            super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
            (1, 1),
        );
        let mut checked = 0_usize;
        super::ascii_folded_literal_set_ordinary_facade_probe::reset();
        for word in [
            b"alpha".as_slice(),
            b"bravo".as_slice(),
            b"charlie".as_slice(),
            b"delta".as_slice(),
        ] {
            for casing in ascii_casings(word) {
                let mut haystack = vec![b'!'; 4_097];
                haystack.extend_from_slice(&casing);
                haystack.extend_from_slice(b"\0\xfftail");
                let expected = upstream
                    .find(&haystack)
                    .map(|matched| Match {
                        start: matched.start(),
                        end: matched.end(),
                    });
                assert_eq!(regex.is_match(&haystack), expected.is_some());
                assert_eq!(regex.find(&haystack), expected);
                checked += 1;
            }
        }
        assert_eq!(checked, 224);
        assert_eq!(
            super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
            (checked, checked),
        );

        let mut storage = vec![b'!'; 8_192];
        let address = storage.as_ptr();
        storage[8_185..].copy_from_slice(b"ChArLiE");
        assert_eq!(
            regex.find(&storage),
            Some(Match {
                start: 8_185,
                end: 8_192,
            }),
        );
        storage[8_185..].copy_from_slice(b"ChArLiX");
        assert_eq!(storage.as_ptr(), address);
        assert!(!regex.is_match(&storage));
        assert_eq!(regex.find(&storage), None);
        storage[8_187..].copy_from_slice(b"DeLtA");
        assert_eq!(storage.as_ptr(), address);
        assert_eq!(
            regex.find(&storage),
            Some(Match {
                start: 8_187,
                end: 8_192,
            }),
        );

        let mut earlier_later_branch = vec![b'!'; 4_096];
        earlier_later_branch.extend_from_slice(b"cHaRlIe---ALPHA");
        assert_eq!(
            regex.find(&earlier_later_branch),
            Some(Match {
                start: 4_096,
                end: 4_103,
            }),
            "a later source branch at an earlier start wins",
        );

        let mut invalid_prefix = vec![b'!'; 4_160];
        invalid_prefix[..2].copy_from_slice(b"\xff\x80");
        invalid_prefix[4_096..4_103].copy_from_slice(b"ChArLiE");
        assert_eq!(
            regex.find(&invalid_prefix),
            Some(Match {
                start: 4_096,
                end: 4_103,
            }),
            "invalid bytes before a match preserve byte-regex semantics",
        );
    }

    #[test]
    fn ascii_folded_literal_set_sidecar_preserves_equal_start_source_priority() {
        for (pattern, expected_width) in [
            ("(?i-u:abcde|ab|fghijk|lmnopqrs)", 5),
            ("(?i-u:ab|abcde|fghijk|lmnopqrs)", 2),
        ] {
            let regex = PortableBuilder::new(pattern)
                .unicode(false)
                .build()
                .expect("prefix-related ASCII-folded alternation builds");
            assert!(
                ascii_folded_literal_set_sidecar_is_present(&regex),
                "prefix-related fixture must exercise the sidecar: {pattern:?}",
            );
            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            let mut haystack = vec![b'!'; 4_160];
            haystack[..2].copy_from_slice(b"\xff\x80");
            haystack[4_096..4_101].copy_from_slice(b"AbCdE");
            let expected = upstream.find(&haystack).map(|matched| Match {
                start: matched.start(),
                end: matched.end(),
            });
            assert_eq!(
                expected,
                Some(Match {
                    start: 4_096,
                    end: 4_096 + expected_width,
                }),
            );

            super::ascii_folded_literal_set_ordinary_facade_probe::reset();
            assert_eq!(regex.find(&haystack), expected, "pattern={pattern:?}");
            assert!(regex.is_match(&haystack), "pattern={pattern:?}");
            assert_eq!(
                super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
                (1, 1),
            );
        }
    }

    #[test]
    fn ascii_folded_literal_set_sidecar_isolated_from_checked_and_session_apis() {
        let regex = ascii_folded_literal_set_fixture();
        let mut haystack = vec![b'!'; 8_192];
        haystack.extend_from_slice(b"ChArLiE");
        let expected = Some(Match {
            start: 8_192,
            end: 8_199,
        });
        let limits = SearchLimits::unlimited();
        let window = SearchWindow::full(&haystack);

        super::ascii_folded_literal_set_ordinary_facade_probe::reset();
        assert!(regex.is_match_value(&haystack, limits).unwrap());
        assert_eq!(regex.find_value(&haystack, limits).unwrap(), expected);
        assert!(regex.is_match_accounted(&haystack, limits).unwrap().0);
        assert_eq!(regex.find_accounted(&haystack, limits).unwrap().0, expected);
        assert!(regex.is_match_window_value(&haystack, window, limits).unwrap());
        assert_eq!(
            regex.find_window_value(&haystack, window, limits).unwrap(),
            expected,
        );
        assert!(regex.is_match_value_at(&haystack, 1, limits).unwrap());
        assert_eq!(regex.find_at_value(&haystack, 1, limits).unwrap(), expected);

        let mut checked = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(checked.is_match_value(&haystack, limits).unwrap());
        assert_eq!(checked.find_value(&haystack, limits).unwrap(), expected);
        let prepared = checked.prepare_is_match_value_token(haystack.len(), limits);
        assert!(!prepared.uses_prepared_route());
        assert_eq!(
            checked.is_match_value_prepared(&haystack, prepared),
            Ok(true),
        );
        let session_spans = checked
            .find_iter_value(&haystack, PortableFindIterRunLimits::unlimited())
            .map(Result::unwrap)
            .collect::<Vec<_>>();
        assert_eq!(session_spans, vec![expected.unwrap()]);
        let mut ordinary = regex.ordinary_session().unwrap();
        assert!(ordinary.is_match_at(&haystack, 0).unwrap());
        assert_eq!(ordinary.first_acceptance_at(&haystack, 0), Ok(Some(8_199)));
        assert_eq!(ordinary.find_at(&haystack, 0).unwrap(), expected);
        let mut ordinary_spans = Vec::new();
        assert_eq!(
            ordinary.try_visit_spans_at(&haystack, 0, |matched| {
                ordinary_spans.push(matched);
                Ok::<bool, ()>(true)
            }),
            Ok(Ok(())),
        );
        assert_eq!(ordinary_spans, vec![expected.unwrap()]);
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(&haystack, 0),
            Ok(Some(1)),
        );
        assert_eq!(
            regex
                .shortest_match_at_value(&haystack, 0, limits)
                .unwrap(),
            Some(8_199),
        );
        assert_eq!(
            regex.selected_end_value(&haystack, limits).unwrap(),
            Some(8_199),
        );
        let spans = regex
            .find_iter(&haystack, PortableFindIterLimits::unlimited())
            .unwrap()
            .map(Result::unwrap)
            .collect::<Vec<_>>();
        assert_eq!(spans, vec![expected.unwrap()]);
        let mut locations = regex.capture_locations();
        assert_eq!(
            regex
                .captures_read_value(&mut locations, &haystack, limits)
                .unwrap()
                .map(|matched| Match {
                    start: matched.start(),
                    end: matched.end(),
                }),
            expected,
        );
        assert_eq!(
            super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
            (0, 0),
            "checked, session, iterator, and capture APIs stay canonical",
        );

        assert!(regex.is_match(&haystack));
        assert_eq!(regex.find(&haystack), expected);
        assert_eq!(
            super::ascii_folded_literal_set_ordinary_facade_probe::snapshot(),
            (1, 1),
        );
    }

    #[test]
    fn ascii_folded_literal_set_sidecar_resource_refusal_keeps_canonical_build() {
        let baseline = ascii_folded_literal_set_fixture();
        let baseline_report = baseline.build_report();
        assert!(baseline_report.charged_persistent_bytes > 0);
        assert!(baseline_report.planner_work > 0);

        let exact = PortableBuilder::new(ASCII_FOLDED_LITERAL_SET_PATTERN)
            .unicode(false)
            .limits(BuildLimits {
                max_planner_work: baseline_report.planner_work,
                max_persistent_bytes: baseline_report.charged_persistent_bytes,
                ..BuildLimits::default()
            })
            .build()
            .expect("published exact sidecar limits replay");
        assert!(ascii_folded_literal_set_sidecar_is_present(&exact));
        assert_eq!(exact.build_report().planner_work, baseline_report.planner_work);
        assert_eq!(
            exact.build_report().charged_persistent_bytes,
            baseline_report.charged_persistent_bytes,
        );

        let persistent_limit = baseline_report.charged_persistent_bytes - 1;
        let persistent_refusal = PortableBuilder::new(ASCII_FOLDED_LITERAL_SET_PATTERN)
            .unicode(false)
            .limits(BuildLimits {
                max_persistent_bytes: persistent_limit,
                ..BuildLimits::default()
            })
            .build()
            .expect("optional sidecar persistent refusal keeps the incumbent");
        let PortablePlan::LiteralSetDfa(plan) = &persistent_refusal.plan else {
            panic!("persistent-refusal build changed the incumbent family")
        };
        assert!(plan.ordinary_ascii_folded().is_none());
        assert!(persistent_refusal.build_report().charged_persistent_bytes <= persistent_limit);

        let planner_limit = baseline_report.planner_work - 1;
        let planner_refusal = PortableBuilder::new(ASCII_FOLDED_LITERAL_SET_PATTERN)
            .unicode(false)
            .limits(BuildLimits {
                max_planner_work: planner_limit,
                ..BuildLimits::default()
            })
            .build()
            .expect("optional sidecar planner refusal keeps the incumbent");
        let PortablePlan::LiteralSetDfa(plan) = &planner_refusal.plan else {
            panic!("planner-refusal build changed the incumbent family")
        };
        assert!(plan.ordinary_ascii_folded().is_none());
        assert!(planner_refusal.build_report().planner_work <= planner_limit);
    }

    fn ascii_folded_literal_set_sidecar_is_present(regex: &PortableRegex) -> bool {
        let PortablePlan::LiteralSetDfa(plan) = &regex.plan else {
            return false;
        };
        plan.ordinary_ascii_folded().is_some()
    }

    fn forced_literal_set_dfa(pattern: &str, unicode: bool) -> PortableRegex {
        PortableBuilder::new(pattern)
            .unicode(unicode)
            .limits(BuildLimits {
                packed_literal_set: fre_kernels::PackedLiteralSetBuildLimits {
                    max_patterns: 0,
                    ..fre_kernels::PackedLiteralSetBuildLimits::default()
                },
                ..BuildLimits::default()
            })
            .build()
            .expect("ineligibility fixture builds")
    }

    #[test]
    fn ascii_folded_literal_set_sidecar_requires_exact_authenticated_shape() {
        let packed = PortableBuilder::new("(?i-u:alpha|bravo)")
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(packed.build_report().plan, PlanKind::PackedLiteralSet);
        assert!(!ascii_folded_literal_set_sidecar_is_present(&packed));

        let literal_set_dfa_cases = [
            "(?i-u:alpha|bravo|charlie)",
            "(?i-u:alphaa|bravoo|charly|deltaa)",
            "(?i-u:alpha|bravo|charlie|delt(?-i:[A-C]))",
            "(?i-u:alpha|bravo|charlie|delta|omega)",
            "(?i-u:alph(?-i:a)|bravo|charlie|delta)",
            "(?i-u:[a-c]lpha|bravo|charlie|delta)",
        ];
        for pattern in literal_set_dfa_cases {
            let regex = forced_literal_set_dfa(pattern, false);
            assert_eq!(
                regex.build_report().plan,
                PlanKind::LiteralSetDfa,
                "ineligibility fixture changed family for {pattern:?}",
            );
            assert!(
                !ascii_folded_literal_set_sidecar_is_present(&regex),
                "ineligible shape admitted a folded sidecar for {pattern:?}",
            );
        }

        for (pattern, unicode) in [
            ("(?i-u:a{2}pha|bravo|charlie|delta)", false),
            ("(?i:alpha|bravo|charlie|delta)", true),
        ] {
            let regex = forced_literal_set_dfa(pattern, unicode);
            assert!(
                !ascii_folded_literal_set_sidecar_is_present(&regex),
                "repeat or Unicode folding admitted the byte-only sidecar for {pattern:?}",
            );
        }
    }

    fn literal_set_dfa_fixture(pattern: &str) -> PortableRegex {
        let regex = PortableBuilder::new(pattern)
            .unicode(false)
            .limits(BuildLimits {
                packed_literal_set: fre_kernels::PackedLiteralSetBuildLimits {
                    max_patterns: 0,
                    ..fre_kernels::PackedLiteralSetBuildLimits::default()
                },
                ..BuildLimits::default()
            })
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::LiteralSetDfa);
        regex
    }

    #[test]
    fn literal_set_dfa_ordinary_facades_preserve_upstream_priority_and_source_reads() {
        let haystacks: &[&[u8]] = &[
            b"",
            b"ab",
            b"abzzzz",
            b"zzzzzz",
            b"abababababababab",
            b"\xff\x80zzab\0abab",
        ];
        for pattern in ["a|ab", "ab|a"] {
            let regex = literal_set_dfa_fixture(pattern);
            let PortablePlan::LiteralSetDfa(plan) = &regex.plan else {
                panic!("fixture did not retain a literal-set DFA")
            };
            assert!(plan.ordinary_executor().is_some());
            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            for &haystack in haystacks {
                let expected = upstream
                    .find(haystack)
                    .map(|matched| (matched.start(), matched.end()));
                super::literal_set_dfa_ordinary_facade_probe::reset();
                assert_eq!(
                    regex.is_match(haystack),
                    expected.is_some(),
                    "pattern={pattern:?}, haystack={haystack:?}",
                );
                assert_eq!(
                    regex
                        .find(haystack)
                        .map(|matched| (matched.start(), matched.end())),
                    expected,
                    "pattern={pattern:?}, haystack={haystack:?}",
                );
                assert_eq!(
                    super::literal_set_dfa_ordinary_facade_probe::snapshot(),
                    (1, 1),
                );
            }
        }

        assert_eq!(
            literal_set_dfa_fixture("a|ab").find(b"ab"),
            Some(Match { start: 0, end: 1 }),
        );
        assert_eq!(
            literal_set_dfa_fixture("ab|a").find(b"ab"),
            Some(Match { start: 0, end: 2 }),
        );

        let regex = literal_set_dfa_fixture("a|ab");
        let mut reused = b"\xffab--".to_vec();
        let address = reused.as_ptr();
        super::literal_set_dfa_ordinary_facade_probe::reset();
        assert!(regex.is_match(&reused));
        assert_eq!(regex.find(&reused), Some(Match { start: 1, end: 2 }));
        reused.copy_from_slice(b"\xffzz--");
        assert_eq!(reused.as_ptr(), address);
        assert!(!regex.is_match(&reused));
        assert_eq!(regex.find(&reused), None);
        assert_eq!(
            super::literal_set_dfa_ordinary_facade_probe::snapshot(),
            (2, 2),
            "ordinary calls must reread the borrowed source",
        );
    }

    #[test]
    fn literal_set_dfa_ordinary_facades_decline_nullable_and_folded_attachments() {
        let nullable = literal_set_dfa_fixture("a|");
        let PortablePlan::LiteralSetDfa(nullable_plan) = &nullable.plan else {
            panic!("nullable fixture did not retain a literal-set DFA")
        };
        assert_eq!(nullable.build_report().minimum_match_bytes, Some(0));
        assert!(nullable_plan.ordinary_executor().is_none());
        let nullable_upstream = regex::bytes::RegexBuilder::new("a|")
            .unicode(false)
            .build()
            .unwrap();
        for haystack in [b"".as_slice(), b"a", b"zzz", b"\xffa"] {
            let expected = nullable_upstream
                .find(haystack)
                .map(|matched| Match {
                    start: matched.start(),
                    end: matched.end(),
                });
            super::literal_set_dfa_ordinary_facade_probe::reset();
            assert_eq!(nullable.is_match(haystack), expected.is_some());
            assert_eq!(nullable.find(haystack), expected);
            assert_eq!(
                super::literal_set_dfa_ordinary_facade_probe::snapshot(),
                (0, 0),
                "nullable DFA must retain the canonical ordinary fallback",
            );
        }

        const FOLDED_SOURCE: &str = "(?i:\u{212A}\u{212A}\u{212A}\u{212A}a)";
        let folded = PortableRegex::new(FOLDED_SOURCE).unwrap();
        assert_eq!(folded.build_report().plan, PlanKind::LiteralSetDfa);
        let PortablePlan::LiteralSetDfa(folded_plan) = &folded.plan else {
            panic!("folded fixture did not retain a literal-set DFA")
        };
        assert!(folded_plan.build_accounting().minimum_pattern_bytes > 0);
        assert!(
            folded_plan.ordinary_executor().is_none(),
            "the attached folded route must own ordinary full searches",
        );
        let folded_upstream = regex::bytes::Regex::new(FOLDED_SOURCE).unwrap();
        let mut folded_hit = vec![b'z'; 264];
        folded_hit.extend_from_slice(b"KKKKa");
        let folded_miss = vec![b'z'; folded_hit.len()];
        for haystack in [&folded_hit, &folded_miss] {
            let expected = folded_upstream
                .find(haystack)
                .map(|matched| Match {
                    start: matched.start(),
                    end: matched.end(),
                });
            super::literal_set_dfa_ordinary_facade_probe::reset();
            assert_eq!(folded.is_match(haystack), expected.is_some());
            assert_eq!(folded.find(haystack), expected);
            assert_eq!(
                super::literal_set_dfa_ordinary_facade_probe::snapshot(),
                (0, 0),
                "folded attachment must retain the checked canonical route",
            );
        }
    }

    #[test]
    fn literal_set_dfa_ordinary_facade_isolated_from_explicit_apis() {
        let regex = literal_set_dfa_fixture("ab|a|ba");
        let haystack = b"zzababa";
        let full = SearchWindow::full(haystack);
        let expected = Some(Match { start: 2, end: 4 });
        let unlimited = SearchLimits::unlimited();

        super::literal_set_dfa_ordinary_facade_probe::reset();
        assert!(regex.is_match_value(haystack, unlimited).unwrap());
        assert_eq!(regex.find_value(haystack, unlimited).unwrap(), expected);
        assert!(regex.is_match_accounted(haystack, unlimited).unwrap().0);
        assert_eq!(regex.find_accounted(haystack, unlimited).unwrap().0, expected);
        assert!(regex.is_match_at(haystack, 1, unlimited).unwrap().0);
        assert!(regex.is_match_value_at(haystack, 1, unlimited).unwrap());
        assert_eq!(regex.find_at(haystack, 1, unlimited).unwrap().0, expected);
        assert_eq!(regex.find_at_value(haystack, 1, unlimited).unwrap(), expected);
        assert!(regex.is_match_window(haystack, full, unlimited).unwrap().0);
        assert!(regex
            .is_match_window_value(haystack, full, unlimited)
            .unwrap());
        assert_eq!(regex.find_window(haystack, full, unlimited).unwrap().0, expected);
        assert_eq!(
            regex.find_window_value(haystack, full, unlimited).unwrap(),
            expected,
        );

        let refusing = SearchLimits {
            max_work: 0,
            max_scratch_bytes: 0,
        };
        assert!(matches!(
            regex.is_match_value(haystack, refusing),
            Err(SearchError::LiteralSetDfa(
                LiteralSetError::TransitionLimit { .. }
            )),
        ));
        assert!(matches!(
            regex.find_value(haystack, refusing),
            Err(SearchError::LiteralSetDfa(
                LiteralSetError::TransitionLimit { .. }
            )),
        ));
        assert!(matches!(
            regex.find_window_value(haystack, SearchWindow::new(3, 2), refusing),
            Err(SearchError::LiteralSetDfa(LiteralSetError::InvalidWindow {
                start: 3,
                end: 2,
                haystack_len: 7,
            })),
        ));

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(session.is_match_value(haystack, unlimited).unwrap());
        assert_eq!(session.find_value(haystack, unlimited).unwrap(), expected);
        let mut ordinary = regex.ordinary_session().unwrap();
        assert!(ordinary.is_match_at(haystack, 0).unwrap());
        assert_eq!(ordinary.find_at(haystack, 0).unwrap(), expected);

        let spans = regex
            .find_iter(haystack, PortableFindIterLimits::unlimited())
            .unwrap()
            .map(Result::unwrap)
            .collect::<Vec<_>>();
        let value_spans = regex
            .find_iter_value(haystack, PortableFindIterLimits::unlimited())
            .unwrap()
            .map(Result::unwrap)
            .collect::<Vec<_>>();
        assert_eq!(spans, value_spans);
        assert_eq!(spans.first().copied(), expected);

        let mut locations = regex.capture_locations();
        let captured = regex
            .captures_read(&mut locations, haystack, unlimited)
            .unwrap()
            .0;
        assert_eq!(
            captured.map(|matched| (matched.start(), matched.end())),
            Some((2, 4)),
        );
        let captured = regex
            .captures_read_value(&mut locations, haystack, unlimited)
            .unwrap();
        assert_eq!(
            captured.map(|matched| (matched.start(), matched.end())),
            Some((2, 4)),
        );
        assert_eq!(locations.get(0), Some((2, 4)));
        assert_eq!(
            super::literal_set_dfa_ordinary_facade_probe::snapshot(),
            (0, 0),
            "finite, accounted, window, session, iterator, and capture APIs stay canonical",
        );

        assert!(regex.is_match(haystack));
        assert_eq!(regex.find(haystack), expected);
        assert_eq!(
            super::literal_set_dfa_ordinary_facade_probe::snapshot(),
            (1, 1),
        );
    }

    #[test]
    fn ordinary_literal_set_dfa_binds_positive_ordered_span_and_endpoint_engine() {
        let regex = PortableBuilder::new("ab|a|ba")
            .unicode(false)
            .limits(BuildLimits {
                packed_literal_set: fre_kernels::PackedLiteralSetBuildLimits {
                    max_patterns: 0,
                    ..fre_kernels::PackedLiteralSetBuildLimits::default()
                },
                ..BuildLimits::default()
            })
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::LiteralSetDfa);
        let mut ordinary = regex.ordinary_session().unwrap();
        assert!(matches!(
            &ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa { .. }
        ));
        let haystack = b"zzababa";
        for start in 0..=haystack.len() {
            let expected = regex
                .find_at_value(haystack, start, SearchLimits::unlimited())
                .unwrap();
            assert_eq!(ordinary.find_at(haystack, start), Ok(expected));
            let first = ordinary.first_acceptance_at(haystack, start).unwrap();
            assert_eq!(first.is_some(), expected.is_some());
            if let (Some(first), Some(selected)) = (first, expected) {
                assert!(first > start);
                assert!(first <= selected.end());
            }
            if start == 0 {
                assert_eq!(first, Some(3));
            }
            assert_eq!(ordinary.is_match_at(haystack, start), Ok(expected.is_some()));

            let mut expected_spans = Vec::new();
            let mut cursor = start;
            while let Some(matched) = regex
                .find_at_value(haystack, cursor, SearchLimits::unlimited())
                .unwrap()
            {
                expected_spans.push((matched.start(), matched.end()));
                cursor = matched.end();
            }
            let mut actual_spans = Vec::new();
            assert_eq!(
                ordinary
                    .try_visit_spans_at(haystack, start, |matched| {
                        actual_spans.push((matched.start(), matched.end()));
                        Ok::<bool, ()>(true)
                    })
                    .unwrap(),
                Ok(()),
            );
            assert_eq!(actual_spans, expected_spans);
            assert_eq!(
                ordinary.count_positive_width_selected_ends_at(haystack, start),
                Ok(Some(u64::try_from(expected_spans.len()).unwrap())),
            );
        }

        let mut stopped = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(haystack, |matched| {
                    stopped.push((matched.start(), matched.end()));
                    Ok::<bool, &'static str>(false)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(stopped, [(2, 4)]);
        assert_eq!(
            ordinary
                .try_visit_spans(haystack, |_| Err::<bool, _>("callback"))
                .unwrap(),
            Err("callback"),
        );

        let mut callback_called = false;
        assert!(matches!(
            ordinary.try_visit_spans_at(haystack, haystack.len() + 1, |_| {
                callback_called = true;
                Ok::<bool, ()>(true)
            }),
            Err(PortableFindIterError::Search(
                SearchError::LiteralSetDfa(LiteralSetError::InvalidWindow {
                    start: 8,
                    end: 7,
                    haystack_len: 7,
                })
            )),
        ));
        assert!(!callback_called);

        assert!(matches!(
            ordinary.count_positive_width_selected_ends_at(haystack, usize::MAX),
            Err(SearchError::LiteralSetDfa(LiteralSetError::InvalidWindow {
                start: usize::MAX,
                end: 7,
                haystack_len: 7,
            })),
        ));
        assert!(matches!(
            ordinary.find_at(haystack, haystack.len() + 1),
            Err(SearchError::LiteralSetDfa(LiteralSetError::InvalidWindow {
                start: 8,
                end: 7,
                haystack_len: 7,
            })),
        ));
    }

    #[test]
    fn ordinary_uniform_standard_dfa_bounds_session_local_direct_probes() {
        let source = (0..=128)
            .map(|index| format!("p{index:03}"))
            .collect::<Vec<_>>()
            .join("|");
        let regex = PortableBuilder::new(&source)
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::LiteralSetDfa);
        let mut ordinary = regex.ordinary_session().unwrap();
        let direct_next = |session: &super::PortableOrdinarySession<'_>| match &session.plan {
            super::PortableOrdinarySessionPlan::LiteralSetUniformStandardDfa {
                executor,
                direct_next,
            } => {
                assert_eq!(executor.pattern_bytes(), 4);
                *direct_next
            }
            other => panic!("uniform literal set did not bind its sealed executor: {other:?}"),
        };

        let near = b"p000zzzz";
        let nonzero = b"xxp001zz";
        let distinct = b"p002yyyy";
        let miss = b"zzzzzzzz";
        let far = b"zzzzzzzzp000";
        let seeded_tail = b"p000p001p002";
        let mut exact_probe_edge = vec![b'z'; 36];
        exact_probe_edge[28..32].copy_from_slice(b"p003");
        let mut crossing_probe_edge = vec![b'z'; 36];
        crossing_probe_edge[29..33].copy_from_slice(b"p004");
        let mut long = vec![b'z'; super::LITERAL_SET_DFA_DIRECT_MAX_PROBE_BYTES + 1];
        long[..4].copy_from_slice(b"p000");
        let mut long_crossing = vec![b'z'; super::LITERAL_SET_DFA_DIRECT_MAX_PROBE_BYTES + 1];
        long_crossing[29..33].copy_from_slice(b"p005");
        let long_miss = vec![b'z'; super::LITERAL_SET_DFA_DIRECT_MAX_PROBE_BYTES + 1];

        super::literal_set_dfa_ordinary_route_probe::reset();
        assert!(!direct_next(&ordinary));

        // An exhaustive dense span call learns the next-call route even when
        // it starts cold. This is the first-line case for an embedding that
        // retains one ordinary session across successive lines.
        let mut cold_spans = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(seeded_tail, |matched| {
                    cold_spans.push((matched.start(), matched.end()));
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(cold_spans, [(0, 4), (4, 8), (8, 12)]);
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(miss, 0), Ok(None));
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (0, 1));
        assert!(!direct_next(&ordinary));
        super::literal_set_dfa_ordinary_route_probe::reset();

        // A first near result is prefiltered and promotes exactly its
        // successor. Another near result may re-promote the following call.
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (1, 0));
        assert_eq!(ordinary.is_match_at(near, 0), Ok(true));
        assert!(direct_next(&ordinary));
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (1, 1));

        // The route bit contains no source identity. It is safe to spend and
        // refresh across distinct haystacks and a nonzero search start.
        assert_eq!(
            ordinary.find_at(nonzero, 2),
            Ok(Some(Match { start: 2, end: 6 }))
        );
        assert!(direct_next(&ordinary));
        assert_eq!(
            ordinary.find_at(distinct, 0),
            Ok(Some(Match { start: 0, end: 4 }))
        );
        assert!(direct_next(&ordinary));

        // A direct miss replays the authoritative prefiltered search and
        // immediately demotes.
        assert_eq!(ordinary.first_acceptance_at(miss, 0), Ok(None));
        assert!(!direct_next(&ordinary));
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (1, 4));

        // An acceptance exactly at 8W is inside the direct probe. An
        // acceptance at 8W+1 crosses its edge and is recovered by replaying
        // the canonical selected-span search from the original start.
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert_eq!(
            ordinary.find_at(&exact_probe_edge, 0),
            Ok(Some(Match { start: 28, end: 32 }))
        );
        assert!(!direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert_eq!(
            ordinary.find_at(&crossing_probe_edge, 0),
            Ok(Some(Match { start: 29, end: 33 }))
        );
        assert!(!direct_next(&ordinary));

        // A far direct result is semantically authoritative but does not
        // promote another direct probe.
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(far, 0), Ok(Some(12)));
        assert!(!direct_next(&ordinary));

        // A long remaining window may spend prior evidence, but its direct
        // work is still bounded by 8W and 256 bytes. A near direct hit may
        // refresh the bit; a bounded miss replays canonically and demotes.
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(&long, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert_eq!(
            ordinary.find_at(&long_crossing, 0),
            Ok(Some(Match { start: 29, end: 33 }))
        );
        assert!(!direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(&long_miss, 0), Ok(None));
        assert!(!direct_next(&ordinary));

        // Errors discard stale evidence.
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert!(matches!(
            ordinary.first_acceptance_at(near, near.len() + 1),
            Err(SearchError::LiteralSetDfa(
                LiteralSetError::InvalidWindow { .. }
            )),
        ));
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));
        assert_eq!(
            ordinary.find_at(near, 0),
            Ok(Some(Match { start: 0, end: 4 }))
        );
        assert!(direct_next(&ordinary));
        assert_eq!(
            ordinary.find_at(far, 0),
            Ok(Some(Match { start: 8, end: 12 }))
        );
        assert!(!direct_next(&ordinary));

        // Exhaustive span iteration may carry a source-free recommendation
        // when both its final selected-end spacing and terminal gap are near.
        assert_eq!(
            ordinary.find_at(seeded_tail, 0),
            Ok(Some(Match { start: 0, end: 4 }))
        );
        assert!(direct_next(&ordinary));
        let mut seeded_spans = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans_at(seeded_tail, 4, |matched| {
                    seeded_spans.push((matched.start(), matched.end()));
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(seeded_spans, [(4, 8), (8, 12)]);
        assert!(direct_next(&ordinary));

        // The carried bit is spent on exactly one bounded probe even when the
        // next operation uses a distinct haystack.
        super::literal_set_dfa_ordinary_route_probe::reset();
        assert_eq!(
            ordinary.find_at(distinct, 0),
            Ok(Some(Match { start: 0, end: 4 }))
        );
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (0, 1));
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(miss, 0), Ok(None));
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        let mut spans = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(near, |matched| {
                    spans.push((matched.start(), matched.end()));
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(spans, [(0, 4)]);
        assert!(direct_next(&ordinary));

        super::literal_set_dfa_ordinary_route_probe::reset();
        assert_eq!(ordinary.first_acceptance_at(distinct, 0), Ok(Some(4)));
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (0, 1));
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(miss, 0), Ok(None));
        assert!(!direct_next(&ordinary));

        // A far final acceptance and an artificial-edge miss both discard the
        // predecessor observation, even if the visitor exhausts its window.
        let far_iteration = b"zzzzzzzzp000zzzz";
        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        let mut far_spans = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(far_iteration, |matched| {
                    far_spans.push((matched.start(), matched.end()));
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(far_spans, [(8, 12)]);
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        let mut truncated_callback_called = false;
        assert_eq!(
            ordinary
                .try_visit_spans(&long_miss, |_| {
                    truncated_callback_called = true;
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(()),
        );
        assert!(!truncated_callback_called);
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        let mut stopped = 0;
        assert_eq!(
            ordinary
                .try_visit_spans(near, |_| {
                    stopped += 1;
                    Ok::<bool, ()>(false)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(stopped, 1);
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert_eq!(
            ordinary
                .try_visit_spans(near, |_| Err::<bool, _>("callback"))
                .unwrap(),
            Err("callback"),
        );
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        let mut callback_called = false;
        assert!(ordinary
            .try_visit_spans_at(near, near.len() + 1, |_| {
                callback_called = true;
                Ok::<bool, ()>(true)
            })
            .is_err());
        assert!(!callback_called);
        assert!(!direct_next(&ordinary));

        // Native count also learns the next-call route from a cold exhaustive
        // dense call, without asking the embedding to retry with spans.
        assert!(!direct_next(&ordinary));
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(seeded_tail, 0),
            Ok(Some(3)),
        );
        assert!(direct_next(&ordinary));
        assert_eq!(ordinary.first_acceptance_at(miss, 0), Ok(None));
        assert!(!direct_next(&ordinary));

        // A seeded tail count publishes the same exhaustive recommendation.
        assert_eq!(
            ordinary.find_at(seeded_tail, 0),
            Ok(Some(Match { start: 0, end: 4 }))
        );
        assert!(direct_next(&ordinary));
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(seeded_tail, 4),
            Ok(Some(2)),
        );
        assert!(direct_next(&ordinary));

        super::literal_set_dfa_ordinary_route_probe::reset();
        assert_eq!(ordinary.first_acceptance_at(distinct, 0), Ok(Some(4)));
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (0, 1));
        assert!(direct_next(&ordinary));

        // A match-free call cannot perpetuate an old source-free observation.
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(seeded_tail, 12),
            Ok(Some(0)),
        );
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(direct_next(&ordinary));

        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(&long_miss, 0),
            Ok(Some(0)),
        );
        assert!(!direct_next(&ordinary));

        assert_eq!(ordinary.first_acceptance_at(near, 0), Ok(Some(4)));
        assert!(matches!(
            ordinary.count_positive_width_selected_ends_at(near, usize::MAX),
            Err(SearchError::LiteralSetDfa(
                LiteralSetError::InvalidWindow { .. }
            )),
        ));
        assert!(!direct_next(&ordinary));
    }

    #[cfg(target_arch = "aarch64")]
    #[test]
    fn ordinary_literal_set_dfa_prepares_arbitrary_ascii_roots_for_exists_only() {
        let source = [
            "0", "2", "4", "6", "8", "A", "C", "E", "G", "I", "a", "c", "e", "g", "i", "k",
        ]
        .into_iter()
        .flat_map(|root| (4_usize..=20).map(move |width| root.repeat(width)))
        .collect::<Vec<_>>()
        .join("|");
        let regex = PortableBuilder::new(&source)
            .unicode(false)
            .limits(BuildLimits {
                packed_literal_set: fre_kernels::PackedLiteralSetBuildLimits {
                    max_patterns: 0,
                    ..fre_kernels::PackedLiteralSetBuildLimits::default()
                },
                ..BuildLimits::default()
            })
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::LiteralSetDfa);
        super::literal_set_dfa_ordinary_exists_bind_probe::reset();
        let mut ordinary = regex.ordinary_session().unwrap();
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 0);
        assert!(matches!(
            &ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa {
                ascii_exists: super::PortableOrdinaryLiteralSetExists::Unbound,
                ..
            }
        ));

        let matched_start = 32 + 19;
        let mut haystack = vec![b'!'; 32 + 128 + 16];
        haystack[matched_start..matched_start + 4].copy_from_slice(b"AAAA");
        // Selected-span and count projections work without binding the Exists
        // sidecar or preparing its qualified root classifier.
        assert_eq!(
            ordinary.find_at(&haystack, 0),
            Ok(Some(Match {
                start: matched_start,
                end: matched_start + 4,
            })),
        );
        let mut visited = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(&haystack, |matched| {
                    visited.push(matched);
                    Ok::<bool, ()>(true)
                })
                .unwrap(),
            Ok(()),
        );
        assert_eq!(
            visited,
            [Match {
                start: matched_start,
                end: matched_start + 4,
            }],
        );
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(&haystack, 0),
            Ok(Some(1)),
        );
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 0);
        assert!(matches!(
            &ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa {
                ascii_exists: super::PortableOrdinaryLiteralSetExists::Unbound,
                ..
            }
        ));
        assert_eq!(ordinary.is_match_at(&haystack, 0), Ok(true));
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 1);
        assert!(matches!(
            &ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa {
                ascii_exists: super::PortableOrdinaryLiteralSetExists::Bound(_),
                ..
            }
        ));
        assert_eq!(
            ordinary.first_acceptance_at(&haystack, 0),
            Ok(Some(matched_start + 4)),
        );
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 1);
    }

    #[test]
    fn ordinary_nonuniform_literal_set_routes_shortest_to_first_acceptance() {
        let regex = PortableBuilder::new("b|abc|ab")
            .unicode(false)
            .limits(BuildLimits {
                packed_literal_set: fre_kernels::PackedLiteralSetBuildLimits {
                    max_patterns: 0,
                    ..fre_kernels::PackedLiteralSetBuildLimits::default()
                },
                ..BuildLimits::default()
            })
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::LiteralSetDfa);
        super::literal_set_dfa_ordinary_exists_bind_probe::reset();
        let mut ordinary = regex.ordinary_session().unwrap();
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 0);
        let super::PortableOrdinarySessionPlan::LiteralSetDfa { executor, .. } = &ordinary.plan
        else {
            panic!("nonuniform literal set did not bind its ordinary executor");
        };
        assert_eq!(
            executor.selected_end_window_value(b"abc", LiteralWindow::new(0, 3)),
            Ok(Some(3)),
        );
        assert_eq!(
            ordinary.find_at(b"abc", 0),
            Ok(Some(Match { start: 0, end: 3 })),
        );
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(b"abc", 0),
            Ok(Some(1)),
        );
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 0);

        assert_eq!(ordinary.first_acceptance_at(b"abc", 0), Ok(Some(2)));
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 1);
        assert!(matches!(
            &ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa {
                ascii_exists: super::PortableOrdinaryLiteralSetExists::Unavailable,
                ..
            }
        ));
        assert_eq!(ordinary.shortest_match_at(b"abc", 0), Ok(Some(2)));
        assert_eq!(ordinary.is_match_at(b"abc", 0), Ok(true));
        assert_eq!(super::literal_set_dfa_ordinary_exists_bind_probe::calls(), 1);
        assert_eq!(
            ordinary.find_at(b"abc", 0),
            Ok(Some(Match { start: 0, end: 3 })),
        );
        assert!(matches!(
            ordinary.shortest_match_at(b"abc", 4),
            Err(SearchError::LiteralSetDfa(
                LiteralSetError::InvalidWindow { .. }
            )),
        ));
    }

    #[test]
    fn ordinary_nonuniform_and_unprefiltered_dfas_never_bind_direct_route() {
        let nonuniform = PortableBuilder::new("ab|a|ba")
            .unicode(false)
            .limits(BuildLimits {
                packed_literal_set: fre_kernels::PackedLiteralSetBuildLimits {
                    max_patterns: 0,
                    ..fre_kernels::PackedLiteralSetBuildLimits::default()
                },
                ..BuildLimits::default()
            })
            .build()
            .unwrap();
        let mut ordinary = nonuniform.ordinary_session().unwrap();
        assert!(matches!(
            ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa { .. }
        ));
        super::literal_set_dfa_ordinary_route_probe::reset();
        assert_eq!(ordinary.first_acceptance_at(b"zzab", 0), Ok(Some(3)));
        assert_eq!(ordinary.is_match_at(b"zzab", 0), Ok(true));
        assert_eq!(
            ordinary.find_at(b"zzab", 0),
            Ok(Some(Match { start: 2, end: 4 })),
        );
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(b"zzababa", 0),
            Ok(Some(3)),
        );
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (0, 0));

        let source = (0_u8..=u8::MAX)
            .map(|byte| format!(r"\x{byte:02X}\x{byte:02X}"))
            .collect::<Vec<_>>()
            .join("|");
        let no_prefilter = PortableBuilder::new(&source)
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(no_prefilter.build_report().plan, PlanKind::LiteralSetDfa);
        let mut ordinary = no_prefilter.ordinary_session().unwrap();
        assert!(matches!(
            ordinary.plan,
            super::PortableOrdinarySessionPlan::LiteralSetDfa { .. }
        ));
        super::literal_set_dfa_ordinary_route_probe::reset();
        assert_eq!(ordinary.first_acceptance_at(b"z\x01\x01", 0), Ok(Some(3)));
        assert_eq!(ordinary.is_match_at(b"z\x01\x01", 0), Ok(true));
        assert_eq!(
            ordinary.count_positive_width_selected_ends_at(b"z\x01\x01\x02\x02", 0),
            Ok(Some(2)),
        );
        assert_eq!(super::literal_set_dfa_ordinary_route_probe::calls(), (0, 0));
    }

    #[test]
    fn ordinary_k0_span_visitor_starts_directly_and_makes_byte_empty_progress() {
        let regex = PortableBuilder::new("a*")
            .unicode(false)
            .plan_selection(PlanSelection::ForceK0)
            .build()
            .unwrap();
        let mut ordinary = regex.ordinary_session().unwrap();

        let mut visited = Vec::new();
        assert_eq!(
            ordinary
                .try_visit_spans(b"bbb", |matched| {
                    visited.push((matched.start(), matched.end()));
                    Ok::<bool, &'static str>(true)
                })
                .unwrap(),
            Ok(())
        );
        assert_eq!(visited, [(0, 0), (1, 1), (2, 2), (3, 3)]);

        visited.clear();
        assert_eq!(
            ordinary
                .try_visit_spans_at(b"bbb", 1, |matched| {
                    visited.push((matched.start(), matched.end()));
                    Ok::<bool, &'static str>(true)
                })
                .unwrap(),
            Ok(())
        );
        assert_eq!(visited, [(1, 1), (2, 2), (3, 3)]);

        visited.clear();
        assert_eq!(
            ordinary
                .try_visit_spans(b"aaa", |matched| {
                    visited.push((matched.start(), matched.end()));
                    Ok::<bool, &'static str>(true)
                })
                .unwrap(),
            Ok(())
        );
        assert_eq!(visited, [(0, 3)]);

        let mut callbacks = 0;
        assert_eq!(
            ordinary
                .try_visit_spans(b"bbb", |_| {
                    callbacks += 1;
                    Ok::<bool, &'static str>(false)
                })
                .unwrap(),
            Ok(())
        );
        assert_eq!(callbacks, 1, "the first item is delivered directly");
        assert_eq!(
            ordinary
                .try_visit_spans(b"bbb", |_| Err::<bool, _>("callback"))
                .unwrap(),
            Err("callback")
        );
        assert_eq!(
            ordinary.find_at(b"aaa", 0),
            Ok(Some(Match { start: 0, end: 3 }))
        );

        let mut callback_called = false;
        assert!(matches!(
            ordinary.try_visit_spans_at(b"bbb", 4, |_| {
                callback_called = true;
                Ok::<bool, &'static str>(true)
            }),
            Err(PortableFindIterError::Search(SearchError::K0(
                fre_automata::SearchError::InvalidWindow {
                    start: 4,
                    end: 3,
                    haystack_len: 3,
                }
            )))
        ));
        assert!(!callback_called);
    }

    #[test]
    fn direct_native_sessions_bind_selected_plans_without_layout_growth() {
        #[allow(
            dead_code,
            reason = "the test-only baseline pins the two-variant session layout"
        )]
        enum BaselinePortableSearchSessionPlan<'a> {
            Native(&'a PortableRegex),
            K0 {
                session: fre_automata::K0SearchSession<'a>,
                aggregate_setup: super::SearchSessionSetupAccounting,
                k0_plan: &'a super::PortableK0Plan,
                line_total_grep_plan: Option<super::line_total_grep::Plan>,
                reverse_inner:
                    Option<Box<super::k0_general_reverse_inner::SearchSession<'a>>>,
                lazy_delimited_repeat: Option<&'a super::lazy_delimited_repeat::Plan>,
                greedy_class_literal_tail: Option<&'a super::greedy_class_literal_tail::Plan>,
                mandatory_suffix: Option<&'a super::K0MandatorySuffixPlan>,
                mandatory_cut: Option<&'a super::K0MandatoryCutPlan>,
                negative_prefilter: Option<&'a super::K0NegativePrefilterPlan>,
                exclusive_route_state: super::K0ExclusiveRouteState,
                mandatory_suffix_exists_state: super::K0NegativePrefilterState,
                mandatory_suffix_span_state: super::K0NegativePrefilterState,
                negative_prefilter_exists_state: super::K0NegativePrefilterState,
                negative_prefilter_span_state: super::K0NegativePrefilterState,
            },
        }

        let regex = PortableBuilder::new("needle")
            .unicode(false)
            .build()
            .unwrap();
        let zero_setup = SearchSessionLimits {
            max_setup_work: 0,
            max_scratch_bytes: 0,
        };
        let mut session = regex.search_session(zero_setup).unwrap();
        let PortableSearchSessionPlan::ExactLiteral {
            regex: bound_regex,
            plan: bound_plan,
        } = &session.plan
        else {
            panic!("exact literal did not bind its direct session variant")
        };
        let PortablePlan::ExactLiteral(owner_plan) = &regex.plan else {
            unreachable!()
        };
        assert!(core::ptr::eq(*bound_regex, &regex));
        assert!(core::ptr::eq(*bound_plan, owner_plan));
        assert_eq!(session.runtime_implementation_id(), "exact-literal");
        assert_eq!(session.workspace_setup_accounting(), None);
        let endpoint = regex.endpoint_search_session(zero_setup).unwrap();
        assert!(matches!(
            &endpoint.plan,
            PortableSearchSessionPlan::ExactLiteral { .. }
        ));
        assert_eq!(endpoint.workspace_setup_accounting(), None);
        let matches = session.find_iter(
            b"needle",
            PortableFindIterRunLimits::unlimited(),
        );
        assert!(matches!(
            &matches.state,
            super::PortableMatchIterState::General(_)
        ));
        drop(matches);
        let value_matches = session.find_iter_value(
            b"needle",
            PortableFindIterRunLimits::unlimited(),
        );
        assert!(matches!(
            &value_matches.state,
            super::PortableValueMatchIterState::General(_)
        ));
        drop(value_matches);

        let fixed = fixed_predicate_regex(r"[ab][cd][ef]");
        let mut fixed_session = fixed.search_session(zero_setup).unwrap();
        let PortableSearchSessionPlan::FixedPredicateWord64 {
            regex: bound_regex,
            plan: bound_plan,
        } = &fixed_session.plan
        else {
            panic!("fixed predicate did not bind its direct session variant")
        };
        let PortablePlan::FixedPredicateWord64(owner_plan) = &fixed.plan else {
            unreachable!()
        };
        assert!(core::ptr::eq(*bound_regex, &fixed));
        assert!(core::ptr::eq(*bound_plan, owner_plan.as_ref()));
        assert_eq!(
            fixed_session.runtime_implementation_id(),
            super::FIXED_PREDICATE_WORD64_SEARCH_PLAN_ID,
        );
        assert_eq!(fixed_session.workspace_setup_accounting(), None);
        let fixed_endpoint = fixed.endpoint_search_session(zero_setup).unwrap();
        assert!(matches!(
            &fixed_endpoint.plan,
            PortableSearchSessionPlan::FixedPredicateWord64 { .. }
        ));
        assert_eq!(fixed_endpoint.workspace_setup_accounting(), None);
        let fixed_matches = fixed_session.find_iter(
            b"acebdf",
            PortableFindIterRunLimits::unlimited(),
        );
        assert!(fixed_matches.state.is_fixed_predicate());
        drop(fixed_matches);
        let fixed_value_matches = fixed_session.find_iter_value(
            b"acebdf",
            PortableFindIterRunLimits::unlimited(),
        );
        assert!(fixed_value_matches.state.is_fixed_predicate());
        drop(fixed_value_matches);

        assert_eq!(
            core::mem::size_of::<PortableSearchSessionPlan<'static>>(),
            core::mem::size_of::<BaselinePortableSearchSessionPlan<'static>>(),
            "binding a second reference must fit inside the existing K0-led enum layout",
        );
        assert_eq!(
            core::mem::align_of::<PortableSearchSessionPlan<'static>>(),
            core::mem::align_of::<BaselinePortableSearchSessionPlan<'static>>(),
        );
        assert_eq!(
            core::mem::size_of::<PortableSearchSession<'static>>(),
            core::mem::size_of::<PortableSearchSessionPlan<'static>>(),
        );
    }

    #[test]
    fn exact_literal_session_exhaustively_matches_its_owner_routes() {
        let patterns = words(2);
        let haystacks = words(3);
        for pattern in &patterns {
            let pattern = core::str::from_utf8(pattern).unwrap();
            let regex = PortableBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap_or_else(|error| panic!("pattern={pattern:?}: {error:?}"));
            assert_eq!(regex.build_report().plan, PlanKind::ExactLiteral);
            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            let mut session = regex
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    let mut source = K0SpanSourceCursor::new(haystack);
                    assert_eq!(
                        session
                            .find_iter_at(
                                &mut source,
                                start,
                                SearchLimits::unlimited(),
                            )
                            .map(|(matched, accounting)| {
                                (matched, accounting.work_or_linear_terms)
                            }),
                        regex.find_iter_at(haystack, start, SearchLimits::unlimited()),
                        "iterator pattern={pattern:?}, haystack={haystack:?}, start={start}",
                    );
                    assert_eq!(
                        session.find_at(haystack, start, SearchLimits::unlimited()),
                        regex.find_at(haystack, start, SearchLimits::unlimited()),
                    );
                    assert_eq!(
                        session.find_at_value(haystack, start, SearchLimits::unlimited()),
                        regex.find_at_value(haystack, start, SearchLimits::unlimited()),
                    );
                    assert_eq!(
                        session.is_match_at(haystack, start, SearchLimits::unlimited()),
                        regex.is_match_at(haystack, start, SearchLimits::unlimited()),
                    );
                    assert_eq!(
                        session.is_match_value_at(
                            haystack,
                            start,
                            SearchLimits::unlimited(),
                        ),
                        regex.is_match_value_at(
                            haystack,
                            start,
                            SearchLimits::unlimited(),
                        ),
                    );
                }
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        assert_eq!(
                            session.is_match_window(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                            regex.is_match_window(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                        );
                        assert_eq!(
                            session.is_match_window_value(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                            regex.is_match_window_value(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                        );
                        assert_eq!(
                            session.find_window(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                            regex.find_window(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                        );
                        assert_eq!(
                            session.find_window_value(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                            regex.find_window_value(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                        );
                        let expected_shortest = regex.shortest_match_window(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        );
                        assert_eq!(
                            session.shortest_match_window(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                            expected_shortest,
                        );
                        assert_eq!(
                            session.shortest_match_window_value(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            ),
                            expected_shortest.map(|(output, _)| output),
                        );
                    }
                }
                assert_eq!(
                    session.selected_end(haystack, SearchLimits::unlimited()),
                    regex.selected_end(haystack, SearchLimits::unlimited()),
                );
                assert_eq!(
                    session.selected_end_value(haystack, SearchLimits::unlimited()),
                    regex.selected_end(haystack, SearchLimits::unlimited())
                        .map(|(output, _)| output),
                );

                let expected: Vec<_> = upstream
                    .find_iter(haystack)
                    .map(|matched| (matched.start(), matched.end()))
                    .collect();
                let actual: Vec<_> = session
                    .find_iter(haystack, PortableFindIterRunLimits::unlimited())
                    .map(|matched| {
                        let matched = matched.unwrap();
                        (matched.start(), matched.end())
                    })
                    .collect();
                assert_eq!(actual, expected, "pattern={pattern:?}, haystack={haystack:?}");
                let actual_value: Vec<_> = session
                    .find_iter_value(haystack, PortableFindIterRunLimits::unlimited())
                    .map(|matched| {
                        let matched = matched.unwrap();
                        (matched.start(), matched.end())
                    })
                    .collect();
                assert_eq!(
                    actual_value, expected,
                    "value pattern={pattern:?}, haystack={haystack:?}",
                );
            }
        }
    }

    #[test]
    fn exact_literal_session_refuses_at_the_owner_boundary_before_search() {
        let regex = PortableBuilder::new("needle")
            .unicode(false)
            .build()
            .unwrap();
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let haystack = b"zzneedlexx";
        let refused = SearchLimits {
            max_work: 15,
            max_scratch_bytes: 0,
        };
        let expected = SearchError::ExactLiteral(
            fre_kernels::LiteralError::LinearTermLimit {
                needed: 16,
                limit: 15,
            },
        );
        assert_eq!(session.find(haystack, refused), Err(expected.clone()));
        assert_eq!(session.find_value(haystack, refused), Err(expected.clone()));
        assert_eq!(session.is_match(haystack, refused), Err(expected.clone()));
        assert_eq!(session.is_match_value(haystack, refused), Err(expected.clone()));
        assert_eq!(
            session.shortest_match(haystack, refused),
            Err(expected.clone()),
        );
        assert_eq!(
            session.shortest_match_value(haystack, refused),
            Err(expected.clone()),
        );
        assert_eq!(
            session.selected_end(haystack, refused),
            Err(expected.clone()),
        );
        assert_eq!(
            session.selected_end_value(haystack, refused),
            Err(expected.clone()),
        );
        assert_eq!(regex.find_accounted(haystack, refused), Err(expected.clone()));

        for window in [
            SearchWindow::new(4, 3),
            SearchWindow::new(0, haystack.len() + 1),
        ] {
            assert_eq!(
                session.find_window(haystack, window, SearchLimits::unlimited()),
                regex.find_window(haystack, window, SearchLimits::unlimited()),
            );
            assert_eq!(
                session.find_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
                regex.find_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
            );
            assert_eq!(
                session.is_match_window(haystack, window, SearchLimits::unlimited()),
                regex.is_match_window(haystack, window, SearchLimits::unlimited()),
            );
            assert_eq!(
                session.shortest_match_window(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
                regex.shortest_match_window(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
            );
        }

        let mut refused_iter = session.find_iter(
            haystack,
            PortableFindIterRunLimits {
                search: refused,
                max_search_calls: usize::MAX,
            },
        );
        assert_eq!(
            refused_iter.next(),
            Some(Err(PortableFindIterError::Search(expected))),
        );
        assert_eq!(refused_iter.next(), None);
        drop(refused_iter);
        assert_eq!(
            session.find_value(haystack, SearchLimits::unlimited()),
            Ok(Some(Match { start: 2, end: 8 })),
            "a refusal must not retain any source-dependent session state",
        );
        let mut reused = haystack.to_vec();
        let address = reused.as_ptr();
        assert_eq!(
            session.find_value(&reused, SearchLimits::unlimited()),
            Ok(Some(Match { start: 2, end: 8 })),
        );
        reused.fill(b'x');
        assert_eq!(reused.as_ptr(), address);
        assert_eq!(
            session.find_value(&reused, SearchLimits::unlimited()),
            Ok(None),
            "the plan-bound session must not retain same-address source results",
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "every direct fixed-predicate session projection is compared with its owner"
    )]
    fn fixed_predicate_session_exhaustively_matches_its_owner_routes() {
        let regex = fixed_predicate_regex(r"[ab][cd][ef]");
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let haystacks = byte_words(b"acefx", 3);
        for haystack in &haystacks {
            for start in 0..=haystack.len() {
                let mut source = K0SpanSourceCursor::new(haystack);
                assert_eq!(
                    session
                        .find_iter_at(
                            &mut source,
                            start,
                            SearchLimits::unlimited(),
                        )
                        .map(|(matched, accounting)| {
                            (matched, accounting.work_or_linear_terms)
                        }),
                    regex.find_iter_at(haystack, start, SearchLimits::unlimited()),
                    "iterator haystack={haystack:?}, start={start}",
                );
                assert_eq!(
                    session.find_at(haystack, start, SearchLimits::unlimited()),
                    regex.find_at(haystack, start, SearchLimits::unlimited()),
                );
                assert_eq!(
                    session.find_at_value(haystack, start, SearchLimits::unlimited()),
                    regex.find_at_value(haystack, start, SearchLimits::unlimited()),
                );
                assert_eq!(
                    session.is_match_at(haystack, start, SearchLimits::unlimited()),
                    regex.is_match_at(haystack, start, SearchLimits::unlimited()),
                );
                assert_eq!(
                    session.is_match_value_at(
                        haystack,
                        start,
                        SearchLimits::unlimited(),
                    ),
                    regex.is_match_value_at(
                        haystack,
                        start,
                        SearchLimits::unlimited(),
                    ),
                );
                assert_eq!(
                    session.shortest_match_at(
                        haystack,
                        start,
                        SearchLimits::unlimited(),
                    ),
                    regex.shortest_match_at(
                        haystack,
                        start,
                        SearchLimits::unlimited(),
                    ),
                );
                assert_eq!(
                    session.shortest_match_at_value(
                        haystack,
                        start,
                        SearchLimits::unlimited(),
                    ),
                    regex.shortest_match_at_value(
                        haystack,
                        start,
                        SearchLimits::unlimited(),
                    ),
                );
            }
            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let window = SearchWindow::new(start, end);
                    assert_eq!(
                        session.is_match_window(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                        regex.is_match_window(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                    );
                    assert_eq!(
                        session.is_match_window_value(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                        regex.is_match_window_value(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                    );
                    assert_eq!(
                        session.find_window(haystack, window, SearchLimits::unlimited()),
                        regex.find_window(haystack, window, SearchLimits::unlimited()),
                    );
                    assert_eq!(
                        session.find_window_value(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                        regex.find_window_value(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                    );
                    assert_eq!(
                        session.shortest_match_window(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                        regex.shortest_match_window(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                    );
                    assert_eq!(
                        session.shortest_match_window_value(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                        regex.shortest_match_window_value(
                            haystack,
                            window,
                            SearchLimits::unlimited(),
                        ),
                    );
                }
            }
            assert_eq!(
                session.selected_end(haystack, SearchLimits::unlimited()),
                regex.selected_end(haystack, SearchLimits::unlimited()),
            );
            assert_eq!(
                session.selected_end_value(haystack, SearchLimits::unlimited()),
                regex.selected_end_value(haystack, SearchLimits::unlimited()),
            );
        }

        let other = fixed_predicate_regex(r"[xy][xy][xy]");
        let mut other_session = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let shared = b"acexxx";
        assert_eq!(
            session.find_value(shared, SearchLimits::unlimited()),
            Ok(Some(Match { start: 0, end: 3 })),
        );
        assert_eq!(
            other_session.find_value(shared, SearchLimits::unlimited()),
            Ok(Some(Match { start: 3, end: 6 })),
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "finite work, invalid windows and iterator fusion share one exact owner oracle"
    )]
    fn fixed_predicate_session_preserves_limits_errors_and_source_freshness() {
        let regex = fixed_predicate_regex(r"[ab][cd][ef]");
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let haystack = b"xxaceace";
        let (_, accounting) = regex
            .find_accounted(haystack, SearchLimits::unlimited())
            .unwrap();
        let SearchAccounting::FixedPredicateWord64(accounting) = accounting else {
            panic!("fixed owner lost its search accounting")
        };
        let exact = SearchLimits {
            max_work: accounting.upper_bounds.work,
            max_scratch_bytes: 0,
        };
        let one_below = SearchLimits {
            max_work: accounting.upper_bounds.work.checked_sub(1).unwrap(),
            max_scratch_bytes: 0,
        };
        assert_eq!(
            session.find(haystack, exact),
            regex.find_accounted(haystack, exact)
        );
        assert_eq!(
            session.find_value(haystack, exact),
            regex.find_value(haystack, exact),
        );
        assert_eq!(
            session.is_match(haystack, one_below),
            regex.is_match_accounted(haystack, one_below),
        );
        assert_eq!(
            session.is_match_value(haystack, one_below),
            regex.is_match_value(haystack, one_below),
        );
        assert_eq!(
            session.shortest_match(haystack, one_below),
            regex.shortest_match(haystack, one_below),
        );
        assert_eq!(
            session.shortest_match_value(haystack, one_below),
            regex.shortest_match_value(haystack, one_below),
        );
        assert_eq!(
            session.find(haystack, one_below),
            regex.find_accounted(haystack, one_below),
        );
        assert_eq!(
            session.find_value(haystack, one_below),
            regex.find_value(haystack, one_below),
        );
        assert_eq!(
            session.selected_end(haystack, one_below),
            regex.selected_end(haystack, one_below),
        );
        assert_eq!(
            session.selected_end_value(haystack, one_below),
            regex.selected_end_value(haystack, one_below),
        );

        for window in [
            SearchWindow::new(4, 3),
            SearchWindow::new(0, haystack.len() + 1),
        ] {
            assert_eq!(
                session.find_window(haystack, window, SearchLimits::unlimited()),
                regex.find_window(haystack, window, SearchLimits::unlimited()),
            );
            assert_eq!(
                session.find_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
                regex.find_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
            );
            assert_eq!(
                session.is_match_window(haystack, window, SearchLimits::unlimited()),
                regex.is_match_window(haystack, window, SearchLimits::unlimited()),
            );
            assert_eq!(
                session.is_match_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
                regex.is_match_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
            );
            assert_eq!(
                session.shortest_match_window(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
                regex.shortest_match_window(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
            );
            assert_eq!(
                session.shortest_match_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
                regex.shortest_match_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                ),
            );
        }

        let expected_error = regex.find_accounted(haystack, one_below).unwrap_err();
        let mut refused = session.find_iter(
            haystack,
            PortableFindIterRunLimits {
                search: one_below,
                max_search_calls: usize::MAX,
            },
        );
        assert!(refused.state.is_fixed_predicate());
        assert_eq!(
            refused.next(),
            Some(Err(PortableFindIterError::Search(expected_error.clone()))),
        );
        assert_eq!(refused.next(), None);
        drop(refused);
        let mut refused_value = session.find_iter_value(
            haystack,
            PortableFindIterRunLimits {
                search: one_below,
                max_search_calls: usize::MAX,
            },
        );
        assert!(refused_value.state.is_fixed_predicate());
        assert_eq!(
            refused_value.next(),
            Some(Err(PortableFindIterError::Search(expected_error))),
        );
        assert_eq!(refused_value.next(), None);
        drop(refused_value);

        let mut reused = haystack.to_vec();
        let address = reused.as_ptr();
        assert_eq!(
            session
                .find_iter_value(&reused, PortableFindIterRunLimits::unlimited())
                .next(),
            Some(Ok(Match { start: 2, end: 5 })),
        );
        reused.fill(b'x');
        assert_eq!(reused.as_ptr(), address);
        assert_eq!(
            session
                .find_iter_value(&reused, PortableFindIterRunLimits::unlimited())
                .next(),
            None,
            "a new iterator must bind the mutated source rather than retained masks",
        );
    }

    #[test]
    fn exact_literal_ordinary_facades_match_pinned_bytes_at_boundaries() {
        let cases: &[(&str, &[&[u8]])] = &[
            ("", &[b"", b"a", b"\xff\x80"]),
            ("a", &[b"", b"a", b"\xffa", b"bbb"]),
            ("aba", &[b"ab", b"aba", b"ababa", b"xababax", b"\xffaba"]),
            ("(aba)", &[b"ababa", b"zzaba", b"none"]),
            ("needle", &[b"need", b"needle", b"--needle--", b"\xff\x80"]),
            (r"(?-u:\xFF)", &[b"", b"\xff", b"\x80\xff\0", b"ascii"]),
        ];
        for &(pattern, haystacks) in cases {
            let regex = PortableBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap_or_else(|error| panic!("pattern={pattern:?}: {error:?}"));
            assert_eq!(
                regex.build_report().plan,
                PlanKind::ExactLiteral,
                "pattern={pattern:?}",
            );
            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            for &haystack in haystacks {
                let expected = upstream
                    .find(haystack)
                    .map(|matched| (matched.start(), matched.end()));
                super::exact_literal_ordinary_facade_probe::reset();
                assert_eq!(
                    regex.is_match(haystack),
                    expected.is_some(),
                    "is_match pattern={pattern:?}, haystack={haystack:?}",
                );
                assert_eq!(
                    regex
                        .find(haystack)
                        .map(|matched| (matched.start(), matched.end())),
                    expected,
                    "find pattern={pattern:?}, haystack={haystack:?}",
                );
                assert_eq!(
                    super::exact_literal_ordinary_facade_probe::snapshot(),
                    (1, 1),
                );
            }
        }

        let regex = PortableBuilder::new("needle")
            .unicode(false)
            .build()
            .unwrap();
        let mut reused = b"--needle--".to_vec();
        let address = reused.as_ptr();
        super::exact_literal_ordinary_facade_probe::reset();
        assert!(regex.is_match(&reused));
        assert_eq!(regex.find(&reused), Some(Match { start: 2, end: 8 }));
        reused.fill(b'x');
        assert_eq!(reused.as_ptr(), address);
        assert!(!regex.is_match(&reused));
        assert_eq!(regex.find(&reused), None);
        assert_eq!(
            super::exact_literal_ordinary_facade_probe::snapshot(),
            (2, 2),
            "each ordinary call must inspect the current borrowed source",
        );
    }

    #[test]
    fn exact_literal_ordinary_facade_is_isolated_from_finite_and_reusable_apis() {
        let regex = PortableBuilder::new("needle")
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::ExactLiteral);
        let haystack = b"--needle--";
        let full = SearchWindow::full(haystack);
        let expected = Some(Match { start: 2, end: 8 });

        super::exact_literal_ordinary_facade_probe::reset();
        assert!(regex
            .is_match_value(haystack, SearchLimits::unlimited())
            .unwrap());
        assert_eq!(
            regex
                .find_value(haystack, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert!(regex
            .is_match_accounted(haystack, SearchLimits::unlimited())
            .unwrap()
            .0);
        assert_eq!(
            regex
                .find_accounted(haystack, SearchLimits::unlimited())
                .unwrap()
                .0,
            expected,
        );
        assert!(regex
            .is_match_window_value(haystack, full, SearchLimits::unlimited())
            .unwrap());
        assert_eq!(
            regex
                .find_window_value(haystack, full, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert!(regex
            .is_match_window(haystack, full, SearchLimits::unlimited())
            .unwrap()
            .0);
        assert_eq!(
            regex
                .find_window(haystack, full, SearchLimits::unlimited())
                .unwrap()
                .0,
            expected,
        );

        let refusing = SearchLimits {
            max_work: 15,
            max_scratch_bytes: 0,
        };
        let expected_error = SearchError::ExactLiteral(
            fre_kernels::LiteralError::LinearTermLimit {
                needed: 16,
                limit: 15,
            },
        );
        assert_eq!(
            regex.is_match_value(haystack, refusing),
            Err(expected_error.clone()),
        );
        assert_eq!(
            regex.find_value(haystack, refusing),
            Err(expected_error.clone()),
        );
        assert_eq!(
            regex.find_window_value(
                haystack,
                SearchWindow::new(3, 2),
                SearchLimits {
                    max_work: 0,
                    max_scratch_bytes: 0,
                },
            ),
            Err(SearchError::ExactLiteral(
                fre_kernels::LiteralError::InvalidWindow {
                    start: 3,
                    end: 2,
                    haystack_len: haystack.len(),
                },
            )),
        );

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(session
            .is_match_value(haystack, SearchLimits::unlimited())
            .unwrap());
        assert_eq!(
            session
                .find_value(haystack, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        let mut ordinary = regex.ordinary_session().unwrap();
        assert!(ordinary.is_match_at(haystack, 0).unwrap());
        assert_eq!(ordinary.find_at(haystack, 0).unwrap(), expected);

        let mut locations = regex.capture_locations();
        assert_eq!(
            regex
                .captures_read_value(
                    &mut locations,
                    haystack,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .map(|matched| (matched.start(), matched.end())),
            Some((2, 8)),
        );
        assert_eq!(
            regex
                .captures_read(&mut locations, haystack, SearchLimits::unlimited())
                .unwrap()
                .0
                .map(|matched| (matched.start(), matched.end())),
            Some((2, 8)),
        );
        assert_eq!(
            super::exact_literal_ordinary_facade_probe::snapshot(),
            (0, 0),
            "finite, accounted, windowed, explicit-session, and capture APIs stay canonical",
        );

        assert!(regex.is_match(haystack));
        assert_eq!(regex.find(haystack), expected);
        assert_eq!(
            super::exact_literal_ordinary_facade_probe::snapshot(),
            (1, 1),
        );
    }

    #[test]
    fn exact_literal_plan_exhaustively_matches_the_rebar_baseline() {
        let patterns = words(3);
        let haystacks = words(5);
        for pattern in &patterns {
            let pattern = core::str::from_utf8(pattern).unwrap();
            let fre = PortableBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap_or_else(|error| panic!("pattern={pattern:?}: {error:?}"));
            assert_eq!(fre.build_report().plan, PlanKind::ExactLiteral);
            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            for haystack in &haystacks {
                let expected = upstream
                    .find(haystack)
                    .map(|matched| (matched.start(), matched.end()));
                let (actual, _) = fre
                    .find_accounted(haystack, SearchLimits::unlimited())
                    .unwrap();
                assert_eq!(
                    actual.map(|matched| (matched.start(), matched.end())),
                    expected,
                    "pattern={pattern:?}, haystack={haystack:?}"
                );
                let (exists, _) = fre
                    .is_match_accounted(haystack, SearchLimits::unlimited())
                    .unwrap();
                let (end, _) = fre
                    .selected_end(haystack, SearchLimits::unlimited())
                    .unwrap();
                assert_eq!(exists, expected.is_some());
                assert_eq!(end, expected.map(|(_, end)| end));
            }
        }
    }

