    #[test]
    fn forced_k0_root_run_iterator_reuses_source_bound_masks_and_releases_them_on_drop() {
        let fre = PortableBuilder::new("[aceg]{2}")
            .unicode(false)
            .plan_selection(PlanSelection::ForceK0)
            .build()
            .unwrap();
        assert_eq!(fre.build_report().plan, PlanKind::K0);
        let mut session = fre
            .search_session(super::SearchSessionLimits::unlimited())
            .unwrap();
        let dense = b"acegacegacegacegacegacegacegacegacegacegacegacegacegacegacegaceg";
        let expected: Vec<_> = (0..dense.len())
            .step_by(2)
            .map(|start| (start, start.checked_add(2).unwrap()))
            .collect();

        let fresh: Result<Vec<_>, _> = fre
            .find_iter(dense, PortableFindIterLimits::unlimited())
            .unwrap()
            .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
            .collect();
        assert_eq!(fresh.unwrap(), expected);
        let fresh_value: Result<Vec<_>, _> = fre
            .find_iter_value(dense, PortableFindIterLimits::unlimited())
            .unwrap()
            .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
            .collect();
        assert_eq!(fresh_value.unwrap(), expected);

        let PortableSearchSessionPlan::K0 {
            session: k0_session,
            k0_plan,
            mandatory_suffix: None,
            mandatory_cut: None,
            negative_prefilter: None,
            ..
        } = &session.plan
        else {
            panic!("root-run value fixture unexpectedly retained a facade sidecar");
        };
        assert!(k0_plan.correlated_terminal().is_none());
        assert!(k0_session.retained_root_run_cursor_available());

        {
            let mut matches = session.find_iter(dense, PortableFindIterRunLimits::unlimited());
            let first = matches.next().unwrap().unwrap();
            assert_eq!((first.start(), first.end()), (0, 2));
            let second = matches.next().unwrap().unwrap();
            assert_eq!((second.start(), second.end()), (2, 4));
            let third = matches.next().unwrap().unwrap();
            assert_eq!((third.start(), third.end()), (4, 6));
            let activated_work = matches.accounting().work_or_linear_terms;
            let fourth = matches.next().unwrap().unwrap();
            assert_eq!((fourth.start(), fourth.end()), (6, 8));
            assert_eq!(
                matches
                    .accounting()
                    .work_or_linear_terms
                    .checked_sub(activated_work)
                    .unwrap(),
                3,
                "a retained qualified-start mask needs only the K0 invocation reset"
            );
            // End the iterator borrow early; the next block must start with
            // fresh source-bound cursors while retaining the session itself.
        }

        let restarted: Result<Vec<_>, _> = session
            .find_iter(dense, PortableFindIterRunLimits::unlimited())
            .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
            .collect();
        assert_eq!(
            restarted.unwrap(),
            expected,
            "a new non-fixed K0 iterator must start with fresh source cursors after early drop"
        );

        {
            let mut value_matches =
                session.find_iter_value(dense, PortableFindIterRunLimits::unlimited());
            assert_eq!(
                value_matches.next().unwrap().unwrap(),
                Match { start: 0, end: 2 }
            );
            assert_eq!(
                value_matches.next().unwrap().unwrap(),
                Match { start: 2, end: 4 }
            );
        }
        let restarted_value: Result<Vec<_>, _> = session
            .find_iter_value(dense, PortableFindIterRunLimits::unlimited())
            .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
            .collect();
        assert_eq!(
            restarted_value.unwrap(),
            expected,
            "a new value iterator must restart its source-bound root-run cursor after early drop"
        );

        assert_eq!(
            session
                .find(b"zzaceg", SearchLimits::unlimited())
                .unwrap()
                .0
                .map(|matched| (matched.start(), matched.end())),
            Some((2, 4))
        );
    }

    #[test]
    fn reused_k0_value_iterators_cache_scanner_routes_for_bounded_runs() {
        fn plain_forced_k0(pattern: &str) -> PortableRegex {
            let mut regex = PortableBuilder::new(pattern)
                .unicode(false)
                .plan_selection(PlanSelection::ForceK0)
                .build()
                .unwrap();
            let PortablePlan::K0(plan) = &mut regex.plan else {
                unreachable!("forced value-iterator route fixture must retain K0");
            };
            plan.absolute_end_proof = None;
            plan.exclusive = super::K0ExclusivePlan::None;
            plan.reverse_inner = None;
            plan.mandatory_suffix = None;
            plan.mandatory_cut = None;
            plan.negative_prefilter = None;
            regex
        }

        fn is_source_bound(state: &super::PortableValueMatchIterState<'_, '_>) -> bool {
            matches!(
                state,
                super::PortableValueMatchIterState::Native {
                    cursor: super::PortableNativeSearchCursor::K0SourceBound,
                    ..
                }
            )
        }

        let broad = [
            (r"[\x20-\x60][\x80-\xFF]", [0x40_u8, 0x80]),
            (r"[aceg][\x00-\x40]", [b'a', 0x20]),
            (r"[\x80\x82\xFE\xFF][\x00-\x40]", [0x80, 0x20]),
        ];
        for (pattern, matched_bytes) in broad {
            let regex = plain_forced_k0(pattern);
            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            let mut haystack = vec![b'p'; 128];
            for position in [20_usize, 22, 24, 26] {
                haystack[position..position + 2].copy_from_slice(&matched_bytes);
            }
            let expected = upstream
                .find_iter(&haystack)
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>();
            let mut session = regex
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            let PortableSearchSessionPlan::K0 {
                session: k0_session,
                exclusive_route_state,
                ..
            } = &session.plan
            else {
                unreachable!();
            };
            assert!(!k0_session.retained_root_run_cursor_available());
            assert_eq!(
                exclusive_route_state.value_iter_route(),
                super::K0ValueIterRoute::Unknown
            );

            let cold = session
                .find_iter_value(&haystack, PortableFindIterRunLimits::unlimited());
            assert!(!is_source_bound(&cold.state), "cold pattern={pattern}");
            let actual = cold
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            assert_eq!(actual, expected, "cold pattern={pattern}");

            let warm = session
                .find_iter_value(&haystack, PortableFindIterRunLimits::unlimited());
            assert!(is_source_bound(&warm.state), "warm pattern={pattern}");
            let actual = warm
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            assert_eq!(actual, expected, "warm pattern={pattern}");

            let finite = PortableFindIterRunLimits {
                search: SearchLimits {
                    max_work: u64::MAX - 1,
                    max_scratch_bytes: usize::MAX,
                },
                max_search_calls: usize::MAX,
            };
            let finite_iter = session.find_iter_value(&haystack, finite);
            assert!(
                is_source_bound(&finite_iter.state),
                "finite pattern={pattern}"
            );
            let actual = finite_iter
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            assert_eq!(actual, expected, "finite pattern={pattern}");

            let refused_limits = PortableFindIterRunLimits {
                search: SearchLimits {
                    max_work: 0,
                    max_scratch_bytes: usize::MAX,
                },
                max_search_calls: usize::MAX,
            };
            let mut refused = session.find_iter_value(&haystack, refused_limits);
            assert!(is_source_bound(&refused.state), "refused pattern={pattern}");
            assert!(matches!(
                refused.next(),
                Some(Err(PortableFindIterError::Search(SearchError::K0(
                    fre_automata::SearchError::WorkLimitExceeded { limit: 0, .. }
                ))))
            ));
            assert_eq!(refused.next(), None, "refused pattern={pattern}");
            drop(refused);

            let PortableSearchSessionPlan::K0 {
                exclusive_route_state,
                ..
            } = &session.plan
            else {
                unreachable!();
            };
            assert_eq!(
                exclusive_route_state.value_iter_route(),
                super::K0ValueIterRoute::SourceBound
            );
        }

        for pattern in [
            r"a[\x00-\x40]",
            r"[ac][\x00-\x40]",
            r"[ace][\x00-\x40]",
        ] {
            let regex = plain_forced_k0(pattern);
            let mut session = regex
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            let haystack = b"ppppppppppppppppppppa ppa ppa ppa pppppppppppppppp";
            let cold = session
                .find_iter_value(haystack, PortableFindIterRunLimits::unlimited());
            assert!(!is_source_bound(&cold.state), "cold pattern={pattern}");
            let expected = cold.collect::<Result<Vec<_>, _>>().unwrap();
            let warm = session
                .find_iter_value(haystack, PortableFindIterRunLimits::unlimited());
            assert!(is_source_bound(&warm.state), "warm pattern={pattern}");
            assert_eq!(warm.collect::<Result<Vec<_>, _>>().unwrap(), expected);
            let PortableSearchSessionPlan::K0 {
                exclusive_route_state,
                ..
            } = &session.plan
            else {
                unreachable!();
            };
            assert_eq!(
                exclusive_route_state.value_iter_route(),
                super::K0ValueIterRoute::SourceBound
            );
        }
    }

    #[test]
    fn forced_k0_ordinary_iterators_release_source_masks_on_drop_and_mutation() {
        let cases = [
            (r"[\x20-\x7F][\x00-\x40]", [0x60_u8, 0x20]),
            (r"[aceg][\x00-\x40]", [b'a', 0x20]),
            (r"[\x80\x82\xFE\xFF][\x00-\x40]", [0x80, 0x20]),
        ];

        for (pattern, matched_bytes) in cases {
            let mut fre = PortableBuilder::new(pattern)
                .unicode(false)
                .plan_selection(PlanSelection::ForceK0)
                .build()
                .unwrap();
            assert_eq!(fre.build_report().plan, PlanKind::K0);
            let PortablePlan::K0(plan) = &mut fre.plan else {
                unreachable!("forced ordinary iterator fixture must retain K0");
            };
            plan.absolute_end_proof = None;
            plan.exclusive = super::K0ExclusivePlan::None;
            plan.reverse_inner = None;
            plan.mandatory_suffix = None;
            plan.mandatory_cut = None;
            plan.negative_prefilter = None;

            let upstream = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            let mut session = fre
                .search_session(super::SearchSessionLimits::unlimited())
                .unwrap();
            let PortableSearchSessionPlan::K0 {
                session: k0_session,
                reverse_inner: None,
                mandatory_suffix: None,
                mandatory_cut: None,
                negative_prefilter: None,
                ..
            } = &session.plan
            else {
                panic!("ordinary iterator fixture retained a facade sidecar");
            };
            assert!(!k0_session.retained_root_run_cursor_available());

            let mut haystack = vec![b'p'; 128];
            for position in [20_usize, 22, 24, 26] {
                haystack[position..position + 2].copy_from_slice(&matched_bytes);
            }
            let allocation = haystack.as_ptr();
            let expected = |source: &[u8]| {
                upstream
                    .find_iter(source)
                    .map(|matched| (matched.start(), matched.end()))
                    .collect::<Vec<_>>()
            };

            let fresh: Result<Vec<_>, _> = fre
                .find_iter(&haystack, PortableFindIterLimits::unlimited())
                .unwrap()
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect();
            assert_eq!(fresh.unwrap(), expected(&haystack), "pattern={pattern}");
            let fresh_value: Result<Vec<_>, _> = fre
                .find_iter_value(&haystack, PortableFindIterLimits::unlimited())
                .unwrap()
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect();
            assert_eq!(
                fresh_value.unwrap(),
                expected(&haystack),
                "value pattern={pattern}"
            );

            {
                let mut matches =
                    session.find_iter(&haystack, PortableFindIterRunLimits::unlimited());
                for expected_match in expected(&haystack).into_iter().take(2) {
                    let actual = matches.next().unwrap().unwrap();
                    assert_eq!((actual.start(), actual.end()), expected_match);
                }
            }
            haystack.fill(b'p');
            for position in [40_usize, 42, 44, 46] {
                haystack[position..position + 2].copy_from_slice(&matched_bytes);
            }
            assert_eq!(haystack.as_ptr(), allocation);
            let restarted: Result<Vec<_>, _> = session
                .find_iter(&haystack, PortableFindIterRunLimits::unlimited())
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect();
            assert_eq!(
                restarted.unwrap(),
                expected(&haystack),
                "same-address accounted restart pattern={pattern}"
            );

            {
                let mut matches =
                    session.find_iter_value(&haystack, PortableFindIterRunLimits::unlimited());
                for expected_match in expected(&haystack).into_iter().take(2) {
                    let actual = matches.next().unwrap().unwrap();
                    assert_eq!((actual.start(), actual.end()), expected_match);
                }
            }
            haystack.fill(b'p');
            for position in [68_usize, 70, 72, 74] {
                haystack[position..position + 2].copy_from_slice(&matched_bytes);
            }
            assert_eq!(haystack.as_ptr(), allocation);
            let restarted_value: Result<Vec<_>, _> = session
                .find_iter_value(&haystack, PortableFindIterRunLimits::unlimited())
                .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
                .collect();
            assert_eq!(
                restarted_value.unwrap(),
                expected(&haystack),
                "same-address value restart pattern={pattern}"
            );
        }
    }

    fn assert_correlated_delimited_session_matches_upstream(
        session: &mut super::PortableSearchSession<'_>,
        upstream: &regex::bytes::Regex,
        haystack: &[u8],
    ) {
        let expected = upstream
            .find(haystack)
            .map(|matched| (matched.start(), matched.end()));
        assert_eq!(
            session
                .find_value(haystack, SearchLimits::unlimited())
                .unwrap()
                .map(|matched| (matched.start(), matched.end())),
            expected,
        );
        assert_eq!(
            session
                .is_match_window_value(
                    haystack,
                    SearchWindow::full(haystack),
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected.is_some(),
        );
        assert_eq!(
            session
                .shortest_match_window_value(
                    haystack,
                    SearchWindow::full(haystack),
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            upstream.shortest_match(haystack),
        );
        assert_eq!(
            session
                .selected_end_value(haystack, SearchLimits::unlimited())
                .unwrap(),
            expected.map(|(_, end)| end),
        );
        let expected_iter = upstream
            .find_iter(haystack)
            .map(|matched| (matched.start(), matched.end()))
            .collect::<Vec<_>>();
        let actual_iter = session
            .find_iter_value(haystack, PortableFindIterRunLimits::unlimited())
            .map(|matched| {
                let matched = matched.unwrap();
                (matched.start(), matched.end())
            })
            .collect::<Vec<_>>();
        assert_eq!(actual_iter, expected_iter);
    }

    fn assert_correlated_delimited_window_matches_upstream(
        session: &mut super::PortableSearchSession<'_>,
        upstream: &regex::bytes::Regex,
        haystack: &[u8],
        window: SearchWindow,
    ) {
        let expected = upstream
            .find(&haystack[window.start()..window.end()])
            .map(|matched| Match {
                start: window.start() + matched.start(),
                end: window.start() + matched.end(),
            });
        let expected_end = upstream
            .shortest_match(&haystack[window.start()..window.end()])
            .map(|end| window.start() + end);
        assert_eq!(
            session
                .find_window_value(haystack, window, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert_eq!(
            session
                .is_match_window_value(haystack, window, SearchLimits::unlimited())
                .unwrap(),
            expected.is_some(),
        );
        assert_eq!(
            session
                .shortest_match_window_value(
                    haystack,
                    window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected_end,
        );
    }

    #[test]
    fn correlated_delimited_root_alternation_is_exhaustive_over_small_sources_and_windows() {
        const PATTERN: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        let regex = PortableBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        let upstream = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let PortableSearchSessionPlan::K0 { k0_plan, .. } = &session.plan
        else {
            panic!("exact correlated alternation lost its K0 sidecar");
        };
        let plan = k0_plan
            .correlated_terminal()
            .expect("exact correlated alternation lost its K0 sidecar");
        assert!(plan.is_exact_delimited());

        fn enumerate(
            alphabet: &[u8],
            remaining: usize,
            source: &mut Vec<u8>,
            visit: &mut impl FnMut(&[u8]),
        ) {
            visit(source);
            if remaining == 0 {
                return;
            }
            for &byte in alphabet {
                source.push(byte);
                enumerate(alphabet, remaining - 1, source, visit);
                source.pop();
            }
        }

        enumerate(
            b"abcZqdeYx",
            4,
            &mut Vec::new(),
            &mut |haystack| {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let slice = &haystack[start..end];
                        let expected = upstream.find(slice).map(|matched| {
                            (start + matched.start(), start + matched.end())
                        });
                        let expected_shortest = upstream
                            .shortest_match(slice)
                            .map(|matched_end| start + matched_end);
                        assert_eq!(
                            session
                                .find_window_value(
                                    haystack,
                                    window,
                                    SearchLimits::unlimited(),
                                )
                                .unwrap()
                                .map(|matched| (matched.start(), matched.end())),
                            expected,
                            "span haystack={haystack:?} window={start}..{end}",
                        );
                        assert_eq!(
                            session
                                .is_match_window_value(
                                    haystack,
                                    window,
                                    SearchLimits::unlimited(),
                                )
                                .unwrap(),
                            expected.is_some(),
                            "exists haystack={haystack:?} window={start}..{end}",
                        );
                        assert_eq!(
                            session
                                .shortest_match_window_value(
                                    haystack,
                                    window,
                                    SearchLimits::unlimited(),
                                )
                                .unwrap(),
                            expected_shortest,
                            "shortest haystack={haystack:?} window={start}..{end}",
                        );
                    }
                }
            },
        );

        for haystack in [
            b"xxabbbbbZyyqddYzz".as_slice(),
            b"Z~abbbbbY~qddddY~abccZ~Y",
            b"qYqdeYabZabbbbbZ",
        ] {
            assert_correlated_delimited_session_matches_upstream(
                &mut session,
                &upstream,
                haystack,
            );
        }
    }

    #[test]
    fn correlated_delimited_sparse_fallback_preserves_operations_and_window_bounds() {
        const PATTERN: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        let regex = PortableBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let upstream = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();

        let long_absent = vec![b'~'; BYTE_SET_BLOCK_BYTES * 8];
        assert_correlated_delimited_session_matches_upstream(
            &mut session,
            &upstream,
            &long_absent,
        );

        let late_start = BYTE_SET_BLOCK_BYTES * 5 + 3;
        let mut late = vec![b'~'; BYTE_SET_BLOCK_BYTES * 8];
        late[late_start..late_start + 6].copy_from_slice(b"qddddY");
        assert_correlated_delimited_session_matches_upstream(
            &mut session,
            &upstream,
            &late,
        );
        assert_correlated_delimited_window_matches_upstream(
            &mut session,
            &upstream,
            &late,
            SearchWindow::new(7, late.len() - 5),
        );

        let far_rejection = BYTE_SET_BLOCK_BYTES * 4 + 3;
        let mut rejected_then_valid = vec![b'~'; BYTE_SET_BLOCK_BYTES * 8];
        rejected_then_valid[far_rejection] = b'Z';
        let valid_start = far_rejection + 7;
        rejected_then_valid[valid_start..valid_start + 4]
            .copy_from_slice(b"qddY");
        assert_correlated_delimited_session_matches_upstream(
            &mut session,
            &upstream,
            &rejected_then_valid,
        );

        let mut rejected_then_farther_valid = vec![b'~'; BYTE_SET_BLOCK_BYTES * 8];
        rejected_then_farther_valid[far_rejection] = b'Z';
        let farther_valid_start = far_rejection + BYTE_SET_BLOCK_BYTES * 2;
        rejected_then_farther_valid[farther_valid_start..farther_valid_start + 4]
            .copy_from_slice(b"qddY");
        assert_correlated_delimited_session_matches_upstream(
            &mut session,
            &upstream,
            &rejected_then_farther_valid,
        );

        let dense_false_terminals = vec![b'Z'; BYTE_SET_BLOCK_BYTES * 8];
        assert_correlated_delimited_session_matches_upstream(
            &mut session,
            &upstream,
            &dense_false_terminals,
        );

        let mut haystack = vec![b'~'; BYTE_SET_BLOCK_BYTES * 6];
        haystack[1] = b'Z';
        let late = haystack.len() - 8;
        haystack[late..late + 6].copy_from_slice(b"qddddY");
        assert_correlated_delimited_session_matches_upstream(
            &mut session,
            &upstream,
            &haystack,
        );

        let window = SearchWindow::new(7, haystack.len() - 1);
        haystack[window.start() + 1] = b'Y';
        assert_correlated_delimited_window_matches_upstream(
            &mut session,
            &upstream,
            &haystack,
            window,
        );
    }

    #[test]
    fn correlated_delimited_sessions_retain_no_cross_plan_or_same_address_state() {
        const LEFT: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        const RIGHT: &str = r"(?-u:(?:mn[no]*X|r[st]+W))";
        let left = PortableBuilder::new(LEFT)
            .unicode(false)
            .build()
            .unwrap();
        let right = PortableBuilder::new(RIGHT)
            .unicode(false)
            .build()
            .unwrap();
        let left_upstream = regex::bytes::RegexBuilder::new(LEFT)
            .unicode(false)
            .build()
            .unwrap();
        let right_upstream = regex::bytes::RegexBuilder::new(RIGHT)
            .unicode(false)
            .build()
            .unwrap();
        let mut left_session = left
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let mut right_session = right
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        for session in [&left_session, &right_session] {
            let PortableSearchSessionPlan::K0 { k0_plan, .. } = &session.plan
            else {
                panic!("cross-plan fixture lost its exact sidecar");
            };
            let plan = k0_plan
                .correlated_terminal()
                .expect("cross-plan fixture lost its exact sidecar");
            assert!(plan.is_exact_delimited());
        }

        const SOURCE_BYTES: usize = BYTE_SET_BLOCK_BYTES * 8;
        let mut variants = Vec::new();
        for placements in [
            &[][..],
            &[(7_usize, b"abbbbZ".as_slice())][..],
            &[(BYTE_SET_BLOCK_BYTES * 5 + 3, b"rsttW".as_slice())][..],
            &[
                (3_usize, b"qdddY".as_slice()),
                (BYTE_SET_BLOCK_BYTES * 4 + 1, b"mnnnX".as_slice()),
                (BYTE_SET_BLOCK_BYTES * 6 + 2, b"abZ".as_slice()),
            ][..],
        ] {
            let mut source = vec![b'~'; SOURCE_BYTES];
            for &(start, bytes) in placements {
                source[start..start + bytes.len()].copy_from_slice(bytes);
            }
            variants.push(source);
        }
        variants.push(b"ZYXW".repeat(SOURCE_BYTES / 4));
        assert!(
            variants
                .iter()
                .all(|variant| variant.len() == SOURCE_BYTES)
        );

        let mut haystack = vec![0_u8; SOURCE_BYTES];
        let address = haystack.as_ptr();
        let capacity = haystack.capacity();
        for variant in variants.iter().cycle().take(12) {
            haystack.copy_from_slice(variant);
            assert_eq!(haystack.as_ptr(), address);
            assert_eq!(haystack.capacity(), capacity);
            assert_correlated_delimited_session_matches_upstream(
                &mut left_session,
                &left_upstream,
                &haystack,
            );
            assert_correlated_delimited_session_matches_upstream(
                &mut right_session,
                &right_upstream,
                &haystack,
            );
        }

        let limited = SearchLimits {
            max_work: 0,
            max_scratch_bytes: 0,
        };
        assert!(left_session.find_value(&haystack, limited).is_err());
        assert!(
            left_session
                .find_window_value(
                    &haystack,
                    SearchWindow::new(1, haystack.len() + 1),
                    SearchLimits::unlimited(),
                )
                .is_err(),
        );
    }

    fn prepare_correlated_iter_for_test(
        session: &mut PortableSearchSession<'_>,
        source: &mut K0SpanSourceCursor<'_>,
        start: usize,
        limits: SearchLimits,
    ) -> Option<Result<super::K0CorrelatedIterPrepared, SearchError>> {
        let PortableSearchSessionPlan::K0 {
            session: k0_session,
            k0_plan,
            reverse_inner,
            mandatory_suffix,
            mandatory_cut,
            negative_prefilter,
            ..
        } = &mut session.plan
        else {
            return None;
        };
        k0_plan.correlated_terminal()?;
        let sidecars_absent = reverse_inner.is_none()
            && mandatory_suffix.is_none()
            && mandatory_cut.is_none()
            && negative_prefilter.is_none()
            && k0_plan.absolute_end_proof.is_none();
        super::prepare_k0_correlated_iter_at(
            k0_session,
            k0_plan,
            sidecars_absent,
            source,
            start,
            limits,
        )
    }

    fn k0_automaton_identity(session: &PortableSearchSession<'_>) -> u64 {
        let PortableSearchSessionPlan::K0 { k0_plan, .. } = &session.plan else {
            panic!("correlated iterator fixture lost K0");
        };
        k0_plan.automaton.identity()
    }

    #[test]
    fn correlated_delimited_accounted_iterator_prepays_one_linear_envelope() {
        const PATTERN: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        let regex = PortableBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let upstream = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let haystack = b"abbbbZqdddYabZ";
        let expected = upstream
            .find_iter(haystack)
            .map(|matched| (matched.start(), matched.end()))
            .collect::<Vec<_>>();
        assert_eq!(expected, vec![(0, 6), (6, 11), (11, 14)]);

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let automaton_identity = k0_automaton_identity(&session);
        let mut matches =
            session.find_iter(haystack, PortableFindIterRunLimits::unlimited());
        let mut actual = Vec::new();
        for expected_match in &expected {
            let matched = matches.next().unwrap().unwrap();
            actual.push((matched.start(), matched.end()));
            let accounting = matches.accounting();
            if actual.len() == 1 {
                assert_eq!(
                    accounting.work_or_linear_terms,
                    super::k0_correlated_iter_linear_work(haystack.len()).unwrap(),
                );
            } else {
                assert_eq!(
                    accounting.work_or_linear_terms,
                    super::k0_correlated_iter_linear_work(haystack.len()).unwrap(),
                    "contiguous continuations must consume the prepaid source envelope",
                );
            }
            assert_eq!(
                matches
                    .state
                    .core()
                    .k0_source
                    .retained_facade_continuation(automaton_identity)
                    .unwrap(),
                Some((haystack.len(), expected_match.1)),
            );
            assert_eq!(actual.last(), Some(expected_match));
        }
        assert!(matches.next().is_none());
        assert_eq!(actual, expected);
        assert_eq!(matches.accounting().matches, expected.len());
        assert_eq!(matches.accounting().search_calls, expected.len() + 1);
        assert_eq!(
            matches
                .state
                .core()
                .k0_source
                .retained_facade_continuation(automaton_identity)
                .unwrap(),
            Some((haystack.len(), haystack.len())),
        );

        drop(matches);
        let value = session
            .find_iter_value(haystack, PortableFindIterRunLimits::unlimited())
            .map(|matched| {
                let matched = matched.unwrap();
                (matched.start(), matched.end())
            })
            .collect::<Vec<_>>();
        assert_eq!(value, expected);
    }

    #[test]
    fn correlated_delimited_cursor_refusal_reset_and_late_failure_are_transactional() {
        const PATTERN: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        let regex = PortableBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let haystack = b"abbbbZqdddY";
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let automaton_identity = k0_automaton_identity(&session);
        let mut source = K0SpanSourceCursor::new(haystack);
        let cold = source
            .retained_facade_continuation(automaton_identity)
            .unwrap();
        assert_eq!(cold, None);
        let refused = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            0,
            SearchLimits {
                max_work: u64::MAX - 1,
                max_scratch_bytes: usize::MAX,
            },
        );
        assert!(refused.is_none());
        assert_eq!(
            source
                .retained_facade_continuation(automaton_identity)
                .unwrap(),
            cold,
        );

        let staged = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            0,
            SearchLimits::unlimited(),
        )
            .expect("unlimited exact-delimited admission")
            .unwrap();
        assert_eq!(staged.matched, Some(Match { start: 0, end: 6 }));
        assert_eq!(
            source
                .retained_facade_continuation(automaton_identity)
                .unwrap(),
            cold,
            "a completed but uncommitted transaction must not publish progress",
        );
        let _uncommitted = staged;

        let prepared = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            0,
            SearchLimits::unlimited(),
        )
            .unwrap()
            .unwrap();
        let (first, first_work) = prepared.commit(&mut source);
        assert_eq!(first, Some(Match { start: 0, end: 6 }));
        assert_eq!(
            first_work,
            PortableFindIterStepAccounting::work(
                super::k0_correlated_iter_linear_work(haystack.len()).unwrap(),
            ),
        );
        let prepared = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            1,
            SearchLimits::unlimited(),
        )
            .unwrap()
            .unwrap();
        let (noncontiguous, reset_work) = prepared.commit(&mut source);
        assert_eq!(noncontiguous, Some(Match { start: 6, end: 11 }));
        assert_eq!(
            reset_work,
            PortableFindIterStepAccounting::work(
                super::k0_correlated_iter_linear_work(haystack.len() - 1).unwrap(),
            ),
        );
    }

    #[test]
    fn correlated_delimited_accounted_cursor_falls_back_from_the_proved_floor() {
        const PATTERN: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        let regex = PortableBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let upstream = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        let false_terminal = 3;
        let valid_start = false_terminal + BYTE_SET_BLOCK_BYTES * 2;
        let mut haystack = vec![b'~'; BYTE_SET_BLOCK_BYTES * 5];
        haystack[false_terminal] = b'Z';
        haystack[valid_start..valid_start + 4].copy_from_slice(b"qddY");
        let expected = upstream.find(&haystack).map(|matched| Match {
            start: matched.start(),
            end: matched.end(),
        });
        assert_eq!(expected, Some(Match { start: valid_start, end: valid_start + 4 }));

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let PortableSearchSessionPlan::K0 { k0_plan, .. } = &session.plan else {
            panic!("fallback fixture lost K0");
        };
        let plan = k0_plan.correlated_terminal().unwrap();
        assert!(matches!(
            plan.probe_exact_delimited(&haystack, 0, haystack.len()),
            super::correlated_bounded_alternation::ExactDelimitedProbe::Fallback {
                first_unproved_start
            } if first_unproved_start == false_terminal + 1
        ));
        let mut charge_session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let charge_identity = k0_automaton_identity(&charge_session);
        let mut charge_source = K0SpanSourceCursor::new(&haystack);
        let prepared = prepare_correlated_iter_for_test(
            &mut charge_session,
            &mut charge_source,
            0,
            SearchLimits::unlimited(),
        )
            .unwrap()
            .unwrap();
        assert_eq!(prepared.matched, expected);
        assert_eq!(
            prepared.accounting.work_or_linear_terms,
            super::k0_correlated_iter_linear_work(haystack.len())
                .unwrap()
                .checked_add(prepared.fallback_work)
                .unwrap(),
            "a fresh cursor must charge exactly its prepaid pass plus fresh authoritative fallback work",
        );
        assert_eq!(
            charge_source
                .retained_facade_continuation(charge_identity)
                .unwrap(),
            None,
            "preparation must not publish before the caller accepts its accounting",
        );

        let automaton_identity = k0_automaton_identity(&session);
        let mut source = K0SpanSourceCursor::new(&haystack);
        let cursor_before = source
            .retained_facade_continuation(automaton_identity)
            .unwrap();
        let staged = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            0,
            SearchLimits::unlimited(),
        )
            .expect("the exact-delimited probe reaches its authoritative fallback")
            .unwrap();
        assert_eq!(staged.matched, expected);
        assert_eq!(
            source
                .retained_facade_continuation(automaton_identity)
                .unwrap(),
            cursor_before,
            "a post-fallback failure must not publish retained cursor progress",
        );
        let _uncommitted = staged;
        let prepared = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            0,
            SearchLimits::unlimited(),
        )
            .unwrap()
            .unwrap();
        let (matched, _) = prepared.commit(&mut source);
        assert_eq!(matched, expected);
        let prepared = prepare_correlated_iter_for_test(
            &mut session,
            &mut source,
            expected.unwrap().end(),
            SearchLimits::unlimited(),
        )
            .unwrap()
            .unwrap();
        let (exhausted, continuation_work) = prepared.commit(&mut source);
        assert_eq!(exhausted, None);
        assert_eq!(continuation_work, PortableFindIterStepAccounting::default());
    }

    #[test]
    fn correlated_delimited_accounted_iterators_bind_each_plan_and_same_address_source() {
        const LEFT: &str = r"(?-u:(?:ab[bc]*Z|q[de]*Y))";
        const RIGHT: &str = r"(?-u:(?:mn[no]*X|r[st]+W))";
        let left = PortableBuilder::new(LEFT).unicode(false).build().unwrap();
        let right = PortableBuilder::new(RIGHT).unicode(false).build().unwrap();
        let left_upstream = regex::bytes::RegexBuilder::new(LEFT)
            .unicode(false)
            .build()
            .unwrap();
        let right_upstream = regex::bytes::RegexBuilder::new(RIGHT)
            .unicode(false)
            .build()
            .unwrap();
        let mut left_session = left
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let mut right_session = right
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let mut source = vec![b'~'; BYTE_SET_BLOCK_BYTES * 5];
        let source_address = source.as_ptr();
        for (left_token, right_token) in [
            (b"abbbbZ".as_slice(), b"mnnnX".as_slice()),
            (b"qdddY".as_slice(), b"rsttW".as_slice()),
            (b"abZ".as_slice(), b"mnX".as_slice()),
        ] {
            source.fill(b'~');
            source[7..7 + left_token.len()].copy_from_slice(left_token);
            let right_start = BYTE_SET_BLOCK_BYTES * 3 + 1;
            source[right_start..right_start + right_token.len()].copy_from_slice(right_token);
            assert_eq!(source.as_ptr(), source_address);
            let left_expected = left_upstream
                .find_iter(&source)
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>();
            let right_expected = right_upstream
                .find_iter(&source)
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>();
            let left_actual = left_session
                .find_iter(&source, PortableFindIterRunLimits::unlimited())
                .map(|matched| {
                    let matched = matched.unwrap();
                    (matched.start(), matched.end())
                })
                .collect::<Vec<_>>();
            let right_actual = right_session
                .find_iter(&source, PortableFindIterRunLimits::unlimited())
                .map(|matched| {
                    let matched = matched.unwrap();
                    (matched.start(), matched.end())
                })
                .collect::<Vec<_>>();
            assert_eq!(left_actual, left_expected);
            assert_eq!(right_actual, right_expected);
            let left_identity = k0_automaton_identity(&left_session);
            let mut bound_source = K0SpanSourceCursor::new(&source);
            assert_eq!(
                bound_source
                    .retained_facade_continuation(left_identity)
                    .unwrap(),
                None,
                "a new immutable borrow at the same address must start cold",
            );
            let prepared = prepare_correlated_iter_for_test(
                &mut left_session,
                &mut bound_source,
                0,
                SearchLimits::unlimited(),
            )
                .expect("left plan retains its exact continuation")
                .unwrap();
            let (left_first, _) = prepared.commit(&mut bound_source);
            assert_eq!(
                left_first.map(|matched| (matched.start(), matched.end())),
                left_expected.first().copied(),
            );
            let cursor_before = bound_source
                .retained_facade_continuation(left_identity)
                .unwrap();
            let cross_plan = prepare_correlated_iter_for_test(
                &mut right_session,
                &mut bound_source,
                0,
                SearchLimits::unlimited(),
            )
                .expect("a cross-plan use is an authenticated error")
                .unwrap_err();
            assert!(matches!(
                cross_plan,
                SearchError::K0(fre_automata::SearchError::InternalInvariant {
                    detail: "source-bound facade continuation received a different immutable plan"
                })
            ));
            assert_eq!(
                bound_source
                    .retained_facade_continuation(left_identity)
                    .unwrap(),
                cursor_before,
                "cross-plan refusal must precede cursor publication",
            );
        }
    }

    #[test]
    fn correlated_terminal_value_iterator_keeps_the_sidecar_and_adaptive_route() {
        let pattern =
            r"(?-u:\x10(?:\x70[\x30\x31]{0,16}\x60|\x71[\x36\x37]{1,16}\x61))";
        let fre = PortableBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        assert_eq!(fre.build_report().plan, PlanKind::K0);
        let upstream = regex::bytes::RegexBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();

        let mut haystack = Vec::new();
        for _ in 0..4 {
            for _ in 0..4_000 {
                haystack.extend_from_slice(b"\x10\x70\x62");
            }
            haystack.extend_from_slice(b"\x10\x70\x30\x60");
        }
        let expected = upstream
            .find_iter(&haystack)
            .map(|matched| (matched.start(), matched.end()))
            .collect::<Vec<_>>();
        assert_eq!(expected.len(), 4);

        let fresh = fre
            .find_iter_value(&haystack, PortableFindIterLimits::unlimited())
            .unwrap()
            .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(fresh, expected);

        let mut session = fre
            .search_session(super::SearchSessionLimits::unlimited())
            .unwrap();
        let PortableSearchSessionPlan::K0 { k0_plan, .. } = &session.plan
        else {
            panic!("correlated value-iterator fixture lost its facade sidecar");
        };
        assert!(k0_plan.correlated_terminal().is_some());

        // The first long, decoy-heavy search teaches the adaptive route. A
        // fresh iterator over the same immutable plan and source then starts
        // with the terminal sidecar while preserving the complete sequence.
        {
            let mut learning = session
                .find_iter_value(&haystack, PortableFindIterRunLimits::unlimited());
            assert_eq!(
                learning.next().unwrap().unwrap(),
                Match {
                    start: expected[0].0,
                    end: expected[0].1,
                }
            );
        }
        let PortableSearchSessionPlan::K0 {
            exclusive_route_state,
            ..
        } = &mut session.plan
        else {
            unreachable!("the fixture was checked as K0 above");
        };
        let super::K0ExclusiveRouteState::Correlated(correlated_states) =
            exclusive_route_state
        else {
            panic!("correlated iterator fixture lost its exclusive route state");
        };
        assert!(matches!(
            correlated_states.span.select(haystack.len()),
            super::correlated_bounded_alternation::Route::Terminal { .. }
        ));

        let retained = session
            .find_iter_value(&haystack, PortableFindIterRunLimits::unlimited())
            .map(|matched| matched.map(|matched| (matched.start(), matched.end())))
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(retained, expected);
    }

    #[test]
    fn finite_planner_work_limit_is_an_exact_preselection_boundary() {
        let pattern = "(?:ab|cd)(?:e|f)";
        let baseline = PortableBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        let required = baseline.build_report().planner_work;
        assert!(required > 0);
        let exact = BuildLimits {
            max_planner_work: required,
            ..BuildLimits::default()
        };
        assert!(
            PortableBuilder::new(pattern)
                .unicode(false)
                .limits(exact)
                .build()
                .is_ok()
        );
        let refused = BuildLimits {
            max_planner_work: required - 1,
            ..BuildLimits::default()
        };
        assert!(matches!(
            PortableBuilder::new(pattern)
                .unicode(false)
                .limits(refused)
                .build(),
            Err(BuildError::PlannerWorkLimit { .. })
        ));
    }

    #[test]
    fn certified_ordered_empty_loops_build_through_k0() {
        let certified = PortableBuilder::new("(?:|a)*")
            .unicode(false)
            .build()
            .expect("empty-first nullable loop is normalized");
        assert_eq!(certified.build_report().plan, PlanKind::K0);
        assert_eq!(
            certified
                .build_report()
                .lowering
                .expect("K0 lowering report")
                .normalized_nullable_repetitions(),
            1
        );

        let consuming_first = PortableBuilder::new("(?:a|)*b")
            .unicode(false)
            .build()
            .expect("one-byte consuming-first nullable loop is normalized");
        assert_eq!(consuming_first.build_report().plan, PlanKind::K0);
        let (matched, _) = consuming_first
            .find_accounted(b"aaab", SearchLimits::unlimited())
            .expect("normalized K0 search succeeds");
        assert_eq!(
            matched.map(|matched| (matched.start(), matched.end())),
            Some((0, 4))
        );
    }

